INSERT INTO public.questions (category, scenario, question, options, correct_answer, explanation)
VALUES
('Segurança e Governança', '{"pt-br":"Você precisa restringir o acesso a linhas específicas de dados em um modelo semântico, garantindo que cada gerente veja apenas os dados de sua região.","en-us":"You need to restrict access to specific data rows in a semantic model, ensuring each manager sees only their region''s data.","es":"Necesita restringir el acceso a filas específicas de datos en un modelo semántico, garantizando que cada gerente vea solo los datos de su región.","fr":"Vous devez restreindre l''accès à des lignes spécifiques dans un modèle sémantique, en garantissant que chaque responsable ne voit que les données de sa région."}', '{"pt-br":"Qual recurso deve ser configurado?","en-us":"Which feature should be configured?","es":"¿Qué recurso debe configurarse?","fr":"Quelle fonctionnalité doit être configurée ?"}', '[{"key":"A","text":{"pt-br":"Object-Level Security (OLS)","en-us":"Object-Level Security (OLS)","es":"Object-Level Security (OLS)","fr":"Object-Level Security (OLS)"}},{"key":"B","text":{"pt-br":"Row-Level Security (RLS)","en-us":"Row-Level Security (RLS)","es":"Row-Level Security (RLS)","fr":"Row-Level Security (RLS)"}},{"key":"C","text":{"pt-br":"Workspace Roles","en-us":"Workspace Roles","es":"Workspace Roles","fr":"Workspace Roles"}},{"key":"D","text":{"pt-br":"Sensitivity Labels","en-us":"Sensitivity Labels","es":"Sensitivity Labels","fr":"Sensitivity Labels"}}]', 'B', '{"pt-br":"RLS permite definir filtros DAX que restringem o acesso a linhas com base na identidade do usuário. OLS restringe colunas/tabelas, Workspace Roles controlam permissões no workspace.","en-us":"RLS allows defining DAX filters that restrict row access based on user identity. OLS restricts columns/tables, Workspace Roles control workspace permissions.","es":"RLS permite definir filtros DAX que restringen el acceso a filas según la identidad del usuario. OLS restringe columnas/tablas, Workspace Roles controlan permisos.","fr":"RLS permet de définir des filtres DAX restreignant l''accès aux lignes selon l''identité utilisateur. OLS restreint colonnes/tables, Workspace Roles contrôlent les permissions."}'),
('Segurança e Governança', '{"pt-br":"Sua organização precisa classificar dados confidenciais no Microsoft Fabric para atender a requisitos de conformidade do LGPD.","en-us":"Your organization needs to classify sensitive data in Microsoft Fabric to meet GDPR compliance requirements.","es":"Su organización necesita clasificar datos confidenciales en Microsoft Fabric para cumplir requisitos de conformidad del RGPD.","fr":"Votre organisation doit classifier les données sensibles dans Microsoft Fabric pour répondre aux exigences de conformité RGPD."}', '{"pt-br":"Qual recurso do Microsoft Purview deve ser utilizado?","en-us":"Which Microsoft Purview feature should be used?","es":"¿Qué recurso de Microsoft Purview debe utilizarse?","fr":"Quelle fonctionnalité de Microsoft Purview doit être utilisée ?"}', '[{"key":"A","text":{"pt-br":"Sensitivity Labels","en-us":"Sensitivity Labels","es":"Sensitivity Labels","fr":"Sensitivity Labels"}},{"key":"B","text":{"pt-br":"Data Loss Prevention (DLP)","en-us":"Data Loss Prevention (DLP)","es":"Data Loss Prevention (DLP)","fr":"Data Loss Prevention (DLP)"}},{"key":"C","text":{"pt-br":"Audit Logs","en-us":"Audit Logs","es":"Audit Logs","fr":"Audit Logs"}},{"key":"D","text":{"pt-br":"Information Barriers","en-us":"Information Barriers","es":"Information Barriers","fr":"Information Barriers"}}]', 'A', '{"pt-br":"Sensitivity Labels do Microsoft Purview permitem classificar e proteger dados sensíveis aplicando rótulos que definem políticas de proteção, criptografia e controle de acesso.","en-us":"Microsoft Purview Sensitivity Labels allow classifying and protecting sensitive data by applying labels that define protection policies, encryption, and access control.","es":"Las Sensitivity Labels de Microsoft Purview permiten clasificar y proteger datos sensibles aplicando etiquetas que definen políticas de protección, cifrado y control de acceso.","fr":"Les Sensitivity Labels de Microsoft Purview permettent de classifier et protéger les données sensibles en appliquant des étiquettes définissant politiques de protection, chiffrement et contrôle d''accès."}'),
('Segurança e Governança', '{"pt-br":"Você precisa ocultar uma coluna de salário em um modelo semântico para que determinados usuários não possam vê-la nos relatórios.","en-us":"You need to hide a salary column in a semantic model so certain users cannot see it in reports.","es":"Necesita ocultar una columna de salario en un modelo semántico para que ciertos usuarios no puedan verla en los informes.","fr":"Vous devez masquer une colonne de salaire dans un modèle sémantique pour que certains utilisateurs ne puissent pas la voir dans les rapports."}', '{"pt-br":"Qual recurso de segurança deve ser implementado?","en-us":"Which security feature should be implemented?","es":"¿Qué recurso de seguridad debe implementarse?","fr":"Quelle fonctionnalité de sécurité doit être implémentée ?"}', '[{"key":"A","text":{"pt-br":"Row-Level Security (RLS)","en-us":"Row-Level Security (RLS)","es":"Row-Level Security (RLS)","fr":"Row-Level Security (RLS)"}},{"key":"B","text":{"pt-br":"Object-Level Security (OLS)","en-us":"Object-Level Security (OLS)","es":"Object-Level Security (OLS)","fr":"Object-Level Security (OLS)"}},{"key":"C","text":{"pt-br":"Dynamic Data Masking","en-us":"Dynamic Data Masking","es":"Dynamic Data Masking","fr":"Dynamic Data Masking"}},{"key":"D","text":{"pt-br":"Column Encryption","en-us":"Column Encryption","es":"Column Encryption","fr":"Column Encryption"}}]', 'B', '{"pt-br":"OLS permite restringir a visibilidade de colunas ou tabelas inteiras com base em roles. RLS filtra linhas, não colunas. Dynamic Data Masking mascara valores mas não oculta a coluna.","en-us":"OLS allows restricting visibility of entire columns or tables based on roles. RLS filters rows, not columns. Dynamic Data Masking masks values but doesn''t hide the column.","es":"OLS permite restringir la visibilidad de columnas o tablas completas según roles. RLS filtra filas, no columnas. Dynamic Data Masking enmascara valores pero no oculta la columna.","fr":"OLS permet de restreindre la visibilité de colonnes ou tables entières selon les rôles. RLS filtre les lignes, pas les colonnes. Dynamic Data Masking masque les valeurs mais ne cache pas la colonne."}'),
('Segurança e Governança', '{"pt-br":"Você precisa conceder a um analista permissão para criar relatórios usando datasets existentes no workspace, mas sem poder modificar os datasets.","en-us":"You need to grant an analyst permission to create reports using existing datasets in the workspace, without being able to modify the datasets.","es":"Necesita conceder a un analista permiso para crear informes usando datasets existentes en el workspace, sin poder modificar los datasets.","fr":"Vous devez accorder à un analyste la permission de créer des rapports en utilisant les datasets existants dans l''espace de travail, sans pouvoir les modifier."}', '{"pt-br":"Qual Workspace Role deve ser atribuída?","en-us":"Which Workspace Role should be assigned?","es":"¿Qué Workspace Role debe asignarse?","fr":"Quel Workspace Role doit être attribué ?"}', '[{"key":"A","text":{"pt-br":"Admin","en-us":"Admin","es":"Admin","fr":"Admin"}},{"key":"B","text":{"pt-br":"Member","en-us":"Member","es":"Member","fr":"Member"}},{"key":"C","text":{"pt-br":"Contributor","en-us":"Contributor","es":"Contributor","fr":"Contributor"}},{"key":"D","text":{"pt-br":"Viewer","en-us":"Viewer","es":"Viewer","fr":"Viewer"}}]', 'C', '{"pt-br":"Contributor permite criar conteúdo novo (relatórios) no workspace usando recursos existentes, mas não pode gerenciar permissões. Viewer só visualiza, Member pode publicar apps, Admin tem controle total.","en-us":"Contributor allows creating new content (reports) in the workspace using existing resources but cannot manage permissions. Viewer can only view, Member can publish apps, Admin has full control.","es":"Contributor permite crear contenido nuevo (informes) usando recursos existentes pero no puede gestionar permisos. Viewer solo visualiza, Member puede publicar apps, Admin tiene control total.","fr":"Contributor permet de créer du contenu (rapports) en utilisant les ressources existantes sans gérer les permissions. Viewer ne fait que visualiser, Member peut publier des apps, Admin a le contrôle total."}'),
('Segurança e Governança', '{"pt-br":"Você configurou RLS no modelo semântico. Precisa testar se as regras estão funcionando corretamente para um usuário específico.","en-us":"You configured RLS on the semantic model. You need to test if the rules are working correctly for a specific user.","es":"Configuró RLS en el modelo semántico. Necesita probar si las reglas funcionan correctamente para un usuario específico.","fr":"Vous avez configuré RLS sur le modèle sémantique. Vous devez tester si les règles fonctionnent correctement pour un utilisateur spécifique."}', '{"pt-br":"Como validar a configuração de RLS?","en-us":"How to validate the RLS configuration?","es":"¿Cómo validar la configuración de RLS?","fr":"Comment valider la configuration de RLS ?"}', '[{"key":"A","text":{"pt-br":"Usar ''View As'' no Power BI Service","en-us":"Use ''View As'' in Power BI Service","es":"Usar ''View As'' en Power BI Service","fr":"Utiliser ''View As'' dans Power BI Service"}},{"key":"B","text":{"pt-br":"Publicar o relatório e pedir ao usuário testar","en-us":"Publish the report and ask the user to test","es":"Publicar el informe y pedir al usuario que pruebe","fr":"Publier le rapport et demander à l''utilisateur de tester"}},{"key":"C","text":{"pt-br":"Verificar os logs de auditoria","en-us":"Check the audit logs","es":"Verificar los logs de auditoría","fr":"Vérifier les journaux d''audit"}},{"key":"D","text":{"pt-br":"Executar uma query DAX no DAX Studio","en-us":"Run a DAX query in DAX Studio","es":"Ejecutar una query DAX en DAX Studio","fr":"Exécuter une requête DAX dans DAX Studio"}}]', 'A', '{"pt-br":"''View As'' permite simular a visualização como um role ou usuário específico para validar que os filtros RLS estão aplicados corretamente antes de publicar.","en-us":"''View As'' allows simulating the view as a specific role or user to validate that RLS filters are applied correctly before publishing.","es":"''View As'' permite simular la visualización como un role o usuario específico para validar que los filtros RLS se aplican correctamente antes de publicar.","fr":"''View As'' permet de simuler la vue en tant que rôle ou utilisateur spécifique pour valider que les filtres RLS sont correctement appliqués avant publication."}'),
('Segurança e Governança', '{"pt-br":"Um relatório do Power BI contém dados de RH e precisa ser compartilhado apenas com o departamento de RH via um app do Power BI.","en-us":"A Power BI report contains HR data and needs to be shared only with the HR department via a Power BI app.","es":"Un informe de Power BI contiene datos de RH y necesita ser compartido solo con el departamento de RH a través de una app de Power BI.","fr":"Un rapport Power BI contient des données RH et doit être partagé uniquement avec le département RH via une app Power BI."}', '{"pt-br":"Qual abordagem garante o acesso restrito?","en-us":"Which approach ensures restricted access?","es":"¿Qué enfoque garantiza el acceso restringido?","fr":"Quelle approche garantit un accès restreint ?"}', '[{"key":"A","text":{"pt-br":"Configurar audiência do App para o grupo de segurança do RH","en-us":"Configure App audience to the HR security group","es":"Configurar audiencia del App para el grupo de seguridad de RH","fr":"Configurer l''audience de l''App pour le groupe de sécurité RH"}},{"key":"B","text":{"pt-br":"Compartilhar o link do relatório por email","en-us":"Share the report link by email","es":"Compartir el enlace del informe por email","fr":"Partager le lien du rapport par email"}},{"key":"C","text":{"pt-br":"Adicionar todos ao workspace como Viewers","en-us":"Add everyone to the workspace as Viewers","es":"Agregar a todos al workspace como Viewers","fr":"Ajouter tout le monde au workspace comme Viewers"}},{"key":"D","text":{"pt-br":"Exportar o relatório para PDF e enviar","en-us":"Export the report to PDF and send","es":"Exportar el informe a PDF y enviar","fr":"Exporter le rapport en PDF et envoyer"}}]', 'A', '{"pt-br":"Configurar a audiência do App permite controlar exatamente quem pode acessar o conteúdo usando grupos de segurança do Microsoft Entra ID, mantendo a governança centralizada.","en-us":"Configuring the App audience allows controlling exactly who can access the content using Microsoft Entra ID security groups, keeping governance centralized.","es":"Configurar la audiencia del App permite controlar exactamente quién puede acceder al contenido usando grupos de seguridad de Microsoft Entra ID, manteniendo la gobernanza centralizada.","fr":"Configurer l''audience de l''App permet de contrôler exactement qui peut accéder au contenu en utilisant les groupes de sécurité Microsoft Entra ID, maintenant la gouvernance centralisée."}'),
('Segurança e Governança', '{"pt-br":"Você precisa garantir que dados sensíveis exportados de relatórios do Power BI mantenham suas classificações de segurança em arquivos Excel.","en-us":"You need to ensure sensitive data exported from Power BI reports maintains its security classifications in Excel files.","es":"Necesita garantizar que los datos sensibles exportados de informes de Power BI mantengan sus clasificaciones de seguridad en archivos Excel.","fr":"Vous devez garantir que les données sensibles exportées des rapports Power BI conservent leurs classifications de sécurité dans les fichiers Excel."}', '{"pt-br":"Qual recurso propaga automaticamente a classificação?","en-us":"Which feature automatically propagates the classification?","es":"¿Qué recurso propaga automáticamente la clasificación?","fr":"Quelle fonctionnalité propage automatiquement la classification ?"}', '[{"key":"A","text":{"pt-br":"Sensitivity Labels com herança automática","en-us":"Sensitivity Labels with automatic inheritance","es":"Sensitivity Labels con herencia automática","fr":"Sensitivity Labels avec héritage automatique"}},{"key":"B","text":{"pt-br":"Data Loss Prevention policies","en-us":"Data Loss Prevention policies","es":"Data Loss Prevention policies","fr":"Data Loss Prevention policies"}},{"key":"C","text":{"pt-br":"Microsoft Defender for Cloud Apps","en-us":"Microsoft Defender for Cloud Apps","es":"Microsoft Defender for Cloud Apps","fr":"Microsoft Defender for Cloud Apps"}},{"key":"D","text":{"pt-br":"Azure Information Protection","en-us":"Azure Information Protection","es":"Azure Information Protection","fr":"Azure Information Protection"}}]', 'A', '{"pt-br":"Sensitivity Labels com herança automática garantem que quando dados são exportados do Power BI para Excel, a classificação de segurança é mantida automaticamente no arquivo exportado.","en-us":"Sensitivity Labels with automatic inheritance ensure that when data is exported from Power BI to Excel, the security classification is automatically maintained in the exported file.","es":"Las Sensitivity Labels con herencia automática garantizan que al exportar datos de Power BI a Excel, la clasificación de seguridad se mantiene automáticamente en el archivo exportado.","fr":"Les Sensitivity Labels avec héritage automatique garantissent que lors de l''exportation depuis Power BI vers Excel, la classification de sécurité est automatiquement maintenue dans le fichier exporté."}'),
('Segurança e Governança', '{"pt-br":"Sua empresa precisa monitorar quem acessou quais relatórios e datasets no Power BI nos últimos 30 dias para fins de auditoria.","en-us":"Your company needs to monitor who accessed which reports and datasets in Power BI in the last 30 days for auditing purposes.","es":"Su empresa necesita monitorear quién accedió a qué informes y datasets en Power BI en los últimos 30 días para fines de auditoría.","fr":"Votre entreprise doit surveiller qui a accédé à quels rapports et datasets dans Power BI au cours des 30 derniers jours à des fins d''audit."}', '{"pt-br":"Qual ferramenta deve ser utilizada?","en-us":"Which tool should be used?","es":"¿Qué herramienta debe utilizarse?","fr":"Quel outil doit être utilisé ?"}', '[{"key":"A","text":{"pt-br":"Power BI Activity Log via Admin Portal","en-us":"Power BI Activity Log via Admin Portal","es":"Power BI Activity Log via Admin Portal","fr":"Power BI Activity Log via Admin Portal"}},{"key":"B","text":{"pt-br":"Azure Monitor","en-us":"Azure Monitor","es":"Azure Monitor","fr":"Azure Monitor"}},{"key":"C","text":{"pt-br":"Microsoft 365 Compliance Center","en-us":"Microsoft 365 Compliance Center","es":"Microsoft 365 Compliance Center","fr":"Microsoft 365 Compliance Center"}},{"key":"D","text":{"pt-br":"Power BI Usage Metrics","en-us":"Power BI Usage Metrics","es":"Power BI Usage Metrics","fr":"Power BI Usage Metrics"}}]', 'A', '{"pt-br":"O Activity Log no Admin Portal fornece registros detalhados de atividades dos usuários, incluindo acessos a relatórios e datasets, podendo ser consultado via REST API ou PowerShell.","en-us":"The Activity Log in Admin Portal provides detailed user activity records, including report and dataset access, and can be queried via REST API or PowerShell.","es":"El Activity Log en el Admin Portal proporciona registros detallados de actividades de usuarios, incluyendo accesos a informes y datasets, pudiendo consultarse via REST API o PowerShell.","fr":"L''Activity Log dans le Admin Portal fournit des enregistrements détaillés d''activité utilisateur, y compris l''accès aux rapports et datasets, consultable via REST API ou PowerShell."}'),
('Segurança e Governança', '{"pt-br":"Você precisa implementar RLS dinâmico onde o filtro é baseado no email do usuário logado, sem criar um role para cada usuário individualmente.","en-us":"You need to implement dynamic RLS where the filter is based on the logged-in user''s email, without creating a role for each individual user.","es":"Necesita implementar RLS dinámico donde el filtro se basa en el email del usuario conectado, sin crear un role para cada usuario individualmente.","fr":"Vous devez implémenter un RLS dynamique où le filtre est basé sur l''email de l''utilisateur connecté, sans créer un rôle pour chaque utilisateur."}', '{"pt-br":"Qual função DAX deve ser usada na expressão de filtro RLS?","en-us":"Which DAX function should be used in the RLS filter expression?","es":"¿Qué función DAX debe usarse en la expresión de filtro RLS?","fr":"Quelle fonction DAX doit être utilisée dans l''expression de filtre RLS ?"}', '[{"key":"A","text":{"pt-br":"USERNAME()","en-us":"USERNAME()","es":"USERNAME()","fr":"USERNAME()"}},{"key":"B","text":{"pt-br":"USERPRINCIPALNAME()","en-us":"USERPRINCIPALNAME()","es":"USERPRINCIPALNAME()","fr":"USERPRINCIPALNAME()"}},{"key":"C","text":{"pt-br":"LOOKUPVALUE()","en-us":"LOOKUPVALUE()","es":"LOOKUPVALUE()","fr":"LOOKUPVALUE()"}},{"key":"D","text":{"pt-br":"SELECTEDVALUE()","en-us":"SELECTEDVALUE()","es":"SELECTEDVALUE()","fr":"SELECTEDVALUE()"}}]', 'B', '{"pt-br":"USERPRINCIPALNAME() retorna o email (UPN) do usuário autenticado no Power BI Service, permitindo RLS dinâmico comparando com uma tabela de mapeamento de usuários-regiões.","en-us":"USERPRINCIPALNAME() returns the email (UPN) of the authenticated user in Power BI Service, enabling dynamic RLS by comparing with a user-region mapping table.","es":"USERPRINCIPALNAME() retorna el email (UPN) del usuario autenticado en Power BI Service, permitiendo RLS dinámico comparando con una tabla de mapeo usuarios-regiones.","fr":"USERPRINCIPALNAME() retourne l''email (UPN) de l''utilisateur authentifié dans Power BI Service, permettant un RLS dynamique en comparant avec une table de correspondance utilisateurs-régions."}'),
('Segurança e Governança', '{"pt-br":"Uma organização quer impedir que usuários do Power BI exportem dados para CSV ou Excel a partir de relatórios publicados.","en-us":"An organization wants to prevent Power BI users from exporting data to CSV or Excel from published reports.","es":"Una organización quiere impedir que los usuarios de Power BI exporten datos a CSV o Excel desde informes publicados.","fr":"Une organisation veut empêcher les utilisateurs Power BI d''exporter des données en CSV ou Excel depuis les rapports publiés."}', '{"pt-br":"Onde essa restrição deve ser configurada?","en-us":"Where should this restriction be configured?","es":"¿Dónde debe configurarse esta restricción?","fr":"Où cette restriction doit-elle être configurée ?"}', '[{"key":"A","text":{"pt-br":"Tenant Settings no Admin Portal","en-us":"Tenant Settings in Admin Portal","es":"Tenant Settings en Admin Portal","fr":"Tenant Settings dans le Admin Portal"}},{"key":"B","text":{"pt-br":"Workspace Settings","en-us":"Workspace Settings","es":"Workspace Settings","fr":"Workspace Settings"}},{"key":"C","text":{"pt-br":"Dataset Settings","en-us":"Dataset Settings","es":"Dataset Settings","fr":"Dataset Settings"}},{"key":"D","text":{"pt-br":"Report Settings","en-us":"Report Settings","es":"Report Settings","fr":"Report Settings"}}]', 'A', '{"pt-br":"As configurações de exportação são controladas via Tenant Settings no Admin Portal, onde o administrador pode habilitar ou desabilitar a exportação de dados para grupos de segurança específicos.","en-us":"Export settings are controlled via Tenant Settings in the Admin Portal, where the administrator can enable or disable data export for specific security groups.","es":"Las configuraciones de exportación se controlan via Tenant Settings en el Admin Portal, donde el administrador puede habilitar o deshabilitar la exportación para grupos de seguridad específicos.","fr":"Les paramètres d''exportation sont contrôlés via Tenant Settings dans le Admin Portal, où l''administrateur peut activer ou désactiver l''exportation pour des groupes de sécurité spécifiques."}'),
('Segurança e Governança', '{"pt-br":"Você precisa garantir que um dataset certificado no Fabric seja facilmente descoberto por toda a organização como uma fonte confiável.","en-us":"You need to ensure a certified dataset in Fabric is easily discoverable by the entire organization as a trusted source.","es":"Necesita garantizar que un dataset certificado en Fabric sea fácilmente descubierto por toda la organización como fuente confiable.","fr":"Vous devez garantir qu''un dataset certifié dans Fabric soit facilement découvrable par toute l''organisation comme source fiable."}', '{"pt-br":"Qual recurso de governança deve ser aplicado?","en-us":"Which governance feature should be applied?","es":"¿Qué recurso de gobernanza debe aplicarse?","fr":"Quelle fonctionnalité de gouvernance doit être appliquée ?"}', '[{"key":"A","text":{"pt-br":"Endorsement - Certified","en-us":"Endorsement - Certified","es":"Endorsement - Certified","fr":"Endorsement - Certified"}},{"key":"B","text":{"pt-br":"Endorsement - Promoted","en-us":"Endorsement - Promoted","es":"Endorsement - Promoted","fr":"Endorsement - Promoted"}},{"key":"C","text":{"pt-br":"Data Catalog tagging","en-us":"Data Catalog tagging","es":"Data Catalog tagging","fr":"Data Catalog tagging"}},{"key":"D","text":{"pt-br":"Lineage view","en-us":"Lineage view","es":"Lineage view","fr":"Lineage view"}}]', 'A', '{"pt-br":"Endorsement - Certified marca datasets como fontes oficiais e confiáveis da organização. Apenas admins podem certificar. Promoted é um nível inferior indicando que o conteúdo é útil mas não oficialmente validado.","en-us":"Endorsement - Certified marks datasets as official, trusted organizational sources. Only admins can certify. Promoted is a lower level indicating content is useful but not officially validated.","es":"Endorsement - Certified marca datasets como fuentes oficiales y confiables de la organización. Solo admins pueden certificar. Promoted es un nivel inferior indicando que el contenido es útil pero no validado oficialmente.","fr":"Endorsement - Certified marque les datasets comme sources officielles et fiables. Seuls les admins peuvent certifier. Promoted est un niveau inférieur indiquant que le contenu est utile mais pas officiellement validé."}'),
('Segurança e Governança', '{"pt-br":"Você precisa configurar um workspace para que as alterações feitas nele não afetem o ambiente de produção até serem promovidas explicitamente.","en-us":"You need to configure a workspace so changes made in it don''t affect the production environment until explicitly promoted.","es":"Necesita configurar un workspace para que los cambios hechos en él no afecten el ambiente de producción hasta ser promovidos explícitamente.","fr":"Vous devez configurer un workspace pour que les modifications n''affectent pas l''environnement de production jusqu''à promotion explicite."}', '{"pt-br":"Qual recurso do Fabric deve ser utilizado?","en-us":"Which Fabric feature should be used?","es":"¿Qué recurso de Fabric debe utilizarse?","fr":"Quelle fonctionnalité de Fabric doit être utilisée ?"}', '[{"key":"A","text":{"pt-br":"Deployment Pipelines","en-us":"Deployment Pipelines","es":"Deployment Pipelines","fr":"Deployment Pipelines"}},{"key":"B","text":{"pt-br":"Git Integration","en-us":"Git Integration","es":"Git Integration","fr":"Git Integration"}},{"key":"C","text":{"pt-br":"Workspace Backup","en-us":"Workspace Backup","es":"Workspace Backup","fr":"Workspace Backup"}},{"key":"D","text":{"pt-br":"Snapshot Recovery","en-us":"Snapshot Recovery","es":"Snapshot Recovery","fr":"Snapshot Recovery"}}]', 'A', '{"pt-br":"Deployment Pipelines permitem criar estágios (Dev, Test, Prod) para promover conteúdo de forma controlada, garantindo que produção só receba alterações validadas.","en-us":"Deployment Pipelines allow creating stages (Dev, Test, Prod) to promote content in a controlled way, ensuring production only receives validated changes.","es":"Deployment Pipelines permiten crear etapas (Dev, Test, Prod) para promover contenido de forma controlada, garantizando que producción solo reciba cambios validados.","fr":"Les Deployment Pipelines permettent de créer des étapes (Dev, Test, Prod) pour promouvoir le contenu de manière contrôlée, garantissant que la production ne reçoit que les modifications validées."}'),
('Segurança e Governança', '{"pt-br":"Sua organização requer que os dados no OneLake sejam criptografados em repouso usando chaves gerenciadas pelo cliente (CMK).","en-us":"Your organization requires data in OneLake to be encrypted at rest using customer-managed keys (CMK).","es":"Su organización requiere que los datos en OneLake sean cifrados en reposo usando claves administradas por el cliente (CMK).","fr":"Votre organisation exige que les données dans OneLake soient chiffrées au repos en utilisant des clés gérées par le client (CMK)."}', '{"pt-br":"Qual serviço deve ser usado para gerenciar as chaves?","en-us":"Which service should be used to manage the keys?","es":"¿Qué servicio debe usarse para administrar las claves?","fr":"Quel service doit être utilisé pour gérer les clés ?"}', '[{"key":"A","text":{"pt-br":"Azure Key Vault","en-us":"Azure Key Vault","es":"Azure Key Vault","fr":"Azure Key Vault"}},{"key":"B","text":{"pt-br":"Microsoft Purview","en-us":"Microsoft Purview","es":"Microsoft Purview","fr":"Microsoft Purview"}},{"key":"C","text":{"pt-br":"Azure Active Directory","en-us":"Azure Active Directory","es":"Azure Active Directory","fr":"Azure Active Directory"}},{"key":"D","text":{"pt-br":"Power BI Admin Portal","en-us":"Power BI Admin Portal","es":"Power BI Admin Portal","fr":"Power BI Admin Portal"}}]', 'A', '{"pt-br":"Azure Key Vault é o serviço padrão para gerenciar chaves de criptografia gerenciadas pelo cliente (CMK). Integra-se com o Fabric para criptografia de dados em repouso.","en-us":"Azure Key Vault is the standard service for managing customer-managed encryption keys (CMK). It integrates with Fabric for data-at-rest encryption.","es":"Azure Key Vault es el servicio estándar para administrar claves de cifrado del cliente (CMK). Se integra con Fabric para cifrado de datos en reposo.","fr":"Azure Key Vault est le service standard pour gérer les clés de chiffrement client (CMK). Il s''intègre avec Fabric pour le chiffrement des données au repos."}'),
('Segurança e Governança', '{"pt-br":"Você precisa impedir que workspaces do Fabric sejam criados por qualquer usuário da organização, limitando isso apenas aos administradores.","en-us":"You need to prevent Fabric workspaces from being created by any user, limiting it to administrators only.","es":"Necesita impedir que los workspaces de Fabric sean creados por cualquier usuario, limitándolo solo a administradores.","fr":"Vous devez empêcher la création de workspaces Fabric par n''importe quel utilisateur, en la limitant aux administrateurs."}', '{"pt-br":"Onde essa configuração deve ser feita?","en-us":"Where should this setting be configured?","es":"¿Dónde debe hacerse esta configuración?","fr":"Où ce paramètre doit-il être configuré ?"}', '[{"key":"A","text":{"pt-br":"Tenant Settings - Workspace creation","en-us":"Tenant Settings - Workspace creation","es":"Tenant Settings - Workspace creation","fr":"Tenant Settings - Workspace creation"}},{"key":"B","text":{"pt-br":"Microsoft 365 Admin Center","en-us":"Microsoft 365 Admin Center","es":"Microsoft 365 Admin Center","fr":"Microsoft 365 Admin Center"}},{"key":"C","text":{"pt-br":"Azure Portal - Resource Groups","en-us":"Azure Portal - Resource Groups","es":"Azure Portal - Resource Groups","fr":"Azure Portal - Resource Groups"}},{"key":"D","text":{"pt-br":"Capacity Settings","en-us":"Capacity Settings","es":"Capacity Settings","fr":"Capacity Settings"}}]', 'A', '{"pt-br":"Tenant Settings no Admin Portal permite configurar quem pode criar workspaces, podendo restringir para grupos de segurança específicos ou apenas administradores.","en-us":"Tenant Settings in the Admin Portal allows configuring who can create workspaces, restricting it to specific security groups or administrators only.","es":"Tenant Settings en el Admin Portal permite configurar quién puede crear workspaces, restringiéndolo a grupos de seguridad específicos o solo administradores.","fr":"Tenant Settings dans le Admin Portal permet de configurer qui peut créer des workspaces, en les restreignant à des groupes de sécurité spécifiques ou aux administrateurs uniquement."}'),
('Segurança e Governança', '{"pt-br":"Você precisa rastrear a linhagem de dados desde a fonte no Lakehouse até o relatório final do Power BI para garantir a rastreabilidade.","en-us":"You need to track data lineage from the Lakehouse source to the final Power BI report to ensure traceability.","es":"Necesita rastrear el linaje de datos desde la fuente en el Lakehouse hasta el informe final de Power BI para garantizar la trazabilidad.","fr":"Vous devez suivre la lignée des données depuis la source Lakehouse jusqu''au rapport Power BI final pour garantir la traçabilité."}', '{"pt-br":"Qual recurso do Fabric fornece essa visão?","en-us":"Which Fabric feature provides this view?","es":"¿Qué recurso de Fabric proporciona esta vista?","fr":"Quelle fonctionnalité de Fabric fournit cette vue ?"}', '[{"key":"A","text":{"pt-br":"Lineage View","en-us":"Lineage View","es":"Lineage View","fr":"Lineage View"}},{"key":"B","text":{"pt-br":"Impact Analysis","en-us":"Impact Analysis","es":"Impact Analysis","fr":"Impact Analysis"}},{"key":"C","text":{"pt-br":"Data Catalog","en-us":"Data Catalog","es":"Data Catalog","fr":"Data Catalog"}},{"key":"D","text":{"pt-br":"Monitoring Hub","en-us":"Monitoring Hub","es":"Monitoring Hub","fr":"Monitoring Hub"}}]', 'A', '{"pt-br":"Lineage View mostra visualmente o fluxo de dados de ponta a ponta, desde fontes até relatórios. Impact Analysis mostra o impacto de mudanças em um item. Data Catalog lista metadados.","en-us":"Lineage View visually shows the end-to-end data flow from sources to reports. Impact Analysis shows the impact of changes on an item. Data Catalog lists metadata.","es":"Lineage View muestra visualmente el flujo de datos de extremo a extremo, desde fuentes hasta informes. Impact Analysis muestra el impacto de cambios. Data Catalog lista metadatos.","fr":"Lineage View montre visuellement le flux de données de bout en bout, des sources aux rapports. Impact Analysis montre l''impact des modifications. Data Catalog liste les métadonnées."}'),
('Ciclo de Vida', '{"pt-br":"Sua equipe precisa versionar os artefatos do Fabric usando um repositório Git para controle de mudanças e colaboração.","en-us":"Your team needs to version Fabric artifacts using a Git repository for change control and collaboration.","es":"Su equipo necesita versionar los artefactos de Fabric usando un repositorio Git para control de cambios y colaboración.","fr":"Votre équipe doit versionner les artefacts Fabric en utilisant un dépôt Git pour le contrôle des modifications et la collaboration."}', '{"pt-br":"Qual serviço de repositório é suportado nativamente pelo Fabric?","en-us":"Which repository service is natively supported by Fabric?","es":"¿Qué servicio de repositorio es soportado nativamente por Fabric?","fr":"Quel service de dépôt est nativement supporté par Fabric ?"}', '[{"key":"A","text":{"pt-br":"Azure DevOps e GitHub","en-us":"Azure DevOps and GitHub","es":"Azure DevOps y GitHub","fr":"Azure DevOps et GitHub"}},{"key":"B","text":{"pt-br":"Apenas GitHub","en-us":"GitHub only","es":"Solo GitHub","fr":"GitHub uniquement"}},{"key":"C","text":{"pt-br":"Apenas Azure DevOps","en-us":"Azure DevOps only","es":"Solo Azure DevOps","fr":"Azure DevOps uniquement"}},{"key":"D","text":{"pt-br":"GitLab e Bitbucket","en-us":"GitLab and Bitbucket","es":"GitLab y Bitbucket","fr":"GitLab et Bitbucket"}}]', 'A', '{"pt-br":"O Microsoft Fabric suporta nativamente integração com Azure DevOps e GitHub para versionamento de artefatos via Git Integration.","en-us":"Microsoft Fabric natively supports integration with Azure DevOps and GitHub for artifact versioning via Git Integration.","es":"Microsoft Fabric soporta nativamente integración con Azure DevOps y GitHub para versionamiento de artefactos via Git Integration.","fr":"Microsoft Fabric supporte nativement l''intégration avec Azure DevOps et GitHub pour le versionnement des artefacts via Git Integration."}'),
('Ciclo de Vida', '{"pt-br":"Você precisa promover artefatos de um workspace de desenvolvimento para produção de forma controlada e auditável.","en-us":"You need to promote artifacts from a development workspace to production in a controlled and auditable way.","es":"Necesita promover artefactos de un workspace de desarrollo a producción de forma controlada y auditable.","fr":"Vous devez promouvoir les artefacts d''un workspace de développement vers la production de manière contrôlée et auditable."}', '{"pt-br":"Quantos estágios um Deployment Pipeline pode ter?","en-us":"How many stages can a Deployment Pipeline have?","es":"¿Cuántas etapas puede tener un Deployment Pipeline?","fr":"Combien d''étapes un Deployment Pipeline peut-il avoir ?"}', '[{"key":"A","text":{"pt-br":"2 estágios","en-us":"2 stages","es":"2 etapas","fr":"2 étapes"}},{"key":"B","text":{"pt-br":"3 estágios","en-us":"3 stages","es":"3 etapas","fr":"3 étapes"}},{"key":"C","text":{"pt-br":"Até 10 estágios","en-us":"Up to 10 stages","es":"Hasta 10 etapas","fr":"Jusqu''à 10 étapes"}},{"key":"D","text":{"pt-br":"Ilimitado","en-us":"Unlimited","es":"Ilimitado","fr":"Illimité"}}]', 'C', '{"pt-br":"Deployment Pipelines no Fabric suportam até 10 estágios customizáveis, permitindo fluxos como Dev > QA > Staging > Prod ou configurações mais complexas.","en-us":"Deployment Pipelines in Fabric support up to 10 customizable stages, allowing flows like Dev > QA > Staging > Prod or more complex configurations.","es":"Los Deployment Pipelines en Fabric soportan hasta 10 etapas personalizables, permitiendo flujos como Dev > QA > Staging > Prod o configuraciones más complejas.","fr":"Les Deployment Pipelines dans Fabric supportent jusqu''à 10 étapes personnalisables, permettant des flux comme Dev > QA > Staging > Prod ou des configurations plus complexes."}'),
('Ciclo de Vida', '{"pt-br":"Após conectar um workspace ao Git, você fez alterações locais no workspace. Precisa salvar essas mudanças no repositório.","en-us":"After connecting a workspace to Git, you made local changes in the workspace. You need to save these changes to the repository.","es":"Después de conectar un workspace a Git, hizo cambios locales en el workspace. Necesita guardar estos cambios en el repositorio.","fr":"Après avoir connecté un workspace à Git, vous avez fait des modifications locales. Vous devez sauvegarder ces modifications dans le dépôt."}', '{"pt-br":"Qual ação deve ser realizada?","en-us":"Which action should be performed?","es":"¿Qué acción debe realizarse?","fr":"Quelle action doit être effectuée ?"}', '[{"key":"A","text":{"pt-br":"Commit to Git","en-us":"Commit to Git","es":"Commit to Git","fr":"Commit to Git"}},{"key":"B","text":{"pt-br":"Update from Git","en-us":"Update from Git","es":"Update from Git","fr":"Update from Git"}},{"key":"C","text":{"pt-br":"Deploy to next stage","en-us":"Deploy to next stage","es":"Deploy to next stage","fr":"Deploy to next stage"}},{"key":"D","text":{"pt-br":"Sync workspace","en-us":"Sync workspace","es":"Sync workspace","fr":"Sync workspace"}}]', 'A', '{"pt-br":"Commit to Git salva as alterações feitas no workspace para o repositório Git. Update from Git faz o inverso, trazendo mudanças do repositório para o workspace.","en-us":"Commit to Git saves workspace changes to the Git repository. Update from Git does the reverse, bringing repository changes to the workspace.","es":"Commit to Git guarda los cambios del workspace en el repositorio Git. Update from Git hace lo inverso, trayendo cambios del repositorio al workspace.","fr":"Commit to Git sauvegarde les modifications du workspace vers le dépôt Git. Update from Git fait l''inverse, ramenant les modifications du dépôt vers le workspace."}'),
('Ciclo de Vida', '{"pt-br":"Você precisa automatizar o deployment de artefatos entre estágios do pipeline usando scripts, sem intervenção manual no portal.","en-us":"You need to automate artifact deployment between pipeline stages using scripts, without manual portal intervention.","es":"Necesita automatizar el despliegue de artefactos entre etapas del pipeline usando scripts, sin intervención manual en el portal.","fr":"Vous devez automatiser le déploiement des artefacts entre les étapes du pipeline à l''aide de scripts, sans intervention manuelle dans le portail."}', '{"pt-br":"Qual API deve ser utilizada?","en-us":"Which API should be used?","es":"¿Qué API debe utilizarse?","fr":"Quelle API doit être utilisée ?"}', '[{"key":"A","text":{"pt-br":"Fabric REST API - Deployment Pipelines","en-us":"Fabric REST API - Deployment Pipelines","es":"Fabric REST API - Deployment Pipelines","fr":"Fabric REST API - Deployment Pipelines"}},{"key":"B","text":{"pt-br":"Power BI Embedded API","en-us":"Power BI Embedded API","es":"Power BI Embedded API","fr":"Power BI Embedded API"}},{"key":"C","text":{"pt-br":"Azure Resource Manager API","en-us":"Azure Resource Manager API","es":"Azure Resource Manager API","fr":"Azure Resource Manager API"}},{"key":"D","text":{"pt-br":"Microsoft Graph API","en-us":"Microsoft Graph API","es":"Microsoft Graph API","fr":"Microsoft Graph API"}}]', 'A', '{"pt-br":"A Fabric REST API para Deployment Pipelines permite automatizar operações de deploy, comparação entre estágios e promoção de artefatos programaticamente.","en-us":"The Fabric REST API for Deployment Pipelines allows automating deploy operations, stage comparison, and artifact promotion programmatically.","es":"La Fabric REST API para Deployment Pipelines permite automatizar operaciones de deploy, comparación entre etapas y promoción de artefactos programáticamente.","fr":"L''API REST Fabric pour Deployment Pipelines permet d''automatiser les opérations de déploiement, la comparaison entre étapes et la promotion des artefacts de manière programmatique."}'),
('Ciclo de Vida', '{"pt-br":"Ao promover um relatório do estágio de Dev para Test no Deployment Pipeline, você precisa que a conexão do dataset mude automaticamente para o banco de dados de teste.","en-us":"When promoting a report from Dev to Test stage in the Deployment Pipeline, you need the dataset connection to automatically switch to the test database.","es":"Al promover un informe de Dev a Test en el Deployment Pipeline, necesita que la conexión del dataset cambie automáticamente a la base de datos de prueba.","fr":"Lors de la promotion d''un rapport de Dev à Test dans le Deployment Pipeline, vous devez que la connexion du dataset bascule automatiquement vers la base de données de test."}', '{"pt-br":"Qual recurso do Deployment Pipeline permite isso?","en-us":"Which Deployment Pipeline feature allows this?","es":"¿Qué recurso del Deployment Pipeline permite esto?","fr":"Quelle fonctionnalité du Deployment Pipeline permet cela ?"}', '[{"key":"A","text":{"pt-br":"Deployment Rules","en-us":"Deployment Rules","es":"Deployment Rules","fr":"Deployment Rules"}},{"key":"B","text":{"pt-br":"Parameter Binding","en-us":"Parameter Binding","es":"Parameter Binding","fr":"Parameter Binding"}},{"key":"C","text":{"pt-br":"Auto-Refresh Settings","en-us":"Auto-Refresh Settings","es":"Auto-Refresh Settings","fr":"Auto-Refresh Settings"}},{"key":"D","text":{"pt-br":"Connection Override","en-us":"Connection Override","es":"Connection Override","fr":"Connection Override"}}]', 'A', '{"pt-br":"Deployment Rules permitem definir regras que alteram automaticamente parâmetros como data source, connection strings e parâmetros ao promover entre estágios.","en-us":"Deployment Rules allow defining rules that automatically change parameters like data source, connection strings, and parameters when promoting between stages.","es":"Las Deployment Rules permiten definir reglas que cambian automáticamente parámetros como data source, connection strings y parámetros al promover entre etapas.","fr":"Les Deployment Rules permettent de définir des règles qui modifient automatiquement les paramètres comme la source de données, les chaînes de connexion lors de la promotion entre étapes."}'),
('Ciclo de Vida', '{"pt-br":"Você precisa monitorar o status de refresh de todos os datasets em um workspace e receber alertas quando um refresh falhar.","en-us":"You need to monitor the refresh status of all datasets in a workspace and receive alerts when a refresh fails.","es":"Necesita monitorear el estado de actualización de todos los datasets en un workspace y recibir alertas cuando falle una actualización.","fr":"Vous devez surveiller l''état de rafraîchissement de tous les datasets dans un workspace et recevoir des alertes en cas d''échec."}', '{"pt-br":"Qual recurso do Fabric oferece essa funcionalidade?","en-us":"Which Fabric feature offers this functionality?","es":"¿Qué recurso de Fabric ofrece esta funcionalidad?","fr":"Quelle fonctionnalité de Fabric offre cette fonctionnalité ?"}', '[{"key":"A","text":{"pt-br":"Monitoring Hub","en-us":"Monitoring Hub","es":"Monitoring Hub","fr":"Monitoring Hub"}},{"key":"B","text":{"pt-br":"Azure Monitor","en-us":"Azure Monitor","es":"Azure Monitor","fr":"Azure Monitor"}},{"key":"C","text":{"pt-br":"Power Automate","en-us":"Power Automate","es":"Power Automate","fr":"Power Automate"}},{"key":"D","text":{"pt-br":"Capacity Metrics App","en-us":"Capacity Metrics App","es":"Capacity Metrics App","fr":"Capacity Metrics App"}}]', 'A', '{"pt-br":"O Monitoring Hub no Fabric fornece uma visão centralizada de todas as atividades em andamento e recentes, incluindo status de refresh de datasets, com capacidade de filtrar e monitorar falhas.","en-us":"The Monitoring Hub in Fabric provides a centralized view of all ongoing and recent activities, including dataset refresh status, with ability to filter and monitor failures.","es":"El Monitoring Hub en Fabric proporciona una vista centralizada de todas las actividades en curso y recientes, incluyendo estado de actualización de datasets, con capacidad de filtrar y monitorear fallos.","fr":"Le Monitoring Hub dans Fabric fournit une vue centralisée de toutes les activités en cours et récentes, y compris l''état de rafraîchissement des datasets, avec la possibilité de filtrer et surveiller les échecs."}'),
('Ciclo de Vida', '{"pt-br":"Após uma atualização de relatório que causou problemas, você precisa reverter para a versão anterior do workspace.","en-us":"After a report update that caused issues, you need to revert to the previous workspace version.","es":"Después de una actualización de informe que causó problemas, necesita revertir a la versión anterior del workspace.","fr":"Après une mise à jour de rapport ayant causé des problèmes, vous devez revenir à la version précédente du workspace."}', '{"pt-br":"Qual a melhor abordagem usando Git Integration?","en-us":"What is the best approach using Git Integration?","es":"¿Cuál es el mejor enfoque usando Git Integration?","fr":"Quelle est la meilleure approche avec Git Integration ?"}', '[{"key":"A","text":{"pt-br":"Reverter o commit no Git e fazer Update from Git","en-us":"Revert the commit in Git and Update from Git","es":"Revertir el commit en Git y hacer Update from Git","fr":"Reverter le commit dans Git et faire Update from Git"}},{"key":"B","text":{"pt-br":"Recriar o workspace manualmente","en-us":"Recreate the workspace manually","es":"Recrear el workspace manualmente","fr":"Recréer le workspace manuellement"}},{"key":"C","text":{"pt-br":"Usar Deployment Pipeline para fazer rollback","en-us":"Use Deployment Pipeline for rollback","es":"Usar Deployment Pipeline para hacer rollback","fr":"Utiliser Deployment Pipeline pour le rollback"}},{"key":"D","text":{"pt-br":"Restaurar de um backup automático","en-us":"Restore from automatic backup","es":"Restaurar desde un backup automático","fr":"Restaurer à partir d''une sauvegarde automatique"}}]', 'A', '{"pt-br":"Com Git Integration, você pode reverter commits no repositório Git e usar ''Update from Git'' para sincronizar o workspace com a versão anterior, proporcionando rollback controlado.","en-us":"With Git Integration, you can revert commits in the Git repository and use ''Update from Git'' to sync the workspace with the previous version, providing controlled rollback.","es":"Con Git Integration, puede revertir commits en el repositorio Git y usar ''Update from Git'' para sincronizar el workspace con la versión anterior, proporcionando rollback controlado.","fr":"Avec Git Integration, vous pouvez reverter les commits dans le dépôt Git et utiliser ''Update from Git'' pour synchroniser le workspace avec la version précédente, offrant un rollback contrôlé."}'),
('Ciclo de Vida', '{"pt-br":"Você precisa configurar um refresh agendado para um dataset semântico que é atualizado diariamente às 6h da manhã.","en-us":"You need to configure a scheduled refresh for a semantic dataset that is updated daily at 6 AM.","es":"Necesita configurar una actualización programada para un dataset semántico que se actualiza diariamente a las 6 AM.","fr":"Vous devez configurer un rafraîchissement programmé pour un dataset sémantique mis à jour quotidiennement à 6h du matin."}', '{"pt-br":"Quantos refreshes por dia são permitidos em um workspace com capacidade Premium?","en-us":"How many refreshes per day are allowed in a workspace with Premium capacity?","es":"¿Cuántas actualizaciones por día se permiten en un workspace con capacidad Premium?","fr":"Combien de rafraîchissements par jour sont autorisés dans un workspace avec capacité Premium ?"}', '[{"key":"A","text":{"pt-br":"8 por dia","en-us":"8 per day","es":"8 por día","fr":"8 par jour"}},{"key":"B","text":{"pt-br":"48 por dia","en-us":"48 per day","es":"48 por día","fr":"48 par jour"}},{"key":"C","text":{"pt-br":"24 por dia","en-us":"24 per day","es":"24 por día","fr":"24 par jour"}},{"key":"D","text":{"pt-br":"Ilimitado","en-us":"Unlimited","es":"Ilimitado","fr":"Illimité"}}]', 'B', '{"pt-br":"Com capacidade Premium/Fabric, datasets podem ser atualizados até 48 vezes por dia (a cada 30 minutos). Em capacidade compartilhada (Pro), o limite é 8 por dia.","en-us":"With Premium/Fabric capacity, datasets can be refreshed up to 48 times per day (every 30 minutes). In shared capacity (Pro), the limit is 8 per day.","es":"Con capacidad Premium/Fabric, los datasets pueden actualizarse hasta 48 veces por día (cada 30 minutos). En capacidad compartida (Pro), el límite es 8 por día.","fr":"Avec la capacité Premium/Fabric, les datasets peuvent être rafraîchis jusqu''à 48 fois par jour (toutes les 30 minutes). En capacité partagée (Pro), la limite est de 8 par jour."}'),
('Ciclo de Vida', '{"pt-br":"Você precisa verificar o consumo de recursos da capacidade Fabric para identificar gargalos de performance em refreshes e queries.","en-us":"You need to verify Fabric capacity resource consumption to identify performance bottlenecks in refreshes and queries.","es":"Necesita verificar el consumo de recursos de la capacidad Fabric para identificar cuellos de botella de rendimiento en actualizaciones y consultas.","fr":"Vous devez vérifier la consommation des ressources de la capacité Fabric pour identifier les goulots d''étranglement dans les rafraîchissements et requêtes."}', '{"pt-br":"Qual ferramenta fornece métricas detalhadas de uso da capacidade?","en-us":"Which tool provides detailed capacity usage metrics?","es":"¿Qué herramienta proporciona métricas detalladas de uso de capacidad?","fr":"Quel outil fournit des métriques détaillées d''utilisation de la capacité ?"}', '[{"key":"A","text":{"pt-br":"Microsoft Fabric Capacity Metrics App","en-us":"Microsoft Fabric Capacity Metrics App","es":"Microsoft Fabric Capacity Metrics App","fr":"Microsoft Fabric Capacity Metrics App"}},{"key":"B","text":{"pt-br":"Azure Cost Management","en-us":"Azure Cost Management","es":"Azure Cost Management","fr":"Azure Cost Management"}},{"key":"C","text":{"pt-br":"Power BI Usage Metrics","en-us":"Power BI Usage Metrics","es":"Power BI Usage Metrics","fr":"Power BI Usage Metrics"}},{"key":"D","text":{"pt-br":"Monitoring Hub","en-us":"Monitoring Hub","es":"Monitoring Hub","fr":"Monitoring Hub"}}]', 'A', '{"pt-br":"O Capacity Metrics App fornece métricas detalhadas de CU (Capacity Units), throttling, overload e consumo por workload, essencial para capacity planning.","en-us":"The Capacity Metrics App provides detailed CU (Capacity Units) metrics, throttling, overload, and consumption per workload, essential for capacity planning.","es":"El Capacity Metrics App proporciona métricas detalladas de CU (Capacity Units), throttling, overload y consumo por workload, esencial para capacity planning.","fr":"Le Capacity Metrics App fournit des métriques détaillées de CU (Capacity Units), throttling, surcharge et consommation par workload, essentiel pour la planification de capacité."}'),
('Ciclo de Vida', '{"pt-br":"Sua equipe de BI tem 5 desenvolvedores trabalhando simultaneamente em um mesmo workspace. Você precisa evitar conflitos entre suas alterações.","en-us":"Your BI team has 5 developers working simultaneously on the same workspace. You need to avoid conflicts between their changes.","es":"Su equipo de BI tiene 5 desarrolladores trabajando simultáneamente en un mismo workspace. Necesita evitar conflictos entre sus cambios.","fr":"Votre équipe BI a 5 développeurs travaillant simultanément sur le même workspace. Vous devez éviter les conflits entre leurs modifications."}', '{"pt-br":"Qual é a melhor prática recomendada?","en-us":"What is the recommended best practice?","es":"¿Cuál es la mejor práctica recomendada?","fr":"Quelle est la meilleure pratique recommandée ?"}', '[{"key":"A","text":{"pt-br":"Usar Git Integration com branches individuais","en-us":"Use Git Integration with individual branches","es":"Usar Git Integration con branches individuales","fr":"Utiliser Git Integration avec des branches individuelles"}},{"key":"B","text":{"pt-br":"Criar um workspace por desenvolvedor","en-us":"Create one workspace per developer","es":"Crear un workspace por desarrollador","fr":"Créer un workspace par développeur"}},{"key":"C","text":{"pt-br":"Usar controle de acesso por horário","en-us":"Use time-based access control","es":"Usar control de acceso por horario","fr":"Utiliser un contrôle d''accès par horaire"}},{"key":"D","text":{"pt-br":"Designar um único editor por artefato","en-us":"Designate a single editor per artifact","es":"Designar un único editor por artefacto","fr":"Désigner un seul éditeur par artefact"}}]', 'A', '{"pt-br":"Git Integration com branches permite que cada desenvolvedor trabalhe em sua própria branch, fazendo merge quando pronto, evitando conflitos e mantendo rastreabilidade completa.","en-us":"Git Integration with branches allows each developer to work in their own branch, merging when ready, avoiding conflicts and maintaining full traceability.","es":"Git Integration con branches permite que cada desarrollador trabaje en su propia branch, haciendo merge cuando esté listo, evitando conflictos y manteniendo trazabilidad completa.","fr":"Git Integration avec des branches permet à chaque développeur de travailler dans sa propre branche, fusionnant quand prêt, évitant les conflits et maintenant une traçabilité complète."}'),
('Ciclo de Vida', '{"pt-br":"Você precisa configurar alertas automáticos quando o consumo de CU da capacidade Fabric exceder 80% do limite.","en-us":"You need to configure automatic alerts when Fabric capacity CU consumption exceeds 80% of the limit.","es":"Necesita configurar alertas automáticas cuando el consumo de CU de la capacidad Fabric exceda el 80% del límite.","fr":"Vous devez configurer des alertes automatiques lorsque la consommation CU de la capacité Fabric dépasse 80% de la limite."}', '{"pt-br":"Qual recurso deve ser configurado?","en-us":"Which feature should be configured?","es":"¿Qué recurso debe configurarse?","fr":"Quelle fonctionnalité doit être configurée ?"}', '[{"key":"A","text":{"pt-br":"Capacity settings com notificações","en-us":"Capacity settings with notifications","es":"Capacity settings con notificaciones","fr":"Capacity settings avec notifications"}},{"key":"B","text":{"pt-br":"Azure Monitor alerts","en-us":"Azure Monitor alerts","es":"Azure Monitor alerts","fr":"Azure Monitor alerts"}},{"key":"C","text":{"pt-br":"Power Automate com Fabric connector","en-us":"Power Automate with Fabric connector","es":"Power Automate con Fabric connector","fr":"Power Automate avec Fabric connector"}},{"key":"D","text":{"pt-br":"Email subscriptions no Admin Portal","en-us":"Email subscriptions in Admin Portal","es":"Email subscriptions en Admin Portal","fr":"Email subscriptions dans Admin Portal"}}]', 'A', '{"pt-br":"As configurações de capacidade do Fabric permitem definir notificações automáticas quando o consumo atinge limites definidos, alertando os administradores sobre potenciais problemas de throttling.","en-us":"Fabric capacity settings allow defining automatic notifications when consumption reaches defined limits, alerting administrators about potential throttling issues.","es":"Las configuraciones de capacidad de Fabric permiten definir notificaciones automáticas cuando el consumo alcanza límites definidos, alertando administradores sobre potenciales problemas de throttling.","fr":"Les paramètres de capacité Fabric permettent de définir des notifications automatiques lorsque la consommation atteint les limites définies, alertant les administrateurs sur les problèmes potentiels de throttling."}'),
('Ciclo de Vida', '{"pt-br":"Você precisa documentar e implementar um processo de CI/CD para artefatos do Fabric usando Azure DevOps.","en-us":"You need to document and implement a CI/CD process for Fabric artifacts using Azure DevOps.","es":"Necesita documentar e implementar un proceso de CI/CD para artefactos de Fabric usando Azure DevOps.","fr":"Vous devez documenter et implémenter un processus CI/CD pour les artefacts Fabric en utilisant Azure DevOps."}', '{"pt-br":"Qual componente do Azure DevOps executa o deploy automatizado?","en-us":"Which Azure DevOps component executes the automated deploy?","es":"¿Qué componente de Azure DevOps ejecuta el deploy automatizado?","fr":"Quel composant d''Azure DevOps exécute le déploiement automatisé ?"}', '[{"key":"A","text":{"pt-br":"Azure Pipelines (Release Pipeline)","en-us":"Azure Pipelines (Release Pipeline)","es":"Azure Pipelines (Release Pipeline)","fr":"Azure Pipelines (Release Pipeline)"}},{"key":"B","text":{"pt-br":"Azure Repos","en-us":"Azure Repos","es":"Azure Repos","fr":"Azure Repos"}},{"key":"C","text":{"pt-br":"Azure Boards","en-us":"Azure Boards","es":"Azure Boards","fr":"Azure Boards"}},{"key":"D","text":{"pt-br":"Azure Artifacts","en-us":"Azure Artifacts","es":"Azure Artifacts","fr":"Azure Artifacts"}}]', 'A', '{"pt-br":"Azure Pipelines permite criar pipelines de release que chamam a Fabric REST API para automatizar deploys entre estágios, integrando com o Deployment Pipeline do Fabric.","en-us":"Azure Pipelines allows creating release pipelines that call the Fabric REST API to automate deploys between stages, integrating with Fabric''s Deployment Pipeline.","es":"Azure Pipelines permite crear pipelines de release que llaman a la Fabric REST API para automatizar deploys entre etapas, integrando con el Deployment Pipeline de Fabric.","fr":"Azure Pipelines permet de créer des pipelines de release appelant l''API REST Fabric pour automatiser les déploiements entre étapes, s''intégrant avec le Deployment Pipeline de Fabric."}'),
('Ciclo de Vida', '{"pt-br":"Você precisa garantir que alterações no dataset semântico sejam testadas antes de chegarem aos relatórios de produção.","en-us":"You need to ensure changes to the semantic dataset are tested before reaching production reports.","es":"Necesita garantizar que los cambios en el dataset semántico sean probados antes de llegar a los informes de producción.","fr":"Vous devez garantir que les modifications du dataset sémantique sont testées avant d''atteindre les rapports de production."}', '{"pt-br":"Qual estratégia de Deployment Pipeline é mais adequada?","en-us":"Which Deployment Pipeline strategy is most appropriate?","es":"¿Qué estrategia de Deployment Pipeline es más adecuada?","fr":"Quelle stratégie de Deployment Pipeline est la plus appropriée ?"}', '[{"key":"A","text":{"pt-br":"Dev → Test → Prod com validação em Test","en-us":"Dev → Test → Prod with validation in Test","es":"Dev → Test → Prod con validación en Test","fr":"Dev → Test → Prod avec validation en Test"}},{"key":"B","text":{"pt-br":"Dev → Prod direto","en-us":"Dev → Prod direct","es":"Dev → Prod directo","fr":"Dev → Prod direct"}},{"key":"C","text":{"pt-br":"Prod → Dev (rollback)","en-us":"Prod → Dev (rollback)","es":"Prod → Dev (rollback)","fr":"Prod → Dev (rollback)"}},{"key":"D","text":{"pt-br":"Test → Prod → Dev","en-us":"Test → Prod → Dev","es":"Test → Prod → Dev","fr":"Test → Prod → Dev"}}]', 'A', '{"pt-br":"O fluxo Dev → Test → Prod é a prática recomendada, permitindo validar alterações no ambiente de teste antes de promover para produção, minimizando riscos.","en-us":"The Dev → Test → Prod flow is the recommended practice, allowing changes to be validated in the test environment before promoting to production, minimizing risks.","es":"El flujo Dev → Test → Prod es la práctica recomendada, permitiendo validar cambios en el ambiente de prueba antes de promover a producción, minimizando riesgos.","fr":"Le flux Dev → Test → Prod est la pratique recommandée, permettant de valider les modifications dans l''environnement de test avant de promouvoir en production, minimisant les risques."}'),
('Ciclo de Vida', '{"pt-br":"Você precisa executar um refresh incremental em um dataset grande para reduzir o tempo de processamento e consumo de recursos.","en-us":"You need to execute an incremental refresh on a large dataset to reduce processing time and resource consumption.","es":"Necesita ejecutar una actualización incremental en un dataset grande para reducir el tiempo de procesamiento y consumo de recursos.","fr":"Vous devez exécuter un rafraîchissement incrémentiel sur un grand dataset pour réduire le temps de traitement et la consommation de ressources."}', '{"pt-br":"Qual é um pré-requisito para configurar o refresh incremental?","en-us":"What is a prerequisite for configuring incremental refresh?","es":"¿Cuál es un prerrequisito para configurar la actualización incremental?","fr":"Quel est un prérequis pour configurer le rafraîchissement incrémentiel ?"}', '[{"key":"A","text":{"pt-br":"A fonte de dados deve suportar query folding","en-us":"The data source must support query folding","es":"La fuente de datos debe soportar query folding","fr":"La source de données doit supporter le query folding"}},{"key":"B","text":{"pt-br":"O dataset deve estar em modo DirectQuery","en-us":"The dataset must be in DirectQuery mode","es":"El dataset debe estar en modo DirectQuery","fr":"Le dataset doit être en mode DirectQuery"}},{"key":"C","text":{"pt-br":"O workspace deve ter capacidade F64 ou superior","en-us":"The workspace must have F64 or higher capacity","es":"El workspace debe tener capacidad F64 o superior","fr":"Le workspace doit avoir une capacité F64 ou supérieure"}},{"key":"D","text":{"pt-br":"A tabela deve ter menos de 1 milhão de linhas","en-us":"The table must have fewer than 1 million rows","es":"La tabla debe tener menos de 1 millón de filas","fr":"La table doit avoir moins d''1 million de lignes"}}]', 'A', '{"pt-br":"Query folding é essencial para refresh incremental, pois permite que os filtros de data sejam traduzidos em queries nativas da fonte de dados, carregando apenas os dados novos ou modificados.","en-us":"Query folding is essential for incremental refresh, as it allows date filters to be translated into native data source queries, loading only new or modified data.","es":"Query folding es esencial para actualización incremental, ya que permite que los filtros de fecha se traduzcan en consultas nativas de la fuente de datos, cargando solo datos nuevos o modificados.","fr":"Le query folding est essentiel pour le rafraîchissement incrémentiel, car il permet de traduire les filtres de date en requêtes natives de la source de données, ne chargeant que les données nouvelles ou modifiées."}'),
('Ciclo de Vida', '{"pt-br":"Você precisa implementar um processo de disaster recovery para artefatos críticos do Fabric em caso de falha regional.","en-us":"You need to implement a disaster recovery process for critical Fabric artifacts in case of regional failure.","es":"Necesita implementar un proceso de recuperación ante desastres para artefactos críticos de Fabric en caso de falla regional.","fr":"Vous devez implémenter un processus de reprise après sinistre pour les artefacts critiques Fabric en cas de défaillance régionale."}', '{"pt-br":"Qual abordagem é recomendada?","en-us":"Which approach is recommended?","es":"¿Qué enfoque se recomienda?","fr":"Quelle approche est recommandée ?"}', '[{"key":"A","text":{"pt-br":"Usar Git Integration para manter cópia dos artefatos e Deployment Pipelines para restore","en-us":"Use Git Integration to keep artifact copies and Deployment Pipelines for restore","es":"Usar Git Integration para mantener copia de artefactos y Deployment Pipelines para restore","fr":"Utiliser Git Integration pour garder une copie des artefacts et Deployment Pipelines pour la restauration"}},{"key":"B","text":{"pt-br":"Confiar apenas no backup automático do Fabric","en-us":"Rely only on Fabric''s automatic backup","es":"Confiar solo en el backup automático de Fabric","fr":"Se fier uniquement à la sauvegarde automatique de Fabric"}},{"key":"C","text":{"pt-br":"Exportar PBIX manualmente toda semana","en-us":"Export PBIX manually every week","es":"Exportar PBIX manualmente cada semana","fr":"Exporter PBIX manuellement chaque semaine"}},{"key":"D","text":{"pt-br":"Criar snapshots manuais do workspace","en-us":"Create manual workspace snapshots","es":"Crear snapshots manuales del workspace","fr":"Créer des snapshots manuels du workspace"}}]', 'A', '{"pt-br":"Git Integration garante que todos os artefatos estejam versionados externamente. Combinado com Deployment Pipelines, permite reconstruir workspaces rapidamente em caso de falha.","en-us":"Git Integration ensures all artifacts are externally versioned. Combined with Deployment Pipelines, it allows quickly rebuilding workspaces in case of failure.","es":"Git Integration garantiza que todos los artefactos estén versionados externamente. Combinado con Deployment Pipelines, permite reconstruir workspaces rápidamente en caso de falla.","fr":"Git Integration garantit que tous les artefacts sont versionnés en externe. Combiné avec Deployment Pipelines, il permet de reconstruire rapidement les workspaces en cas de défaillance."}'),
('Obter Dados', '{"pt-br":"Você precisa ingerir dados de um banco SQL Server on-premises para o Lakehouse no Microsoft Fabric.","en-us":"You need to ingest data from an on-premises SQL Server to the Lakehouse in Microsoft Fabric.","es":"Necesita ingerir datos de un SQL Server on-premises al Lakehouse en Microsoft Fabric.","fr":"Vous devez ingérer des données d''un SQL Server on-premises vers le Lakehouse dans Microsoft Fabric."}', '{"pt-br":"Qual componente é necessário para conectar a fontes on-premises?","en-us":"Which component is needed to connect to on-premises sources?","es":"¿Qué componente es necesario para conectar a fuentes on-premises?","fr":"Quel composant est nécessaire pour se connecter aux sources on-premises ?"}', '[{"key":"A","text":{"pt-br":"On-premises Data Gateway","en-us":"On-premises Data Gateway","es":"On-premises Data Gateway","fr":"On-premises Data Gateway"}},{"key":"B","text":{"pt-br":"VNet Gateway","en-us":"VNet Gateway","es":"VNet Gateway","fr":"VNet Gateway"}},{"key":"C","text":{"pt-br":"Azure ExpressRoute","en-us":"Azure ExpressRoute","es":"Azure ExpressRoute","fr":"Azure ExpressRoute"}},{"key":"D","text":{"pt-br":"Direct Connect","en-us":"Direct Connect","es":"Direct Connect","fr":"Direct Connect"}}]', 'A', '{"pt-br":"O On-premises Data Gateway é o componente padrão para conectar o Fabric a fontes de dados locais, agindo como ponte segura entre a rede on-premises e o serviço na nuvem.","en-us":"The On-premises Data Gateway is the standard component for connecting Fabric to local data sources, acting as a secure bridge between on-premises network and the cloud service.","es":"El On-premises Data Gateway es el componente estándar para conectar Fabric a fuentes de datos locales, actuando como puente seguro entre la red on-premises y el servicio en la nube.","fr":"L''On-premises Data Gateway est le composant standard pour connecter Fabric aux sources de données locales, agissant comme pont sécurisé entre le réseau on-premises et le service cloud."}'),
('Obter Dados', '{"pt-br":"Você precisa copiar dados de um Azure Blob Storage para o Lakehouse de forma rápida e simples, sem necessidade de transformações.","en-us":"You need to copy data from Azure Blob Storage to the Lakehouse quickly and simply, without needing transformations.","es":"Necesita copiar datos de un Azure Blob Storage al Lakehouse de forma rápida y simple, sin necesidad de transformaciones.","fr":"Vous devez copier des données d''un Azure Blob Storage vers le Lakehouse rapidement et simplement, sans transformations."}', '{"pt-br":"Qual atividade do Data Pipeline é mais adequada?","en-us":"Which Data Pipeline activity is most appropriate?","es":"¿Qué actividad del Data Pipeline es más adecuada?","fr":"Quelle activité du Data Pipeline est la plus appropriée ?"}', '[{"key":"A","text":{"pt-br":"Copy Data activity","en-us":"Copy Data activity","es":"Copy Data activity","fr":"Copy Data activity"}},{"key":"B","text":{"pt-br":"Dataflow Gen2 activity","en-us":"Dataflow Gen2 activity","es":"Dataflow Gen2 activity","fr":"Dataflow Gen2 activity"}},{"key":"C","text":{"pt-br":"Notebook activity","en-us":"Notebook activity","es":"Notebook activity","fr":"Notebook activity"}},{"key":"D","text":{"pt-br":"Script activity","en-us":"Script activity","es":"Script activity","fr":"Script activity"}}]', 'A', '{"pt-br":"Copy Data activity é otimizada para cópia direta de dados entre fontes e destinos sem transformação, oferecendo alta performance com paralelismo automático.","en-us":"Copy Data activity is optimized for direct data copy between sources and destinations without transformation, offering high performance with automatic parallelism.","es":"Copy Data activity está optimizada para copia directa de datos entre fuentes y destinos sin transformación, ofreciendo alto rendimiento con paralelismo automático.","fr":"L''activité Copy Data est optimisée pour la copie directe de données entre sources et destinations sans transformation, offrant haute performance avec parallélisme automatique."}'),
('Obter Dados', '{"pt-br":"Você precisa criar um processo de ingestão no-code para transformar e carregar dados de uma API REST para o Lakehouse.","en-us":"You need to create a no-code ingestion process to transform and load data from a REST API to the Lakehouse.","es":"Necesita crear un proceso de ingestión no-code para transformar y cargar datos de una API REST al Lakehouse.","fr":"Vous devez créer un processus d''ingestion no-code pour transformer et charger des données d''une API REST vers le Lakehouse."}', '{"pt-br":"Qual ferramenta do Fabric é mais adequada?","en-us":"Which Fabric tool is most appropriate?","es":"¿Qué herramienta de Fabric es más adecuada?","fr":"Quel outil Fabric est le plus approprié ?"}', '[{"key":"A","text":{"pt-br":"Dataflow Gen2","en-us":"Dataflow Gen2","es":"Dataflow Gen2","fr":"Dataflow Gen2"}},{"key":"B","text":{"pt-br":"Spark Notebook","en-us":"Spark Notebook","es":"Spark Notebook","fr":"Spark Notebook"}},{"key":"C","text":{"pt-br":"Data Pipeline","en-us":"Data Pipeline","es":"Data Pipeline","fr":"Data Pipeline"}},{"key":"D","text":{"pt-br":"KQL Queryset","en-us":"KQL Queryset","es":"KQL Queryset","fr":"KQL Queryset"}}]', 'A', '{"pt-br":"Dataflow Gen2 usa Power Query Online para ingestão no-code/low-code com interface visual de transformação, ideal para conectar APIs REST e transformar dados sem código.","en-us":"Dataflow Gen2 uses Power Query Online for no-code/low-code ingestion with visual transformation interface, ideal for connecting REST APIs and transforming data without code.","es":"Dataflow Gen2 usa Power Query Online para ingestión no-code/low-code con interfaz visual de transformación, ideal para conectar APIs REST y transformar datos sin código.","fr":"Dataflow Gen2 utilise Power Query Online pour l''ingestion no-code/low-code avec interface de transformation visuelle, idéal pour connecter des APIs REST et transformer des données sans code."}'),
('Obter Dados', '{"pt-br":"Você tem um Lakehouse e precisa criar um atalho (shortcut) para dados armazenados em um Azure Data Lake Storage Gen2 externo.","en-us":"You have a Lakehouse and need to create a shortcut to data stored in an external Azure Data Lake Storage Gen2.","es":"Tiene un Lakehouse y necesita crear un acceso directo (shortcut) a datos almacenados en un Azure Data Lake Storage Gen2 externo.","fr":"Vous avez un Lakehouse et devez créer un raccourci vers des données stockées dans un Azure Data Lake Storage Gen2 externe."}', '{"pt-br":"Qual é a principal vantagem dos shortcuts no OneLake?","en-us":"What is the main advantage of OneLake shortcuts?","es":"¿Cuál es la principal ventaja de los shortcuts en OneLake?","fr":"Quel est le principal avantage des raccourcis dans OneLake ?"}', '[{"key":"A","text":{"pt-br":"Acessar dados sem copiá-los, evitando duplicação","en-us":"Access data without copying, avoiding duplication","es":"Acceder a datos sin copiarlos, evitando duplicación","fr":"Accéder aux données sans les copier, évitant la duplication"}},{"key":"B","text":{"pt-br":"Melhorar a performance de leitura em 10x","en-us":"Improve read performance by 10x","es":"Mejorar el rendimiento de lectura en 10x","fr":"Améliorer les performances de lecture de 10x"}},{"key":"C","text":{"pt-br":"Converter automaticamente para formato Delta","en-us":"Automatically convert to Delta format","es":"Convertir automáticamente a formato Delta","fr":"Convertir automatiquement au format Delta"}},{"key":"D","text":{"pt-br":"Criptografar os dados automaticamente","en-us":"Automatically encrypt the data","es":"Cifrar los datos automáticamente","fr":"Chiffrer automatiquement les données"}}]', 'A', '{"pt-br":"Shortcuts no OneLake criam referências virtuais para dados em outras localizações, permitindo acessá-los como se estivessem locais sem duplicação de armazenamento.","en-us":"OneLake shortcuts create virtual references to data in other locations, allowing access as if they were local without storage duplication.","es":"Los shortcuts en OneLake crean referencias virtuales a datos en otras ubicaciones, permitiendo acceder como si fueran locales sin duplicación de almacenamiento.","fr":"Les raccourcis OneLake créent des références virtuelles vers des données dans d''autres emplacements, permettant d''y accéder comme si elles étaient locales sans duplication de stockage."}'),
('Obter Dados', '{"pt-br":"Você precisa ingerir dados de streaming em tempo real de dispositivos IoT para análise no Fabric.","en-us":"You need to ingest real-time streaming data from IoT devices for analysis in Fabric.","es":"Necesita ingerir datos de streaming en tiempo real de dispositivos IoT para análisis en Fabric.","fr":"Vous devez ingérer des données de streaming en temps réel de dispositifs IoT pour analyse dans Fabric."}', '{"pt-br":"Qual componente do Fabric é projetado para dados de streaming?","en-us":"Which Fabric component is designed for streaming data?","es":"¿Qué componente de Fabric está diseñado para datos de streaming?","fr":"Quel composant Fabric est conçu pour les données de streaming ?"}', '[{"key":"A","text":{"pt-br":"Eventstream","en-us":"Eventstream","es":"Eventstream","fr":"Eventstream"}},{"key":"B","text":{"pt-br":"Data Pipeline","en-us":"Data Pipeline","es":"Data Pipeline","fr":"Data Pipeline"}},{"key":"C","text":{"pt-br":"Dataflow Gen2","en-us":"Dataflow Gen2","es":"Dataflow Gen2","fr":"Dataflow Gen2"}},{"key":"D","text":{"pt-br":"Spark Structured Streaming","en-us":"Spark Structured Streaming","es":"Spark Structured Streaming","fr":"Spark Structured Streaming"}}]', 'A', '{"pt-br":"Eventstream é o componente nativo do Fabric para ingestão de dados de streaming em tempo real, suportando Azure Event Hubs, IoT Hub e custom endpoints como fontes.","en-us":"Eventstream is Fabric''s native component for real-time streaming data ingestion, supporting Azure Event Hubs, IoT Hub, and custom endpoints as sources.","es":"Eventstream es el componente nativo de Fabric para ingestión de datos de streaming en tiempo real, soportando Azure Event Hubs, IoT Hub y custom endpoints como fuentes.","fr":"Eventstream est le composant natif de Fabric pour l''ingestion de données de streaming en temps réel, supportant Azure Event Hubs, IoT Hub et endpoints personnalisés comme sources."}'),
('Obter Dados', '{"pt-br":"Você precisa orquestrar a execução de múltiplos notebooks Spark e atividades de cópia em uma sequência definida com tratamento de erros.","en-us":"You need to orchestrate the execution of multiple Spark notebooks and copy activities in a defined sequence with error handling.","es":"Necesita orquestar la ejecución de múltiples notebooks Spark y actividades de copia en una secuencia definida con manejo de errores.","fr":"Vous devez orchestrer l''exécution de plusieurs notebooks Spark et activités de copie dans une séquence définie avec gestion des erreurs."}', '{"pt-br":"Qual recurso do Fabric é o mais adequado para orquestração?","en-us":"Which Fabric feature is most appropriate for orchestration?","es":"¿Qué recurso de Fabric es más adecuado para orquestación?","fr":"Quelle fonctionnalité Fabric est la plus appropriée pour l''orchestration ?"}', '[{"key":"A","text":{"pt-br":"Data Pipeline","en-us":"Data Pipeline","es":"Data Pipeline","fr":"Data Pipeline"}},{"key":"B","text":{"pt-br":"Dataflow Gen2","en-us":"Dataflow Gen2","es":"Dataflow Gen2","fr":"Dataflow Gen2"}},{"key":"C","text":{"pt-br":"Spark Job Definition","en-us":"Spark Job Definition","es":"Spark Job Definition","fr":"Spark Job Definition"}},{"key":"D","text":{"pt-br":"Eventstream","en-us":"Eventstream","es":"Eventstream","fr":"Eventstream"}}]', 'A', '{"pt-br":"Data Pipelines oferecem orquestração completa com atividades de controle de fluxo (If, ForEach, Until), tratamento de erros e integração com Notebooks, Copy Data e outros.","en-us":"Data Pipelines offer complete orchestration with flow control activities (If, ForEach, Until), error handling, and integration with Notebooks, Copy Data, and more.","es":"Los Data Pipelines ofrecen orquestación completa con actividades de control de flujo (If, ForEach, Until), manejo de errores e integración con Notebooks, Copy Data y otros.","fr":"Les Data Pipelines offrent une orchestration complète avec des activités de contrôle de flux (If, ForEach, Until), gestion des erreurs et intégration avec Notebooks, Copy Data et autres."}'),
('Obter Dados', '{"pt-br":"Você precisa ingerir dados de um arquivo CSV grande (5GB) armazenado no ADLS Gen2 diretamente em uma tabela Delta no Lakehouse.","en-us":"You need to ingest data from a large CSV file (5GB) stored in ADLS Gen2 directly into a Delta table in the Lakehouse.","es":"Necesita ingerir datos de un archivo CSV grande (5GB) almacenado en ADLS Gen2 directamente en una tabla Delta en el Lakehouse.","fr":"Vous devez ingérer des données d''un gros fichier CSV (5 Go) stocké dans ADLS Gen2 directement dans une table Delta dans le Lakehouse."}', '{"pt-br":"Qual abordagem oferece melhor performance para arquivos grandes?","en-us":"Which approach offers best performance for large files?","es":"¿Qué enfoque ofrece mejor rendimiento para archivos grandes?","fr":"Quelle approche offre les meilleures performances pour les gros fichiers ?"}', '[{"key":"A","text":{"pt-br":"Spark Notebook com spark.read.csv()","en-us":"Spark Notebook with spark.read.csv()","es":"Spark Notebook con spark.read.csv()","fr":"Spark Notebook avec spark.read.csv()"}},{"key":"B","text":{"pt-br":"Dataflow Gen2","en-us":"Dataflow Gen2","es":"Dataflow Gen2","fr":"Dataflow Gen2"}},{"key":"C","text":{"pt-br":"Upload manual via interface","en-us":"Manual upload via interface","es":"Upload manual via interfaz","fr":"Upload manuel via l''interface"}},{"key":"D","text":{"pt-br":"Power Query Desktop","en-us":"Power Query Desktop","es":"Power Query Desktop","fr":"Power Query Desktop"}}]', 'A', '{"pt-br":"Para arquivos grandes, Spark Notebooks oferecem processamento distribuído e paralelo, sendo muito mais eficientes que Dataflow Gen2 ou upload manual para volumes acima de 1GB.","en-us":"For large files, Spark Notebooks offer distributed and parallel processing, being much more efficient than Dataflow Gen2 or manual upload for volumes above 1GB.","es":"Para archivos grandes, los Spark Notebooks ofrecen procesamiento distribuido y paralelo, siendo mucho más eficientes que Dataflow Gen2 o upload manual para volúmenes superiores a 1GB.","fr":"Pour les gros fichiers, les Spark Notebooks offrent un traitement distribué et parallèle, étant beaucoup plus efficaces que Dataflow Gen2 ou l''upload manuel pour des volumes supérieurs à 1 Go."}'),
('Obter Dados', '{"pt-br":"Você precisa acessar dados de um Warehouse no Fabric a partir de um Lakehouse usando T-SQL.","en-us":"You need to access data from a Fabric Warehouse from a Lakehouse using T-SQL.","es":"Necesita acceder a datos de un Warehouse en Fabric desde un Lakehouse usando T-SQL.","fr":"Vous devez accéder aux données d''un Warehouse Fabric depuis un Lakehouse en utilisant T-SQL."}', '{"pt-br":"Qual recurso permite consultar dados entre Lakehouse e Warehouse?","en-us":"Which feature allows querying data between Lakehouse and Warehouse?","es":"¿Qué recurso permite consultar datos entre Lakehouse y Warehouse?","fr":"Quelle fonctionnalité permet d''interroger des données entre Lakehouse et Warehouse ?"}', '[{"key":"A","text":{"pt-br":"Cross-database queries no SQL Analytics Endpoint","en-us":"Cross-database queries in SQL Analytics Endpoint","es":"Cross-database queries en SQL Analytics Endpoint","fr":"Cross-database queries dans SQL Analytics Endpoint"}},{"key":"B","text":{"pt-br":"Linked Service","en-us":"Linked Service","es":"Linked Service","fr":"Linked Service"}},{"key":"C","text":{"pt-br":"Data Gateway","en-us":"Data Gateway","es":"Data Gateway","fr":"Data Gateway"}},{"key":"D","text":{"pt-br":"External Tables","en-us":"External Tables","es":"External Tables","fr":"External Tables"}}]', 'A', '{"pt-br":"Cross-database queries no SQL Analytics Endpoint permitem consultar dados entre diferentes Lakehouses e Warehouses dentro do mesmo workspace usando T-SQL padrão.","en-us":"Cross-database queries in SQL Analytics Endpoint allow querying data between different Lakehouses and Warehouses within the same workspace using standard T-SQL.","es":"Las cross-database queries en SQL Analytics Endpoint permiten consultar datos entre diferentes Lakehouses y Warehouses dentro del mismo workspace usando T-SQL estándar.","fr":"Les cross-database queries dans SQL Analytics Endpoint permettent d''interroger des données entre différents Lakehouses et Warehouses dans le même workspace en utilisant T-SQL standard."}'),
('Obter Dados', '{"pt-br":"Você precisa configurar um shortcut no OneLake para acessar dados de um bucket Amazon S3.","en-us":"You need to configure a shortcut in OneLake to access data from an Amazon S3 bucket.","es":"Necesita configurar un shortcut en OneLake para acceder a datos de un bucket Amazon S3.","fr":"Vous devez configurer un raccourci dans OneLake pour accéder aux données d''un bucket Amazon S3."}', '{"pt-br":"Qual dos seguintes é um destino de shortcut suportado?","en-us":"Which of the following is a supported shortcut destination?","es":"¿Cuál de los siguientes es un destino de shortcut soportado?","fr":"Lequel des éléments suivants est une destination de raccourci supportée ?"}', '[{"key":"A","text":{"pt-br":"Amazon S3, ADLS Gen2 e Google Cloud Storage","en-us":"Amazon S3, ADLS Gen2 and Google Cloud Storage","es":"Amazon S3, ADLS Gen2 y Google Cloud Storage","fr":"Amazon S3, ADLS Gen2 et Google Cloud Storage"}},{"key":"B","text":{"pt-br":"Apenas ADLS Gen2","en-us":"ADLS Gen2 only","es":"Solo ADLS Gen2","fr":"ADLS Gen2 uniquement"}},{"key":"C","text":{"pt-br":"Apenas fontes Azure","en-us":"Azure sources only","es":"Solo fuentes Azure","fr":"Sources Azure uniquement"}},{"key":"D","text":{"pt-br":"Apenas OneLake interno","en-us":"Internal OneLake only","es":"Solo OneLake interno","fr":"OneLake interne uniquement"}}]', 'A', '{"pt-br":"OneLake shortcuts suportam múltiplos provedores de nuvem incluindo Amazon S3, ADLS Gen2, Google Cloud Storage e Dataverse, além de outros lakehouses OneLake.","en-us":"OneLake shortcuts support multiple cloud providers including Amazon S3, ADLS Gen2, Google Cloud Storage, and Dataverse, plus other OneLake lakehouses.","es":"Los shortcuts de OneLake soportan múltiples proveedores de nube incluyendo Amazon S3, ADLS Gen2, Google Cloud Storage y Dataverse, además de otros lakehouses OneLake.","fr":"Les raccourcis OneLake supportent plusieurs fournisseurs cloud dont Amazon S3, ADLS Gen2, Google Cloud Storage et Dataverse, plus d''autres lakehouses OneLake."}'),
('Obter Dados', '{"pt-br":"Você precisa carregar dados de um banco de dados Oracle para o Lakehouse, mas não quer configurar um gateway.","en-us":"You need to load data from an Oracle database to the Lakehouse but don''t want to configure a gateway.","es":"Necesita cargar datos de una base de datos Oracle al Lakehouse pero no quiere configurar un gateway.","fr":"Vous devez charger des données d''une base Oracle vers le Lakehouse sans configurer de passerelle."}', '{"pt-br":"Qual pré-requisito é necessário para evitar o gateway?","en-us":"What prerequisite is needed to avoid the gateway?","es":"¿Qué prerrequisito es necesario para evitar el gateway?","fr":"Quel prérequis est nécessaire pour éviter la passerelle ?"}', '[{"key":"A","text":{"pt-br":"O Oracle deve estar acessível publicamente ou via VNet Data Gateway","en-us":"Oracle must be publicly accessible or via VNet Data Gateway","es":"Oracle debe ser accesible públicamente o via VNet Data Gateway","fr":"Oracle doit être accessible publiquement ou via VNet Data Gateway"}},{"key":"B","text":{"pt-br":"Usar apenas Dataflow Gen2","en-us":"Use Dataflow Gen2 only","es":"Usar solo Dataflow Gen2","fr":"Utiliser uniquement Dataflow Gen2"}},{"key":"C","text":{"pt-br":"Converter os dados para CSV primeiro","en-us":"Convert data to CSV first","es":"Convertir los datos a CSV primero","fr":"Convertir d''abord les données en CSV"}},{"key":"D","text":{"pt-br":"Não é possível sem gateway","en-us":"Not possible without gateway","es":"No es posible sin gateway","fr":"Pas possible sans passerelle"}}]', 'A', '{"pt-br":"Para evitar o On-premises Data Gateway, a fonte deve ser acessível na nuvem ou via VNet Data Gateway, que permite conexões seguras através de redes virtuais do Azure.","en-us":"To avoid the On-premises Data Gateway, the source must be cloud-accessible or via VNet Data Gateway, which allows secure connections through Azure virtual networks.","es":"Para evitar el On-premises Data Gateway, la fuente debe ser accesible en la nube o via VNet Data Gateway, que permite conexiones seguras a través de redes virtuales de Azure.","fr":"Pour éviter l''On-premises Data Gateway, la source doit être accessible dans le cloud ou via VNet Data Gateway, permettant des connexions sécurisées via les réseaux virtuels Azure."}'),
('Obter Dados', '{"pt-br":"Você precisa carregar dados de múltiplas tabelas de um banco SQL Azure para o Lakehouse de forma paralela.","en-us":"You need to load data from multiple tables of an Azure SQL database to the Lakehouse in parallel.","es":"Necesita cargar datos de múltiples tablas de un banco SQL Azure al Lakehouse de forma paralela.","fr":"Vous devez charger des données de plusieurs tables d''une base SQL Azure vers le Lakehouse en parallèle."}', '{"pt-br":"Qual atividade do Data Pipeline permite iterar sobre uma lista de tabelas?","en-us":"Which Data Pipeline activity allows iterating over a list of tables?","es":"¿Qué actividad del Data Pipeline permite iterar sobre una lista de tablas?","fr":"Quelle activité du Data Pipeline permet d''itérer sur une liste de tables ?"}', '[{"key":"A","text":{"pt-br":"ForEach activity","en-us":"ForEach activity","es":"ForEach activity","fr":"ForEach activity"}},{"key":"B","text":{"pt-br":"Until activity","en-us":"Until activity","es":"Until activity","fr":"Until activity"}},{"key":"C","text":{"pt-br":"Switch activity","en-us":"Switch activity","es":"Switch activity","fr":"Switch activity"}},{"key":"D","text":{"pt-br":"If Condition activity","en-us":"If Condition activity","es":"If Condition activity","fr":"If Condition activity"}}]', 'A', '{"pt-br":"ForEach activity permite iterar sobre uma coleção (lista de tabelas) e executar atividades como Copy Data para cada item, com suporte a execução paralela configurável.","en-us":"ForEach activity allows iterating over a collection (table list) and executing activities like Copy Data for each item, with configurable parallel execution support.","es":"ForEach activity permite iterar sobre una colección (lista de tablas) y ejecutar actividades como Copy Data para cada elemento, con soporte de ejecución paralela configurable.","fr":"ForEach activity permet d''itérer sur une collection (liste de tables) et d''exécuter des activités comme Copy Data pour chaque élément, avec support d''exécution parallèle configurable."}'),
('Obter Dados', '{"pt-br":"Você precisa conectar o Power BI a dados armazenados no Lakehouse do Fabric para construir relatórios.","en-us":"You need to connect Power BI to data stored in the Fabric Lakehouse to build reports.","es":"Necesita conectar Power BI a datos almacenados en el Lakehouse de Fabric para construir informes.","fr":"Vous devez connecter Power BI aux données stockées dans le Lakehouse Fabric pour créer des rapports."}', '{"pt-br":"Qual endpoint do Lakehouse deve ser usado para conexão via T-SQL?","en-us":"Which Lakehouse endpoint should be used for T-SQL connection?","es":"¿Qué endpoint del Lakehouse debe usarse para conexión via T-SQL?","fr":"Quel endpoint du Lakehouse doit être utilisé pour la connexion via T-SQL ?"}', '[{"key":"A","text":{"pt-br":"SQL Analytics Endpoint","en-us":"SQL Analytics Endpoint","es":"SQL Analytics Endpoint","fr":"SQL Analytics Endpoint"}},{"key":"B","text":{"pt-br":"Spark Endpoint","en-us":"Spark Endpoint","es":"Spark Endpoint","fr":"Spark Endpoint"}},{"key":"C","text":{"pt-br":"REST API Endpoint","en-us":"REST API Endpoint","es":"REST API Endpoint","fr":"REST API Endpoint"}},{"key":"D","text":{"pt-br":"OneLake Endpoint","en-us":"OneLake Endpoint","es":"OneLake Endpoint","fr":"OneLake Endpoint"}}]', 'A', '{"pt-br":"O SQL Analytics Endpoint permite consultar tabelas Delta do Lakehouse usando T-SQL, tornando-o ideal para conexão com Power BI e outras ferramentas de BI tradicionais.","en-us":"The SQL Analytics Endpoint allows querying Delta tables in the Lakehouse using T-SQL, making it ideal for connecting with Power BI and other traditional BI tools.","es":"El SQL Analytics Endpoint permite consultar tablas Delta del Lakehouse usando T-SQL, haciéndolo ideal para conexión con Power BI y otras herramientas de BI tradicionales.","fr":"Le SQL Analytics Endpoint permet d''interroger les tables Delta du Lakehouse en utilisant T-SQL, le rendant idéal pour la connexion avec Power BI et d''autres outils BI traditionnels."}'),
('Obter Dados', '{"pt-br":"Você precisa carregar dados incrementais de uma fonte que suporta Change Data Capture (CDC) para manter o Lakehouse atualizado.","en-us":"You need to load incremental data from a source that supports Change Data Capture (CDC) to keep the Lakehouse updated.","es":"Necesita cargar datos incrementales de una fuente que soporta Change Data Capture (CDC) para mantener el Lakehouse actualizado.","fr":"Vous devez charger des données incrémentielles d''une source supportant le Change Data Capture (CDC) pour maintenir le Lakehouse à jour."}', '{"pt-br":"Qual recurso do Fabric facilita a ingestão baseada em CDC?","en-us":"Which Fabric feature facilitates CDC-based ingestion?","es":"¿Qué recurso de Fabric facilita la ingestión basada en CDC?","fr":"Quelle fonctionnalité Fabric facilite l''ingestion basée sur CDC ?"}', '[{"key":"A","text":{"pt-br":"Mirroring","en-us":"Mirroring","es":"Mirroring","fr":"Mirroring"}},{"key":"B","text":{"pt-br":"Shortcuts","en-us":"Shortcuts","es":"Shortcuts","fr":"Shortcuts"}},{"key":"C","text":{"pt-br":"Copy Data com modo incremental","en-us":"Copy Data with incremental mode","es":"Copy Data con modo incremental","fr":"Copy Data avec mode incrémentiel"}},{"key":"D","text":{"pt-br":"Scheduled Refresh","en-us":"Scheduled Refresh","es":"Scheduled Refresh","fr":"Scheduled Refresh"}}]', 'A', '{"pt-br":"Mirroring no Fabric replica dados automaticamente de fontes como Azure SQL Database, Cosmos DB e Snowflake usando CDC, mantendo uma cópia sincronizada no OneLake.","en-us":"Mirroring in Fabric automatically replicates data from sources like Azure SQL Database, Cosmos DB, and Snowflake using CDC, maintaining a synchronized copy in OneLake.","es":"Mirroring en Fabric replica automáticamente datos de fuentes como Azure SQL Database, Cosmos DB y Snowflake usando CDC, manteniendo una copia sincronizada en OneLake.","fr":"Le Mirroring dans Fabric réplique automatiquement les données de sources comme Azure SQL Database, Cosmos DB et Snowflake en utilisant CDC, maintenant une copie synchronisée dans OneLake."}'),
('Obter Dados', '{"pt-br":"Você precisa criar uma camada bronze no Lakehouse para armazenar dados brutos em seu formato original antes de transformações.","en-us":"You need to create a bronze layer in the Lakehouse to store raw data in its original format before transformations.","es":"Necesita crear una capa bronze en el Lakehouse para almacenar datos brutos en su formato original antes de transformaciones.","fr":"Vous devez créer une couche bronze dans le Lakehouse pour stocker les données brutes dans leur format original avant transformation."}', '{"pt-br":"Onde os arquivos brutos devem ser armazenados no Lakehouse?","en-us":"Where should raw files be stored in the Lakehouse?","es":"¿Dónde deben almacenarse los archivos brutos en el Lakehouse?","fr":"Où les fichiers bruts doivent-ils être stockés dans le Lakehouse ?"}', '[{"key":"A","text":{"pt-br":"Na seção Files do Lakehouse","en-us":"In the Files section of the Lakehouse","es":"En la sección Files del Lakehouse","fr":"Dans la section Files du Lakehouse"}},{"key":"B","text":{"pt-br":"Na seção Tables do Lakehouse","en-us":"In the Tables section of the Lakehouse","es":"En la sección Tables del Lakehouse","fr":"Dans la section Tables du Lakehouse"}},{"key":"C","text":{"pt-br":"Em um Warehouse separado","en-us":"In a separate Warehouse","es":"En un Warehouse separado","fr":"Dans un Warehouse séparé"}},{"key":"D","text":{"pt-br":"Em um Data Pipeline","en-us":"In a Data Pipeline","es":"En un Data Pipeline","fr":"Dans un Data Pipeline"}}]', 'A', '{"pt-br":"A seção Files do Lakehouse é destinada a arquivos não estruturados ou semi-estruturados em formato bruto. A seção Tables armazena tabelas Delta gerenciadas.","en-us":"The Files section of the Lakehouse is for unstructured or semi-structured files in raw format. The Tables section stores managed Delta tables.","es":"La sección Files del Lakehouse es para archivos no estructurados o semi-estructurados en formato bruto. La sección Tables almacena tablas Delta administradas.","fr":"La section Files du Lakehouse est destinée aux fichiers non structurés ou semi-structurés en format brut. La section Tables stocke les tables Delta gérées."}'),
('Obter Dados', '{"pt-br":"Você precisa garantir que um pipeline de dados no Fabric seja executado automaticamente após o término de outro pipeline com sucesso.","en-us":"You need to ensure a data pipeline in Fabric runs automatically after another pipeline completes successfully.","es":"Necesita garantizar que un pipeline de datos en Fabric se ejecute automáticamente después de que otro pipeline termine con éxito.","fr":"Vous devez garantir qu''un pipeline de données dans Fabric s''exécute automatiquement après la fin réussie d''un autre pipeline."}', '{"pt-br":"Qual recurso permite encadear execuções de pipelines?","en-us":"Which feature allows chaining pipeline executions?","es":"¿Qué recurso permite encadenar ejecuciones de pipelines?","fr":"Quelle fonctionnalité permet d''enchaîner les exécutions de pipelines ?"}', '[{"key":"A","text":{"pt-br":"Invoke Pipeline activity","en-us":"Invoke Pipeline activity","es":"Invoke Pipeline activity","fr":"Invoke Pipeline activity"}},{"key":"B","text":{"pt-br":"Trigger com dependência","en-us":"Trigger with dependency","es":"Trigger con dependencia","fr":"Trigger avec dépendance"}},{"key":"C","text":{"pt-br":"Event-based trigger","en-us":"Event-based trigger","es":"Event-based trigger","fr":"Event-based trigger"}},{"key":"D","text":{"pt-br":"Schedule trigger sequencial","en-us":"Sequential schedule trigger","es":"Schedule trigger secuencial","fr":"Schedule trigger séquentiel"}}]', 'A', '{"pt-br":"A atividade Invoke Pipeline permite chamar outro pipeline como parte do fluxo, podendo aguardar sua conclusão e agir com base no resultado (sucesso/falha).","en-us":"The Invoke Pipeline activity allows calling another pipeline as part of the flow, waiting for its completion and acting based on the result (success/failure).","es":"La actividad Invoke Pipeline permite llamar a otro pipeline como parte del flujo, pudiendo esperar su conclusión y actuar según el resultado (éxito/fallo).","fr":"L''activité Invoke Pipeline permet d''appeler un autre pipeline comme partie du flux, en attendant sa complétion et agissant selon le résultat (succès/échec)."}'),
('Obter Dados', '{"pt-br":"Você precisa usar o Dataflow Gen2 para carregar dados de um SharePoint Online para o Lakehouse.","en-us":"You need to use Dataflow Gen2 to load data from SharePoint Online to the Lakehouse.","es":"Necesita usar Dataflow Gen2 para cargar datos de SharePoint Online al Lakehouse.","fr":"Vous devez utiliser Dataflow Gen2 pour charger des données de SharePoint Online vers le Lakehouse."}', '{"pt-br":"Qual é o destino de dados recomendado no Dataflow Gen2?","en-us":"What is the recommended data destination in Dataflow Gen2?","es":"¿Cuál es el destino de datos recomendado en Dataflow Gen2?","fr":"Quelle est la destination de données recommandée dans Dataflow Gen2 ?"}', '[{"key":"A","text":{"pt-br":"Lakehouse Table","en-us":"Lakehouse Table","es":"Lakehouse Table","fr":"Lakehouse Table"}},{"key":"B","text":{"pt-br":"Warehouse Table","en-us":"Warehouse Table","es":"Warehouse Table","fr":"Warehouse Table"}},{"key":"C","text":{"pt-br":"KQL Database","en-us":"KQL Database","es":"KQL Database","fr":"KQL Database"}},{"key":"D","text":{"pt-br":"Azure SQL Database","en-us":"Azure SQL Database","es":"Azure SQL Database","fr":"Azure SQL Database"}}]', 'A', '{"pt-br":"O Dataflow Gen2 pode direcionar dados para Lakehouse Tables como destino, aproveitando o formato Delta Lake e integrando com o ecossistema OneLake do Fabric.","en-us":"Dataflow Gen2 can direct data to Lakehouse Tables as destination, leveraging Delta Lake format and integrating with Fabric''s OneLake ecosystem.","es":"Dataflow Gen2 puede dirigir datos a Lakehouse Tables como destino, aprovechando el formato Delta Lake e integrándose con el ecosistema OneLake de Fabric.","fr":"Dataflow Gen2 peut diriger les données vers des Lakehouse Tables comme destination, tirant parti du format Delta Lake et s''intégrant à l''écosystème OneLake de Fabric."}'),
('Obter Dados', '{"pt-br":"Você precisa verificar se um Dataflow Gen2 está aplicando query folding para otimizar a performance da ingestão.","en-us":"You need to verify if a Dataflow Gen2 is applying query folding to optimize ingestion performance.","es":"Necesita verificar si un Dataflow Gen2 está aplicando query folding para optimizar el rendimiento de la ingestión.","fr":"Vous devez vérifier si un Dataflow Gen2 applique le query folding pour optimiser les performances d''ingestion."}', '{"pt-br":"Como verificar se query folding está ativo em uma etapa do Power Query?","en-us":"How to verify if query folding is active on a Power Query step?","es":"¿Cómo verificar si query folding está activo en un paso de Power Query?","fr":"Comment vérifier si le query folding est actif sur une étape de Power Query ?"}', '[{"key":"A","text":{"pt-br":"Indicador de query folding na etapa (ícone verde)","en-us":"Query folding indicator on the step (green icon)","es":"Indicador de query folding en el paso (ícono verde)","fr":"Indicateur de query folding sur l''étape (icône vert)"}},{"key":"B","text":{"pt-br":"Verificar nos logs de auditoria","en-us":"Check in audit logs","es":"Verificar en los logs de auditoría","fr":"Vérifier dans les journaux d''audit"}},{"key":"C","text":{"pt-br":"Analisar o tempo de execução","en-us":"Analyze execution time","es":"Analizar el tiempo de ejecución","fr":"Analyser le temps d''exécution"}},{"key":"D","text":{"pt-br":"Não é possível verificar","en-us":"Cannot be verified","es":"No es posible verificar","fr":"Ne peut pas être vérifié"}}]', 'A', '{"pt-br":"O Power Query Online mostra um indicador visual em cada etapa indicando se query folding está sendo aplicado, com um ícone verde quando totalmente dobrado.","en-us":"Power Query Online shows a visual indicator on each step indicating if query folding is being applied, with a green icon when fully folded.","es":"Power Query Online muestra un indicador visual en cada paso indicando si query folding está siendo aplicado, con un ícono verde cuando está completamente doblado.","fr":"Power Query Online affiche un indicateur visuel sur chaque étape indiquant si le query folding est appliqué, avec une icône verte lorsqu''il est entièrement plié."}'),
('Obter Dados', '{"pt-br":"Você precisa decidir entre usar Lakehouse ou Warehouse no Fabric para uma workload analítica.","en-us":"You need to decide between using Lakehouse or Warehouse in Fabric for an analytical workload.","es":"Necesita decidir entre usar Lakehouse o Warehouse en Fabric para una carga de trabajo analítica.","fr":"Vous devez choisir entre Lakehouse et Warehouse dans Fabric pour une charge de travail analytique."}', '{"pt-br":"Quando o Warehouse é preferível ao Lakehouse?","en-us":"When is Warehouse preferable to Lakehouse?","es":"¿Cuándo es preferible Warehouse sobre Lakehouse?","fr":"Quand le Warehouse est-il préférable au Lakehouse ?"}', '[{"key":"A","text":{"pt-br":"Quando se precisa de transações ACID completas com T-SQL e modelagem dimensional tradicional","en-us":"When full ACID transactions with T-SQL and traditional dimensional modeling are needed","es":"Cuando se necesitan transacciones ACID completas con T-SQL y modelado dimensional tradicional","fr":"Quand des transactions ACID complètes avec T-SQL et modélisation dimensionnelle traditionnelle sont nécessaires"}},{"key":"B","text":{"pt-br":"Quando se trabalha com dados não estruturados","en-us":"When working with unstructured data","es":"Cuando se trabaja con datos no estructurados","fr":"Quand on travaille avec des données non structurées"}},{"key":"C","text":{"pt-br":"Quando se precisa de Spark notebooks","en-us":"When Spark notebooks are needed","es":"Cuando se necesitan Spark notebooks","fr":"Quand des notebooks Spark sont nécessaires"}},{"key":"D","text":{"pt-br":"Quando o volume de dados é menor que 1GB","en-us":"When data volume is less than 1GB","es":"Cuando el volumen de datos es menor a 1GB","fr":"Quand le volume de données est inférieur à 1 Go"}}]', 'A', '{"pt-br":"Warehouse é preferível quando a equipe tem expertise em T-SQL, precisa de modelagem dimensional tradicional (star schema) e transações ACID completas com suporte a DML (INSERT, UPDATE, DELETE).","en-us":"Warehouse is preferable when the team has T-SQL expertise, needs traditional dimensional modeling (star schema) and full ACID transactions with DML support (INSERT, UPDATE, DELETE).","es":"Warehouse es preferible cuando el equipo tiene experiencia en T-SQL, necesita modelado dimensional tradicional (star schema) y transacciones ACID completas con soporte DML (INSERT, UPDATE, DELETE).","fr":"Le Warehouse est préférable quand l''équipe a une expertise T-SQL, nécessite une modélisation dimensionnelle traditionnelle (star schema) et des transactions ACID complètes avec support DML (INSERT, UPDATE, DELETE)."}'),
('Obter Dados', '{"pt-br":"Você precisa monitorar a execução de um Data Pipeline e identificar qual atividade falhou.","en-us":"You need to monitor a Data Pipeline execution and identify which activity failed.","es":"Necesita monitorear la ejecución de un Data Pipeline e identificar qué actividad falló.","fr":"Vous devez surveiller l''exécution d''un Data Pipeline et identifier quelle activité a échoué."}', '{"pt-br":"Onde encontrar o detalhamento de execução do pipeline?","en-us":"Where to find the pipeline execution details?","es":"¿Dónde encontrar el detalle de ejecución del pipeline?","fr":"Où trouver le détail d''exécution du pipeline ?"}', '[{"key":"A","text":{"pt-br":"Pipeline Run view com output de cada atividade","en-us":"Pipeline Run view with output of each activity","es":"Pipeline Run view con output de cada actividad","fr":"Pipeline Run view avec la sortie de chaque activité"}},{"key":"B","text":{"pt-br":"Azure Monitor logs","en-us":"Azure Monitor logs","es":"Azure Monitor logs","fr":"Azure Monitor logs"}},{"key":"C","text":{"pt-br":"Capacity Metrics App","en-us":"Capacity Metrics App","es":"Capacity Metrics App","fr":"Capacity Metrics App"}},{"key":"D","text":{"pt-br":"Power BI Activity Log","en-us":"Power BI Activity Log","es":"Power BI Activity Log","fr":"Power BI Activity Log"}}]', 'A', '{"pt-br":"A Pipeline Run view mostra o status de cada atividade, duração, input/output e mensagens de erro detalhadas, facilitando a identificação e resolução de falhas.","en-us":"The Pipeline Run view shows each activity''s status, duration, input/output, and detailed error messages, facilitating failure identification and resolution.","es":"La Pipeline Run view muestra el estado de cada actividad, duración, input/output y mensajes de error detallados, facilitando la identificación y resolución de fallos.","fr":"La Pipeline Run view montre le statut de chaque activité, la durée, l''entrée/sortie et les messages d''erreur détaillés, facilitant l''identification et la résolution des défaillances."}'),
('Obter Dados', '{"pt-br":"Você precisa carregar dados de um arquivo Parquet armazenado no OneLake para uma tabela gerenciada no Lakehouse.","en-us":"You need to load data from a Parquet file stored in OneLake to a managed table in the Lakehouse.","es":"Necesita cargar datos de un archivo Parquet almacenado en OneLake a una tabla administrada en el Lakehouse.","fr":"Vous devez charger des données d''un fichier Parquet stocké dans OneLake vers une table gérée dans le Lakehouse."}', '{"pt-br":"Qual comando Spark cria uma tabela Delta gerenciada a partir de um Parquet?","en-us":"Which Spark command creates a managed Delta table from a Parquet?","es":"¿Qué comando Spark crea una tabla Delta administrada a partir de un Parquet?","fr":"Quelle commande Spark crée une table Delta gérée à partir d''un Parquet ?"}', '[{"key":"A","text":{"pt-br":"df.write.format(''delta'').saveAsTable(''table_name'')","en-us":"df.write.format(''delta'').saveAsTable(''table_name'')","es":"df.write.format(''delta'').saveAsTable(''table_name'')","fr":"df.write.format(''delta'').saveAsTable(''table_name'')"}},{"key":"B","text":{"pt-br":"df.write.parquet(''table_name'')","en-us":"df.write.parquet(''table_name'')","es":"df.write.parquet(''table_name'')","fr":"df.write.parquet(''table_name'')"}},{"key":"C","text":{"pt-br":"df.save(''table_name'')","en-us":"df.save(''table_name'')","es":"df.save(''table_name'')","fr":"df.save(''table_name'')"}},{"key":"D","text":{"pt-br":"CREATE TABLE table_name AS PARQUET","en-us":"CREATE TABLE table_name AS PARQUET","es":"CREATE TABLE table_name AS PARQUET","fr":"CREATE TABLE table_name AS PARQUET"}}]', 'A', '{"pt-br":"df.write.format(''delta'').saveAsTable() cria uma tabela Delta gerenciada no Lakehouse, que é o formato padrão para tabelas no Microsoft Fabric.","en-us":"df.write.format(''delta'').saveAsTable() creates a managed Delta table in the Lakehouse, which is the default format for tables in Microsoft Fabric.","es":"df.write.format(''delta'').saveAsTable() crea una tabla Delta administrada en el Lakehouse, que es el formato predeterminado para tablas en Microsoft Fabric.","fr":"df.write.format(''delta'').saveAsTable() crée une table Delta gérée dans le Lakehouse, qui est le format par défaut pour les tables dans Microsoft Fabric."}'),
('Transformar Dados', '{"pt-br":"Você tem um Lakehouse com tabelas Delta e precisa consolidar arquivos pequenos para melhorar a performance de leitura.","en-us":"You have a Lakehouse with Delta tables and need to consolidate small files to improve read performance.","es":"Tiene un Lakehouse con tablas Delta y necesita consolidar archivos pequeños para mejorar el rendimiento de lectura.","fr":"Vous avez un Lakehouse avec des tables Delta et devez consolider les petits fichiers pour améliorer les performances de lecture."}', '{"pt-br":"Qual comando deve ser utilizado no Spark Notebook?","en-us":"Which command should be used in the Spark Notebook?","es":"¿Qué comando debe utilizarse en el Spark Notebook?","fr":"Quelle commande doit être utilisée dans le Spark Notebook ?"}', '[{"key":"A","text":{"pt-br":"VACUUM","en-us":"VACUUM","es":"VACUUM","fr":"VACUUM"}},{"key":"B","text":{"pt-br":"OPTIMIZE","en-us":"OPTIMIZE","es":"OPTIMIZE","fr":"OPTIMIZE"}},{"key":"C","text":{"pt-br":"COMPACT","en-us":"COMPACT","es":"COMPACT","fr":"COMPACT"}},{"key":"D","text":{"pt-br":"MERGE INTO","en-us":"MERGE INTO","es":"MERGE INTO","fr":"MERGE INTO"}}]', 'B', '{"pt-br":"O comando OPTIMIZE consolida arquivos menores em arquivos maiores para melhorar a performance de leitura, aplicando V-Order no Microsoft Fabric por padrão.","en-us":"The OPTIMIZE command consolidates smaller files into larger ones to improve read performance, applying V-Order in Microsoft Fabric by default.","es":"El comando OPTIMIZE consolida archivos más pequeños en archivos más grandes para mejorar el rendimiento de lectura, aplicando V-Order en Microsoft Fabric por defecto.","fr":"La commande OPTIMIZE consolide les petits fichiers en fichiers plus grands pour améliorer les performances de lecture, appliquant V-Order dans Microsoft Fabric par défaut."}'),
('Transformar Dados', '{"pt-br":"Você precisa remover arquivos de dados antigos que não são mais referenciados pela tabela Delta para liberar espaço.","en-us":"You need to remove old data files no longer referenced by the Delta table to free up space.","es":"Necesita eliminar archivos de datos antiguos que ya no son referenciados por la tabla Delta para liberar espacio.","fr":"Vous devez supprimer les anciens fichiers de données qui ne sont plus référencés par la table Delta pour libérer de l''espace."}', '{"pt-br":"Qual comando realiza essa limpeza?","en-us":"Which command performs this cleanup?","es":"¿Qué comando realiza esta limpieza?","fr":"Quelle commande effectue ce nettoyage ?"}', '[{"key":"A","text":{"pt-br":"VACUUM","en-us":"VACUUM","es":"VACUUM","fr":"VACUUM"}},{"key":"B","text":{"pt-br":"OPTIMIZE","en-us":"OPTIMIZE","es":"OPTIMIZE","fr":"OPTIMIZE"}},{"key":"C","text":{"pt-br":"TRUNCATE","en-us":"TRUNCATE","es":"TRUNCATE","fr":"TRUNCATE"}},{"key":"D","text":{"pt-br":"DROP TABLE","en-us":"DROP TABLE","es":"DROP TABLE","fr":"DROP TABLE"}}]', 'A', '{"pt-br":"VACUUM remove arquivos Parquet que não são mais referenciados pelo log de transações Delta, liberando espaço de armazenamento. Por padrão, mantém arquivos dos últimos 7 dias.","en-us":"VACUUM removes Parquet files no longer referenced by the Delta transaction log, freeing storage space. By default, it retains files from the last 7 days.","es":"VACUUM elimina archivos Parquet que ya no son referenciados por el log de transacciones Delta, liberando espacio de almacenamiento. Por defecto, mantiene archivos de los últimos 7 días.","fr":"VACUUM supprime les fichiers Parquet qui ne sont plus référencés par le journal de transactions Delta, libérant de l''espace de stockage. Par défaut, il conserve les fichiers des 7 derniers jours."}'),
('Transformar Dados', '{"pt-br":"Você precisa fazer upsert (inserir ou atualizar) registros em uma tabela Delta com base em uma chave primária.","en-us":"You need to upsert (insert or update) records in a Delta table based on a primary key.","es":"Necesita hacer upsert (insertar o actualizar) registros en una tabla Delta basándose en una clave primaria.","fr":"Vous devez faire un upsert (insérer ou mettre à jour) des enregistrements dans une table Delta basé sur une clé primaire."}', '{"pt-br":"Qual comando SQL é usado para upsert em tabelas Delta?","en-us":"Which SQL command is used for upsert in Delta tables?","es":"¿Qué comando SQL se usa para upsert en tablas Delta?","fr":"Quelle commande SQL est utilisée pour l''upsert dans les tables Delta ?"}', '[{"key":"A","text":{"pt-br":"MERGE INTO","en-us":"MERGE INTO","es":"MERGE INTO","fr":"MERGE INTO"}},{"key":"B","text":{"pt-br":"INSERT OR UPDATE","en-us":"INSERT OR UPDATE","es":"INSERT OR UPDATE","fr":"INSERT OR UPDATE"}},{"key":"C","text":{"pt-br":"UPSERT INTO","en-us":"UPSERT INTO","es":"UPSERT INTO","fr":"UPSERT INTO"}},{"key":"D","text":{"pt-br":"UPDATE OR INSERT","en-us":"UPDATE OR INSERT","es":"UPDATE OR INSERT","fr":"UPDATE OR INSERT"}}]', 'A', '{"pt-br":"MERGE INTO permite combinar operações INSERT, UPDATE e DELETE em uma única instrução, ideal para cenários de upsert e SCD (Slowly Changing Dimensions) em tabelas Delta.","en-us":"MERGE INTO allows combining INSERT, UPDATE, and DELETE operations in a single statement, ideal for upsert and SCD (Slowly Changing Dimensions) scenarios in Delta tables.","es":"MERGE INTO permite combinar operaciones INSERT, UPDATE y DELETE en una sola instrucción, ideal para escenarios de upsert y SCD (Slowly Changing Dimensions) en tablas Delta.","fr":"MERGE INTO permet de combiner les opérations INSERT, UPDATE et DELETE en une seule instruction, idéal pour les scénarios d''upsert et SCD dans les tables Delta."}'),
('Transformar Dados', '{"pt-br":"Você precisa adicionar uma nova coluna calculada a uma tabela Delta existente no Lakehouse usando Spark.","en-us":"You need to add a new calculated column to an existing Delta table in the Lakehouse using Spark.","es":"Necesita agregar una nueva columna calculada a una tabla Delta existente en el Lakehouse usando Spark.","fr":"Vous devez ajouter une nouvelle colonne calculée à une table Delta existante dans le Lakehouse en utilisant Spark."}', '{"pt-br":"Qual método PySpark é usado para adicionar uma coluna a um DataFrame?","en-us":"Which PySpark method is used to add a column to a DataFrame?","es":"¿Qué método PySpark se usa para agregar una columna a un DataFrame?","fr":"Quelle méthode PySpark est utilisée pour ajouter une colonne à un DataFrame ?"}', '[{"key":"A","text":{"pt-br":"withColumn()","en-us":"withColumn()","es":"withColumn()","fr":"withColumn()"}},{"key":"B","text":{"pt-br":"addColumn()","en-us":"addColumn()","es":"addColumn()","fr":"addColumn()"}},{"key":"C","text":{"pt-br":"createColumn()","en-us":"createColumn()","es":"createColumn()","fr":"createColumn()"}},{"key":"D","text":{"pt-br":"appendColumn()","en-us":"appendColumn()","es":"appendColumn()","fr":"appendColumn()"}}]', 'A', '{"pt-br":"withColumn() é o método padrão do PySpark DataFrame para adicionar ou substituir colunas, aceitando expressões de colunas para cálculos complexos.","en-us":"withColumn() is the standard PySpark DataFrame method for adding or replacing columns, accepting column expressions for complex calculations.","es":"withColumn() es el método estándar del PySpark DataFrame para agregar o reemplazar columnas, aceptando expresiones de columnas para cálculos complejos.","fr":"withColumn() est la méthode standard du DataFrame PySpark pour ajouter ou remplacer des colonnes, acceptant des expressions de colonnes pour des calculs complexes."}'),
('Transformar Dados', '{"pt-br":"Você precisa implementar uma arquitetura medallion (bronze, silver, gold) no Lakehouse do Fabric.","en-us":"You need to implement a medallion architecture (bronze, silver, gold) in the Fabric Lakehouse.","es":"Necesita implementar una arquitectura medallion (bronze, silver, gold) en el Lakehouse de Fabric.","fr":"Vous devez implémenter une architecture medallion (bronze, silver, gold) dans le Lakehouse Fabric."}', '{"pt-br":"Qual é a principal transformação aplicada na camada Silver?","en-us":"What is the main transformation applied in the Silver layer?","es":"¿Cuál es la principal transformación aplicada en la capa Silver?","fr":"Quelle est la principale transformation appliquée dans la couche Silver ?"}', '[{"key":"A","text":{"pt-br":"Limpeza, deduplicação e tipagem de dados","en-us":"Cleaning, deduplication, and data typing","es":"Limpieza, deduplicación y tipado de datos","fr":"Nettoyage, déduplication et typage des données"}},{"key":"B","text":{"pt-br":"Agregações para relatórios","en-us":"Aggregations for reports","es":"Agregaciones para informes","fr":"Agrégations pour les rapports"}},{"key":"C","text":{"pt-br":"Ingestão de dados brutos","en-us":"Raw data ingestion","es":"Ingestión de datos brutos","fr":"Ingestion de données brutes"}},{"key":"D","text":{"pt-br":"Modelagem dimensional","en-us":"Dimensional modeling","es":"Modelado dimensional","fr":"Modélisation dimensionnelle"}}]', 'A', '{"pt-br":"A camada Silver aplica limpeza, validação, deduplicação e tipagem correta dos dados. Bronze contém dados brutos, Gold contém dados agregados e modelados para consumo.","en-us":"The Silver layer applies cleaning, validation, deduplication, and correct data typing. Bronze contains raw data, Gold contains aggregated and modeled data for consumption.","es":"La capa Silver aplica limpieza, validación, deduplicación y tipado correcto de datos. Bronze contiene datos brutos, Gold contiene datos agregados y modelados para consumo.","fr":"La couche Silver applique nettoyage, validation, déduplication et typage correct des données. Bronze contient les données brutes, Gold contient les données agrégées et modélisées pour la consommation."}'),
('Transformar Dados', '{"pt-br":"Você precisa particionar uma tabela Delta por data no Lakehouse para otimizar consultas que filtram por período.","en-us":"You need to partition a Delta table by date in the Lakehouse to optimize queries that filter by period.","es":"Necesita particionar una tabla Delta por fecha en el Lakehouse para optimizar consultas que filtran por período.","fr":"Vous devez partitionner une table Delta par date dans le Lakehouse pour optimiser les requêtes filtrant par période."}', '{"pt-br":"Qual método PySpark define o particionamento ao salvar?","en-us":"Which PySpark method defines partitioning when saving?","es":"¿Qué método PySpark define el particionamiento al guardar?","fr":"Quelle méthode PySpark définit le partitionnement lors de la sauvegarde ?"}', '[{"key":"A","text":{"pt-br":"partitionBy()","en-us":"partitionBy()","es":"partitionBy()","fr":"partitionBy()"}},{"key":"B","text":{"pt-br":"groupBy()","en-us":"groupBy()","es":"groupBy()","fr":"groupBy()"}},{"key":"C","text":{"pt-br":"bucketBy()","en-us":"bucketBy()","es":"bucketBy()","fr":"bucketBy()"}},{"key":"D","text":{"pt-br":"splitBy()","en-us":"splitBy()","es":"splitBy()","fr":"splitBy()"}}]', 'A', '{"pt-br":"partitionBy() organiza os dados em diretórios separados por valor da coluna especificada, permitindo que o Spark pule partições irrelevantes (partition pruning) durante consultas.","en-us":"partitionBy() organizes data into separate directories by specified column value, allowing Spark to skip irrelevant partitions (partition pruning) during queries.","es":"partitionBy() organiza los datos en directorios separados por valor de la columna especificada, permitiendo que Spark salte particiones irrelevantes (partition pruning) durante consultas.","fr":"partitionBy() organise les données en répertoires séparés par valeur de colonne spécifiée, permettant à Spark de sauter les partitions non pertinentes (partition pruning) lors des requêtes."}'),
('Transformar Dados', '{"pt-br":"Você precisa aplicar transformações complexas em dados usando SQL no Lakehouse, como window functions e CTEs.","en-us":"You need to apply complex data transformations in the Lakehouse using SQL, like window functions and CTEs.","es":"Necesita aplicar transformaciones complejas en datos del Lakehouse usando SQL, como window functions y CTEs.","fr":"Vous devez appliquer des transformations complexes sur les données du Lakehouse en utilisant SQL, comme les window functions et CTEs."}', '{"pt-br":"Onde você pode executar T-SQL contra tabelas do Lakehouse?","en-us":"Where can you execute T-SQL against Lakehouse tables?","es":"¿Dónde puede ejecutar T-SQL contra tablas del Lakehouse?","fr":"Où pouvez-vous exécuter du T-SQL contre les tables du Lakehouse ?"}', '[{"key":"A","text":{"pt-br":"SQL Analytics Endpoint do Lakehouse","en-us":"Lakehouse SQL Analytics Endpoint","es":"SQL Analytics Endpoint del Lakehouse","fr":"SQL Analytics Endpoint du Lakehouse"}},{"key":"B","text":{"pt-br":"Spark Notebook com magic command %%sql","en-us":"Spark Notebook with magic command %%sql","es":"Spark Notebook con magic command %%sql","fr":"Spark Notebook avec magic command %%sql"}},{"key":"C","text":{"pt-br":"Ambas as opções A e B","en-us":"Both options A and B","es":"Ambas opciones A y B","fr":"Les deux options A et B"}},{"key":"D","text":{"pt-br":"Apenas via Warehouse","en-us":"Only via Warehouse","es":"Solo via Warehouse","fr":"Uniquement via Warehouse"}}]', 'C', '{"pt-br":"Você pode executar SQL tanto no SQL Analytics Endpoint (T-SQL read-only) quanto no Spark Notebook usando %%sql (Spark SQL com suporte a DDL e DML).","en-us":"You can execute SQL both in the SQL Analytics Endpoint (read-only T-SQL) and in Spark Notebook using %%sql (Spark SQL with DDL and DML support).","es":"Puede ejecutar SQL tanto en el SQL Analytics Endpoint (T-SQL de solo lectura) como en Spark Notebook usando %%sql (Spark SQL con soporte DDL y DML).","fr":"Vous pouvez exécuter du SQL à la fois dans le SQL Analytics Endpoint (T-SQL en lecture seule) et dans Spark Notebook en utilisant %%sql (Spark SQL avec support DDL et DML)."}'),
('Transformar Dados', '{"pt-br":"Você precisa viajar no tempo e consultar uma versão anterior de uma tabela Delta para auditoria.","en-us":"You need to time travel and query a previous version of a Delta table for auditing.","es":"Necesita viajar en el tiempo y consultar una versión anterior de una tabla Delta para auditoría.","fr":"Vous devez voyager dans le temps et interroger une version précédente d''une table Delta pour audit."}', '{"pt-br":"Qual sintaxe permite time travel em tabelas Delta?","en-us":"Which syntax allows time travel in Delta tables?","es":"¿Qué sintaxis permite time travel en tablas Delta?","fr":"Quelle syntaxe permet le time travel dans les tables Delta ?"}', '[{"key":"A","text":{"pt-br":"SELECT * FROM table VERSION AS OF 5","en-us":"SELECT * FROM table VERSION AS OF 5","es":"SELECT * FROM table VERSION AS OF 5","fr":"SELECT * FROM table VERSION AS OF 5"}},{"key":"B","text":{"pt-br":"SELECT * FROM table AT VERSION 5","en-us":"SELECT * FROM table AT VERSION 5","es":"SELECT * FROM table AT VERSION 5","fr":"SELECT * FROM table AT VERSION 5"}},{"key":"C","text":{"pt-br":"SELECT * FROM table ROLLBACK TO 5","en-us":"SELECT * FROM table ROLLBACK TO 5","es":"SELECT * FROM table ROLLBACK TO 5","fr":"SELECT * FROM table ROLLBACK TO 5"}},{"key":"D","text":{"pt-br":"SELECT * FROM table HISTORY(5)","en-us":"SELECT * FROM table HISTORY(5)","es":"SELECT * FROM table HISTORY(5)","fr":"SELECT * FROM table HISTORY(5)"}}]', 'A', '{"pt-br":"Delta Lake suporta time travel usando VERSION AS OF (por número de versão) ou TIMESTAMP AS OF (por data/hora) para consultar estados anteriores dos dados.","en-us":"Delta Lake supports time travel using VERSION AS OF (by version number) or TIMESTAMP AS OF (by date/time) to query previous data states.","es":"Delta Lake soporta time travel usando VERSION AS OF (por número de versión) o TIMESTAMP AS OF (por fecha/hora) para consultar estados anteriores de los datos.","fr":"Delta Lake supporte le time travel en utilisant VERSION AS OF (par numéro de version) ou TIMESTAMP AS OF (par date/heure) pour interroger les états précédents des données."}'),
('Transformar Dados', '{"pt-br":"Você precisa transformar dados no Dataflow Gen2 removendo linhas duplicadas com base em uma combinação de colunas.","en-us":"You need to transform data in Dataflow Gen2 by removing duplicate rows based on a column combination.","es":"Necesita transformar datos en Dataflow Gen2 eliminando filas duplicadas basándose en una combinación de columnas.","fr":"Vous devez transformer des données dans Dataflow Gen2 en supprimant les lignes dupliquées basées sur une combinaison de colonnes."}', '{"pt-br":"Qual operação do Power Query é usada para deduplicação?","en-us":"Which Power Query operation is used for deduplication?","es":"¿Qué operación de Power Query se usa para deduplicación?","fr":"Quelle opération Power Query est utilisée pour la déduplication ?"}', '[{"key":"A","text":{"pt-br":"Remove Duplicates","en-us":"Remove Duplicates","es":"Remove Duplicates","fr":"Remove Duplicates"}},{"key":"B","text":{"pt-br":"Group By com Count","en-us":"Group By with Count","es":"Group By con Count","fr":"Group By avec Count"}},{"key":"C","text":{"pt-br":"Filter Rows","en-us":"Filter Rows","es":"Filter Rows","fr":"Filter Rows"}},{"key":"D","text":{"pt-br":"Distinct Values","en-us":"Distinct Values","es":"Distinct Values","fr":"Distinct Values"}}]', 'A', '{"pt-br":"Remove Duplicates no Power Query permite selecionar colunas-chave e remover linhas duplicadas, mantendo apenas a primeira ocorrência de cada combinação de valores.","en-us":"Remove Duplicates in Power Query allows selecting key columns and removing duplicate rows, keeping only the first occurrence of each value combination.","es":"Remove Duplicates en Power Query permite seleccionar columnas clave y eliminar filas duplicadas, manteniendo solo la primera ocurrencia de cada combinación de valores.","fr":"Remove Duplicates dans Power Query permet de sélectionner les colonnes clés et de supprimer les lignes dupliquées, ne gardant que la première occurrence de chaque combinaison de valeurs."}'),
('Transformar Dados', '{"pt-br":"Você precisa criar uma view no Lakehouse que combine dados de múltiplas tabelas Delta para simplificar consultas downstream.","en-us":"You need to create a view in the Lakehouse that combines data from multiple Delta tables to simplify downstream queries.","es":"Necesita crear una vista en el Lakehouse que combine datos de múltiples tablas Delta para simplificar consultas downstream.","fr":"Vous devez créer une vue dans le Lakehouse combinant des données de plusieurs tables Delta pour simplifier les requêtes en aval."}', '{"pt-br":"Onde views podem ser criadas no contexto do Lakehouse?","en-us":"Where can views be created in the Lakehouse context?","es":"¿Dónde pueden crearse vistas en el contexto del Lakehouse?","fr":"Où les vues peuvent-elles être créées dans le contexte du Lakehouse ?"}', '[{"key":"A","text":{"pt-br":"No SQL Analytics Endpoint usando CREATE VIEW","en-us":"In SQL Analytics Endpoint using CREATE VIEW","es":"En el SQL Analytics Endpoint usando CREATE VIEW","fr":"Dans le SQL Analytics Endpoint en utilisant CREATE VIEW"}},{"key":"B","text":{"pt-br":"No Spark Notebook usando CREATE VIEW","en-us":"In Spark Notebook using CREATE VIEW","es":"En el Spark Notebook usando CREATE VIEW","fr":"Dans le Spark Notebook en utilisant CREATE VIEW"}},{"key":"C","text":{"pt-br":"Em ambos SQL Analytics Endpoint e Spark","en-us":"In both SQL Analytics Endpoint and Spark","es":"En ambos SQL Analytics Endpoint y Spark","fr":"Dans les deux, SQL Analytics Endpoint et Spark"}},{"key":"D","text":{"pt-br":"Views não são suportadas no Lakehouse","en-us":"Views are not supported in the Lakehouse","es":"Las vistas no son soportadas en el Lakehouse","fr":"Les vues ne sont pas supportées dans le Lakehouse"}}]', 'C', '{"pt-br":"Views podem ser criadas tanto no SQL Analytics Endpoint (T-SQL views) quanto no Spark Notebook (temporary views ou views persistentes), cada um com seu escopo.","en-us":"Views can be created in both SQL Analytics Endpoint (T-SQL views) and Spark Notebook (temporary views or persistent views), each with its own scope.","es":"Las vistas pueden crearse tanto en SQL Analytics Endpoint (T-SQL views) como en Spark Notebook (temporary views o views persistentes), cada una con su propio alcance.","fr":"Les vues peuvent être créées dans le SQL Analytics Endpoint (T-SQL views) et dans Spark Notebook (vues temporaires ou persistantes), chacune avec sa propre portée."}'),
('Transformar Dados', '{"pt-br":"Você precisa converter uma coluna de string para tipo date em um DataFrame PySpark.","en-us":"You need to convert a string column to date type in a PySpark DataFrame.","es":"Necesita convertir una columna de string a tipo date en un DataFrame PySpark.","fr":"Vous devez convertir une colonne de chaîne en type date dans un DataFrame PySpark."}', '{"pt-br":"Qual função PySpark converte string para date?","en-us":"Which PySpark function converts string to date?","es":"¿Qué función PySpark convierte string a date?","fr":"Quelle fonction PySpark convertit une chaîne en date ?"}', '[{"key":"A","text":{"pt-br":"to_date()","en-us":"to_date()","es":"to_date()","fr":"to_date()"}},{"key":"B","text":{"pt-br":"cast(''date'')","en-us":"cast(''date'')","es":"cast(''date'')","fr":"cast(''date'')"}},{"key":"C","text":{"pt-br":"Ambos A e B funcionam","en-us":"Both A and B work","es":"Ambos A y B funcionan","fr":"Les deux A et B fonctionnent"}},{"key":"D","text":{"pt-br":"convert_date()","en-us":"convert_date()","es":"convert_date()","fr":"convert_date()"}}]', 'C', '{"pt-br":"Ambos to_date() e cast(''date'') convertem strings para date. to_date() aceita formato customizado como parâmetro, cast() usa o formato ISO padrão.","en-us":"Both to_date() and cast(''date'') convert strings to date. to_date() accepts a custom format parameter, cast() uses the standard ISO format.","es":"Ambos to_date() y cast(''date'') convierten strings a date. to_date() acepta formato personalizado como parámetro, cast() usa el formato ISO estándar.","fr":"Les deux to_date() et cast(''date'') convertissent des chaînes en date. to_date() accepte un format personnalisé en paramètre, cast() utilise le format ISO standard."}'),
('Transformar Dados', '{"pt-br":"Você precisa aplicar Z-Order em uma tabela Delta para otimizar consultas que filtram frequentemente por uma coluna específica.","en-us":"You need to apply Z-Order on a Delta table to optimize queries that frequently filter by a specific column.","es":"Necesita aplicar Z-Order en una tabla Delta para optimizar consultas que filtran frecuentemente por una columna específica.","fr":"Vous devez appliquer le Z-Order sur une table Delta pour optimiser les requêtes filtrant fréquemment par une colonne spécifique."}', '{"pt-br":"Qual comando aplica Z-Order em uma tabela Delta?","en-us":"Which command applies Z-Order on a Delta table?","es":"¿Qué comando aplica Z-Order en una tabla Delta?","fr":"Quelle commande applique le Z-Order sur une table Delta ?"}', '[{"key":"A","text":{"pt-br":"OPTIMIZE table ZORDER BY (column)","en-us":"OPTIMIZE table ZORDER BY (column)","es":"OPTIMIZE table ZORDER BY (column)","fr":"OPTIMIZE table ZORDER BY (column)"}},{"key":"B","text":{"pt-br":"ALTER TABLE table ZORDER BY (column)","en-us":"ALTER TABLE table ZORDER BY (column)","es":"ALTER TABLE table ZORDER BY (column)","fr":"ALTER TABLE table ZORDER BY (column)"}},{"key":"C","text":{"pt-br":"CREATE INDEX ON table (column)","en-us":"CREATE INDEX ON table (column)","es":"CREATE INDEX ON table (column)","fr":"CREATE INDEX ON table (column)"}},{"key":"D","text":{"pt-br":"SET TBLPROPERTIES (''zorder'' = ''column'')","en-us":"SET TBLPROPERTIES (''zorder'' = ''column'')","es":"SET TBLPROPERTIES (''zorder'' = ''column'')","fr":"SET TBLPROPERTIES (''zorder'' = ''column'')"}}]', 'A', '{"pt-br":"Z-Order é aplicado junto com OPTIMIZE, co-localizando dados relacionados nos mesmos arquivos para minimizar I/O em consultas com filtros na coluna especificada.","en-us":"Z-Order is applied with OPTIMIZE, co-locating related data in the same files to minimize I/O in queries filtering on the specified column.","es":"Z-Order se aplica junto con OPTIMIZE, co-localizando datos relacionados en los mismos archivos para minimizar I/O en consultas con filtros en la columna especificada.","fr":"Le Z-Order est appliqué avec OPTIMIZE, co-localisant les données liées dans les mêmes fichiers pour minimiser les I/O dans les requêtes filtrant sur la colonne spécifiée."}'),
('Transformar Dados', '{"pt-br":"Você precisa implementar SCD Type 2 (Slowly Changing Dimension) em uma tabela de clientes no Lakehouse.","en-us":"You need to implement SCD Type 2 (Slowly Changing Dimension) on a customer table in the Lakehouse.","es":"Necesita implementar SCD Type 2 (Slowly Changing Dimension) en una tabla de clientes en el Lakehouse.","fr":"Vous devez implémenter SCD Type 2 (Slowly Changing Dimension) sur une table de clients dans le Lakehouse."}', '{"pt-br":"Qual abordagem é mais eficiente para SCD Type 2 em Delta Lake?","en-us":"Which approach is most efficient for SCD Type 2 in Delta Lake?","es":"¿Qué enfoque es más eficiente para SCD Type 2 en Delta Lake?","fr":"Quelle approche est la plus efficace pour SCD Type 2 dans Delta Lake ?"}', '[{"key":"A","text":{"pt-br":"MERGE INTO com cláusulas WHEN MATCHED e WHEN NOT MATCHED","en-us":"MERGE INTO with WHEN MATCHED and WHEN NOT MATCHED clauses","es":"MERGE INTO con cláusulas WHEN MATCHED y WHEN NOT MATCHED","fr":"MERGE INTO avec clauses WHEN MATCHED et WHEN NOT MATCHED"}},{"key":"B","text":{"pt-br":"DELETE e INSERT separados","en-us":"Separate DELETE and INSERT","es":"DELETE e INSERT separados","fr":"DELETE et INSERT séparés"}},{"key":"C","text":{"pt-br":"UPDATE direto","en-us":"Direct UPDATE","es":"UPDATE directo","fr":"UPDATE direct"}},{"key":"D","text":{"pt-br":"Recriar tabela completa","en-us":"Recreate entire table","es":"Recrear tabla completa","fr":"Recréer la table entière"}}]', 'A', '{"pt-br":"MERGE INTO com múltiplas cláusulas permite fechar registros antigos (WHEN MATCHED) e inserir novos registros (WHEN NOT MATCHED) em uma operação atômica, ideal para SCD Type 2.","en-us":"MERGE INTO with multiple clauses allows closing old records (WHEN MATCHED) and inserting new records (WHEN NOT MATCHED) in an atomic operation, ideal for SCD Type 2.","es":"MERGE INTO con múltiples cláusulas permite cerrar registros antiguos (WHEN MATCHED) e insertar nuevos registros (WHEN NOT MATCHED) en una operación atómica, ideal para SCD Type 2.","fr":"MERGE INTO avec plusieurs clauses permet de fermer les anciens enregistrements (WHEN MATCHED) et d''insérer de nouveaux (WHEN NOT MATCHED) en une opération atomique, idéal pour SCD Type 2."}'),
('Transformar Dados', '{"pt-br":"Você precisa lidar com valores nulos em um DataFrame PySpark, substituindo-os por valores padrão.","en-us":"You need to handle null values in a PySpark DataFrame, replacing them with default values.","es":"Necesita manejar valores nulos en un DataFrame PySpark, reemplazándolos con valores predeterminados.","fr":"Vous devez gérer les valeurs nulles dans un DataFrame PySpark, les remplaçant par des valeurs par défaut."}', '{"pt-br":"Qual método é usado para substituir valores nulos?","en-us":"Which method is used to replace null values?","es":"¿Qué método se usa para reemplazar valores nulos?","fr":"Quelle méthode est utilisée pour remplacer les valeurs nulles ?"}', '[{"key":"A","text":{"pt-br":"fillna() ou na.fill()","en-us":"fillna() or na.fill()","es":"fillna() o na.fill()","fr":"fillna() ou na.fill()"}},{"key":"B","text":{"pt-br":"replaceNull()","en-us":"replaceNull()","es":"replaceNull()","fr":"replaceNull()"}},{"key":"C","text":{"pt-br":"coalesce()","en-us":"coalesce()","es":"coalesce()","fr":"coalesce()"}},{"key":"D","text":{"pt-br":"ifnull()","en-us":"ifnull()","es":"ifnull()","fr":"ifnull()"}}]', 'A', '{"pt-br":"fillna() (ou df.na.fill()) é o método padrão do PySpark para substituir valores nulos. Aceita um valor escalar ou um dicionário com valores diferentes por coluna.","en-us":"fillna() (or df.na.fill()) is the standard PySpark method for replacing null values. It accepts a scalar value or a dictionary with different values per column.","es":"fillna() (o df.na.fill()) es el método estándar de PySpark para reemplazar valores nulos. Acepta un valor escalar o un diccionario con valores diferentes por columna.","fr":"fillna() (ou df.na.fill()) est la méthode standard PySpark pour remplacer les valeurs nulles. Elle accepte une valeur scalaire ou un dictionnaire avec des valeurs différentes par colonne."}'),
('Transformar Dados', '{"pt-br":"Você precisa criar uma tabela calculada no Warehouse do Fabric que é atualizada automaticamente quando as tabelas fonte mudam.","en-us":"You need to create a calculated table in the Fabric Warehouse that automatically updates when source tables change.","es":"Necesita crear una tabla calculada en el Warehouse de Fabric que se actualice automáticamente cuando las tablas fuente cambien.","fr":"Vous devez créer une table calculée dans le Warehouse Fabric qui se met à jour automatiquement quand les tables source changent."}', '{"pt-br":"Qual objeto T-SQL no Warehouse se comporta como uma tabela calculada em tempo de leitura?","en-us":"Which T-SQL object in the Warehouse behaves like a calculated table at read time?","es":"¿Qué objeto T-SQL en el Warehouse se comporta como una tabla calculada en tiempo de lectura?","fr":"Quel objet T-SQL dans le Warehouse se comporte comme une table calculée en lecture ?"}', '[{"key":"A","text":{"pt-br":"View","en-us":"View","es":"View","fr":"View"}},{"key":"B","text":{"pt-br":"Materialized View","en-us":"Materialized View","es":"Materialized View","fr":"Materialized View"}},{"key":"C","text":{"pt-br":"Stored Procedure","en-us":"Stored Procedure","es":"Stored Procedure","fr":"Stored Procedure"}},{"key":"D","text":{"pt-br":"Temporary Table","en-us":"Temporary Table","es":"Temporary Table","fr":"Temporary Table"}}]', 'A', '{"pt-br":"Views são consultas salvas que retornam dados em tempo de leitura, sempre refletindo o estado atual das tabelas fonte sem necessidade de refresh manual.","en-us":"Views are saved queries that return data at read time, always reflecting the current state of source tables without manual refresh.","es":"Las Views son consultas guardadas que retornan datos en tiempo de lectura, siempre reflejando el estado actual de las tablas fuente sin necesidad de refresh manual.","fr":"Les Views sont des requêtes sauvegardées qui retournent les données en lecture, reflétant toujours l''état actuel des tables source sans rafraîchissement manuel."}'),
('Transformar Dados', '{"pt-br":"Você precisa unir dois DataFrames PySpark usando uma coluna em comum, mantendo todos os registros da tabela esquerda.","en-us":"You need to join two PySpark DataFrames using a common column, keeping all records from the left table.","es":"Necesita unir dos DataFrames PySpark usando una columna en común, manteniendo todos los registros de la tabla izquierda.","fr":"Vous devez joindre deux DataFrames PySpark en utilisant une colonne commune, en conservant tous les enregistrements de la table gauche."}', '{"pt-br":"Qual tipo de join deve ser usado?","en-us":"Which type of join should be used?","es":"¿Qué tipo de join debe usarse?","fr":"Quel type de jointure doit être utilisé ?"}', '[{"key":"A","text":{"pt-br":"left join","en-us":"left join","es":"left join","fr":"left join"}},{"key":"B","text":{"pt-br":"inner join","en-us":"inner join","es":"inner join","fr":"inner join"}},{"key":"C","text":{"pt-br":"cross join","en-us":"cross join","es":"cross join","fr":"cross join"}},{"key":"D","text":{"pt-br":"semi join","en-us":"semi join","es":"semi join","fr":"semi join"}}]', 'A', '{"pt-br":"Left join mantém todos os registros do DataFrame esquerdo, preenchendo com null as colunas do DataFrame direito quando não há correspondência.","en-us":"Left join keeps all records from the left DataFrame, filling with null the right DataFrame columns when there''s no match.","es":"Left join mantiene todos los registros del DataFrame izquierdo, llenando con null las columnas del DataFrame derecho cuando no hay correspondencia.","fr":"Left join conserve tous les enregistrements du DataFrame gauche, remplissant avec null les colonnes du DataFrame droit quand il n''y a pas de correspondance."}'),
('Transformar Dados', '{"pt-br":"Você precisa alterar o schema de uma tabela Delta existente, adicionando uma nova coluna sem recriar a tabela.","en-us":"You need to alter the schema of an existing Delta table, adding a new column without recreating the table.","es":"Necesita alterar el schema de una tabla Delta existente, agregando una nueva columna sin recrear la tabla.","fr":"Vous devez modifier le schéma d''une table Delta existante, en ajoutant une nouvelle colonne sans recréer la table."}', '{"pt-br":"Qual opção permite evolução de schema no Delta Lake?","en-us":"Which option enables schema evolution in Delta Lake?","es":"¿Qué opción permite evolución de schema en Delta Lake?","fr":"Quelle option permet l''évolution de schéma dans Delta Lake ?"}', '[{"key":"A","text":{"pt-br":"mergeSchema = true ou overwriteSchema = true","en-us":"mergeSchema = true or overwriteSchema = true","es":"mergeSchema = true o overwriteSchema = true","fr":"mergeSchema = true ou overwriteSchema = true"}},{"key":"B","text":{"pt-br":"ALTER TABLE ADD COLUMN","en-us":"ALTER TABLE ADD COLUMN","es":"ALTER TABLE ADD COLUMN","fr":"ALTER TABLE ADD COLUMN"}},{"key":"C","text":{"pt-br":"Ambos A e B","en-us":"Both A and B","es":"Ambos A y B","fr":"Les deux A et B"}},{"key":"D","text":{"pt-br":"Não é possível alterar o schema","en-us":"Schema cannot be altered","es":"No es posible alterar el schema","fr":"Le schéma ne peut pas être modifié"}}]', 'C', '{"pt-br":"Ambas as abordagens funcionam: mergeSchema/overwriteSchema na operação de escrita evolui o schema automaticamente, e ALTER TABLE ADD COLUMN adiciona colunas explicitamente.","en-us":"Both approaches work: mergeSchema/overwriteSchema in write operations evolves the schema automatically, and ALTER TABLE ADD COLUMN adds columns explicitly.","es":"Ambos enfoques funcionan: mergeSchema/overwriteSchema en operaciones de escritura evoluciona el schema automáticamente, y ALTER TABLE ADD COLUMN agrega columnas explícitamente.","fr":"Les deux approches fonctionnent : mergeSchema/overwriteSchema dans les opérations d''écriture fait évoluer le schéma automatiquement, et ALTER TABLE ADD COLUMN ajoute des colonnes explicitement."}'),
('Transformar Dados', '{"pt-br":"Você precisa garantir que uma transformação Spark processe apenas dados que foram modificados desde a última execução.","en-us":"You need to ensure a Spark transformation processes only data modified since the last execution.","es":"Necesita garantizar que una transformación Spark procese solo datos modificados desde la última ejecución.","fr":"Vous devez garantir qu''une transformation Spark ne traite que les données modifiées depuis la dernière exécution."}', '{"pt-br":"Qual recurso do Delta Lake suporta processamento incremental?","en-us":"Which Delta Lake feature supports incremental processing?","es":"¿Qué recurso de Delta Lake soporta procesamiento incremental?","fr":"Quelle fonctionnalité de Delta Lake supporte le traitement incrémentiel ?"}', '[{"key":"A","text":{"pt-br":"Change Data Feed (CDF)","en-us":"Change Data Feed (CDF)","es":"Change Data Feed (CDF)","fr":"Change Data Feed (CDF)"}},{"key":"B","text":{"pt-br":"Auto Loader","en-us":"Auto Loader","es":"Auto Loader","fr":"Auto Loader"}},{"key":"C","text":{"pt-br":"Delta Streaming","en-us":"Delta Streaming","es":"Delta Streaming","fr":"Delta Streaming"}},{"key":"D","text":{"pt-br":"Watermarking","en-us":"Watermarking","es":"Watermarking","fr":"Watermarking"}}]', 'A', '{"pt-br":"Change Data Feed (CDF) captura automaticamente as mudanças (inserts, updates, deletes) em tabelas Delta, permitindo processamento incremental eficiente downstream.","en-us":"Change Data Feed (CDF) automatically captures changes (inserts, updates, deletes) in Delta tables, enabling efficient downstream incremental processing.","es":"Change Data Feed (CDF) captura automáticamente los cambios (inserts, updates, deletes) en tablas Delta, permitiendo procesamiento incremental eficiente downstream.","fr":"Change Data Feed (CDF) capture automatiquement les modifications (inserts, updates, deletes) dans les tables Delta, permettant un traitement incrémentiel efficace en aval."}'),
('Transformar Dados', '{"pt-br":"Você precisa pivotar dados no Power Query, transformando valores de linhas em colunas para criar uma tabela de resumo.","en-us":"You need to pivot data in Power Query, transforming row values into columns to create a summary table.","es":"Necesita pivotar datos en Power Query, transformando valores de filas en columnas para crear una tabla de resumen.","fr":"Vous devez pivoter des données dans Power Query, transformant les valeurs de lignes en colonnes pour créer une table de résumé."}', '{"pt-br":"Qual operação do Power Query transforma linhas em colunas?","en-us":"Which Power Query operation transforms rows into columns?","es":"¿Qué operación de Power Query transforma filas en columnas?","fr":"Quelle opération Power Query transforme les lignes en colonnes ?"}', '[{"key":"A","text":{"pt-br":"Pivot Column","en-us":"Pivot Column","es":"Pivot Column","fr":"Pivot Column"}},{"key":"B","text":{"pt-br":"Unpivot Column","en-us":"Unpivot Column","es":"Unpivot Column","fr":"Unpivot Column"}},{"key":"C","text":{"pt-br":"Transpose","en-us":"Transpose","es":"Transpose","fr":"Transpose"}},{"key":"D","text":{"pt-br":"Group By","en-us":"Group By","es":"Group By","fr":"Group By"}}]', 'A', '{"pt-br":"Pivot Column transforma valores distintos de uma coluna em novas colunas, agregando os valores correspondentes. Unpivot faz o inverso.","en-us":"Pivot Column transforms distinct values from a column into new columns, aggregating corresponding values. Unpivot does the reverse.","es":"Pivot Column transforma valores distintos de una columna en nuevas columnas, agregando los valores correspondientes. Unpivot hace lo inverso.","fr":"Pivot Column transforme les valeurs distinctes d''une colonne en nouvelles colonnes, agrégeant les valeurs correspondantes. Unpivot fait l''inverse."}'),
('Transformar Dados', '{"pt-br":"Você precisa escrever dados em modo append em uma tabela Delta existente sem sobrescrever os dados anteriores.","en-us":"You need to write data in append mode to an existing Delta table without overwriting previous data.","es":"Necesita escribir datos en modo append en una tabla Delta existente sin sobrescribir los datos anteriores.","fr":"Vous devez écrire des données en mode append dans une table Delta existante sans écraser les données précédentes."}', '{"pt-br":"Qual modo de escrita deve ser usado?","en-us":"Which write mode should be used?","es":"¿Qué modo de escritura debe usarse?","fr":"Quel mode d''écriture doit être utilisé ?"}', '[{"key":"A","text":{"pt-br":"mode(''append'')","en-us":"mode(''append'')","es":"mode(''append'')","fr":"mode(''append'')"}},{"key":"B","text":{"pt-br":"mode(''overwrite'')","en-us":"mode(''overwrite'')","es":"mode(''overwrite'')","fr":"mode(''overwrite'')"}},{"key":"C","text":{"pt-br":"mode(''insert'')","en-us":"mode(''insert'')","es":"mode(''insert'')","fr":"mode(''insert'')"}},{"key":"D","text":{"pt-br":"mode(''merge'')","en-us":"mode(''merge'')","es":"mode(''merge'')","fr":"mode(''merge'')"}}]', 'A', '{"pt-br":"mode(''append'') adiciona novos dados à tabela sem alterar os existentes. mode(''overwrite'') substitui todos os dados. Os modos ''insert'' e ''merge'' não existem como save modes.","en-us":"mode(''append'') adds new data to the table without altering existing data. mode(''overwrite'') replaces all data. ''insert'' and ''merge'' don''t exist as save modes.","es":"mode(''append'') agrega nuevos datos a la tabla sin alterar los existentes. mode(''overwrite'') reemplaza todos los datos. Los modos ''insert'' y ''merge'' no existen como save modes.","fr":"mode(''append'') ajoute de nouvelles données à la table sans modifier les existantes. mode(''overwrite'') remplace toutes les données. Les modes ''insert'' et ''merge'' n''existent pas comme modes de sauvegarde."}'),
('Consultar e Analisar', '{"pt-br":"Você precisa analisar dados de log em tempo real usando uma linguagem otimizada para consultas ad-hoc em grandes volumes.","en-us":"You need to analyze real-time log data using a language optimized for ad-hoc queries on large volumes.","es":"Necesita analizar datos de log en tiempo real usando un lenguaje optimizado para consultas ad-hoc en grandes volúmenes.","fr":"Vous devez analyser des données de log en temps réel en utilisant un langage optimisé pour les requêtes ad-hoc sur de grands volumes."}', '{"pt-br":"Qual linguagem de consulta é usada no Real-Time Analytics do Fabric?","en-us":"Which query language is used in Fabric''s Real-Time Analytics?","es":"¿Qué lenguaje de consulta se usa en Real-Time Analytics de Fabric?","fr":"Quel langage de requête est utilisé dans Real-Time Analytics de Fabric ?"}', '[{"key":"A","text":{"pt-br":"KQL (Kusto Query Language)","en-us":"KQL (Kusto Query Language)","es":"KQL (Kusto Query Language)","fr":"KQL (Kusto Query Language)"}},{"key":"B","text":{"pt-br":"T-SQL","en-us":"T-SQL","es":"T-SQL","fr":"T-SQL"}},{"key":"C","text":{"pt-br":"PySpark","en-us":"PySpark","es":"PySpark","fr":"PySpark"}},{"key":"D","text":{"pt-br":"DAX","en-us":"DAX","es":"DAX","fr":"DAX"}}]', 'A', '{"pt-br":"KQL é a linguagem nativa do Real-Time Analytics (KQL Database/Eventhouse) no Fabric, otimizada para consultas rápidas em grandes volumes de dados de telemetria e logs.","en-us":"KQL is the native language of Real-Time Analytics (KQL Database/Eventhouse) in Fabric, optimized for fast queries on large volumes of telemetry and log data.","es":"KQL es el lenguaje nativo de Real-Time Analytics (KQL Database/Eventhouse) en Fabric, optimizado para consultas rápidas en grandes volúmenes de datos de telemetría y logs.","fr":"KQL est le langage natif de Real-Time Analytics (KQL Database/Eventhouse) dans Fabric, optimisé pour les requêtes rapides sur de grands volumes de données de télémétrie et logs."}'),
('Consultar e Analisar', '{"pt-br":"Você precisa calcular o total de vendas acumuladas do ano até a data atual em um modelo semântico.","en-us":"You need to calculate year-to-date accumulated sales total in a semantic model.","es":"Necesita calcular el total de ventas acumuladas del año hasta la fecha actual en un modelo semántico.","fr":"Vous devez calculer le total cumulé des ventes de l''année à ce jour dans un modèle sémantique."}', '{"pt-br":"Qual função DAX é a mais adequada?","en-us":"Which DAX function is most appropriate?","es":"¿Qué función DAX es la más adecuada?","fr":"Quelle fonction DAX est la plus appropriée ?"}', '[{"key":"A","text":{"pt-br":"TOTALYTD","en-us":"TOTALYTD","es":"TOTALYTD","fr":"TOTALYTD"}},{"key":"B","text":{"pt-br":"SUMX","en-us":"SUMX","es":"SUMX","fr":"SUMX"}},{"key":"C","text":{"pt-br":"CALCULATE com FILTER","en-us":"CALCULATE with FILTER","es":"CALCULATE con FILTER","fr":"CALCULATE avec FILTER"}},{"key":"D","text":{"pt-br":"RANKX","en-us":"RANKX","es":"RANKX","fr":"RANKX"}}]', 'A', '{"pt-br":"TOTALYTD é uma função de inteligência temporal que calcula automaticamente o acumulado do ano. SUMX itera sobre linhas, CALCULATE com FILTER é mais verboso.","en-us":"TOTALYTD is a time intelligence function that automatically calculates year-to-date accumulation. SUMX iterates over rows, CALCULATE with FILTER is more verbose.","es":"TOTALYTD es una función de inteligencia temporal que calcula automáticamente el acumulado del año. SUMX itera sobre filas, CALCULATE con FILTER es más verboso.","fr":"TOTALYTD est une fonction d''intelligence temporelle qui calcule automatiquement le cumul annuel. SUMX itère sur les lignes, CALCULATE avec FILTER est plus verbeux."}'),
('Consultar e Analisar', '{"pt-br":"Você precisa criar uma medida DAX que calcule a variação percentual das vendas em relação ao mês anterior.","en-us":"You need to create a DAX measure that calculates the percentage change in sales compared to the previous month.","es":"Necesita crear una medida DAX que calcule la variación porcentual de ventas en relación al mes anterior.","fr":"Vous devez créer une mesure DAX qui calcule la variation en pourcentage des ventes par rapport au mois précédent."}', '{"pt-br":"Qual combinação de funções DAX é necessária?","en-us":"Which combination of DAX functions is needed?","es":"¿Qué combinación de funciones DAX es necesaria?","fr":"Quelle combinaison de fonctions DAX est nécessaire ?"}', '[{"key":"A","text":{"pt-br":"DIVIDE e CALCULATE com DATEADD","en-us":"DIVIDE and CALCULATE with DATEADD","es":"DIVIDE y CALCULATE con DATEADD","fr":"DIVIDE et CALCULATE avec DATEADD"}},{"key":"B","text":{"pt-br":"PERCENTILE e PREVIOUSMONTH","en-us":"PERCENTILE and PREVIOUSMONTH","es":"PERCENTILE y PREVIOUSMONTH","fr":"PERCENTILE et PREVIOUSMONTH"}},{"key":"C","text":{"pt-br":"VAR e RETURN com SUM","en-us":"VAR and RETURN with SUM","es":"VAR y RETURN con SUM","fr":"VAR et RETURN avec SUM"}},{"key":"D","text":{"pt-br":"GROWTH e CALCULATE","en-us":"GROWTH and CALCULATE","es":"GROWTH y CALCULATE","fr":"GROWTH et CALCULATE"}}]', 'A', '{"pt-br":"CALCULATE com DATEADD(-1, MONTH) obtém o valor do mês anterior, e DIVIDE calcula a variação percentual de forma segura, tratando divisão por zero.","en-us":"CALCULATE with DATEADD(-1, MONTH) gets the previous month''s value, and DIVIDE calculates percentage change safely, handling division by zero.","es":"CALCULATE con DATEADD(-1, MONTH) obtiene el valor del mes anterior, y DIVIDE calcula la variación porcentual de forma segura, tratando la división por cero.","fr":"CALCULATE avec DATEADD(-1, MONTH) obtient la valeur du mois précédent, et DIVIDE calcule la variation en pourcentage de manière sécurisée, gérant la division par zéro."}'),
('Consultar e Analisar', '{"pt-br":"Você precisa criar uma consulta no Notebook para encontrar os top 10 produtos mais vendidos agrupados por categoria.","en-us":"You need to create a query in Notebook to find the top 10 best-selling products grouped by category.","es":"Necesita crear una consulta en Notebook para encontrar los top 10 productos más vendidos agrupados por categoría.","fr":"Vous devez créer une requête dans Notebook pour trouver les 10 produits les plus vendus groupés par catégorie."}', '{"pt-br":"Qual combinação de operações Spark SQL é necessária?","en-us":"Which combination of Spark SQL operations is needed?","es":"¿Qué combinación de operaciones Spark SQL es necesaria?","fr":"Quelle combinaison d''opérations Spark SQL est nécessaire ?"}', '[{"key":"A","text":{"pt-br":"GROUP BY, ORDER BY DESC e LIMIT 10","en-us":"GROUP BY, ORDER BY DESC and LIMIT 10","es":"GROUP BY, ORDER BY DESC y LIMIT 10","fr":"GROUP BY, ORDER BY DESC et LIMIT 10"}},{"key":"B","text":{"pt-br":"WINDOW FUNCTION com RANK()","en-us":"WINDOW FUNCTION with RANK()","es":"WINDOW FUNCTION con RANK()","fr":"WINDOW FUNCTION avec RANK()"}},{"key":"C","text":{"pt-br":"TOP 10 com GROUP BY","en-us":"TOP 10 with GROUP BY","es":"TOP 10 con GROUP BY","fr":"TOP 10 avec GROUP BY"}},{"key":"D","text":{"pt-br":"HAVING com COUNT > 10","en-us":"HAVING with COUNT > 10","es":"HAVING con COUNT > 10","fr":"HAVING avec COUNT > 10"}}]', 'A', '{"pt-br":"Em Spark SQL, GROUP BY agrupa, SUM calcula o total de vendas, ORDER BY DESC ordena do maior para menor, e LIMIT 10 retorna apenas os 10 primeiros (TOP não é Spark SQL).","en-us":"In Spark SQL, GROUP BY groups, SUM calculates total sales, ORDER BY DESC sorts highest to lowest, and LIMIT 10 returns only the first 10 (TOP is not Spark SQL syntax).","es":"En Spark SQL, GROUP BY agrupa, SUM calcula el total de ventas, ORDER BY DESC ordena de mayor a menor, y LIMIT 10 retorna solo los 10 primeros (TOP no es sintaxis Spark SQL).","fr":"En Spark SQL, GROUP BY groupe, SUM calcule le total des ventes, ORDER BY DESC trie du plus grand au plus petit, et LIMIT 10 retourne uniquement les 10 premiers (TOP n''est pas syntaxe Spark SQL)."}'),
('Consultar e Analisar', '{"pt-br":"Você precisa criar uma medida DAX que retorne valores diferentes dependendo de uma seleção do slicer (vendas brutas vs. líquidas).","en-us":"You need to create a DAX measure that returns different values depending on a slicer selection (gross vs. net sales).","es":"Necesita crear una medida DAX que retorne valores diferentes dependiendo de una selección del slicer (ventas brutas vs. netas).","fr":"Vous devez créer une mesure DAX qui retourne des valeurs différentes selon une sélection de slicer (ventes brutes vs. nettes)."}', '{"pt-br":"Qual função DAX é mais apropriada para lógica condicional em medidas?","en-us":"Which DAX function is most appropriate for conditional logic in measures?","es":"¿Qué función DAX es más apropiada para lógica condicional en medidas?","fr":"Quelle fonction DAX est la plus appropriée pour la logique conditionnelle dans les mesures ?"}', '[{"key":"A","text":{"pt-br":"SWITCH","en-us":"SWITCH","es":"SWITCH","fr":"SWITCH"}},{"key":"B","text":{"pt-br":"IF com múltiplos aninhamentos","en-us":"IF with multiple nesting","es":"IF con múltiples anidamientos","fr":"IF avec imbrications multiples"}},{"key":"C","text":{"pt-br":"CALCULATE com filtros","en-us":"CALCULATE with filters","es":"CALCULATE con filtros","fr":"CALCULATE avec filtres"}},{"key":"D","text":{"pt-br":"SELECTEDVALUE com COALESCE","en-us":"SELECTEDVALUE with COALESCE","es":"SELECTEDVALUE con COALESCE","fr":"SELECTEDVALUE avec COALESCE"}}]', 'A', '{"pt-br":"SWITCH é mais legível e eficiente que múltiplos IF aninhados para lógica condicional com várias opções, sendo ideal para alternar entre cálculos baseados em seleções.","en-us":"SWITCH is more readable and efficient than multiple nested IFs for conditional logic with multiple options, ideal for switching between calculations based on selections.","es":"SWITCH es más legible y eficiente que múltiples IF anidados para lógica condicional con varias opciones, siendo ideal para alternar entre cálculos basados en selecciones.","fr":"SWITCH est plus lisible et efficace que des IF imbriqués multiples pour la logique conditionnelle avec plusieurs options, idéal pour alterner entre calculs basés sur des sélections."}'),
('Consultar e Analisar', '{"pt-br":"Você precisa analisar a performance de uma query DAX lenta em um modelo semântico do Fabric.","en-us":"You need to analyze the performance of a slow DAX query in a Fabric semantic model.","es":"Necesita analizar el rendimiento de una query DAX lenta en un modelo semántico de Fabric.","fr":"Vous devez analyser les performances d''une requête DAX lente dans un modèle sémantique Fabric."}', '{"pt-br":"Qual ferramenta é recomendada para análise de performance DAX?","en-us":"Which tool is recommended for DAX performance analysis?","es":"¿Qué herramienta se recomienda para análisis de rendimiento DAX?","fr":"Quel outil est recommandé pour l''analyse des performances DAX ?"}', '[{"key":"A","text":{"pt-br":"DAX Studio com Server Timings","en-us":"DAX Studio with Server Timings","es":"DAX Studio con Server Timings","fr":"DAX Studio avec Server Timings"}},{"key":"B","text":{"pt-br":"Power BI Performance Analyzer","en-us":"Power BI Performance Analyzer","es":"Power BI Performance Analyzer","fr":"Power BI Performance Analyzer"}},{"key":"C","text":{"pt-br":"Azure Monitor","en-us":"Azure Monitor","es":"Azure Monitor","fr":"Azure Monitor"}},{"key":"D","text":{"pt-br":"SQL Profiler","en-us":"SQL Profiler","es":"SQL Profiler","fr":"SQL Profiler"}}]', 'A', '{"pt-br":"DAX Studio com Server Timings mostra o tempo de execução detalhado (Storage Engine vs Formula Engine), permitindo identificar gargalos específicos em medidas DAX.","en-us":"DAX Studio with Server Timings shows detailed execution time (Storage Engine vs Formula Engine), allowing identification of specific bottlenecks in DAX measures.","es":"DAX Studio con Server Timings muestra el tiempo de ejecución detallado (Storage Engine vs Formula Engine), permitiendo identificar cuellos de botella específicos en medidas DAX.","fr":"DAX Studio avec Server Timings montre le temps d''exécution détaillé (Storage Engine vs Formula Engine), permettant d''identifier les goulots d''étranglement spécifiques dans les mesures DAX."}'),
('Consultar e Analisar', '{"pt-br":"Você precisa criar uma medida DAX que calcule a média móvel de 3 meses das vendas.","en-us":"You need to create a DAX measure that calculates the 3-month moving average of sales.","es":"Necesita crear una medida DAX que calcule el promedio móvil de 3 meses de ventas.","fr":"Vous devez créer une mesure DAX qui calcule la moyenne mobile sur 3 mois des ventes."}', '{"pt-br":"Qual combinação de funções DAX é necessária?","en-us":"Which combination of DAX functions is needed?","es":"¿Qué combinación de funciones DAX es necesaria?","fr":"Quelle combinaison de fonctions DAX est nécessaire ?"}', '[{"key":"A","text":{"pt-br":"AVERAGEX com DATESINPERIOD","en-us":"AVERAGEX with DATESINPERIOD","es":"AVERAGEX con DATESINPERIOD","fr":"AVERAGEX avec DATESINPERIOD"}},{"key":"B","text":{"pt-br":"AVERAGE com LASTDATE","en-us":"AVERAGE with LASTDATE","es":"AVERAGE con LASTDATE","fr":"AVERAGE avec LASTDATE"}},{"key":"C","text":{"pt-br":"MOVINGAVERAGE (função nativa)","en-us":"MOVINGAVERAGE (native function)","es":"MOVINGAVERAGE (función nativa)","fr":"MOVINGAVERAGE (fonction native)"}},{"key":"D","text":{"pt-br":"SUMX com TOPN","en-us":"SUMX with TOPN","es":"SUMX con TOPN","fr":"SUMX avec TOPN"}}]', 'A', '{"pt-br":"AVERAGEX itera sobre cada mês no período definido por DATESINPERIOD (últimos 3 meses) e calcula a média, sendo a abordagem padrão para médias móveis em DAX.","en-us":"AVERAGEX iterates over each month in the period defined by DATESINPERIOD (last 3 months) and calculates the average, being the standard approach for moving averages in DAX.","es":"AVERAGEX itera sobre cada mes en el período definido por DATESINPERIOD (últimos 3 meses) y calcula el promedio, siendo el enfoque estándar para promedios móviles en DAX.","fr":"AVERAGEX itère sur chaque mois dans la période définie par DATESINPERIOD (3 derniers mois) et calcule la moyenne, étant l''approche standard pour les moyennes mobiles en DAX."}'),
('Consultar e Analisar', '{"pt-br":"Você precisa usar CALCULATE em DAX para somar vendas ignorando todos os filtros aplicados por slicers no relatório.","en-us":"You need to use CALCULATE in DAX to sum sales ignoring all filters applied by slicers in the report.","es":"Necesita usar CALCULATE en DAX para sumar ventas ignorando todos los filtros aplicados por slicers en el informe.","fr":"Vous devez utiliser CALCULATE en DAX pour sommer les ventes en ignorant tous les filtres appliqués par les slicers dans le rapport."}', '{"pt-br":"Qual modificador de filtro remove todos os filtros?","en-us":"Which filter modifier removes all filters?","es":"¿Qué modificador de filtro elimina todos los filtros?","fr":"Quel modificateur de filtre supprime tous les filtres ?"}', '[{"key":"A","text":{"pt-br":"ALL()","en-us":"ALL()","es":"ALL()","fr":"ALL()"}},{"key":"B","text":{"pt-br":"REMOVEFILTERS()","en-us":"REMOVEFILTERS()","es":"REMOVEFILTERS()","fr":"REMOVEFILTERS()"}},{"key":"C","text":{"pt-br":"Ambos ALL() e REMOVEFILTERS()","en-us":"Both ALL() and REMOVEFILTERS()","es":"Ambos ALL() y REMOVEFILTERS()","fr":"Les deux ALL() et REMOVEFILTERS()"}},{"key":"D","text":{"pt-br":"CLEARFILTERS()","en-us":"CLEARFILTERS()","es":"CLEARFILTERS()","fr":"CLEARFILTERS()"}}]', 'C', '{"pt-br":"ALL() e REMOVEFILTERS() podem ser usados dentro de CALCULATE para remover filtros. REMOVEFILTERS() é um alias mais legível de ALL() quando usado como modificador de filtro.","en-us":"ALL() and REMOVEFILTERS() can be used inside CALCULATE to remove filters. REMOVEFILTERS() is a more readable alias for ALL() when used as a filter modifier.","es":"ALL() y REMOVEFILTERS() pueden usarse dentro de CALCULATE para eliminar filtros. REMOVEFILTERS() es un alias más legible de ALL() cuando se usa como modificador de filtro.","fr":"ALL() et REMOVEFILTERS() peuvent être utilisés dans CALCULATE pour supprimer les filtres. REMOVEFILTERS() est un alias plus lisible de ALL() quand utilisé comme modificateur de filtre."}'),
('Consultar e Analisar', '{"pt-br":"Você precisa usar uma window function no Spark SQL para calcular um ranking de vendedores por região.","en-us":"You need to use a window function in Spark SQL to calculate a ranking of salespeople by region.","es":"Necesita usar una window function en Spark SQL para calcular un ranking de vendedores por región.","fr":"Vous devez utiliser une window function dans Spark SQL pour calculer un classement des vendeurs par région."}', '{"pt-br":"Qual função cria um ranking sem gaps quando há empates?","en-us":"Which function creates a ranking without gaps when there are ties?","es":"¿Qué función crea un ranking sin gaps cuando hay empates?","fr":"Quelle fonction crée un classement sans gaps en cas d''égalité ?"}', '[{"key":"A","text":{"pt-br":"DENSE_RANK()","en-us":"DENSE_RANK()","es":"DENSE_RANK()","fr":"DENSE_RANK()"}},{"key":"B","text":{"pt-br":"RANK()","en-us":"RANK()","es":"RANK()","fr":"RANK()"}},{"key":"C","text":{"pt-br":"ROW_NUMBER()","en-us":"ROW_NUMBER()","es":"ROW_NUMBER()","fr":"ROW_NUMBER()"}},{"key":"D","text":{"pt-br":"NTILE()","en-us":"NTILE()","es":"NTILE()","fr":"NTILE()"}}]', 'A', '{"pt-br":"DENSE_RANK() atribui ranking sem pular números quando há empates (1,1,2). RANK() pula (1,1,3). ROW_NUMBER() sempre atribui números únicos.","en-us":"DENSE_RANK() assigns ranking without skipping numbers for ties (1,1,2). RANK() skips (1,1,3). ROW_NUMBER() always assigns unique numbers.","es":"DENSE_RANK() asigna ranking sin saltar números cuando hay empates (1,1,2). RANK() salta (1,1,3). ROW_NUMBER() siempre asigna números únicos.","fr":"DENSE_RANK() attribue un classement sans sauter de numéros pour les égalités (1,1,2). RANK() saute (1,1,3). ROW_NUMBER() attribue toujours des numéros uniques."}'),
('Consultar e Analisar', '{"pt-br":"Você precisa criar uma medida que calcule o percentual de contribuição de cada produto no total geral de vendas.","en-us":"You need to create a measure that calculates each product''s contribution percentage to total sales.","es":"Necesita crear una medida que calcule el porcentaje de contribución de cada producto en el total general de ventas.","fr":"Vous devez créer une mesure qui calcule le pourcentage de contribution de chaque produit au total des ventes."}', '{"pt-br":"Qual padrão DAX é usado para calcular % do total?","en-us":"Which DAX pattern is used to calculate % of total?","es":"¿Qué patrón DAX se usa para calcular % del total?","fr":"Quel pattern DAX est utilisé pour calculer le % du total ?"}', '[{"key":"A","text":{"pt-br":"DIVIDE([Vendas], CALCULATE([Vendas], ALL(Produto)))","en-us":"DIVIDE([Sales], CALCULATE([Sales], ALL(Product)))","es":"DIVIDE([Ventas], CALCULATE([Ventas], ALL(Producto)))","fr":"DIVIDE([Ventes], CALCULATE([Ventes], ALL(Produit)))"}},{"key":"B","text":{"pt-br":"[Vendas] / SUM(Vendas[Total])","en-us":"[Sales] / SUM(Sales[Total])","es":"[Ventas] / SUM(Ventas[Total])","fr":"[Ventes] / SUM(Ventes[Total])"}},{"key":"C","text":{"pt-br":"PERCENTAGE([Vendas])","en-us":"PERCENTAGE([Sales])","es":"PERCENTAGE([Ventas])","fr":"PERCENTAGE([Ventes])"}},{"key":"D","text":{"pt-br":"RANKX com PERCENTAGE","en-us":"RANKX with PERCENTAGE","es":"RANKX con PERCENTAGE","fr":"RANKX avec PERCENTAGE"}}]', 'A', '{"pt-br":"DIVIDE com CALCULATE usando ALL() no denominador remove o filtro do contexto de produto, obtendo o total geral para calcular a porcentagem de cada produto.","en-us":"DIVIDE with CALCULATE using ALL() in the denominator removes the product context filter, getting the grand total to calculate each product''s percentage.","es":"DIVIDE con CALCULATE usando ALL() en el denominador remueve el filtro del contexto de producto, obteniendo el total general para calcular el porcentaje de cada producto.","fr":"DIVIDE avec CALCULATE utilisant ALL() dans le dénominateur supprime le filtre du contexte produit, obtenant le total général pour calculer le pourcentage de chaque produit."}'),
('Consultar e Analisar', '{"pt-br":"Você precisa consultar dados de uma tabela do Lakehouse usando T-SQL no SQL Analytics Endpoint, mas precisa saber as limitações.","en-us":"You need to query Lakehouse data using T-SQL in the SQL Analytics Endpoint, but need to know the limitations.","es":"Necesita consultar datos del Lakehouse usando T-SQL en el SQL Analytics Endpoint, pero necesita conocer las limitaciones.","fr":"Vous devez interroger les données du Lakehouse en T-SQL dans le SQL Analytics Endpoint, mais devez connaître les limitations."}', '{"pt-br":"Qual é a principal limitação do SQL Analytics Endpoint do Lakehouse?","en-us":"What is the main limitation of the Lakehouse SQL Analytics Endpoint?","es":"¿Cuál es la principal limitación del SQL Analytics Endpoint del Lakehouse?","fr":"Quelle est la principale limitation du SQL Analytics Endpoint du Lakehouse ?"}', '[{"key":"A","text":{"pt-br":"É somente leitura (não suporta INSERT, UPDATE, DELETE)","en-us":"It is read-only (does not support INSERT, UPDATE, DELETE)","es":"Es de solo lectura (no soporta INSERT, UPDATE, DELETE)","fr":"Il est en lecture seule (ne supporte pas INSERT, UPDATE, DELETE)"}},{"key":"B","text":{"pt-br":"Não suporta JOINs","en-us":"Does not support JOINs","es":"No soporta JOINs","fr":"Ne supporte pas les JOINs"}},{"key":"C","text":{"pt-br":"Limite de 100 tabelas","en-us":"100 table limit","es":"Límite de 100 tablas","fr":"Limite de 100 tables"}},{"key":"D","text":{"pt-br":"Não suporta views","en-us":"Does not support views","es":"No soporta views","fr":"Ne supporte pas les vues"}}]', 'A', '{"pt-br":"O SQL Analytics Endpoint do Lakehouse é read-only para tabelas Delta, não suportando DML (INSERT, UPDATE, DELETE). Para modificar dados, use Spark Notebooks ou Warehouse.","en-us":"The Lakehouse SQL Analytics Endpoint is read-only for Delta tables, not supporting DML (INSERT, UPDATE, DELETE). To modify data, use Spark Notebooks or Warehouse.","es":"El SQL Analytics Endpoint del Lakehouse es de solo lectura para tablas Delta, no soportando DML (INSERT, UPDATE, DELETE). Para modificar datos, use Spark Notebooks o Warehouse.","fr":"Le SQL Analytics Endpoint du Lakehouse est en lecture seule pour les tables Delta, ne supportant pas le DML (INSERT, UPDATE, DELETE). Pour modifier les données, utilisez Spark Notebooks ou Warehouse."}'),
('Consultar e Analisar', '{"pt-br":"Você precisa criar uma tabela calculada DAX que gera uma tabela de datas para uso em inteligência temporal.","en-us":"You need to create a DAX calculated table that generates a date table for use in time intelligence.","es":"Necesita crear una tabla calculada DAX que genere una tabla de fechas para uso en inteligencia temporal.","fr":"Vous devez créer une table calculée DAX qui génère une table de dates pour l''intelligence temporelle."}', '{"pt-br":"Qual função DAX gera uma tabela de datas contínua?","en-us":"Which DAX function generates a continuous date table?","es":"¿Qué función DAX genera una tabla de fechas continua?","fr":"Quelle fonction DAX génère une table de dates continue ?"}', '[{"key":"A","text":{"pt-br":"CALENDARAUTO() ou CALENDAR()","en-us":"CALENDARAUTO() or CALENDAR()","es":"CALENDARAUTO() o CALENDAR()","fr":"CALENDARAUTO() ou CALENDAR()"}},{"key":"B","text":{"pt-br":"DATESBETWEEN()","en-us":"DATESBETWEEN()","es":"DATESBETWEEN()","fr":"DATESBETWEEN()"}},{"key":"C","text":{"pt-br":"GENERATEDATE()","en-us":"GENERATEDATE()","es":"GENERATEDATE()","fr":"GENERATEDATE()"}},{"key":"D","text":{"pt-br":"DATESYTD()","en-us":"DATESYTD()","es":"DATESYTD()","fr":"DATESYTD()"}}]', 'A', '{"pt-br":"CALENDARAUTO() gera automaticamente uma tabela com todas as datas baseada nas colunas de data do modelo. CALENDAR() aceita data início e fim. Ambas são ideais para inteligência temporal.","en-us":"CALENDARAUTO() automatically generates a table with all dates based on the model''s date columns. CALENDAR() accepts start and end dates. Both are ideal for time intelligence.","es":"CALENDARAUTO() genera automáticamente una tabla con todas las fechas basada en las columnas de fecha del modelo. CALENDAR() acepta fecha inicio y fin. Ambas son ideales para inteligencia temporal.","fr":"CALENDARAUTO() génère automatiquement une table avec toutes les dates basée sur les colonnes de date du modèle. CALENDAR() accepte des dates de début et fin. Les deux sont idéales pour l''intelligence temporelle."}'),
('Consultar e Analisar', '{"pt-br":"Você está escrevendo uma query KQL para filtrar eventos dos últimos 30 minutos em uma tabela de logs.","en-us":"You are writing a KQL query to filter events from the last 30 minutes in a log table.","es":"Está escribiendo una query KQL para filtrar eventos de los últimos 30 minutos en una tabla de logs.","fr":"Vous écrivez une requête KQL pour filtrer les événements des 30 dernières minutes dans une table de logs."}', '{"pt-br":"Qual operador KQL filtra por tempo relativo?","en-us":"Which KQL operator filters by relative time?","es":"¿Qué operador KQL filtra por tiempo relativo?","fr":"Quel opérateur KQL filtre par temps relatif ?"}', '[{"key":"A","text":{"pt-br":"where Timestamp > ago(30m)","en-us":"where Timestamp > ago(30m)","es":"where Timestamp > ago(30m)","fr":"where Timestamp > ago(30m)"}},{"key":"B","text":{"pt-br":"filter Timestamp > now() - 30","en-us":"filter Timestamp > now() - 30","es":"filter Timestamp > now() - 30","fr":"filter Timestamp > now() - 30"}},{"key":"C","text":{"pt-br":"WHERE Timestamp > DATEADD(minute, -30, GETDATE())","en-us":"WHERE Timestamp > DATEADD(minute, -30, GETDATE())","es":"WHERE Timestamp > DATEADD(minute, -30, GETDATE())","fr":"WHERE Timestamp > DATEADD(minute, -30, GETDATE())"}},{"key":"D","text":{"pt-br":"having time > last(30min)","en-us":"having time > last(30min)","es":"having time > last(30min)","fr":"having time > last(30min)"}}]', 'A', '{"pt-br":"Em KQL, ago() é a função para calcular tempo relativo e where é o operador de filtro. ago(30m) retorna o timestamp de 30 minutos atrás.","en-us":"In KQL, ago() is the function for relative time calculation and where is the filter operator. ago(30m) returns the timestamp from 30 minutes ago.","es":"En KQL, ago() es la función para calcular tiempo relativo y where es el operador de filtro. ago(30m) retorna el timestamp de 30 minutos atrás.","fr":"En KQL, ago() est la fonction pour le calcul de temps relatif et where est l''opérateur de filtre. ago(30m) retourne le timestamp d''il y a 30 minutes."}'),
('Consultar e Analisar', '{"pt-br":"Você precisa criar uma medida DAX que retorne o nome do produto com maior venda em cada contexto de filtro.","en-us":"You need to create a DAX measure that returns the product name with the highest sales in each filter context.","es":"Necesita crear una medida DAX que retorne el nombre del producto con mayor venta en cada contexto de filtro.","fr":"Vous devez créer une mesure DAX qui retourne le nom du produit avec les ventes les plus élevées dans chaque contexte de filtre."}', '{"pt-br":"Qual combinação de funções DAX é necessária?","en-us":"Which combination of DAX functions is needed?","es":"¿Qué combinación de funciones DAX es necesaria?","fr":"Quelle combinaison de fonctions DAX est nécessaire ?"}', '[{"key":"A","text":{"pt-br":"TOPN com MAXX ou CALCULATE com VALUES","en-us":"TOPN with MAXX or CALCULATE with VALUES","es":"TOPN con MAXX o CALCULATE con VALUES","fr":"TOPN avec MAXX ou CALCULATE avec VALUES"}},{"key":"B","text":{"pt-br":"MAX com FILTER","en-us":"MAX with FILTER","es":"MAX con FILTER","fr":"MAX avec FILTER"}},{"key":"C","text":{"pt-br":"FIRSTNONBLANK","en-us":"FIRSTNONBLANK","es":"FIRSTNONBLANK","fr":"FIRSTNONBLANK"}},{"key":"D","text":{"pt-br":"LOOKUPVALUE com MAX","en-us":"LOOKUPVALUE with MAX","es":"LOOKUPVALUE con MAX","fr":"LOOKUPVALUE avec MAX"}}]', 'A', '{"pt-br":"TOPN(1, tabela, medida) retorna a linha com maior valor, e MAXX extrai o nome do produto dessa linha. Alternativa: CALCULATE com VALUES e filtro TOP.","en-us":"TOPN(1, table, measure) returns the row with highest value, and MAXX extracts the product name. Alternative: CALCULATE with VALUES and TOP filter.","es":"TOPN(1, tabla, medida) retorna la fila con mayor valor, y MAXX extrae el nombre del producto. Alternativa: CALCULATE con VALUES y filtro TOP.","fr":"TOPN(1, table, mesure) retourne la ligne avec la valeur la plus élevée, et MAXX extrait le nom du produit. Alternative : CALCULATE avec VALUES et filtre TOP."}'),
('Consultar e Analisar', '{"pt-br":"Você precisa usar variáveis em DAX para melhorar a legibilidade e performance de uma medida complexa.","en-us":"You need to use variables in DAX to improve readability and performance of a complex measure.","es":"Necesita usar variables en DAX para mejorar la legibilidad y rendimiento de una medida compleja.","fr":"Vous devez utiliser des variables en DAX pour améliorer la lisibilité et les performances d''une mesure complexe."}', '{"pt-br":"Qual é a sintaxe correta para declarar variáveis em DAX?","en-us":"What is the correct syntax for declaring variables in DAX?","es":"¿Cuál es la sintaxis correcta para declarar variables en DAX?","fr":"Quelle est la syntaxe correcte pour déclarer des variables en DAX ?"}', '[{"key":"A","text":{"pt-br":"VAR nome = expressão RETURN resultado","en-us":"VAR name = expression RETURN result","es":"VAR nombre = expresión RETURN resultado","fr":"VAR nom = expression RETURN résultat"}},{"key":"B","text":{"pt-br":"SET nome = expressão","en-us":"SET name = expression","es":"SET nombre = expresión","fr":"SET nom = expression"}},{"key":"C","text":{"pt-br":"DECLARE @nome = expressão","en-us":"DECLARE @name = expression","es":"DECLARE @nombre = expresión","fr":"DECLARE @nom = expression"}},{"key":"D","text":{"pt-br":"LET nome = expressão IN resultado","en-us":"LET name = expression IN result","es":"LET nombre = expresión IN resultado","fr":"LET nom = expression IN résultat"}}]', 'A', '{"pt-br":"Em DAX, variáveis são declaradas com VAR e o resultado final com RETURN. Variáveis são avaliadas uma única vez (lazy evaluation), melhorando performance em cálculos repetidos.","en-us":"In DAX, variables are declared with VAR and the final result with RETURN. Variables are evaluated once (lazy evaluation), improving performance in repeated calculations.","es":"En DAX, las variables se declaran con VAR y el resultado final con RETURN. Las variables se evalúan una sola vez (lazy evaluation), mejorando el rendimiento en cálculos repetidos.","fr":"En DAX, les variables sont déclarées avec VAR et le résultat final avec RETURN. Les variables sont évaluées une seule fois (lazy evaluation), améliorant les performances dans les calculs répétés."}'),
('Projetar Modelos Semânticos', '{"pt-br":"Você está projetando um modelo semântico no Power BI para análise de vendas. Precisa definir a modelagem de dados ideal.","en-us":"You are designing a semantic model in Power BI for sales analysis. You need to define the ideal data modeling.","es":"Está diseñando un modelo semántico en Power BI para análisis de ventas. Necesita definir el modelado de datos ideal.","fr":"Vous concevez un modèle sémantique dans Power BI pour l''analyse des ventes. Vous devez définir la modélisation idéale."}', '{"pt-br":"Qual esquema de modelagem é recomendado para Power BI?","en-us":"Which modeling schema is recommended for Power BI?","es":"¿Qué esquema de modelado se recomienda para Power BI?","fr":"Quel schéma de modélisation est recommandé pour Power BI ?"}', '[{"key":"A","text":{"pt-br":"Star Schema (esquema estrela)","en-us":"Star Schema","es":"Star Schema (esquema estrella)","fr":"Star Schema (schéma en étoile)"}},{"key":"B","text":{"pt-br":"Snowflake Schema","en-us":"Snowflake Schema","es":"Snowflake Schema","fr":"Snowflake Schema"}},{"key":"C","text":{"pt-br":"Flat Table (tabela única)","en-us":"Flat Table (single table)","es":"Flat Table (tabla única)","fr":"Flat Table (table unique)"}},{"key":"D","text":{"pt-br":"Third Normal Form (3NF)","en-us":"Third Normal Form (3NF)","es":"Third Normal Form (3NF)","fr":"Third Normal Form (3NF)"}}]', 'A', '{"pt-br":"Star Schema é o padrão recomendado pela Microsoft para Power BI, com tabelas fato no centro e dimensões ao redor, otimizando performance do engine VertiPaq.","en-us":"Star Schema is Microsoft''s recommended standard for Power BI, with fact tables at the center and dimensions around them, optimizing VertiPaq engine performance.","es":"Star Schema es el estándar recomendado por Microsoft para Power BI, con tablas de hechos en el centro y dimensiones alrededor, optimizando el rendimiento del motor VertiPaq.","fr":"Le Star Schema est le standard recommandé par Microsoft pour Power BI, avec les tables de faits au centre et les dimensions autour, optimisant les performances du moteur VertiPaq."}'),
('Projetar Modelos Semânticos', '{"pt-br":"Você precisa definir o tipo de relacionamento entre uma tabela de vendas (fato) e uma tabela de clientes (dimensão).","en-us":"You need to define the relationship type between a sales table (fact) and a customers table (dimension).","es":"Necesita definir el tipo de relación entre una tabla de ventas (hecho) y una tabla de clientes (dimensión).","fr":"Vous devez définir le type de relation entre une table de ventes (fait) et une table de clients (dimension)."}', '{"pt-br":"Qual cardinalidade é típica entre fato e dimensão?","en-us":"Which cardinality is typical between fact and dimension?","es":"¿Qué cardinalidad es típica entre hecho y dimensión?","fr":"Quelle cardinalité est typique entre fait et dimension ?"}', '[{"key":"A","text":{"pt-br":"Many-to-One (fato → dimensão)","en-us":"Many-to-One (fact → dimension)","es":"Many-to-One (hecho → dimensión)","fr":"Many-to-One (fait → dimension)"}},{"key":"B","text":{"pt-br":"One-to-One","en-us":"One-to-One","es":"One-to-One","fr":"One-to-One"}},{"key":"C","text":{"pt-br":"Many-to-Many","en-us":"Many-to-Many","es":"Many-to-Many","fr":"Many-to-Many"}},{"key":"D","text":{"pt-br":"One-to-Many (fato → dimensão)","en-us":"One-to-Many (fact → dimension)","es":"One-to-Many (hecho → dimensión)","fr":"One-to-Many (fait → dimension)"}}]', 'A', '{"pt-br":"Many-to-One da fato para dimensão é o padrão em star schema. Cada venda refere-se a um cliente, mas cada cliente pode ter muitas vendas. O filtro flui da dimensão para a fato.","en-us":"Many-to-One from fact to dimension is standard in star schema. Each sale refers to one customer, but each customer can have many sales. Filter flows from dimension to fact.","es":"Many-to-One de hecho a dimensión es el estándar en star schema. Cada venta se refiere a un cliente, pero cada cliente puede tener muchas ventas. El filtro fluye de dimensión a hecho.","fr":"Many-to-One de fait à dimension est le standard en star schema. Chaque vente réfère à un client, mais chaque client peut avoir plusieurs ventes. Le filtre va de dimension à fait."}'),
('Projetar Modelos Semânticos', '{"pt-br":"Seu modelo semântico usa o modo DirectLake para acessar dados do Lakehouse. Os usuários relatam que consultas estão caindo para DirectQuery.","en-us":"Your semantic model uses DirectLake mode to access Lakehouse data. Users report queries are falling back to DirectQuery.","es":"Su modelo semántico usa el modo DirectLake para acceder a datos del Lakehouse. Los usuarios informan que consultas caen a DirectQuery.","fr":"Votre modèle sémantique utilise le mode DirectLake pour accéder aux données du Lakehouse. Les utilisateurs signalent que les requêtes retombent en DirectQuery."}', '{"pt-br":"Qual é a causa mais provável do fallback para DirectQuery?","en-us":"What is the most likely cause of the fallback to DirectQuery?","es":"¿Cuál es la causa más probable del fallback a DirectQuery?","fr":"Quelle est la cause la plus probable du fallback vers DirectQuery ?"}', '[{"key":"A","text":{"pt-br":"Os arquivos Parquet excedem os limites de framing","en-us":"Parquet files exceed framing limits","es":"Los archivos Parquet exceden los límites de framing","fr":"Les fichiers Parquet dépassent les limites de framing"}},{"key":"B","text":{"pt-br":"O gateway está mal configurado","en-us":"The gateway is misconfigured","es":"El gateway está mal configurado","fr":"La passerelle est mal configurée"}},{"key":"C","text":{"pt-br":"O modelo está em modo Import","en-us":"The model is in Import mode","es":"El modelo está en modo Import","fr":"Le modèle est en mode Import"}},{"key":"D","text":{"pt-br":"A conexão XMLA foi desabilitada","en-us":"XMLA connection was disabled","es":"La conexión XMLA fue deshabilitada","fr":"La connexion XMLA a été désactivée"}}]', 'A', '{"pt-br":"No DirectLake, quando arquivos Parquet excedem limites de framing (linhas ou row groups por tabela), o engine faz fallback para DirectQuery. Solução: executar OPTIMIZE.","en-us":"In DirectLake, when Parquet files exceed framing limits (rows or row groups per table), the engine falls back to DirectQuery. Solution: run OPTIMIZE.","es":"En DirectLake, cuando archivos Parquet exceden límites de framing (filas o row groups por tabla), el motor hace fallback a DirectQuery. Solución: ejecutar OPTIMIZE.","fr":"En DirectLake, quand les fichiers Parquet dépassent les limites de framing (lignes ou row groups par table), le moteur retombe en DirectQuery. Solution : exécuter OPTIMIZE."}'),
('Projetar Modelos Semânticos', '{"pt-br":"Você precisa criar uma tabela de datas (calendário) no modelo semântico para usar funções de inteligência temporal DAX.","en-us":"You need to create a date table (calendar) in the semantic model to use DAX time intelligence functions.","es":"Necesita crear una tabla de fechas (calendario) en el modelo semántico para usar funciones de inteligencia temporal DAX.","fr":"Vous devez créer une table de dates (calendrier) dans le modèle sémantique pour utiliser les fonctions DAX d''intelligence temporelle."}', '{"pt-br":"Qual é um requisito obrigatório para a tabela de datas funcionar com inteligência temporal?","en-us":"What is a mandatory requirement for the date table to work with time intelligence?","es":"¿Cuál es un requisito obligatorio para que la tabla de fechas funcione con inteligencia temporal?","fr":"Quel est un prérequis obligatoire pour que la table de dates fonctionne avec l''intelligence temporelle ?"}', '[{"key":"A","text":{"pt-br":"Deve ser marcada como Date Table e ter datas contínuas sem gaps","en-us":"Must be marked as Date Table and have continuous dates without gaps","es":"Debe marcarse como Date Table y tener fechas continuas sin gaps","fr":"Doit être marquée comme Date Table et avoir des dates continues sans lacunes"}},{"key":"B","text":{"pt-br":"Deve ter apenas colunas de Ano, Mês e Dia","en-us":"Must have only Year, Month, and Day columns","es":"Debe tener solo columnas de Año, Mes y Día","fr":"Doit avoir uniquement des colonnes Année, Mois et Jour"}},{"key":"C","text":{"pt-br":"Deve ser uma tabela calculada DAX","en-us":"Must be a DAX calculated table","es":"Debe ser una tabla calculada DAX","fr":"Doit être une table calculée DAX"}},{"key":"D","text":{"pt-br":"Deve ter relação bidirecional com a tabela fato","en-us":"Must have bidirectional relationship with fact table","es":"Debe tener relación bidireccional con la tabla de hechos","fr":"Doit avoir une relation bidirectionnelle avec la table de faits"}}]', 'A', '{"pt-br":"Para inteligência temporal, a tabela de datas deve ser marcada como ''Date Table'' nas propriedades e conter datas contínuas (sem lacunas) cobrindo todo o período dos dados.","en-us":"For time intelligence, the date table must be marked as ''Date Table'' in properties and contain continuous dates (no gaps) covering the entire data period.","es":"Para inteligencia temporal, la tabla de fechas debe marcarse como ''Date Table'' en propiedades y contener fechas continuas (sin gaps) cubriendo todo el período de datos.","fr":"Pour l''intelligence temporelle, la table de dates doit être marquée comme ''Date Table'' dans les propriétés et contenir des dates continues (sans lacunes) couvrant toute la période des données."}'),
('Projetar Modelos Semânticos', '{"pt-br":"Você precisa criar um modelo semântico que conecte diretamente ao Lakehouse sem importar dados na memória.","en-us":"You need to create a semantic model that connects directly to the Lakehouse without importing data into memory.","es":"Necesita crear un modelo semántico que conecte directamente al Lakehouse sin importar datos en memoria.","fr":"Vous devez créer un modèle sémantique connecté directement au Lakehouse sans importer de données en mémoire."}', '{"pt-br":"Qual modo de armazenamento é específico do Fabric para esse cenário?","en-us":"Which storage mode is specific to Fabric for this scenario?","es":"¿Qué modo de almacenamiento es específico de Fabric para este escenario?","fr":"Quel mode de stockage est spécifique à Fabric pour ce scénario ?"}', '[{"key":"A","text":{"pt-br":"DirectLake","en-us":"DirectLake","es":"DirectLake","fr":"DirectLake"}},{"key":"B","text":{"pt-br":"Import","en-us":"Import","es":"Import","fr":"Import"}},{"key":"C","text":{"pt-br":"DirectQuery","en-us":"DirectQuery","es":"DirectQuery","fr":"DirectQuery"}},{"key":"D","text":{"pt-br":"Dual","en-us":"Dual","es":"Dual","fr":"Dual"}}]', 'A', '{"pt-br":"DirectLake é exclusivo do Fabric, lendo dados diretamente dos arquivos Parquet no OneLake sem importação, combinando a velocidade do Import com a atualidade do DirectQuery.","en-us":"DirectLake is exclusive to Fabric, reading data directly from Parquet files in OneLake without import, combining Import speed with DirectQuery freshness.","es":"DirectLake es exclusivo de Fabric, leyendo datos directamente de archivos Parquet en OneLake sin importación, combinando la velocidad de Import con la actualidad de DirectQuery.","fr":"DirectLake est exclusif à Fabric, lisant les données directement des fichiers Parquet dans OneLake sans importation, combinant la vitesse d''Import avec la fraîcheur de DirectQuery."}'),
('Projetar Modelos Semânticos', '{"pt-br":"Você precisa criar medidas DAX que serão compartilhadas entre múltiplos relatórios sem duplicação.","en-us":"You need to create DAX measures that will be shared across multiple reports without duplication.","es":"Necesita crear medidas DAX que serán compartidas entre múltiples informes sin duplicación.","fr":"Vous devez créer des mesures DAX qui seront partagées entre plusieurs rapports sans duplication."}', '{"pt-br":"Onde as medidas devem ser definidas para maximizar a reutilização?","en-us":"Where should measures be defined to maximize reuse?","es":"¿Dónde deben definirse las medidas para maximizar la reutilización?","fr":"Où les mesures doivent-elles être définies pour maximiser la réutilisation ?"}', '[{"key":"A","text":{"pt-br":"No modelo semântico (dataset) compartilhado","en-us":"In the shared semantic model (dataset)","es":"En el modelo semántico (dataset) compartido","fr":"Dans le modèle sémantique (dataset) partagé"}},{"key":"B","text":{"pt-br":"Em cada relatório individual","en-us":"In each individual report","es":"En cada informe individual","fr":"Dans chaque rapport individuel"}},{"key":"C","text":{"pt-br":"No Dataflow Gen2","en-us":"In Dataflow Gen2","es":"En Dataflow Gen2","fr":"Dans Dataflow Gen2"}},{"key":"D","text":{"pt-br":"No Lakehouse","en-us":"In the Lakehouse","es":"En el Lakehouse","fr":"Dans le Lakehouse"}}]', 'A', '{"pt-br":"Definir medidas no modelo semântico compartilhado permite que múltiplos relatórios usem as mesmas medidas via Live Connection, garantindo consistência e eliminando duplicação.","en-us":"Defining measures in the shared semantic model allows multiple reports to use the same measures via Live Connection, ensuring consistency and eliminating duplication.","es":"Definir medidas en el modelo semántico compartido permite que múltiples informes usen las mismas medidas via Live Connection, garantizando consistencia y eliminando duplicación.","fr":"Définir les mesures dans le modèle sémantique partagé permet à plusieurs rapports d''utiliser les mêmes mesures via Live Connection, garantissant la cohérence et éliminant la duplication."}'),
('Projetar Modelos Semânticos', '{"pt-br":"Você precisa lidar com uma situação onde uma tabela de vendas tem duas colunas de data: data do pedido e data de entrega, ambas precisando filtrar pela tabela calendário.","en-us":"You need to handle a situation where a sales table has two date columns: order date and delivery date, both needing to filter by the calendar table.","es":"Necesita manejar una situación donde una tabla de ventas tiene dos columnas de fecha: fecha del pedido y fecha de entrega, ambas necesitando filtrar por la tabla calendario.","fr":"Vous devez gérer une situation où une table de ventes a deux colonnes de date : date de commande et date de livraison, les deux devant filtrer par la table calendrier."}', '{"pt-br":"Como resolver múltiplos relacionamentos com a mesma dimensão?","en-us":"How to resolve multiple relationships with the same dimension?","es":"¿Cómo resolver múltiples relaciones con la misma dimensión?","fr":"Comment résoudre les relations multiples avec la même dimension ?"}', '[{"key":"A","text":{"pt-br":"Usar USERELATIONSHIP() em medidas DAX para ativar o relacionamento inativo","en-us":"Use USERELATIONSHIP() in DAX measures to activate the inactive relationship","es":"Usar USERELATIONSHIP() en medidas DAX para activar la relación inactiva","fr":"Utiliser USERELATIONSHIP() dans les mesures DAX pour activer la relation inactive"}},{"key":"B","text":{"pt-br":"Criar duas tabelas de calendário separadas","en-us":"Create two separate calendar tables","es":"Crear dos tablas de calendario separadas","fr":"Créer deux tables calendrier séparées"}},{"key":"C","text":{"pt-br":"Usar relação many-to-many","en-us":"Use many-to-many relationship","es":"Usar relación many-to-many","fr":"Utiliser une relation many-to-many"}},{"key":"D","text":{"pt-br":"Mesclar as duas colunas de data","en-us":"Merge the two date columns","es":"Fusionar las dos columnas de fecha","fr":"Fusionner les deux colonnes de date"}}]', 'A', '{"pt-br":"USERELATIONSHIP() dentro de CALCULATE permite ativar um relacionamento inativo entre a tabela fato e dimensão de data, sendo o padrão para role-playing dimensions.","en-us":"USERELATIONSHIP() inside CALCULATE allows activating an inactive relationship between fact and date dimension tables, being the standard for role-playing dimensions.","es":"USERELATIONSHIP() dentro de CALCULATE permite activar una relación inactiva entre tabla de hechos y dimensión de fecha, siendo el estándar para role-playing dimensions.","fr":"USERELATIONSHIP() dans CALCULATE permet d''activer une relation inactive entre table de faits et dimension de date, étant le standard pour les role-playing dimensions."}'),
('Projetar Modelos Semânticos', '{"pt-br":"Você precisa definir hierarquias no modelo semântico para permitir drill-down em relatórios (ex: Ano > Trimestre > Mês).","en-us":"You need to define hierarchies in the semantic model to enable drill-down in reports (e.g., Year > Quarter > Month).","es":"Necesita definir jerarquías en el modelo semántico para permitir drill-down en informes (ej: Año > Trimestre > Mes).","fr":"Vous devez définir des hiérarchies dans le modèle sémantique pour permettre le drill-down dans les rapports (ex : Année > Trimestre > Mois)."}', '{"pt-br":"Onde as hierarquias são criadas no modelo semântico?","en-us":"Where are hierarchies created in the semantic model?","es":"¿Dónde se crean las jerarquías en el modelo semántico?","fr":"Où les hiérarchies sont-elles créées dans le modèle sémantique ?"}', '[{"key":"A","text":{"pt-br":"Na tabela de dimensão, agrupando colunas em níveis","en-us":"In the dimension table, grouping columns into levels","es":"En la tabla de dimensión, agrupando columnas en niveles","fr":"Dans la table de dimension, groupant les colonnes en niveaux"}},{"key":"B","text":{"pt-br":"Na tabela fato","en-us":"In the fact table","es":"En la tabla de hechos","fr":"Dans la table de faits"}},{"key":"C","text":{"pt-br":"Em uma tabela separada de hierarquia","en-us":"In a separate hierarchy table","es":"En una tabla separada de jerarquía","fr":"Dans une table de hiérarchie séparée"}},{"key":"D","text":{"pt-br":"Nas configurações do relatório","en-us":"In report settings","es":"En la configuración del informe","fr":"Dans les paramètres du rapport"}}]', 'A', '{"pt-br":"Hierarquias são criadas nas tabelas de dimensão, agrupando colunas em uma estrutura de níveis que permite drill-down nos visuais (ex: Geografia > País > Estado > Cidade).","en-us":"Hierarchies are created in dimension tables, grouping columns into a level structure that enables visual drill-down (e.g., Geography > Country > State > City).","es":"Las jerarquías se crean en las tablas de dimensión, agrupando columnas en una estructura de niveles que permite drill-down en los visuales (ej: Geografía > País > Estado > Ciudad).","fr":"Les hiérarchies sont créées dans les tables de dimension, groupant les colonnes en une structure de niveaux permettant le drill-down visuel (ex : Géographie > Pays > État > Ville)."}'),
('Projetar Modelos Semânticos', '{"pt-br":"Você precisa criar um modelo composto no Power BI que combine dados do Lakehouse (DirectLake) com dados de uma planilha Excel importada.","en-us":"You need to create a composite model in Power BI combining Lakehouse data (DirectLake) with data from an imported Excel spreadsheet.","es":"Necesita crear un modelo compuesto en Power BI que combine datos del Lakehouse (DirectLake) con datos de una hoja de cálculo Excel importada.","fr":"Vous devez créer un modèle composite dans Power BI combinant des données du Lakehouse (DirectLake) avec des données d''un fichier Excel importé."}', '{"pt-br":"O que acontece com o modo DirectLake quando dados Import são adicionados?","en-us":"What happens to DirectLake mode when Import data is added?","es":"¿Qué pasa con el modo DirectLake cuando se agregan datos Import?","fr":"Que se passe-t-il avec le mode DirectLake quand des données Import sont ajoutées ?"}', '[{"key":"A","text":{"pt-br":"DirectLake faz fallback para DirectQuery para as tabelas afetadas","en-us":"DirectLake falls back to DirectQuery for affected tables","es":"DirectLake hace fallback a DirectQuery para las tablas afectadas","fr":"DirectLake retombe en DirectQuery pour les tables affectées"}},{"key":"B","text":{"pt-br":"Todas as tabelas mudam para Import","en-us":"All tables switch to Import","es":"Todas las tablas cambian a Import","fr":"Toutes les tables passent en Import"}},{"key":"C","text":{"pt-br":"O modelo composto não é permitido com DirectLake","en-us":"Composite model is not allowed with DirectLake","es":"El modelo compuesto no es permitido con DirectLake","fr":"Le modèle composite n''est pas permis avec DirectLake"}},{"key":"D","text":{"pt-br":"DirectLake continua funcionando normalmente","en-us":"DirectLake continues working normally","es":"DirectLake continúa funcionando normalmente","fr":"DirectLake continue de fonctionner normalement"}}]', 'A', '{"pt-br":"Em um modelo composto com DirectLake, adicionar tabelas Import causa fallback para DirectQuery nas tabelas DirectLake. É importante entender esse comportamento para decisões de modelagem.","en-us":"In a composite model with DirectLake, adding Import tables causes DirectLake tables to fall back to DirectQuery. Understanding this behavior is important for modeling decisions.","es":"En un modelo compuesto con DirectLake, agregar tablas Import causa fallback a DirectQuery en las tablas DirectLake. Es importante entender este comportamiento para decisiones de modelado.","fr":"Dans un modèle composite avec DirectLake, l''ajout de tables Import provoque un fallback en DirectQuery pour les tables DirectLake. Comprendre ce comportement est important pour les décisions de modélisation."}'),
('Projetar Modelos Semânticos', '{"pt-br":"Você precisa definir o formato de exibição de uma medida de receita no modelo semântico para mostrar sempre como moeda brasileira (R$).","en-us":"You need to define the display format of a revenue measure in the semantic model to always show as Brazilian currency (R$).","es":"Necesita definir el formato de visualización de una medida de ingresos en el modelo semántico para mostrar siempre como moneda brasileña (R$).","fr":"Vous devez définir le format d''affichage d''une mesure de revenus dans le modèle sémantique pour toujours afficher en monnaie brésilienne (R$)."}', '{"pt-br":"Onde o formato de exibição de uma medida é configurado?","en-us":"Where is a measure''s display format configured?","es":"¿Dónde se configura el formato de visualización de una medida?","fr":"Où le format d''affichage d''une mesure est-il configuré ?"}', '[{"key":"A","text":{"pt-br":"Nas propriedades da medida (Format String)","en-us":"In the measure properties (Format String)","es":"En las propiedades de la medida (Format String)","fr":"Dans les propriétés de la mesure (Format String)"}},{"key":"B","text":{"pt-br":"No visual do relatório","en-us":"In the report visual","es":"En el visual del informe","fr":"Dans le visuel du rapport"}},{"key":"C","text":{"pt-br":"Na função FORMAT() dentro da medida","en-us":"In the FORMAT() function inside the measure","es":"En la función FORMAT() dentro de la medida","fr":"Dans la fonction FORMAT() à l''intérieur de la mesure"}},{"key":"D","text":{"pt-br":"Nas configurações do workspace","en-us":"In workspace settings","es":"En la configuración del workspace","fr":"Dans les paramètres du workspace"}}]', 'A', '{"pt-br":"O Format String nas propriedades da medida define o formato padrão de exibição, garantindo consistência em todos os relatórios que usam o modelo. FORMAT() retorna texto, não um número formatado.","en-us":"The Format String in measure properties defines the default display format, ensuring consistency across all reports using the model. FORMAT() returns text, not a formatted number.","es":"El Format String en las propiedades de la medida define el formato predeterminado de visualización, garantizando consistencia en todos los informes que usan el modelo. FORMAT() retorna texto, no un número formateado.","fr":"Le Format String dans les propriétés de la mesure définit le format d''affichage par défaut, garantissant la cohérence dans tous les rapports utilisant le modèle. FORMAT() retourne du texte, pas un nombre formaté."}'),
('Projetar Modelos Semânticos', '{"pt-br":"Você precisa controlar a direção do filtro entre duas tabelas no modelo para que os filtros fluam nos dois sentidos.","en-us":"You need to control the filter direction between two tables in the model so filters flow in both directions.","es":"Necesita controlar la dirección del filtro entre dos tablas en el modelo para que los filtros fluyan en ambas direcciones.","fr":"Vous devez contrôler la direction du filtre entre deux tables dans le modèle pour que les filtres circulent dans les deux sens."}', '{"pt-br":"Qual configuração de relacionamento permite filtro bidirecional?","en-us":"Which relationship setting allows bidirectional filtering?","es":"¿Qué configuración de relación permite filtro bidireccional?","fr":"Quel paramètre de relation permet le filtrage bidirectionnel ?"}', '[{"key":"A","text":{"pt-br":"Cross filter direction: Both","en-us":"Cross filter direction: Both","es":"Cross filter direction: Both","fr":"Cross filter direction: Both"}},{"key":"B","text":{"pt-br":"Cardinalidade: Many-to-Many","en-us":"Cardinality: Many-to-Many","es":"Cardinalidad: Many-to-Many","fr":"Cardinalité: Many-to-Many"}},{"key":"C","text":{"pt-br":"Security filter: Enabled","en-us":"Security filter: Enabled","es":"Security filter: Enabled","fr":"Security filter: Enabled"}},{"key":"D","text":{"pt-br":"CROSSFILTER() em DAX","en-us":"CROSSFILTER() in DAX","es":"CROSSFILTER() en DAX","fr":"CROSSFILTER() en DAX"}}]', 'A', '{"pt-br":"Cross filter direction: Both permite que filtros fluam em ambos os sentidos. Use com cautela pois pode causar ambiguidade e impacto na performance. CROSSFILTER() é uma alternativa pontual em medidas.","en-us":"Cross filter direction: Both allows filters to flow in both directions. Use with caution as it can cause ambiguity and performance impact. CROSSFILTER() is a targeted alternative in measures.","es":"Cross filter direction: Both permite que los filtros fluyan en ambas direcciones. Use con cautela ya que puede causar ambigüedad e impacto en el rendimiento. CROSSFILTER() es una alternativa puntual en medidas.","fr":"Cross filter direction: Both permet aux filtres de circuler dans les deux sens. À utiliser avec prudence car cela peut causer de l''ambiguïté et un impact sur les performances. CROSSFILTER() est une alternative ciblée dans les mesures."}'),
('Projetar Modelos Semânticos', '{"pt-br":"Você precisa criar um grupo de cálculo (calculation group) no modelo semântico para aplicar inteligência temporal dinamicamente.","en-us":"You need to create a calculation group in the semantic model to apply time intelligence dynamically.","es":"Necesita crear un grupo de cálculo (calculation group) en el modelo semántico para aplicar inteligencia temporal dinámicamente.","fr":"Vous devez créer un groupe de calcul (calculation group) dans le modèle sémantique pour appliquer l''intelligence temporelle dynamiquement."}', '{"pt-br":"Qual ferramenta é usada para criar calculation groups?","en-us":"Which tool is used to create calculation groups?","es":"¿Qué herramienta se usa para crear calculation groups?","fr":"Quel outil est utilisé pour créer des calculation groups ?"}', '[{"key":"A","text":{"pt-br":"Tabular Editor ou XMLA endpoint","en-us":"Tabular Editor or XMLA endpoint","es":"Tabular Editor o XMLA endpoint","fr":"Tabular Editor ou XMLA endpoint"}},{"key":"B","text":{"pt-br":"Power BI Desktop nativamente","en-us":"Power BI Desktop natively","es":"Power BI Desktop nativamente","fr":"Power BI Desktop nativement"}},{"key":"C","text":{"pt-br":"Dataflow Gen2","en-us":"Dataflow Gen2","es":"Dataflow Gen2","fr":"Dataflow Gen2"}},{"key":"D","text":{"pt-br":"Power BI Service","en-us":"Power BI Service","es":"Power BI Service","fr":"Power BI Service"}}]', 'A', '{"pt-br":"Calculation groups são criados usando ferramentas externas como Tabular Editor ou via XMLA endpoint, permitindo definir padrões de cálculo reutilizáveis como YTD, MoM, YoY.","en-us":"Calculation groups are created using external tools like Tabular Editor or via XMLA endpoint, allowing defining reusable calculation patterns like YTD, MoM, YoY.","es":"Los calculation groups se crean usando herramientas externas como Tabular Editor o via XMLA endpoint, permitiendo definir patrones de cálculo reutilizables como YTD, MoM, YoY.","fr":"Les calculation groups sont créés avec des outils externes comme Tabular Editor ou via XMLA endpoint, permettant de définir des modèles de calcul réutilisables comme YTD, MoM, YoY."}'),
('Projetar Modelos Semânticos', '{"pt-br":"Você precisa ocultar colunas técnicas (como chaves estrangeiras) no modelo semântico para que os usuários de relatórios não as vejam.","en-us":"You need to hide technical columns (like foreign keys) in the semantic model so report users don''t see them.","es":"Necesita ocultar columnas técnicas (como claves foráneas) en el modelo semántico para que los usuarios de informes no las vean.","fr":"Vous devez masquer les colonnes techniques (comme les clés étrangères) dans le modèle sémantique pour que les utilisateurs de rapports ne les voient pas."}', '{"pt-br":"Qual propriedade da coluna deve ser configurada?","en-us":"Which column property should be configured?","es":"¿Qué propiedad de la columna debe configurarse?","fr":"Quelle propriété de colonne doit être configurée ?"}', '[{"key":"A","text":{"pt-br":"Is Hidden = True","en-us":"Is Hidden = True","es":"Is Hidden = True","fr":"Is Hidden = True"}},{"key":"B","text":{"pt-br":"Is Visible = False","en-us":"Is Visible = False","es":"Is Visible = False","fr":"Is Visible = False"}},{"key":"C","text":{"pt-br":"Access Level = None","en-us":"Access Level = None","es":"Access Level = None","fr":"Access Level = None"}},{"key":"D","text":{"pt-br":"Display Folder = _Hidden","en-us":"Display Folder = _Hidden","es":"Display Folder = _Hidden","fr":"Display Folder = _Hidden"}}]', 'A', '{"pt-br":"Is Hidden = True oculta a coluna da lista de campos nos relatórios, mantendo-a disponível para relacionamentos e cálculos DAX internos. É uma prática recomendada para chaves técnicas.","en-us":"Is Hidden = True hides the column from the fields list in reports, keeping it available for relationships and internal DAX calculations. It''s a best practice for technical keys.","es":"Is Hidden = True oculta la columna de la lista de campos en los informes, manteniéndola disponible para relaciones y cálculos DAX internos. Es una práctica recomendada para claves técnicas.","fr":"Is Hidden = True masque la colonne de la liste des champs dans les rapports, la gardant disponible pour les relations et calculs DAX internes. C''est une pratique recommandée pour les clés techniques."}'),
('Projetar Modelos Semânticos', '{"pt-br":"Você precisa criar uma tabela ponte (bridge table) para resolver um relacionamento many-to-many entre alunos e cursos.","en-us":"You need to create a bridge table to resolve a many-to-many relationship between students and courses.","es":"Necesita crear una tabla puente (bridge table) para resolver una relación many-to-many entre alumnos y cursos.","fr":"Vous devez créer une table pont (bridge table) pour résoudre une relation many-to-many entre étudiants et cours."}', '{"pt-br":"Qual é a estrutura correta da tabela ponte?","en-us":"What is the correct bridge table structure?","es":"¿Cuál es la estructura correcta de la tabla puente?","fr":"Quelle est la structure correcte de la table pont ?"}', '[{"key":"A","text":{"pt-br":"Uma tabela com as chaves de ambas as dimensões como colunas","en-us":"A table with both dimension keys as columns","es":"Una tabla con las claves de ambas dimensiones como columnas","fr":"Une table avec les clés des deux dimensions comme colonnes"}},{"key":"B","text":{"pt-br":"Uma tabela com uma coluna concatenada das duas chaves","en-us":"A table with a concatenated column of both keys","es":"Una tabla con una columna concatenada de las dos claves","fr":"Une table avec une colonne concaténée des deux clés"}},{"key":"C","text":{"pt-br":"Usar relação many-to-many direta sem tabela ponte","en-us":"Use direct many-to-many relationship without bridge table","es":"Usar relación many-to-many directa sin tabla puente","fr":"Utiliser une relation many-to-many directe sans table pont"}},{"key":"D","text":{"pt-br":"Duplicar uma das dimensões","en-us":"Duplicate one of the dimensions","es":"Duplicar una de las dimensiones","fr":"Dupliquer une des dimensions"}}]', 'A', '{"pt-br":"A tabela ponte contém as chaves de ambas as dimensões, tendo relações many-to-one com cada dimensão. Isso resolve o many-to-many de forma limpa no star schema.","en-us":"The bridge table contains keys from both dimensions, having many-to-one relationships with each dimension. This cleanly resolves many-to-many in star schema.","es":"La tabla puente contiene las claves de ambas dimensiones, teniendo relaciones many-to-one con cada dimensión. Esto resuelve el many-to-many de forma limpia en star schema.","fr":"La table pont contient les clés des deux dimensions, ayant des relations many-to-one avec chaque dimension. Cela résout proprement le many-to-many dans le star schema."}'),
('Projetar Modelos Semânticos', '{"pt-br":"Você precisa modificar um modelo semântico publicado no Fabric usando ferramentas externas via endpoint programático.","en-us":"You need to modify a published semantic model in Fabric using external tools via programmatic endpoint.","es":"Necesita modificar un modelo semántico publicado en Fabric usando herramientas externas via endpoint programático.","fr":"Vous devez modifier un modèle sémantique publié dans Fabric en utilisant des outils externes via un endpoint programmatique."}', '{"pt-br":"Qual endpoint permite conexão programática a modelos semânticos?","en-us":"Which endpoint allows programmatic connection to semantic models?","es":"¿Qué endpoint permite conexión programática a modelos semánticos?","fr":"Quel endpoint permet la connexion programmatique aux modèles sémantiques ?"}', '[{"key":"A","text":{"pt-br":"XMLA Endpoint","en-us":"XMLA Endpoint","es":"XMLA Endpoint","fr":"XMLA Endpoint"}},{"key":"B","text":{"pt-br":"REST API","en-us":"REST API","es":"REST API","fr":"REST API"}},{"key":"C","text":{"pt-br":"OData Endpoint","en-us":"OData Endpoint","es":"OData Endpoint","fr":"OData Endpoint"}},{"key":"D","text":{"pt-br":"ODBC Connection","en-us":"ODBC Connection","es":"ODBC Connection","fr":"ODBC Connection"}}]', 'A', '{"pt-br":"O XMLA Endpoint permite que ferramentas externas como Tabular Editor, DAX Studio e SSMS se conectem a modelos semânticos para leitura e escrita (com Premium/Fabric).","en-us":"The XMLA Endpoint allows external tools like Tabular Editor, DAX Studio, and SSMS to connect to semantic models for reading and writing (with Premium/Fabric).","es":"El XMLA Endpoint permite que herramientas externas como Tabular Editor, DAX Studio y SSMS se conecten a modelos semánticos para lectura y escritura (con Premium/Fabric).","fr":"Le XMLA Endpoint permet aux outils externes comme Tabular Editor, DAX Studio et SSMS de se connecter aux modèles sémantiques en lecture et écriture (avec Premium/Fabric)."}'),
('Projetar Modelos Semânticos', '{"pt-br":"Você está projetando um modelo e precisa decidir entre criar uma coluna calculada ou uma medida para calcular a margem de lucro.","en-us":"You''re designing a model and need to decide between creating a calculated column or a measure to calculate profit margin.","es":"Está diseñando un modelo y necesita decidir entre crear una columna calculada o una medida para calcular el margen de ganancia.","fr":"Vous concevez un modèle et devez décider entre une colonne calculée ou une mesure pour calculer la marge bénéficiaire."}', '{"pt-br":"Quando usar uma medida em vez de coluna calculada?","en-us":"When to use a measure instead of a calculated column?","es":"¿Cuándo usar una medida en vez de columna calculada?","fr":"Quand utiliser une mesure au lieu d''une colonne calculée ?"}', '[{"key":"A","text":{"pt-br":"Quando o cálculo depende do contexto de filtro do relatório","en-us":"When the calculation depends on the report''s filter context","es":"Cuando el cálculo depende del contexto de filtro del informe","fr":"Quand le calcul dépend du contexte de filtre du rapport"}},{"key":"B","text":{"pt-br":"Quando o valor precisa ser usado como filtro ou slicer","en-us":"When the value needs to be used as filter or slicer","es":"Cuando el valor necesita ser usado como filtro o slicer","fr":"Quand la valeur doit être utilisée comme filtre ou slicer"}},{"key":"C","text":{"pt-br":"Quando o cálculo é row-level (por linha)","en-us":"When the calculation is row-level","es":"Cuando el cálculo es a nivel de fila","fr":"Quand le calcul est au niveau ligne"}},{"key":"D","text":{"pt-br":"Quando precisa ser usado em relacionamentos","en-us":"When it needs to be used in relationships","es":"Cuando necesita ser usado en relaciones","fr":"Quand il doit être utilisé dans les relations"}}]', 'A', '{"pt-br":"Medidas são avaliadas dinamicamente no contexto de filtro do relatório, sendo ideais para agregações. Colunas calculadas são computadas uma vez e armazenadas, ideais para filtros e slicers.","en-us":"Measures are dynamically evaluated in the report''s filter context, ideal for aggregations. Calculated columns are computed once and stored, ideal for filters and slicers.","es":"Las medidas se evalúan dinámicamente en el contexto de filtro del informe, siendo ideales para agregaciones. Las columnas calculadas se computan una vez y se almacenan, ideales para filtros y slicers.","fr":"Les mesures sont évaluées dynamiquement dans le contexte de filtre du rapport, idéales pour les agrégations. Les colonnes calculées sont calculées une fois et stockées, idéales pour les filtres et slicers."}'),
('Projetar Modelos Semânticos', '{"pt-br":"Você precisa organizar medidas em pastas dentro do modelo semântico para facilitar a navegação dos usuários.","en-us":"You need to organize measures into folders within the semantic model to facilitate user navigation.","es":"Necesita organizar medidas en carpetas dentro del modelo semántico para facilitar la navegación de los usuarios.","fr":"Vous devez organiser les mesures en dossiers dans le modèle sémantique pour faciliter la navigation des utilisateurs."}', '{"pt-br":"Qual propriedade permite agrupar medidas em pastas?","en-us":"Which property allows grouping measures into folders?","es":"¿Qué propiedad permite agrupar medidas en carpetas?","fr":"Quelle propriété permet de regrouper les mesures en dossiers ?"}', '[{"key":"A","text":{"pt-br":"Display Folder","en-us":"Display Folder","es":"Display Folder","fr":"Display Folder"}},{"key":"B","text":{"pt-br":"Measure Group","en-us":"Measure Group","es":"Measure Group","fr":"Measure Group"}},{"key":"C","text":{"pt-br":"Category","en-us":"Category","es":"Category","fr":"Category"}},{"key":"D","text":{"pt-br":"Table Group","en-us":"Table Group","es":"Table Group","fr":"Table Group"}}]', 'A', '{"pt-br":"Display Folder é a propriedade que agrupa medidas e colunas em pastas visuais na lista de campos, facilitando a organização (ex: ''Financeiro'', ''KPIs'', ''Temporal'').","en-us":"Display Folder is the property that groups measures and columns into visual folders in the field list, facilitating organization (e.g., ''Financial'', ''KPIs'', ''Temporal'').","es":"Display Folder es la propiedad que agrupa medidas y columnas en carpetas visuales en la lista de campos, facilitando la organización (ej: ''Financiero'', ''KPIs'', ''Temporal'').","fr":"Display Folder est la propriété qui regroupe les mesures et colonnes en dossiers visuels dans la liste des champs, facilitant l''organisation (ex : ''Financier'', ''KPIs'', ''Temporel'')."}'),
('Projetar Modelos Semânticos', '{"pt-br":"Você precisa criar um modelo semântico padrão do Lakehouse no Fabric que é gerado automaticamente.","en-us":"You need to create a default Lakehouse semantic model in Fabric that is automatically generated.","es":"Necesita crear un modelo semántico predeterminado del Lakehouse en Fabric que se genera automáticamente.","fr":"Vous devez créer un modèle sémantique par défaut du Lakehouse dans Fabric qui est automatiquement généré."}', '{"pt-br":"O que é o Default Semantic Model do Lakehouse?","en-us":"What is the Lakehouse Default Semantic Model?","es":"¿Qué es el Default Semantic Model del Lakehouse?","fr":"Qu''est-ce que le Default Semantic Model du Lakehouse ?"}', '[{"key":"A","text":{"pt-br":"Um modelo DirectLake criado automaticamente com todas as tabelas Delta do Lakehouse","en-us":"A DirectLake model automatically created with all Lakehouse Delta tables","es":"Un modelo DirectLake creado automáticamente con todas las tablas Delta del Lakehouse","fr":"Un modèle DirectLake créé automatiquement avec toutes les tables Delta du Lakehouse"}},{"key":"B","text":{"pt-br":"Um modelo Import que precisa ser configurado manualmente","en-us":"An Import model that needs manual configuration","es":"Un modelo Import que necesita configuración manual","fr":"Un modèle Import nécessitant une configuration manuelle"}},{"key":"C","text":{"pt-br":"Um template de modelo sem dados","en-us":"A model template without data","es":"Un template de modelo sin datos","fr":"Un template de modèle sans données"}},{"key":"D","text":{"pt-br":"Um modelo DirectQuery apontando para o SQL Endpoint","en-us":"A DirectQuery model pointing to the SQL Endpoint","es":"Un modelo DirectQuery apuntando al SQL Endpoint","fr":"Un modèle DirectQuery pointant vers le SQL Endpoint"}}]', 'A', '{"pt-br":"O Default Semantic Model é um modelo DirectLake criado e sincronizado automaticamente com as tabelas Delta do Lakehouse, pronto para uso em relatórios sem configuração adicional.","en-us":"The Default Semantic Model is a DirectLake model automatically created and synced with the Lakehouse''s Delta tables, ready for use in reports without additional configuration.","es":"El Default Semantic Model es un modelo DirectLake creado y sincronizado automáticamente con las tablas Delta del Lakehouse, listo para uso en informes sin configuración adicional.","fr":"Le Default Semantic Model est un modèle DirectLake créé et synchronisé automatiquement avec les tables Delta du Lakehouse, prêt à l''emploi dans les rapports sans configuration supplémentaire."}'),
('Otimizar Modelos Semânticos', '{"pt-br":"Seu modelo semântico está consumindo muita memória e o refresh está lento. Você precisa reduzir o tamanho do modelo.","en-us":"Your semantic model is consuming too much memory and refresh is slow. You need to reduce model size.","es":"Su modelo semántico está consumiendo mucha memoria y la actualización está lenta. Necesita reducir el tamaño del modelo.","fr":"Votre modèle sémantique consomme trop de mémoire et le rafraîchissement est lent. Vous devez réduire la taille du modèle."}', '{"pt-br":"Qual técnica é mais eficaz para reduzir o tamanho do modelo?","en-us":"Which technique is most effective for reducing model size?","es":"¿Qué técnica es más eficaz para reducir el tamaño del modelo?","fr":"Quelle technique est la plus efficace pour réduire la taille du modèle ?"}', '[{"key":"A","text":{"pt-br":"Remover colunas desnecessárias e reduzir cardinalidade","en-us":"Remove unnecessary columns and reduce cardinality","es":"Eliminar columnas innecesarias y reducir cardinalidad","fr":"Supprimer les colonnes inutiles et réduire la cardinalité"}},{"key":"B","text":{"pt-br":"Mudar para DirectQuery","en-us":"Switch to DirectQuery","es":"Cambiar a DirectQuery","fr":"Passer en DirectQuery"}},{"key":"C","text":{"pt-br":"Aumentar a capacidade Premium","en-us":"Increase Premium capacity","es":"Aumentar la capacidad Premium","fr":"Augmenter la capacité Premium"}},{"key":"D","text":{"pt-br":"Adicionar mais tabelas de resumo","en-us":"Add more summary tables","es":"Agregar más tablas de resumen","fr":"Ajouter plus de tables de résumé"}}]', 'A', '{"pt-br":"O VertiPaq comprime por coluna - remover colunas não utilizadas e reduzir a cardinalidade (valores distintos) são as técnicas mais eficazes para reduzir o tamanho do modelo.","en-us":"VertiPaq compresses by column - removing unused columns and reducing cardinality (distinct values) are the most effective techniques for reducing model size.","es":"VertiPaq comprime por columna - eliminar columnas no utilizadas y reducir la cardinalidad (valores distintos) son las técnicas más eficaces para reducir el tamaño del modelo.","fr":"VertiPaq compresse par colonne - supprimer les colonnes inutilisées et réduire la cardinalité (valeurs distinctes) sont les techniques les plus efficaces pour réduire la taille du modèle."}'),
('Otimizar Modelos Semânticos', '{"pt-br":"Você precisa analisar quais colunas do modelo semântico consomem mais memória para decidir quais otimizar.","en-us":"You need to analyze which semantic model columns consume the most memory to decide which to optimize.","es":"Necesita analizar qué columnas del modelo semántico consumen más memoria para decidir cuáles optimizar.","fr":"Vous devez analyser quelles colonnes du modèle sémantique consomment le plus de mémoire pour décider lesquelles optimiser."}', '{"pt-br":"Qual ferramenta mostra o consumo de memória por coluna?","en-us":"Which tool shows memory consumption per column?","es":"¿Qué herramienta muestra el consumo de memoria por columna?","fr":"Quel outil montre la consommation de mémoire par colonne ?"}', '[{"key":"A","text":{"pt-br":"VertiPaq Analyzer no DAX Studio","en-us":"VertiPaq Analyzer in DAX Studio","es":"VertiPaq Analyzer en DAX Studio","fr":"VertiPaq Analyzer dans DAX Studio"}},{"key":"B","text":{"pt-br":"Performance Analyzer no Power BI Desktop","en-us":"Performance Analyzer in Power BI Desktop","es":"Performance Analyzer en Power BI Desktop","fr":"Performance Analyzer dans Power BI Desktop"}},{"key":"C","text":{"pt-br":"Capacity Metrics App","en-us":"Capacity Metrics App","es":"Capacity Metrics App","fr":"Capacity Metrics App"}},{"key":"D","text":{"pt-br":"Model View no Power BI Desktop","en-us":"Model View in Power BI Desktop","es":"Model View en Power BI Desktop","fr":"Model View dans Power BI Desktop"}}]', 'A', '{"pt-br":"VertiPaq Analyzer no DAX Studio mostra o tamanho de cada coluna, tabela e relacionamento em memória, cardinalidade e encoding, sendo essencial para otimização de modelos.","en-us":"VertiPaq Analyzer in DAX Studio shows the size of each column, table, and relationship in memory, cardinality and encoding, being essential for model optimization.","es":"VertiPaq Analyzer en DAX Studio muestra el tamaño de cada columna, tabla y relación en memoria, cardinalidad y encoding, siendo esencial para optimización de modelos.","fr":"VertiPaq Analyzer dans DAX Studio montre la taille de chaque colonne, table et relation en mémoire, la cardinalité et l''encodage, étant essentiel pour l''optimisation des modèles."}'),
('Otimizar Modelos Semânticos', '{"pt-br":"Uma medida DAX está executando lentamente porque usa FILTER() em uma tabela grande ao invés de uma abordagem mais eficiente.","en-us":"A DAX measure is running slowly because it uses FILTER() on a large table instead of a more efficient approach.","es":"Una medida DAX se ejecuta lentamente porque usa FILTER() en una tabla grande en vez de un enfoque más eficiente.","fr":"Une mesure DAX s''exécute lentement car elle utilise FILTER() sur une grande table au lieu d''une approche plus efficace."}', '{"pt-br":"Qual é a alternativa mais eficiente ao FILTER() em tabelas grandes?","en-us":"What is the most efficient alternative to FILTER() on large tables?","es":"¿Cuál es la alternativa más eficiente a FILTER() en tablas grandes?","fr":"Quelle est l''alternative la plus efficace à FILTER() sur de grandes tables ?"}', '[{"key":"A","text":{"pt-br":"Usar predicado booleano diretamente no CALCULATE","en-us":"Use boolean predicate directly in CALCULATE","es":"Usar predicado booleano directamente en CALCULATE","fr":"Utiliser un prédicat booléen directement dans CALCULATE"}},{"key":"B","text":{"pt-br":"Usar KEEPFILTERS()","en-us":"Use KEEPFILTERS()","es":"Usar KEEPFILTERS()","fr":"Utiliser KEEPFILTERS()"}},{"key":"C","text":{"pt-br":"Usar VALUES() com FILTER()","en-us":"Use VALUES() with FILTER()","es":"Usar VALUES() con FILTER()","fr":"Utiliser VALUES() avec FILTER()"}},{"key":"D","text":{"pt-br":"Usar TREATAS()","en-us":"Use TREATAS()","es":"Usar TREATAS()","fr":"Utiliser TREATAS()"}}]', 'A', '{"pt-br":"Predicados booleanos em CALCULATE (ex: CALCULATE([Vendas], Produto[Cor] = \"Azul\")) são otimizados pelo engine e muito mais rápidos que FILTER() iterando sobre tabelas grandes.","en-us":"Boolean predicates in CALCULATE (e.g., CALCULATE([Sales], Product[Color] = \"Blue\")) are engine-optimized and much faster than FILTER() iterating over large tables.","es":"Los predicados booleanos en CALCULATE (ej: CALCULATE([Ventas], Producto[Color] = \"Azul\")) son optimizados por el motor y mucho más rápidos que FILTER() iterando sobre tablas grandes.","fr":"Les prédicats booléens dans CALCULATE (ex : CALCULATE([Ventes], Produit[Couleur] = \"Bleu\")) sont optimisés par le moteur et beaucoup plus rapides que FILTER() itérant sur de grandes tables."}'),
('Otimizar Modelos Semânticos', '{"pt-br":"Você precisa configurar agregações no modelo semântico para acelerar consultas em tabelas fato muito grandes.","en-us":"You need to configure aggregations in the semantic model to speed up queries on very large fact tables.","es":"Necesita configurar agregaciones en el modelo semántico para acelerar consultas en tablas de hechos muy grandes.","fr":"Vous devez configurer des agrégations dans le modèle sémantique pour accélérer les requêtes sur de très grandes tables de faits."}', '{"pt-br":"O que são User-Defined Aggregations no Power BI?","en-us":"What are User-Defined Aggregations in Power BI?","es":"¿Qué son las User-Defined Aggregations en Power BI?","fr":"Que sont les User-Defined Aggregations dans Power BI ?"}', '[{"key":"A","text":{"pt-br":"Tabelas pré-agregadas em Import que o engine usa automaticamente antes de consultar a tabela detalhada em DirectQuery","en-us":"Pre-aggregated Import tables the engine automatically uses before querying the detailed DirectQuery table","es":"Tablas pre-agregadas en Import que el motor usa automáticamente antes de consultar la tabla detallada en DirectQuery","fr":"Tables pré-agrégées en Import que le moteur utilise automatiquement avant d''interroger la table détaillée en DirectQuery"}},{"key":"B","text":{"pt-br":"Medidas DAX que fazem SUM, COUNT, etc.","en-us":"DAX measures doing SUM, COUNT, etc.","es":"Medidas DAX que hacen SUM, COUNT, etc.","fr":"Mesures DAX faisant SUM, COUNT, etc."}},{"key":"C","text":{"pt-br":"Views materializadas no Warehouse","en-us":"Materialized views in Warehouse","es":"Views materializadas en Warehouse","fr":"Vues matérialisées dans Warehouse"}},{"key":"D","text":{"pt-br":"Tabelas de resumo criadas manualmente","en-us":"Manually created summary tables","es":"Tablas de resumen creadas manualmente","fr":"Tables de résumé créées manuellement"}}]', 'A', '{"pt-br":"User-Defined Aggregations são tabelas importadas com dados pré-agregados. O engine automaticamente decide se usa a agregação ou a tabela detalhada (DirectQuery) baseado na consulta.","en-us":"User-Defined Aggregations are imported tables with pre-aggregated data. The engine automatically decides whether to use the aggregation or detailed table (DirectQuery) based on the query.","es":"Las User-Defined Aggregations son tablas importadas con datos pre-agregados. El motor decide automáticamente si usa la agregación o la tabla detallada (DirectQuery) según la consulta.","fr":"Les User-Defined Aggregations sont des tables importées avec des données pré-agrégées. Le moteur décide automatiquement d''utiliser l''agrégation ou la table détaillée (DirectQuery) selon la requête."}'),
('Otimizar Modelos Semânticos', '{"pt-br":"Você precisa otimizar uma medida DAX que usa SUMX iterando sobre uma tabela de 10 milhões de linhas.","en-us":"You need to optimize a DAX measure using SUMX iterating over a 10 million row table.","es":"Necesita optimizar una medida DAX que usa SUMX iterando sobre una tabla de 10 millones de filas.","fr":"Vous devez optimiser une mesure DAX utilisant SUMX itérant sur une table de 10 millions de lignes."}', '{"pt-br":"Qual abordagem melhora a performance de iteradores DAX?","en-us":"Which approach improves DAX iterator performance?","es":"¿Qué enfoque mejora el rendimiento de los iteradores DAX?","fr":"Quelle approche améliore les performances des itérateurs DAX ?"}', '[{"key":"A","text":{"pt-br":"Criar uma coluna calculada para o cálculo row-level e usar SUM na medida","en-us":"Create a calculated column for row-level calculation and use SUM in the measure","es":"Crear una columna calculada para el cálculo a nivel de fila y usar SUM en la medida","fr":"Créer une colonne calculée pour le calcul au niveau ligne et utiliser SUM dans la mesure"}},{"key":"B","text":{"pt-br":"Aumentar o timeout da query","en-us":"Increase query timeout","es":"Aumentar el timeout de la query","fr":"Augmenter le timeout de la requête"}},{"key":"C","text":{"pt-br":"Usar COUNTROWS ao invés de SUMX","en-us":"Use COUNTROWS instead of SUMX","es":"Usar COUNTROWS en vez de SUMX","fr":"Utiliser COUNTROWS au lieu de SUMX"}},{"key":"D","text":{"pt-br":"Dividir a tabela em duas","en-us":"Split the table in two","es":"Dividir la tabla en dos","fr":"Diviser la table en deux"}}]', 'A', '{"pt-br":"Se o cálculo SUMX envolve apenas colunas da mesma tabela sem contexto dinâmico, substituir por uma coluna calculada + SUM é mais eficiente pois usa o Storage Engine em vez do Formula Engine.","en-us":"If the SUMX calculation involves only columns from the same table without dynamic context, replacing with a calculated column + SUM is more efficient as it uses Storage Engine instead of Formula Engine.","es":"Si el cálculo SUMX involucra solo columnas de la misma tabla sin contexto dinámico, reemplazar por una columna calculada + SUM es más eficiente ya que usa el Storage Engine en vez del Formula Engine.","fr":"Si le calcul SUMX n''implique que des colonnes de la même table sans contexte dynamique, le remplacer par une colonne calculée + SUM est plus efficace car il utilise le Storage Engine au lieu du Formula Engine."}'),
('Otimizar Modelos Semânticos', '{"pt-br":"Você precisa decidir entre usar Import mode e DirectQuery mode para um modelo semântico de alta performance.","en-us":"You need to decide between Import mode and DirectQuery mode for a high-performance semantic model.","es":"Necesita decidir entre Import mode y DirectQuery mode para un modelo semántico de alto rendimiento.","fr":"Vous devez choisir entre Import mode et DirectQuery mode pour un modèle sémantique haute performance."}', '{"pt-br":"Qual modo geralmente oferece melhor performance de consulta?","en-us":"Which mode generally offers better query performance?","es":"¿Qué modo generalmente ofrece mejor rendimiento de consulta?","fr":"Quel mode offre généralement de meilleures performances de requête ?"}', '[{"key":"A","text":{"pt-br":"Import mode (dados em memória com VertiPaq)","en-us":"Import mode (in-memory data with VertiPaq)","es":"Import mode (datos en memoria con VertiPaq)","fr":"Import mode (données en mémoire avec VertiPaq)"}},{"key":"B","text":{"pt-br":"DirectQuery mode","en-us":"DirectQuery mode","es":"DirectQuery mode","fr":"DirectQuery mode"}},{"key":"C","text":{"pt-br":"Ambos têm performance idêntica","en-us":"Both have identical performance","es":"Ambos tienen rendimiento idéntico","fr":"Les deux ont des performances identiques"}},{"key":"D","text":{"pt-br":"Depende exclusivamente do hardware","en-us":"Depends exclusively on hardware","es":"Depende exclusivamente del hardware","fr":"Dépend exclusivement du matériel"}}]', 'A', '{"pt-br":"Import mode armazena dados comprimidos em memória usando VertiPaq, oferecendo consultas extremamente rápidas. DirectQuery envia queries para a fonte a cada interação, geralmente mais lento.","en-us":"Import mode stores compressed data in memory using VertiPaq, offering extremely fast queries. DirectQuery sends queries to the source on each interaction, generally slower.","es":"Import mode almacena datos comprimidos en memoria usando VertiPaq, ofreciendo consultas extremadamente rápidas. DirectQuery envía queries a la fuente en cada interacción, generalmente más lento.","fr":"Import mode stocke les données compressées en mémoire avec VertiPaq, offrant des requêtes extrêmement rapides. DirectQuery envoie des requêtes à la source à chaque interaction, généralement plus lent."}'),
('Otimizar Modelos Semânticos', '{"pt-br":"Você precisa melhorar o tempo de refresh de um modelo semântico Import que possui tabelas grandes e é atualizado frequentemente.","en-us":"You need to improve the refresh time of an Import semantic model with large tables that refreshes frequently.","es":"Necesita mejorar el tiempo de actualización de un modelo semántico Import con tablas grandes que se actualiza frecuentemente.","fr":"Vous devez améliorer le temps de rafraîchissement d''un modèle sémantique Import avec de grandes tables rafraîchi fréquemment."}', '{"pt-br":"Qual técnica reduz significativamente o tempo de refresh?","en-us":"Which technique significantly reduces refresh time?","es":"¿Qué técnica reduce significativamente el tiempo de actualización?","fr":"Quelle technique réduit significativement le temps de rafraîchissement ?"}', '[{"key":"A","text":{"pt-br":"Incremental Refresh com particionamento automático","en-us":"Incremental Refresh with automatic partitioning","es":"Incremental Refresh con particionamiento automático","fr":"Incremental Refresh avec partitionnement automatique"}},{"key":"B","text":{"pt-br":"Aumentar o paralelismo do refresh","en-us":"Increase refresh parallelism","es":"Aumentar el paralelismo de la actualización","fr":"Augmenter le parallélisme du rafraîchissement"}},{"key":"C","text":{"pt-br":"Usar Dataflow Gen2 como buffer","en-us":"Use Dataflow Gen2 as buffer","es":"Usar Dataflow Gen2 como buffer","fr":"Utiliser Dataflow Gen2 comme tampon"}},{"key":"D","text":{"pt-br":"Comprimir mais os dados","en-us":"Compress data more","es":"Comprimir más los datos","fr":"Compresser davantage les données"}}]', 'A', '{"pt-br":"Incremental Refresh cria partições automaticamente e recarrega apenas as partições com dados novos/modificados, reduzindo drasticamente o tempo e consumo de recursos do refresh.","en-us":"Incremental Refresh automatically creates partitions and reloads only partitions with new/modified data, drastically reducing refresh time and resource consumption.","es":"Incremental Refresh crea particiones automáticamente y recarga solo las particiones con datos nuevos/modificados, reduciendo drásticamente el tiempo y consumo de recursos de la actualización.","fr":"L''Incremental Refresh crée automatiquement des partitions et ne recharge que les partitions avec des données nouvelles/modifiées, réduisant drastiquement le temps et la consommation de ressources du rafraîchissement."}'),
('Otimizar Modelos Semânticos', '{"pt-br":"Você precisa garantir que um modelo semântico DirectLake tenha a melhor performance possível.","en-us":"You need to ensure a DirectLake semantic model has the best possible performance.","es":"Necesita garantizar que un modelo semántico DirectLake tenga el mejor rendimiento posible.","fr":"Vous devez garantir qu''un modèle sémantique DirectLake ait les meilleures performances possibles."}', '{"pt-br":"Qual é a otimização essencial para DirectLake?","en-us":"What is the essential optimization for DirectLake?","es":"¿Cuál es la optimización esencial para DirectLake?","fr":"Quelle est l''optimisation essentielle pour DirectLake ?"}', '[{"key":"A","text":{"pt-br":"Executar OPTIMIZE com V-Order nas tabelas Delta do Lakehouse","en-us":"Run OPTIMIZE with V-Order on Lakehouse Delta tables","es":"Ejecutar OPTIMIZE con V-Order en las tablas Delta del Lakehouse","fr":"Exécuter OPTIMIZE avec V-Order sur les tables Delta du Lakehouse"}},{"key":"B","text":{"pt-br":"Usar particionamento por data","en-us":"Use date partitioning","es":"Usar particionamiento por fecha","fr":"Utiliser le partitionnement par date"}},{"key":"C","text":{"pt-br":"Aumentar o SKU da capacidade","en-us":"Increase capacity SKU","es":"Aumentar el SKU de la capacidad","fr":"Augmenter le SKU de la capacité"}},{"key":"D","text":{"pt-br":"Adicionar índices nas colunas","en-us":"Add indexes on columns","es":"Agregar índices en las columnas","fr":"Ajouter des index sur les colonnes"}}]', 'A', '{"pt-br":"V-Order é uma otimização do Fabric que organiza os dados Parquet para leitura otimizada pelo VertiPaq. OPTIMIZE com V-Order é essencial para performance do DirectLake.","en-us":"V-Order is a Fabric optimization that organizes Parquet data for VertiPaq-optimized reading. OPTIMIZE with V-Order is essential for DirectLake performance.","es":"V-Order es una optimización de Fabric que organiza los datos Parquet para lectura optimizada por VertiPaq. OPTIMIZE con V-Order es esencial para el rendimiento de DirectLake.","fr":"V-Order est une optimisation Fabric qui organise les données Parquet pour une lecture optimisée par VertiPaq. OPTIMIZE avec V-Order est essentiel pour les performances DirectLake."}'),
('Otimizar Modelos Semânticos', '{"pt-br":"Você identificou que colunas de texto com alta cardinalidade estão ocupando muita memória no modelo Import.","en-us":"You identified that high-cardinality text columns are consuming too much memory in the Import model.","es":"Identificó que columnas de texto con alta cardinalidad están ocupando mucha memoria en el modelo Import.","fr":"Vous avez identifié que les colonnes de texte à haute cardinalité consomment trop de mémoire dans le modèle Import."}', '{"pt-br":"Qual técnica reduz o impacto de colunas de alta cardinalidade?","en-us":"Which technique reduces the impact of high-cardinality columns?","es":"¿Qué técnica reduce el impacto de columnas de alta cardinalidad?","fr":"Quelle technique réduit l''impact des colonnes à haute cardinalité ?"}', '[{"key":"A","text":{"pt-br":"Remover a coluna se não for essencial para análise, ou mover para uma dimensão separada","en-us":"Remove the column if not essential for analysis, or move to a separate dimension","es":"Eliminar la columna si no es esencial para el análisis, o mover a una dimensión separada","fr":"Supprimer la colonne si elle n''est pas essentielle à l''analyse, ou la déplacer vers une dimension séparée"}},{"key":"B","text":{"pt-br":"Converter para tipo numérico","en-us":"Convert to numeric type","es":"Convertir a tipo numérico","fr":"Convertir en type numérique"}},{"key":"C","text":{"pt-br":"Aplicar hash na coluna","en-us":"Apply hash on the column","es":"Aplicar hash en la columna","fr":"Appliquer un hash sur la colonne"}},{"key":"D","text":{"pt-br":"Usar compressão personalizada","en-us":"Use custom compression","es":"Usar compresión personalizada","fr":"Utiliser une compression personnalisée"}}]', 'A', '{"pt-br":"Colunas de texto com alta cardinalidade (como descrições livres ou IDs alfanuméricos) consomem muita memória. A melhor abordagem é removê-las se não forem necessárias para análise.","en-us":"High-cardinality text columns (like free descriptions or alphanumeric IDs) consume a lot of memory. The best approach is to remove them if not needed for analysis.","es":"Columnas de texto con alta cardinalidad (como descripciones libres o IDs alfanuméricos) consumen mucha memoria. El mejor enfoque es eliminarlas si no son necesarias para análisis.","fr":"Les colonnes de texte à haute cardinalité (comme les descriptions libres ou les IDs alphanumériques) consomment beaucoup de mémoire. La meilleure approche est de les supprimer si elles ne sont pas nécessaires à l''analyse."}'),
('Otimizar Modelos Semânticos', '{"pt-br":"Você precisa melhorar a performance de um visual que usa uma medida DAX complexa com múltiplos CALCULATE aninhados.","en-us":"You need to improve performance of a visual using a complex DAX measure with multiple nested CALCULATEs.","es":"Necesita mejorar el rendimiento de un visual que usa una medida DAX compleja con múltiples CALCULATE anidados.","fr":"Vous devez améliorer les performances d''un visuel utilisant une mesure DAX complexe avec plusieurs CALCULATE imbriqués."}', '{"pt-br":"Qual técnica DAX melhora a legibilidade e pode melhorar a performance?","en-us":"Which DAX technique improves readability and can improve performance?","es":"¿Qué técnica DAX mejora la legibilidad y puede mejorar el rendimiento?","fr":"Quelle technique DAX améliore la lisibilité et peut améliorer les performances ?"}', '[{"key":"A","text":{"pt-br":"Usar variáveis (VAR/RETURN) para evitar recálculos","en-us":"Use variables (VAR/RETURN) to avoid recalculations","es":"Usar variables (VAR/RETURN) para evitar recálculos","fr":"Utiliser des variables (VAR/RETURN) pour éviter les recalculs"}},{"key":"B","text":{"pt-br":"Usar IF ao invés de SWITCH","en-us":"Use IF instead of SWITCH","es":"Usar IF en vez de SWITCH","fr":"Utiliser IF au lieu de SWITCH"}},{"key":"C","text":{"pt-br":"Adicionar mais CALCULATE","en-us":"Add more CALCULATE","es":"Agregar más CALCULATE","fr":"Ajouter plus de CALCULATE"}},{"key":"D","text":{"pt-br":"Usar FORMAT() para tipos","en-us":"Use FORMAT() for types","es":"Usar FORMAT() para tipos","fr":"Utiliser FORMAT() pour les types"}}]', 'A', '{"pt-br":"Variáveis (VAR) em DAX são avaliadas uma única vez e reutilizadas, evitando recálculos de subexpressões idênticas. Isso melhora tanto performance quanto legibilidade do código.","en-us":"Variables (VAR) in DAX are evaluated once and reused, avoiding recalculations of identical subexpressions. This improves both performance and code readability.","es":"Las variables (VAR) en DAX se evalúan una sola vez y se reutilizan, evitando recálculos de subexpresiones idénticas. Esto mejora tanto el rendimiento como la legibilidad del código.","fr":"Les variables (VAR) en DAX sont évaluées une seule fois et réutilisées, évitant les recalculs de sous-expressions identiques. Cela améliore à la fois les performances et la lisibilité du code."}'),
('Otimizar Modelos Semânticos', '{"pt-br":"Você precisa configurar o modelo semântico para que dados grandes sejam processados pela capacidade Premium sem esgotar a memória.","en-us":"You need to configure the semantic model so large data is processed by Premium capacity without exhausting memory.","es":"Necesita configurar el modelo semántico para que datos grandes sean procesados por la capacidad Premium sin agotar la memoria.","fr":"Vous devez configurer le modèle sémantique pour que les grandes données soient traitées par la capacité Premium sans épuiser la mémoire."}', '{"pt-br":"Qual configuração do dataset controla o uso de memória durante refresh?","en-us":"Which dataset setting controls memory usage during refresh?","es":"¿Qué configuración del dataset controla el uso de memoria durante la actualización?","fr":"Quel paramètre du dataset contrôle l''utilisation de la mémoire pendant le rafraîchissement ?"}', '[{"key":"A","text":{"pt-br":"Large Dataset Storage Format","en-us":"Large Dataset Storage Format","es":"Large Dataset Storage Format","fr":"Large Dataset Storage Format"}},{"key":"B","text":{"pt-br":"Max Memory per Query","en-us":"Max Memory per Query","es":"Max Memory per Query","fr":"Max Memory per Query"}},{"key":"C","text":{"pt-br":"Query Timeout","en-us":"Query Timeout","es":"Query Timeout","fr":"Query Timeout"}},{"key":"D","text":{"pt-br":"Automatic Page Refresh","en-us":"Automatic Page Refresh","es":"Automatic Page Refresh","fr":"Automatic Page Refresh"}}]', 'A', '{"pt-br":"Large Dataset Storage Format permite que datasets Premium excedam 10GB, usando paginação de memória para gerenciar modelos grandes sem esgotar a RAM disponível.","en-us":"Large Dataset Storage Format allows Premium datasets to exceed 10GB, using memory paging to manage large models without exhausting available RAM.","es":"Large Dataset Storage Format permite que datasets Premium excedan 10GB, usando paginación de memoria para administrar modelos grandes sin agotar la RAM disponible.","fr":"Large Dataset Storage Format permet aux datasets Premium de dépasser 10 Go, utilisant la pagination mémoire pour gérer les grands modèles sans épuiser la RAM disponible."}'),
('Otimizar Modelos Semânticos', '{"pt-br":"Você precisa usar o Performance Analyzer no Power BI Desktop para identificar quais visuais estão mais lentos em uma página de relatório.","en-us":"You need to use Performance Analyzer in Power BI Desktop to identify which visuals are slowest on a report page.","es":"Necesita usar Performance Analyzer en Power BI Desktop para identificar qué visuales son más lentos en una página de informe.","fr":"Vous devez utiliser Performance Analyzer dans Power BI Desktop pour identifier quels visuels sont les plus lents sur une page de rapport."}', '{"pt-br":"O que o Performance Analyzer mostra para cada visual?","en-us":"What does Performance Analyzer show for each visual?","es":"¿Qué muestra Performance Analyzer para cada visual?","fr":"Que montre Performance Analyzer pour chaque visuel ?"}', '[{"key":"A","text":{"pt-br":"Tempo de DAX query, Direct Query e renderização visual","en-us":"DAX query time, Direct Query time, and visual rendering time","es":"Tiempo de DAX query, Direct Query y renderización visual","fr":"Temps de requête DAX, Direct Query et rendu visuel"}},{"key":"B","text":{"pt-br":"Apenas o tempo total de carregamento","en-us":"Only total loading time","es":"Solo el tiempo total de carga","fr":"Uniquement le temps de chargement total"}},{"key":"C","text":{"pt-br":"Consumo de memória por visual","en-us":"Memory consumption per visual","es":"Consumo de memoria por visual","fr":"Consommation de mémoire par visuel"}},{"key":"D","text":{"pt-br":"Número de linhas processadas","en-us":"Number of processed rows","es":"Número de filas procesadas","fr":"Nombre de lignes traitées"}}]', 'A', '{"pt-br":"Performance Analyzer decompõe o tempo em DAX query (processamento da medida), Direct Query (tempo na fonte de dados) e renderização visual, permitindo identificar o gargalo específico.","en-us":"Performance Analyzer breaks down time into DAX query (measure processing), Direct Query (data source time), and visual rendering, allowing identification of the specific bottleneck.","es":"Performance Analyzer descompone el tiempo en DAX query (procesamiento de la medida), Direct Query (tiempo en la fuente) y renderización visual, permitiendo identificar el cuello de botella específico.","fr":"Performance Analyzer décompose le temps en requête DAX (traitement de la mesure), Direct Query (temps source) et rendu visuel, permettant d''identifier le goulot d''étranglement spécifique."}'),
('Otimizar Modelos Semânticos', '{"pt-br":"Você precisa evitar que relacionamentos bidirecionais causem ambiguidade e problemas de performance no modelo.","en-us":"You need to prevent bidirectional relationships from causing ambiguity and performance issues in the model.","es":"Necesita evitar que las relaciones bidireccionales causen ambigüedad y problemas de rendimiento en el modelo.","fr":"Vous devez empêcher les relations bidirectionnelles de causer de l''ambiguïté et des problèmes de performance dans le modèle."}', '{"pt-br":"Qual é a melhor prática para filtros bidirecionais?","en-us":"What is the best practice for bidirectional filters?","es":"¿Cuál es la mejor práctica para filtros bidireccionales?","fr":"Quelle est la meilleure pratique pour les filtres bidirectionnels ?"}', '[{"key":"A","text":{"pt-br":"Evitar filtros bidirecionais no modelo; usar CROSSFILTER() em medidas DAX quando necessário","en-us":"Avoid bidirectional filters in the model; use CROSSFILTER() in DAX measures when needed","es":"Evitar filtros bidireccionales en el modelo; usar CROSSFILTER() en medidas DAX cuando sea necesario","fr":"Éviter les filtres bidirectionnels dans le modèle ; utiliser CROSSFILTER() dans les mesures DAX si nécessaire"}},{"key":"B","text":{"pt-br":"Sempre usar filtros bidirecionais para máxima flexibilidade","en-us":"Always use bidirectional filters for maximum flexibility","es":"Siempre usar filtros bidireccionales para máxima flexibilidad","fr":"Toujours utiliser des filtres bidirectionnels pour une flexibilité maximale"}},{"key":"C","text":{"pt-br":"Usar apenas relações many-to-many","en-us":"Use only many-to-many relationships","es":"Usar solo relaciones many-to-many","fr":"Utiliser uniquement des relations many-to-many"}},{"key":"D","text":{"pt-br":"Remover todas as relações e usar LOOKUPVALUE","en-us":"Remove all relationships and use LOOKUPVALUE","es":"Eliminar todas las relaciones y usar LOOKUPVALUE","fr":"Supprimer toutes les relations et utiliser LOOKUPVALUE"}}]', 'A', '{"pt-br":"Filtros bidirecionais permanentes podem causar ambiguidade e circular dependency. A melhor prática é usar CROSSFILTER() em medidas DAX específicas que precisam do comportamento bidirecional.","en-us":"Permanent bidirectional filters can cause ambiguity and circular dependency. Best practice is using CROSSFILTER() in specific DAX measures that need bidirectional behavior.","es":"Los filtros bidireccionales permanentes pueden causar ambigüedad y dependencia circular. La mejor práctica es usar CROSSFILTER() en medidas DAX específicas que necesitan comportamiento bidireccional.","fr":"Les filtres bidirectionnels permanents peuvent causer de l''ambiguïté et des dépendances circulaires. La meilleure pratique est d''utiliser CROSSFILTER() dans les mesures DAX spécifiques nécessitant un comportement bidirectionnel."}'),
('Otimizar Modelos Semânticos', '{"pt-br":"Você precisa implementar refresh parcial via XMLA endpoint para controlar quais partições são atualizadas em um modelo grande.","en-us":"You need to implement partial refresh via XMLA endpoint to control which partitions are updated in a large model.","es":"Necesita implementar actualización parcial via XMLA endpoint para controlar qué particiones se actualizan en un modelo grande.","fr":"Vous devez implémenter un rafraîchissement partiel via XMLA endpoint pour contrôler quelles partitions sont mises à jour dans un grand modèle."}', '{"pt-br":"Qual operação TMSL é usada para refresh parcial?","en-us":"Which TMSL operation is used for partial refresh?","es":"¿Qué operación TMSL se usa para actualización parcial?","fr":"Quelle opération TMSL est utilisée pour le rafraîchissement partiel ?"}', '[{"key":"A","text":{"pt-br":"Refresh command com tipo específico (full, dataOnly, calculate) por partição","en-us":"Refresh command with specific type (full, dataOnly, calculate) per partition","es":"Refresh command con tipo específico (full, dataOnly, calculate) por partición","fr":"Commande Refresh avec type spécifique (full, dataOnly, calculate) par partition"}},{"key":"B","text":{"pt-br":"Process command","en-us":"Process command","es":"Process command","fr":"Process command"}},{"key":"C","text":{"pt-br":"Update command","en-us":"Update command","es":"Update command","fr":"Update command"}},{"key":"D","text":{"pt-br":"Sync command","en-us":"Sync command","es":"Sync command","fr":"Sync command"}}]', 'A', '{"pt-br":"Via XMLA, o comando Refresh com tipos específicos (full, dataOnly, calculate, clearValues, defragment) permite controle granular de quais objetos e partições são processados.","en-us":"Via XMLA, the Refresh command with specific types (full, dataOnly, calculate, clearValues, defragment) allows granular control of which objects and partitions are processed.","es":"Via XMLA, el comando Refresh con tipos específicos (full, dataOnly, calculate, clearValues, defragment) permite control granular de qué objetos y particiones se procesan.","fr":"Via XMLA, la commande Refresh avec des types spécifiques (full, dataOnly, calculate, clearValues, defragment) permet un contrôle granulaire des objets et partitions à traiter."}'),
('Otimizar Modelos Semânticos', '{"pt-br":"Você precisa reduzir a cardinalidade de uma coluna DateTime no modelo para melhorar a compressão VertiPaq.","en-us":"You need to reduce the cardinality of a DateTime column in the model to improve VertiPaq compression.","es":"Necesita reducir la cardinalidad de una columna DateTime en el modelo para mejorar la compresión VertiPaq.","fr":"Vous devez réduire la cardinalité d''une colonne DateTime dans le modèle pour améliorer la compression VertiPaq."}', '{"pt-br":"Qual técnica é recomendada?","en-us":"Which technique is recommended?","es":"¿Qué técnica se recomienda?","fr":"Quelle technique est recommandée ?"}', '[{"key":"A","text":{"pt-br":"Separar Date e Time em colunas distintas","en-us":"Separate Date and Time into distinct columns","es":"Separar Date y Time en columnas distintas","fr":"Séparer Date et Time en colonnes distinctes"}},{"key":"B","text":{"pt-br":"Converter para string","en-us":"Convert to string","es":"Convertir a string","fr":"Convertir en chaîne"}},{"key":"C","text":{"pt-br":"Arredondar para hora cheia","en-us":"Round to full hour","es":"Redondear a hora completa","fr":"Arrondir à l''heure pleine"}},{"key":"D","text":{"pt-br":"Usar epoch time (número inteiro)","en-us":"Use epoch time (integer)","es":"Usar epoch time (número entero)","fr":"Utiliser epoch time (nombre entier)"}}]', 'A', '{"pt-br":"Separar DateTime em Date e Time reduz drasticamente a cardinalidade de cada coluna. Uma coluna Date de um ano tem ~365 valores distintos vs ~86400 de uma DateTime com segundos.","en-us":"Separating DateTime into Date and Time drastically reduces each column''s cardinality. A Date column for one year has ~365 distinct values vs ~86400 for a DateTime with seconds.","es":"Separar DateTime en Date y Time reduce drásticamente la cardinalidad de cada columna. Una columna Date de un año tiene ~365 valores distintos vs ~86400 de una DateTime con segundos.","fr":"Séparer DateTime en Date et Time réduit drastiquement la cardinalité de chaque colonne. Une colonne Date d''un an a ~365 valeurs distinctes vs ~86400 pour un DateTime avec secondes."}'),
('Otimizar Modelos Semânticos', '{"pt-br":"Você precisa garantir que queries enviadas ao modelo semântico não consumam recursos excessivamente durante picos de uso.","en-us":"You need to ensure queries sent to the semantic model don''t consume excessive resources during peak usage.","es":"Necesita garantizar que las queries enviadas al modelo semántico no consuman recursos excesivamente durante picos de uso.","fr":"Vous devez garantir que les requêtes envoyées au modèle sémantique ne consomment pas de ressources excessives pendant les pics d''utilisation."}', '{"pt-br":"Qual configuração limita o impacto de queries pesadas?","en-us":"Which setting limits the impact of heavy queries?","es":"¿Qué configuración limita el impacto de queries pesadas?","fr":"Quel paramètre limite l''impact des requêtes lourdes ?"}', '[{"key":"A","text":{"pt-br":"Query timeout e Max Intermediate Row Count","en-us":"Query timeout and Max Intermediate Row Count","es":"Query timeout y Max Intermediate Row Count","fr":"Query timeout et Max Intermediate Row Count"}},{"key":"B","text":{"pt-br":"Autoscale capacity","en-us":"Autoscale capacity","es":"Autoscale capacity","fr":"Autoscale capacity"}},{"key":"C","text":{"pt-br":"Load balancing","en-us":"Load balancing","es":"Load balancing","fr":"Load balancing"}},{"key":"D","text":{"pt-br":"Query caching","en-us":"Query caching","es":"Query caching","fr":"Query caching"}}]', 'A', '{"pt-br":"Query timeout e Max Intermediate Row Count são configurações que limitam o tempo e recursos que uma query individual pode consumir, protegendo a capacidade durante picos.","en-us":"Query timeout and Max Intermediate Row Count are settings that limit the time and resources an individual query can consume, protecting capacity during peaks.","es":"Query timeout y Max Intermediate Row Count son configuraciones que limitan el tiempo y recursos que una query individual puede consumir, protegiendo la capacidad durante picos.","fr":"Query timeout et Max Intermediate Row Count sont des paramètres limitant le temps et les ressources qu''une requête individuelle peut consommer, protégeant la capacité pendant les pics."}'),
('Otimizar Modelos Semânticos', '{"pt-br":"Você precisa implementar query caching para melhorar o tempo de resposta de dashboards frequentemente acessados.","en-us":"You need to implement query caching to improve response time for frequently accessed dashboards.","es":"Necesita implementar query caching para mejorar el tiempo de respuesta de dashboards frecuentemente accedidos.","fr":"Vous devez implémenter le query caching pour améliorer le temps de réponse des tableaux de bord fréquemment consultés."}', '{"pt-br":"Como o Power BI implementa caching de queries?","en-us":"How does Power BI implement query caching?","es":"¿Cómo Power BI implementa caching de queries?","fr":"Comment Power BI implémente-t-il le cache de requêtes ?"}', '[{"key":"A","text":{"pt-br":"Query caching por dataset habilitado nas configurações do dataset (Premium/Fabric)","en-us":"Per-dataset query caching enabled in dataset settings (Premium/Fabric)","es":"Query caching por dataset habilitado en la configuración del dataset (Premium/Fabric)","fr":"Cache de requêtes par dataset activé dans les paramètres du dataset (Premium/Fabric)"}},{"key":"B","text":{"pt-br":"Cache automático de browser","en-us":"Automatic browser cache","es":"Cache automático del navegador","fr":"Cache automatique du navigateur"}},{"key":"C","text":{"pt-br":"Redis cache externo","en-us":"External Redis cache","es":"Redis cache externo","fr":"Cache Redis externe"}},{"key":"D","text":{"pt-br":"CDN caching","en-us":"CDN caching","es":"CDN caching","fr":"CDN caching"}}]', 'A', '{"pt-br":"Em capacidades Premium/Fabric, o query caching pode ser habilitado por dataset, armazenando resultados de queries frequentes para entrega mais rápida sem reprocessar o modelo.","en-us":"In Premium/Fabric capacities, query caching can be enabled per dataset, storing frequent query results for faster delivery without reprocessing the model.","es":"En capacidades Premium/Fabric, el query caching puede habilitarse por dataset, almacenando resultados de queries frecuentes para entrega más rápida sin reprocesar el modelo.","fr":"Dans les capacités Premium/Fabric, le cache de requêtes peut être activé par dataset, stockant les résultats des requêtes fréquentes pour une livraison plus rapide sans retraiter le modèle."}'),
('Segurança e Governança', '{"pt-br":"Você tem um workspace do Fabric que contém um lakehouse chamado Lakehouse1. Um usuário chamado User1 planeja usar o Lakehouse para ler dados do Lakehouse1.","en-us":"You have a Fabric workspace that contains a lakehouse called Lakehouse1. A user named User1 plans to use the Lakehouse to read data from Lakehouse1.","es":"Tiene un workspace de Fabric que contiene un lakehouse llamado Lakehouse1. Un usuario llamado User1 planea usar el Lakehouse para leer datos de Lakehouse1.","fr":"Vous avez un workspace Fabric contenant un lakehouse appelé Lakehouse1. Un utilisateur nommé User1 prévoit d''utiliser le Lakehouse pour lire les données de Lakehouse1."}', '{"pt-br":"Você precisa atribuir uma função de workspace ao User1. A solução deve seguir o princípio de privilégios mínimos. Qual função de workspace você deve atribuir?","en-us":"You need to assign a workspace role to User1. The solution must follow the principle of least privilege. Which workspace role should you assign?","es":"Necesita asignar un rol de workspace a User1. La solución debe seguir el principio de privilegios mínimos. ¿Qué rol de workspace debe asignar?","fr":"Vous devez attribuer un rôle de workspace à User1. La solution doit suivre le principe du moindre privilège. Quel rôle de workspace devez-vous attribuer ?"}', '[{"key":"A","text":{"pt-br":"Administrador","en-us":"Admin","es":"Administrador","fr":"Administrateur"}},{"key":"B","text":{"pt-br":"Membro","en-us":"Member","es":"Miembro","fr":"Membre"}},{"key":"C","text":{"pt-br":"Colaborador","en-us":"Contributor","es":"Colaborador","fr":"Contributeur"}},{"key":"D","text":{"pt-br":"Visualizador","en-us":"Viewer","es":"Visor","fr":"Visionneur"}}]', 'C', '{"pt-br":"Para ler dados de um lakehouse via Explorador de Lakehouse, os usuários precisam de Admin, Membro ou Colaborador. Pelo princípio de privilégio mínimo, Colaborador é a escolha correta. Visualizador não permite ler dados pelo Explorador do Lakehouse.","en-us":"To read data from a lakehouse via Lakehouse Explorer, users need Admin, Member, or Contributor roles. Following least privilege, Contributor is the correct choice. Viewer doesn''t permit reading data through Lakehouse Explorer.","es":"Para leer datos de un lakehouse vía Explorador de Lakehouse, los usuarios necesitan Admin, Miembro o Colaborador. Siguiendo el principio de privilegio mínimo, Colaborador es la opción correcta.","fr":"Pour lire les données d''un lakehouse via l''Explorateur Lakehouse, les utilisateurs ont besoin des rôles Admin, Membre ou Contributeur. Selon le principe du moindre privilège, Contributeur est le bon choix."}'),
('Ciclo de Vida', '{"pt-br":"Você usa o Microsoft Fabric para gerenciar soluções de análise de dados e precisa configurar um pipeline de implantação que mantenha dependências de item e suporte atualização incremental.","en-us":"You use Microsoft Fabric to manage data analytics solutions and need to configure a deployment pipeline that maintains item dependencies and supports incremental refresh.","es":"Usa Microsoft Fabric para gestionar soluciones de análisis de datos y necesita configurar un pipeline de implementación que mantenga dependencias de ítems y soporte actualización incremental.","fr":"Vous utilisez Microsoft Fabric pour gérer des solutions d''analyse de données et devez configurer un pipeline de déploiement qui maintient les dépendances d''éléments et prend en charge l''actualisation incrémentielle."}', '{"pt-br":"Quais três ações são necessárias para configurar o pipeline de implantação corretamente?","en-us":"Which three actions are required to correctly configure the deployment pipeline?","es":"¿Cuáles tres acciones son necesarias para configurar correctamente el pipeline de implementación?","fr":"Quelles trois actions sont nécessaires pour configurer correctement le pipeline de déploiement ?"}', '[{"key":"A","text":{"pt-br":"Vinculação automática, atualização incremental e regras de implantação para conexões","en-us":"Auto-binding, incremental refresh, and deployment rules for connections","es":"Vinculación automática, actualización incremental y reglas de implementación para conexiones","fr":"Liaison automatique, actualisation incrémentielle et règles de déploiement pour les connexions"}},{"key":"B","text":{"pt-br":"Agenda estática, criação manual de workspaces e vinculação automática","en-us":"Static schedule, manual workspace creation, and auto-binding","es":"Agenda estática, creación manual de workspaces y vinculación automática","fr":"Planning statique, création manuelle de workspaces et liaison automatique"}},{"key":"C","text":{"pt-br":"Regras de implantação, agenda estática e criação manual de workspaces","en-us":"Deployment rules, static schedule, and manual workspace creation","es":"Reglas de implementación, agenda estática y creación manual de workspaces","fr":"Règles de déploiement, planning statique et création manuelle de workspaces"}},{"key":"D","text":{"pt-br":"Vinculação automática, agenda estática e regras de implantação","en-us":"Auto-binding, static schedule, and deployment rules","es":"Vinculación automática, agenda estática y reglas de implementación","fr":"Liaison automatique, planning statique et règles de déploiement"}}]', 'A', '{"pt-br":"Vinculação automática mantém conexões entre estágios. Atualização incremental garante consistência da política de atualização. Regras de implantação gerenciam conexões de fonte de dados entre estágios.","en-us":"Auto-binding maintains connections between stages. Incremental refresh ensures refresh policy consistency. Deployment rules manage data source connections across stages.","es":"La vinculación automática mantiene conexiones entre etapas. La actualización incremental garantiza consistencia. Las reglas de implementación gestionan conexiones de fuentes de datos.","fr":"La liaison automatique maintient les connexions entre les étapes. L''actualisation incrémentielle assure la cohérence. Les règles de déploiement gèrent les connexions sources."}'),
('Segurança e Governança', '{"pt-br":"Você tem um workspace do Fabric com um lakehouse, pipeline de dados, notebook e relatórios Power BI. User1 precisa usar SQL para acessar o lakehouse com acesso somente leitura, sem acessar outros itens e sem usar Spark.","en-us":"You have a Fabric workspace with a lakehouse, data pipeline, notebook, and Power BI reports. User1 needs SQL read-only access to the lakehouse without accessing other items or using Spark.","es":"Tiene un workspace de Fabric con lakehouse, pipeline de datos, notebook e informes Power BI. User1 necesita acceso SQL de solo lectura al lakehouse sin acceder a otros ítems ni usar Spark.","fr":"Vous avez un workspace Fabric avec un lakehouse, un pipeline de données, un notebook et des rapports Power BI. User1 a besoin d''un accès SQL en lecture seule au lakehouse sans accéder aux autres éléments ni utiliser Spark."}', '{"pt-br":"O que você deve fazer para configurar o acesso do User1?","en-us":"What should you do to configure User1''s access?","es":"¿Qué debe hacer para configurar el acceso de User1?","fr":"Que devez-vous faire pour configurer l''accès de User1 ?"}', '[{"key":"A","text":{"pt-br":"Compartilhe o lakehouse diretamente com User1 e selecione ''Ler todos os dados do Endpoint do SQL''","en-us":"Share the lakehouse directly with User1 and select ''Read all SQL Endpoint data''","es":"Comparta el lakehouse directamente con User1 y seleccione ''Leer todos los datos del Endpoint SQL''","fr":"Partagez le lakehouse directement avec User1 et sélectionnez ''Lire toutes les données du point de terminaison SQL''"}},{"key":"B","text":{"pt-br":"Adicione User1 como Visualizador no workspace","en-us":"Add User1 as a Viewer in the workspace","es":"Agregue User1 como Visor en el workspace","fr":"Ajoutez User1 en tant que Visionneur dans le workspace"}},{"key":"C","text":{"pt-br":"Compartilhe o endpoint de análise SQL diretamente","en-us":"Share the SQL analytics endpoint directly","es":"Comparta el endpoint de análisis SQL directamente","fr":"Partagez le point de terminaison SQL directement"}},{"key":"D","text":{"pt-br":"Adicione User1 como Colaborador no workspace","en-us":"Add User1 as a Contributor in the workspace","es":"Agregue User1 como Colaborador en el workspace","fr":"Ajoutez User1 en tant que Contributeur dans le workspace"}}]', 'A', '{"pt-br":"Compartilhar o lakehouse diretamente com ''Ler todos os dados do Endpoint SQL'' dá acesso somente leitura via SQL sem acesso a outros itens do workspace. Adicionar ao workspace como membro/visualizador daria acesso a todos os relatórios.","en-us":"Sharing the lakehouse directly with ''Read all SQL Endpoint data'' gives SQL read-only access without accessing other workspace items. Adding as a workspace member/viewer would give access to all reports.","es":"Compartir el lakehouse directamente con ''Leer datos del Endpoint SQL'' da acceso de solo lectura sin acceder a otros ítems del workspace.","fr":"Partager le lakehouse directement avec ''Lire les données du point de terminaison SQL'' donne un accès en lecture seule sans accéder aux autres éléments du workspace."}'),
('Segurança e Governança', '{"pt-br":"Sua empresa usa Microsoft Fabric para análise de dados. O departamento de marketing precisa compartilhar relatórios com parceiros externos sem comprometer dados confidenciais.","en-us":"Your company uses Microsoft Fabric for data analytics. The marketing department needs to share reports with external partners without compromising sensitive data.","es":"Su empresa usa Microsoft Fabric para análisis de datos. El departamento de marketing necesita compartir informes con socios externos sin comprometer datos confidenciales.","fr":"Votre entreprise utilise Microsoft Fabric pour l''analyse de données. Le département marketing doit partager des rapports avec des partenaires externes sans compromettre les données sensibles."}', '{"pt-br":"Quais três ações você deve executar para compartilhar relatórios de forma segura com parceiros externos?","en-us":"Which three actions should you perform to securely share reports with external partners?","es":"¿Cuáles tres acciones debe ejecutar para compartir informes de forma segura con socios externos?","fr":"Quelles trois actions devez-vous effectuer pour partager des rapports de manière sécurisée avec des partenaires externes ?"}', '[{"key":"A","text":{"pt-br":"Implementar RLS, definir identidade fixa nas credenciais e configurar um aplicativo do Power BI","en-us":"Implement RLS, set fixed identity credentials, and configure a Power BI app","es":"Implementar RLS, definir identidad fija en credenciales y configurar un app de Power BI","fr":"Implémenter RLS, définir une identité fixe dans les identifiants et configurer une application Power BI"}},{"key":"B","text":{"pt-br":"Restringir compartilhamento do workspace, implementar RLS e compartilhar por email","en-us":"Restrict workspace sharing, implement RLS, and share via email","es":"Restringir compartir del workspace, implementar RLS y compartir por email","fr":"Restreindre le partage du workspace, implémenter RLS et partager par email"}},{"key":"C","text":{"pt-br":"Implementar RLS, compartilhar por email e atribuir função de visualizador","en-us":"Implement RLS, share via email, and assign viewer role","es":"Implementar RLS, compartir por email y asignar rol de visor","fr":"Implémenter RLS, partager par email et attribuer le rôle de visionneur"}},{"key":"D","text":{"pt-br":"Definir identidade fixa, restringir compartilhamento e compartilhar por email","en-us":"Set fixed identity, restrict sharing, and share via email","es":"Definir identidad fija, restringir compartir y compartir por email","fr":"Définir une identité fixe, restreindre le partage et partager par email"}}]', 'A', '{"pt-br":"RLS controla visibilidade de dados por identidade do usuário. Identidade fixa garante acesso adequado para parceiros externos. Aplicativos Power BI permitem compartilhamento seguro. Compartilhar por email pode causar vazamento de dados.","en-us":"RLS controls data visibility by user identity. Fixed identity ensures proper external partner access. Power BI apps enable secure sharing. Email sharing may cause data leaks.","es":"RLS controla visibilidad de datos por identidad de usuario. Identidad fija garantiza acceso adecuado para socios externos. Aplicaciones Power BI permiten compartir de forma segura.","fr":"RLS contrôle la visibilité des données par identité utilisateur. L''identité fixe garantit un accès approprié aux partenaires externes. Les applications Power BI permettent un partage sécurisé."}'),
('Segurança e Governança', '{"pt-br":"Sua organização usa Microsoft Fabric para gerenciar um data warehouse com dados confidenciais. Você precisa implementar medidas de segurança para limitar o acesso a determinados elementos de dados sem afetar a camada do aplicativo.","en-us":"Your organization uses Microsoft Fabric to manage a data warehouse with sensitive data. You need to implement security measures to limit access to certain data elements without affecting the application layer.","es":"Su organización usa Microsoft Fabric para gestionar un data warehouse con datos confidenciales. Necesita implementar medidas de seguridad para limitar el acceso a ciertos elementos de datos sin afectar la capa de aplicación.","fr":"Votre organisation utilise Microsoft Fabric pour gérer un data warehouse avec des données sensibles. Vous devez implémenter des mesures de sécurité pour limiter l''accès à certains éléments de données sans affecter la couche application."}', '{"pt-br":"Quais três ações você deve executar para proteger os dados granularmente?","en-us":"Which three actions should you perform to protect data granularly?","es":"¿Cuáles tres acciones debe ejecutar para proteger los datos de forma granular?","fr":"Quelles trois actions devez-vous effectuer pour protéger les données de manière granulaire ?"}', '[{"key":"A","text":{"pt-br":"Segurança em nível de coluna, segurança em nível de linha e máscara dinâmica de dados","en-us":"Column-level security, row-level security, and dynamic data masking","es":"Seguridad a nivel de columna, seguridad a nivel de fila y máscara dinámica de datos","fr":"Sécurité au niveau des colonnes, sécurité au niveau des lignes et masquage dynamique des données"}},{"key":"B","text":{"pt-br":"Funções de workspace, permissões de item e segurança em nível de linha","en-us":"Workspace roles, item permissions, and row-level security","es":"Roles de workspace, permisos de ítem y seguridad a nivel de fila","fr":"Rôles de workspace, autorisations d''éléments et sécurité au niveau des lignes"}},{"key":"C","text":{"pt-br":"Segurança em nível de coluna, permissões de item e funções de workspace","en-us":"Column-level security, item permissions, and workspace roles","es":"Seguridad a nivel de columna, permisos de ítem y roles de workspace","fr":"Sécurité au niveau des colonnes, autorisations d''éléments et rôles de workspace"}},{"key":"D","text":{"pt-br":"Máscara dinâmica de dados, funções de workspace e permissões de item","en-us":"Dynamic data masking, workspace roles, and item permissions","es":"Máscara dinámica de datos, roles de workspace y permisos de ítem","fr":"Masquage dynamique des données, rôles de workspace et autorisations d''éléments"}}]', 'A', '{"pt-br":"CLS limita acesso a colunas específicas. RLS garante que usuários vejam apenas linhas autorizadas. Mascaramento dinâmico oculta dados sensíveis nos resultados sem alterar dados reais. Funções de workspace e permissões de item não oferecem granularidade suficiente.","en-us":"CLS limits access to specific columns. RLS ensures users see only authorized rows. Dynamic masking hides sensitive data in results without altering actual data. Workspace roles and item permissions don''t provide sufficient granularity.","es":"CLS limita acceso a columnas específicas. RLS garantiza que los usuarios vean solo filas autorizadas. El mascaramiento dinámico oculta datos sensibles sin alterar los datos reales.","fr":"CLS limite l''accès aux colonnes spécifiques. RLS garantit que les utilisateurs ne voient que les lignes autorisées. Le masquage dynamique cache les données sensibles sans modifier les données réelles."}'),
('Segurança e Governança', '{"pt-br":"Sua empresa usa Microsoft Fabric para análise de dados e precisa garantir que somente usuários específicos possam acessar determinados dados de relatório com base em suas funções.","en-us":"Your company uses Microsoft Fabric for data analytics and needs to ensure only specific users can access certain report data based on their roles.","es":"Su empresa usa Microsoft Fabric para análisis de datos y necesita garantizar que solo usuarios específicos puedan acceder a ciertos datos de informes según sus roles.","fr":"Votre entreprise utilise Microsoft Fabric pour l''analyse de données et doit s''assurer que seuls des utilisateurs spécifiques peuvent accéder à certaines données de rapport en fonction de leurs rôles."}', '{"pt-br":"O que você deve configurar para controlar o acesso aos dados no relatório?","en-us":"What should you configure to control access to report data?","es":"¿Qué debe configurar para controlar el acceso a los datos del informe?","fr":"Que devez-vous configurer pour contrôler l''accès aux données du rapport ?"}', '[{"key":"A","text":{"pt-br":"Segurança em nível de linha (RLS)","en-us":"Row-level security (RLS)","es":"Seguridad a nivel de fila (RLS)","fr":"Sécurité au niveau des lignes (RLS)"}},{"key":"B","text":{"pt-br":"Funções de workspace","en-us":"Workspace roles","es":"Roles de workspace","fr":"Rôles de workspace"}},{"key":"C","text":{"pt-br":"Rótulos de confidencialidade","en-us":"Sensitivity labels","es":"Etiquetas de confidencialidad","fr":"Étiquettes de confidentialité"}},{"key":"D","text":{"pt-br":"Azure Active Directory B2C","en-us":"Azure Active Directory B2C","es":"Azure Active Directory B2C","fr":"Azure Active Directory B2C"}}]', 'A', '{"pt-br":"RLS garante que somente usuários autorizados vejam dados específicos nos relatórios. Funções de workspace não oferecem granularidade por linha. Rótulos de confidencialidade são para conformidade, não controle de acesso a dados. Azure AD B2C é para identidade externa.","en-us":"RLS ensures only authorized users see specific report data. Workspace roles don''t provide row-level granularity. Sensitivity labels are for compliance, not data access control. Azure AD B2C is for external identity management.","es":"RLS garantiza que solo usuarios autorizados vean datos específicos. Los roles de workspace no ofrecen granularidad por fila.","fr":"RLS garantit que seuls les utilisateurs autorisés voient des données spécifiques. Les rôles de workspace n''offrent pas de granularité au niveau des lignes."}'),
('Ciclo de Vida', '{"pt-br":"Você usa o Power BI Desktop para criar um modelo semântico e precisa colaborar com outro modelador, trabalhando em diferentes partes do modelo simultaneamente.","en-us":"You use Power BI Desktop to create a semantic model and need to collaborate with another modeler, working on different parts of the model simultaneously.","es":"Usa Power BI Desktop para crear un modelo semántico y necesita colaborar con otro modelador, trabajando en diferentes partes del modelo simultáneamente.","fr":"Vous utilisez Power BI Desktop pour créer un modèle sémantique et devez collaborer avec un autre modélisateur, en travaillant simultanément sur différentes parties du modèle."}', '{"pt-br":"O que você deve recomendar para colaboração eficiente?","en-us":"What should you recommend for efficient collaboration?","es":"¿Qué debe recomendar para una colaboración eficiente?","fr":"Que devez-vous recommander pour une collaboration efficace ?"}', '[{"key":"A","text":{"pt-br":"Salvar como PBIP e inicializar repositório Git com controle de versão","en-us":"Save as PBIP and initialize a Git repository with version control","es":"Guardar como PBIP e inicializar repositorio Git con control de versiones","fr":"Enregistrer en PBIP et initialiser un dépôt Git avec contrôle de version"}},{"key":"B","text":{"pt-br":"Enviar o arquivo PBIX por email entre os desenvolvedores","en-us":"Email the PBIX file between developers","es":"Enviar el archivo PBIX por email entre los desarrolladores","fr":"Envoyer le fichier PBIX par email entre les développeurs"}},{"key":"C","text":{"pt-br":"Salvar o PBIX no OneDrive compartilhado","en-us":"Save the PBIX to a shared OneDrive","es":"Guardar el PBIX en OneDrive compartido","fr":"Enregistrer le PBIX sur un OneDrive partagé"}},{"key":"D","text":{"pt-br":"Publicar o PBIX em um workspace compartilhado","en-us":"Publish the PBIX to a shared workspace","es":"Publicar el PBIX en un workspace compartido","fr":"Publier le PBIX dans un workspace partagé"}}]', 'A', '{"pt-br":"PBIP salva como arquivos de texto em estrutura de pastas, compatível com controle de código-fonte (Git), permitindo que múltiplos desenvolvedores trabalhem simultaneamente. PBIX no OneDrive permite apenas um usuário por vez. Email não é eficiente.","en-us":"PBIP saves as text files in a folder structure, compatible with source control (Git), allowing multiple developers to work simultaneously. PBIX on OneDrive only allows one user at a time.","es":"PBIP guarda como archivos de texto en estructura de carpetas, compatible con control de código fuente (Git), permitiendo que múltiples desarrolladores trabajen simultáneamente.","fr":"PBIP enregistre sous forme de fichiers texte dans une structure de dossiers, compatible avec le contrôle de source (Git), permettant à plusieurs développeurs de travailler simultanément."}'),
('Ciclo de Vida', '{"pt-br":"Você tem um modelo semântico sincronizado por pipelines de implantação do Fabric para workspaces de Desenvolvimento, Teste e Produção. O modelo extrai dados de um banco de dados SQL do Azure.","en-us":"You have a semantic model synced through Fabric deployment pipelines to Development, Test, and Production workspaces. The model pulls data from an Azure SQL Database.","es":"Tiene un modelo semántico sincronizado por pipelines de implementación de Fabric para workspaces de Desarrollo, Prueba y Producción. El modelo extrae datos de Azure SQL Database.","fr":"Vous avez un modèle sémantique synchronisé via des pipelines de déploiement Fabric vers les workspaces Développement, Test et Production. Le modèle extrait des données d''une base Azure SQL."}', '{"pt-br":"Você precisa reduzir o tamanho das consultas enviadas ao banco de dados nos workspaces de desenvolvimento e teste. O que você deve fazer?","en-us":"You need to reduce the size of queries sent to the database in development and test workspaces. What should you do?","es":"Necesita reducir el tamaño de las consultas enviadas a la base de datos en los workspaces de desarrollo y prueba. ¿Qué debe hacer?","fr":"Vous devez réduire la taille des requêtes envoyées à la base de données dans les workspaces de développement et de test. Que devez-vous faire ?"}', '[{"key":"A","text":{"pt-br":"Adicionar uma regra de parâmetro de implantação para filtrar os dados","en-us":"Add a deployment parameter rule to filter the data","es":"Agregar una regla de parámetro de implementación para filtrar los datos","fr":"Ajouter une règle de paramètre de déploiement pour filtrer les données"}},{"key":"B","text":{"pt-br":"Habilitar política de atualização incremental","en-us":"Enable incremental refresh policy","es":"Habilitar política de actualización incremental","fr":"Activer la politique d''actualisation incrémentielle"}},{"key":"C","text":{"pt-br":"Habilitar modo DirectQuery","en-us":"Enable DirectQuery mode","es":"Habilitar modo DirectQuery","fr":"Activer le mode DirectQuery"}},{"key":"D","text":{"pt-br":"Configurar regras de conexão de fonte de dados","en-us":"Configure data source connection rules","es":"Configurar reglas de conexión de fuente de datos","fr":"Configurer les règles de connexion de source de données"}}]', 'A', '{"pt-br":"Parâmetros de consulta permitem filtrar dados por categoria ou data, controlando a quantidade de dados extraídos entre workspaces de Dev, Teste e Produção. As outras opções não alteram quais dados são extraídos.","en-us":"Query parameters allow filtering data by category or date, controlling the amount of data pulled across Dev, Test, and Production workspaces. Other options don''t change what data is pulled.","es":"Los parámetros de consulta permiten filtrar datos por categoría o fecha, controlando la cantidad de datos extraídos entre workspaces.","fr":"Les paramètres de requête permettent de filtrer les données par catégorie ou date, contrôlant la quantité de données extraites entre les workspaces."}'),
('Ciclo de Vida', '{"pt-br":"Você tem um locatário do Fabric com endpoint XMLA configurado como Leitura/Gravação. Você precisa usar o endpoint XMLA para implantar alterações em apenas uma tabela do modelo.","en-us":"You have a Fabric tenant with the XMLA endpoint set to Read/Write. You need to use the XMLA endpoint to deploy changes to only one table in the model.","es":"Tiene un tenant de Fabric con el endpoint XMLA configurado como Lectura/Escritura. Necesita usar el endpoint XMLA para implementar cambios en solo una tabla del modelo.","fr":"Vous avez un tenant Fabric avec le point de terminaison XMLA configuré en Lecture/Écriture. Vous devez utiliser le point de terminaison XMLA pour déployer des modifications sur une seule table du modèle."}', '{"pt-br":"Qual é a principal limitação do uso de endpoints XMLA no processo de implantação?","en-us":"What is the main limitation of using XMLA endpoints in the deployment process?","es":"¿Cuál es la principal limitación del uso de endpoints XMLA en el proceso de implementación?","fr":"Quelle est la principale limitation de l''utilisation des points de terminaison XMLA dans le processus de déploiement ?"}', '[{"key":"A","text":{"pt-br":"Um arquivo PBIX não pode ser baixado do serviço do Power BI","en-us":"A PBIX file cannot be downloaded from the Power BI service","es":"Un archivo PBIX no se puede descargar del servicio de Power BI","fr":"Un fichier PBIX ne peut pas être téléchargé depuis le service Power BI"}},{"key":"B","text":{"pt-br":"O particionamento de tabela é impossível","en-us":"Table partitioning is impossible","es":"La partición de tablas es imposible","fr":"Le partitionnement des tables est impossible"}},{"key":"C","text":{"pt-br":"Parâmetros não podem ser usados","en-us":"Parameters cannot be used","es":"Los parámetros no pueden ser usados","fr":"Les paramètres ne peuvent pas être utilisés"}},{"key":"D","text":{"pt-br":"Apenas uma tabela pode ser alterada por vez","en-us":"Only one table can be changed at a time","es":"Solo una tabla puede ser alterada a la vez","fr":"Une seule table peut être modifiée à la fois"}}]', 'A', '{"pt-br":"Quando o modelo é alterado via endpoints XMLA, o arquivo PBIX não pode mais ser baixado do serviço. Particionamento de tabela e parâmetros ainda são suportados.","en-us":"When the model is changed via XMLA endpoints, the PBIX file can no longer be downloaded from the service. Table partitioning and parameters are still supported.","es":"Cuando el modelo se altera vía endpoints XMLA, el archivo PBIX ya no puede descargarse del servicio. La partición de tablas y los parámetros aún son soportados.","fr":"Lorsque le modèle est modifié via les points de terminaison XMLA, le fichier PBIX ne peut plus être téléchargé. Le partitionnement et les paramètres sont toujours pris en charge."}'),
('Obter Dados', '{"pt-br":"Você tem um pipeline de dados com uma tabela de fatos contendo dados de clientes e duas tabelas de dimensão (clientes com CustomerID e calendário com DateID). Você precisa garantir que os dados de cada cliente estejam em seu próprio arquivo Parquet.","en-us":"You have a data pipeline with a fact table containing customer data and two dimension tables. You need to ensure each customer''s data is in its own Parquet file.","es":"Tiene un pipeline de datos con una tabla de hechos que contiene datos de clientes y dos tablas de dimensión. Necesita garantizar que los datos de cada cliente estén en su propio archivo Parquet.","fr":"Vous avez un pipeline de données avec une table de faits contenant des données clients et deux tables de dimension. Vous devez vous assurer que les données de chaque client sont dans leur propre fichier Parquet."}', '{"pt-br":"Qual configuração de pipeline de dados você deve implementar?","en-us":"Which data pipeline configuration should you implement?","es":"¿Qué configuración de pipeline de datos debe implementar?","fr":"Quelle configuration de pipeline de données devez-vous implémenter ?"}', '[{"key":"A","text":{"pt-br":"Partição por ID do cliente na tabela de fatos","en-us":"Partition by Customer ID in the fact table","es":"Partición por ID del cliente en la tabla de hechos","fr":"Partitionnement par ID client dans la table de faits"}},{"key":"B","text":{"pt-br":"Partição por ID de Data na tabela de fatos","en-us":"Partition by Date ID in the fact table","es":"Partición por ID de Fecha en la tabla de hechos","fr":"Partitionnement par ID de date dans la table de faits"}},{"key":"C","text":{"pt-br":"Partição por ID do cliente na tabela de dimensão","en-us":"Partition by Customer ID in the dimension table","es":"Partición por ID del cliente en la tabla de dimensión","fr":"Partitionnement par ID client dans la table de dimension"}},{"key":"D","text":{"pt-br":"Criar um pipeline separado para cada cliente","en-us":"Create a separate pipeline for each customer","es":"Crear un pipeline separado para cada cliente","fr":"Créer un pipeline séparé pour chaque client"}}]', 'A', '{"pt-br":"O particionamento determina a estrutura dos arquivos Parquet. Particionar a tabela de fatos pelo CustomerID gera um arquivo por cliente.","en-us":"Partitioning determines the Parquet file structure. Partitioning the fact table by CustomerID generates one file per customer.","es":"La partición determina la estructura de los archivos Parquet. Particionar la tabla de hechos por CustomerID genera un archivo por cliente.","fr":"Le partitionnement détermine la structure des fichiers Parquet. Partitionner la table de faits par CustomerID génère un fichier par client."}'),
('Obter Dados', '{"pt-br":"Você tem um pipeline de dados Pipeline1 e precisa enviar um email via Outlook quando houver problemas com conectores, minimizando o número de emails enviados.","en-us":"You have a data pipeline Pipeline1 and need to send an email via Outlook when there are connector issues, minimizing the number of emails sent.","es":"Tiene un pipeline de datos Pipeline1 y necesita enviar un email vía Outlook cuando haya problemas con conectores, minimizando el número de emails enviados.","fr":"Vous avez un pipeline de données Pipeline1 et devez envoyer un email via Outlook en cas de problème de connecteur, en minimisant le nombre d''emails envoyés."}', '{"pt-br":"Qual ação de atividade deve ser conectada à atividade do Outlook?","en-us":"Which activity action should be connected to the Outlook activity?","es":"¿Qué acción de actividad debe conectarse a la actividad de Outlook?","fr":"Quelle action d''activité doit être connectée à l''activité Outlook ?"}', '[{"key":"A","text":{"pt-br":"Em caso de falha","en-us":"On failure","es":"En caso de fallo","fr":"En cas d''échec"}},{"key":"B","text":{"pt-br":"Na conclusão","en-us":"On completion","es":"Al completar","fr":"À la fin"}},{"key":"C","text":{"pt-br":"Em caso de sucesso","en-us":"On success","es":"En caso de éxito","fr":"En cas de succès"}},{"key":"D","text":{"pt-br":"Em caso de ignorar","en-us":"On skip","es":"En caso de omitir","fr":"En cas de saut"}}]', 'A', '{"pt-br":"''Em caso de falha'' envia notificação apenas quando há problema causado por falha de atividade. As outras opções notificariam incorretamente ou todas as vezes.","en-us":"''On failure'' sends notification only when there''s a problem caused by activity failure. Other options would notify incorrectly or every time.","es":"''En caso de fallo'' envía notificación solo cuando hay un problema. Las otras opciones notificarían incorrectamente.","fr":"''En cas d''échec'' n''envoie une notification que lorsqu''il y a un problème. Les autres options notifieraient incorrectement."}'),
('Obter Dados', '{"pt-br":"Você tem um pipeline Pipeline1 na região Oeste dos EUA. Precisa que ele execute à meia-noite no fuso horário UTC-0.","en-us":"You have a pipeline Pipeline1 in the US West region. You need it to run at midnight in the UTC-0 timezone.","es":"Tiene un pipeline Pipeline1 en la región Oeste de EE.UU. Necesita que se ejecute a medianoche en la zona horaria UTC-0.","fr":"Vous avez un pipeline Pipeline1 dans la région US West. Vous devez qu''il s''exécute à minuit dans le fuseau horaire UTC-0."}', '{"pt-br":"Como você deve configurar o agendamento?","en-us":"How should you configure the schedule?","es":"¿Cómo debe configurar la programación?","fr":"Comment devez-vous configurer la planification ?"}', '[{"key":"A","text":{"pt-br":"Definir o fuso horário do agendador do Pipeline1 como UTC-0","en-us":"Set Pipeline1''s scheduler timezone to UTC-0","es":"Definir la zona horaria del programador de Pipeline1 como UTC-0","fr":"Définir le fuseau horaire du planificateur de Pipeline1 sur UTC-0"}},{"key":"B","text":{"pt-br":"Alterar o fuso horário do workspace para UTC-0","en-us":"Change the workspace timezone to UTC-0","es":"Cambiar la zona horaria del workspace a UTC-0","fr":"Changer le fuseau horaire du workspace en UTC-0"}},{"key":"C","text":{"pt-br":"Configurar o fuso da capacidade do Fabric","en-us":"Configure the Fabric capacity timezone","es":"Configurar la zona horaria de la capacidad de Fabric","fr":"Configurer le fuseau horaire de la capacité Fabric"}},{"key":"D","text":{"pt-br":"Usar a região do Azure como referência de fuso horário","en-us":"Use the Azure region as the timezone reference","es":"Usar la región de Azure como referencia de zona horaria","fr":"Utiliser la région Azure comme référence de fuseau horaire"}}]', 'A', '{"pt-br":"O pipeline de dados tem sua própria configuração de fuso horário que se aplica somente a ele. É ali que você configura UTC-0.","en-us":"The data pipeline has its own timezone setting that applies only to it. That''s where you configure UTC-0.","es":"El pipeline de datos tiene su propia configuración de zona horaria que solo se aplica a él.","fr":"Le pipeline de données a sa propre configuration de fuseau horaire qui ne s''applique qu''à lui."}'),
('Obter Dados', '{"pt-br":"Você tem um lakehouse e precisa criar um pipeline de dados para ingerir dados usando a atividade Copiar dados.","en-us":"You have a lakehouse and need to create a data pipeline to ingest data using the Copy Data activity.","es":"Tiene un lakehouse y necesita crear un pipeline de datos para ingerir datos usando la actividad Copiar datos.","fr":"Vous avez un lakehouse et devez créer un pipeline de données pour ingérer des données avec l''activité Copier les données."}', '{"pt-br":"Quais propriedades na guia Geral são obrigatórias para a atividade Copiar dados?","en-us":"Which properties on the General tab are mandatory for the Copy Data activity?","es":"¿Qué propiedades en la pestaña General son obligatorias para la actividad Copiar datos?","fr":"Quelles propriétés de l''onglet Général sont obligatoires pour l''activité Copier les données ?"}', '[{"key":"A","text":{"pt-br":"Apenas nome","en-us":"Name only","es":"Solo nombre","fr":"Nom uniquement"}},{"key":"B","text":{"pt-br":"Nome e descrição","en-us":"Name and description","es":"Nombre y descripción","fr":"Nom et description"}},{"key":"C","text":{"pt-br":"Nome, descrição e timeout","en-us":"Name, description, and timeout","es":"Nombre, descripción y timeout","fr":"Nom, description et timeout"}},{"key":"D","text":{"pt-br":"Nome e timeout","en-us":"Name and timeout","es":"Nombre y timeout","fr":"Nom et timeout"}}]', 'A', '{"pt-br":"Na atividade Copiar dados, somente o nome é obrigatório na guia Geral. Todas as outras propriedades são opcionais.","en-us":"In the Copy Data activity, only the name is required on the General tab. All other properties are optional.","es":"En la actividad Copiar datos, solo el nombre es obligatorio en la pestaña General.","fr":"Dans l''activité Copier les données, seul le nom est obligatoire dans l''onglet Général."}'),
('Obter Dados', '{"pt-br":"Você tem um grande conjunto de dados de 1 TB em uma fonte externa. Precisa ingerir no Lakehouse com a maior taxa de transferência e opção low-code/no-code.","en-us":"You have a 1 TB dataset from an external source. You need to ingest it into the Lakehouse with the highest throughput and a low-code/no-code option.","es":"Tiene un dataset de 1 TB de una fuente externa. Necesita ingerirlo en el Lakehouse con la mayor tasa de transferencia y opción low-code/no-code.","fr":"Vous avez un dataset de 1 To provenant d''une source externe. Vous devez l''ingérer dans le Lakehouse avec le débit le plus élevé et une option low-code/no-code."}', '{"pt-br":"O que você deve recomendar?","en-us":"What should you recommend?","es":"¿Qué debe recomendar?","fr":"Que devez-vous recommander ?"}', '[{"key":"A","text":{"pt-br":"Atividade Copiar dados de um pipeline","en-us":"Copy Data activity from a pipeline","es":"Actividad Copiar datos de un pipeline","fr":"Activité Copier les données d''un pipeline"}},{"key":"B","text":{"pt-br":"Dataflow Gen2","en-us":"Dataflow Gen2","es":"Dataflow Gen2","fr":"Dataflow Gen2"}},{"key":"C","text":{"pt-br":"Notebook Spark","en-us":"Spark Notebook","es":"Notebook Spark","fr":"Notebook Spark"}},{"key":"D","text":{"pt-br":"Upload manual de arquivos","en-us":"Manual file upload","es":"Carga manual de archivos","fr":"Téléchargement manuel de fichiers"}}]', 'A', '{"pt-br":"A atividade Copiar dados oferece o melhor desempenho para grandes volumes de dados e é low-code. Dataflow Gen2 é para dados menores. Notebooks exigem codificação.","en-us":"Copy Data activity provides the best performance for large data volumes and is low-code. Dataflow Gen2 is for smaller data. Notebooks require coding.","es":"La actividad Copiar datos ofrece el mejor rendimiento para grandes volúmenes y es low-code.","fr":"L''activité Copier les données offre les meilleures performances pour de grands volumes et est low-code."}'),
('Transformar Dados', '{"pt-br":"Você tem um lakehouse do Fabric com uma tabela Delta chamada Produto. Você carrega os dados em um DataFrame com: df = spark.sql(\"SELECT * FROM Produto\").","en-us":"You have a Fabric lakehouse with a Delta table called Product. You load data into a DataFrame with: df = spark.sql(\"SELECT * FROM Product\").","es":"Tiene un lakehouse de Fabric con una tabla Delta llamada Producto. Carga los datos en un DataFrame con: df = spark.sql(\"SELECT * FROM Producto\").","fr":"Vous avez un lakehouse Fabric avec une table Delta appelée Produit. Vous chargez les données dans un DataFrame avec : df = spark.sql(\"SELECT * FROM Produit\")."}', '{"pt-br":"Qual comando PySpark você deve executar para exibir as 100 primeiras linhas?","en-us":"Which PySpark command should you run to display the first 100 rows?","es":"¿Qué comando PySpark debe ejecutar para mostrar las primeras 100 filas?","fr":"Quelle commande PySpark devez-vous exécuter pour afficher les 100 premières lignes ?"}', '[{"key":"A","text":{"pt-br":"display(df.limit(100))","en-us":"display(df.limit(100))","es":"display(df.limit(100))","fr":"display(df.limit(100))"}},{"key":"B","text":{"pt-br":"df.show(100)","en-us":"df.show(100)","es":"df.show(100)","fr":"df.show(100)"}},{"key":"C","text":{"pt-br":"df.head(100)","en-us":"df.head(100)","es":"df.head(100)","fr":"df.head(100)"}},{"key":"D","text":{"pt-br":"df.take(100)","en-us":"df.take(100)","es":"df.take(100)","fr":"df.take(100)"}}]', 'A', '{"pt-br":"display(df.limit(100)) é o método recomendado em notebooks Fabric para exibir dados formatados. df.show() exibe no console sem formatação rica.","en-us":"display(df.limit(100)) is the recommended method in Fabric notebooks for formatted data display. df.show() displays in console without rich formatting.","es":"display(df.limit(100)) es el método recomendado en notebooks Fabric para mostrar datos formateados.","fr":"display(df.limit(100)) est la méthode recommandée dans les notebooks Fabric pour afficher les données formatées."}'),
('Projetar Modelos Semânticos', '{"pt-br":"Você está projetando um modelo semântico no Power BI e tem tabelas de dimensão normalizadas (snowflaked) que precisam ser implementadas em um esquema estrela.","en-us":"You are designing a semantic model in Power BI and have normalized (snowflaked) dimension tables that need to be implemented in a star schema.","es":"Está diseñando un modelo semántico en Power BI y tiene tablas de dimensión normalizadas (snowflaked) que necesitan implementarse en un esquema estrela.","fr":"Vous concevez un modèle sémantique dans Power BI et avez des tables de dimension normalisées (snowflaked) devant être implémentées en schéma étoile."}', '{"pt-br":"O que você deve fazer com as tabelas de dimensão snowflaked?","en-us":"What should you do with the snowflaked dimension tables?","es":"¿Qué debe hacer con las tablas de dimensión snowflaked?","fr":"Que devez-vous faire avec les tables de dimension snowflaked ?"}', '[{"key":"A","text":{"pt-br":"Desnormalizar as tabelas em uma única tabela de dimensão","en-us":"Denormalize the tables into a single dimension table","es":"Desnormalizar las tablas en una sola tabla de dimensión","fr":"Dénormaliser les tables en une seule table de dimension"}},{"key":"B","text":{"pt-br":"Manter as tabelas normalizadas para performance","en-us":"Keep the tables normalized for performance","es":"Mantener las tablas normalizadas para rendimiento","fr":"Garder les tables normalisées pour la performance"}},{"key":"C","text":{"pt-br":"Criar uma tabela ponte entre as dimensões","en-us":"Create a bridge table between dimensions","es":"Crear una tabla puente entre dimensiones","fr":"Créer une table pont entre les dimensions"}},{"key":"D","text":{"pt-br":"Usar DirectQuery para as tabelas snowflaked","en-us":"Use DirectQuery for the snowflaked tables","es":"Usar DirectQuery para las tablas snowflaked","fr":"Utiliser DirectQuery pour les tables snowflaked"}}]', 'A', '{"pt-br":"Uma dimensão Snowflake é um conjunto de tabelas normalizadas. Para implementar um esquema estrela adequado, é necessário desnormalizar as tabelas em uma única tabela de dimensão com todos os atributos.","en-us":"A Snowflake dimension is a set of normalized tables. To implement a proper star schema, you need to denormalize them into a single dimension table with all attributes.","es":"Una dimensión Snowflake es un conjunto de tablas normalizadas. Para implementar un esquema estrela, se deben desnormalizar en una sola tabla de dimensión.","fr":"Une dimension Snowflake est un ensemble de tables normalisées. Pour implémenter un schéma étoile, il faut les dénormaliser en une seule table de dimension."}'),
('Transformar Dados', '{"pt-br":"Você tem tabelas Employee (EmployeeID, EmployeeName, EmployeePosition) e Contract (EmployeeID, ContractType). Precisa desnormalizar e incluir ContractType, preservando todas as linhas de Employee.","en-us":"You have Employee (EmployeeID, EmployeeName, EmployeePosition) and Contract (EmployeeID, ContractType) tables. You need to denormalize and include ContractType, preserving all Employee rows.","es":"Tiene tablas Employee y Contract. Necesita desnormalizar e incluir ContractType, preservando todas las filas de Employee.","fr":"Vous avez des tables Employee et Contract. Vous devez dénormaliser et inclure ContractType, en préservant toutes les lignes Employee."}', '{"pt-br":"Qual tipo de junção no Power Query você deve usar?","en-us":"Which join type in Power Query should you use?","es":"¿Qué tipo de unión en Power Query debe usar?","fr":"Quel type de jointure dans Power Query devez-vous utiliser ?"}', '[{"key":"A","text":{"pt-br":"Junção externa esquerda","en-us":"Left outer join","es":"Unión externa izquierda","fr":"Jointure externe gauche"}},{"key":"B","text":{"pt-br":"Antijunção esquerda","en-us":"Left anti join","es":"Anti unión izquierda","fr":"Anti-jointure gauche"}},{"key":"C","text":{"pt-br":"Junção interna","en-us":"Inner join","es":"Unión interna","fr":"Jointure interne"}},{"key":"D","text":{"pt-br":"Junção cruzada","en-us":"Cross join","es":"Unión cruzada","fr":"Jointure croisée"}}]', 'A', '{"pt-br":"A junção externa esquerda mantém todas as linhas da tabela esquerda (Employee) e traz as linhas correspondentes da direita (Contract). Antijunção exclui correspondências. Junção interna retorna só correspondências. Junção cruzada retorna produto cartesiano.","en-us":"Left outer join keeps all rows from the left table (Employee) and brings matching rows from the right (Contract). Anti join excludes matches. Inner join returns only matches. Cross join returns cartesian product.","es":"La unión externa izquierda mantiene todas las filas de la tabla izquierda y trae las correspondientes de la derecha.","fr":"La jointure externe gauche conserve toutes les lignes de la table gauche et apporte les correspondances de la droite."}'),
('Transformar Dados', '{"pt-br":"Você tem um warehouse do Fabric com tabelas Product e ProductCategory (ambas com ProductCategoryKey). Precisa mesclar em uma tabela Product combinada usando Dataflow Gen2, mantendo todas as linhas de Product.","en-us":"You have a Fabric warehouse with Product and ProductCategory tables (both with ProductCategoryKey). You need to merge into a combined Product table using Dataflow Gen2, keeping all Product rows.","es":"Tiene un warehouse de Fabric con tablas Product y ProductCategory. Necesita fusionar en una tabla combinada manteniendo todas las filas de Product.","fr":"Vous avez un warehouse Fabric avec des tables Product et ProductCategory. Vous devez fusionner en une table combinée en conservant toutes les lignes Product."}', '{"pt-br":"Qual configuração de junção você deve usar?","en-us":"Which join configuration should you use?","es":"¿Qué configuración de unión debe usar?","fr":"Quelle configuration de jointure devez-vous utiliser ?"}', '[{"key":"A","text":{"pt-br":"Junção externa esquerda de Product para ProductCategory","en-us":"Left outer join from Product to ProductCategory","es":"Unión externa izquierda de Product a ProductCategory","fr":"Jointure externe gauche de Product vers ProductCategory"}},{"key":"B","text":{"pt-br":"Junção externa esquerda de ProductCategory para Product","en-us":"Left outer join from ProductCategory to Product","es":"Unión externa izquierda de ProductCategory a Product","fr":"Jointure externe gauche de ProductCategory vers Product"}},{"key":"C","text":{"pt-br":"Antijunção esquerda de Product para ProductCategory","en-us":"Left anti join from Product to ProductCategory","es":"Anti unión izquierda de Product a ProductCategory","fr":"Anti-jointure gauche de Product vers ProductCategory"}},{"key":"D","text":{"pt-br":"Junção interna de Product para ProductCategory","en-us":"Inner join from Product to ProductCategory","es":"Unión interna de Product a ProductCategory","fr":"Jointure interne de Product vers ProductCategory"}}]', 'A', '{"pt-br":"A junção externa esquerda de Product para ProductCategory mantém todas as linhas do Product e traz apenas as correspondentes de ProductCategory. A direção da junção importa.","en-us":"Left outer join from Product to ProductCategory keeps all Product rows and brings only matching ProductCategory rows. Join direction matters.","es":"La unión externa izquierda de Product a ProductCategory mantiene todas las filas de Product y trae solo las correspondientes.","fr":"La jointure externe gauche de Product vers ProductCategory conserve toutes les lignes Product et apporte uniquement les correspondances."}'),
('Transformar Dados', '{"pt-br":"Você tem um relatório Power BI que usa Power Query para transformar dados de um SQL Server. Precisa garantir que a dobragem de consultas (query folding) permaneça ativa.","en-us":"You have a Power BI report using Power Query to transform data from SQL Server. You need to ensure query folding remains active.","es":"Tiene un informe Power BI que usa Power Query para transformar datos de SQL Server. Necesita garantizar que el query folding permanezca activo.","fr":"Vous avez un rapport Power BI utilisant Power Query pour transformer des données SQL Server. Vous devez vous assurer que le pliage de requêtes reste actif."}', '{"pt-br":"Qual transformação impede a dobragem de consulta?","en-us":"Which transformation prevents query folding?","es":"¿Qué transformación impide el query folding?","fr":"Quelle transformation empêche le pliage de requêtes ?"}', '[{"key":"A","text":{"pt-br":"Adicionar colunas de índice","en-us":"Adding index columns","es":"Agregar columnas de índice","fr":"Ajouter des colonnes d''index"}},{"key":"B","text":{"pt-br":"Pivot/Unpivot de colunas","en-us":"Pivot/Unpivot columns","es":"Pivot/Unpivot de columnas","fr":"Pivot/Dépivot de colonnes"}},{"key":"C","text":{"pt-br":"Manter linhas superiores","en-us":"Keep top rows","es":"Mantener filas superiores","fr":"Garder les premières lignes"}},{"key":"D","text":{"pt-br":"Filtrar linhas","en-us":"Filter rows","es":"Filtrar filas","fr":"Filtrer les lignes"}}]', 'A', '{"pt-br":"Adicionar colunas de índice sempre impede a dobragem de consulta no Power Query. Pivot/Unpivot e Manter linhas são transformações que podem ser dobradas.","en-us":"Adding index columns always prevents query folding in Power Query. Pivot/Unpivot and Keep rows are transformations that can be folded.","es":"Agregar columnas de índice siempre impide el query folding. Pivot/Unpivot y Mantener filas pueden ser dobladas.","fr":"L''ajout de colonnes d''index empêche toujours le pliage. Pivot/Dépivot et Garder les lignes peuvent être pliés."}'),
('Consultar e Analisar', '{"pt-br":"Você tem um lakehouse Fabric com um notebook. Precisa consultar a tabela de fatos para encontrar o total de registros por ProductKey, ordenados de forma decrescente.","en-us":"You have a Fabric lakehouse with a notebook. You need to query the fact table to find total records per ProductKey, sorted descending.","es":"Tiene un lakehouse Fabric con un notebook. Necesita consultar la tabla de hechos para encontrar el total de registros por ProductKey, ordenados de forma descendente.","fr":"Vous avez un lakehouse Fabric avec un notebook. Vous devez interroger la table de faits pour trouver le total d''enregistrements par ProductKey, trié de manière décroissante."}', '{"pt-br":"Como você deve estruturar a consulta PySpark?","en-us":"How should you structure the PySpark query?","es":"¿Cómo debe estructurar la consulta PySpark?","fr":"Comment devez-vous structurer la requête PySpark ?"}', '[{"key":"A","text":{"pt-br":"df.groupBy(\"ProductKey\").count().sort(\"count\", descending=True).show()","en-us":"df.groupBy(\"ProductKey\").count().sort(\"count\", descending=True).show()","es":"df.groupBy(\"ProductKey\").count().sort(\"count\", descending=True).show()","fr":"df.groupBy(\"ProductKey\").count().sort(\"count\", descending=True).show()"}},{"key":"B","text":{"pt-br":"df.filter(\"ProductKey\").count().show()","en-us":"df.filter(\"ProductKey\").count().show()","es":"df.filter(\"ProductKey\").count().show()","fr":"df.filter(\"ProductKey\").count().show()"}},{"key":"C","text":{"pt-br":"df.select(\"ProductKey\").distinct().show()","en-us":"df.select(\"ProductKey\").distinct().show()","es":"df.select(\"ProductKey\").distinct().show()","fr":"df.select(\"ProductKey\").distinct().show()"}},{"key":"D","text":{"pt-br":"df.orderBy(\"ProductKey\").count().show()","en-us":"df.orderBy(\"ProductKey\").count().show()","es":"df.orderBy(\"ProductKey\").count().show()","fr":"df.orderBy(\"ProductKey\").count().show()"}}]', 'A', '{"pt-br":"groupBy agrupa por ProductKey, count() retorna o total de registros para cada chave, sort ordena em ordem decrescente e show() exibe os resultados.","en-us":"groupBy groups by ProductKey, count() returns total records per key, sort orders descending and show() displays results.","es":"groupBy agrupa por ProductKey, count() retorna el total de registros por clave, sort ordena descendente y show() muestra resultados.","fr":"groupBy groupe par ProductKey, count() retourne le total par clé, sort trie en ordre décroissant et show() affiche les résultats."}'),
('Transformar Dados', '{"pt-br":"Você está criando perfil de dados em um lakehouse Fabric e executa df.describe().show(). Precisa saber quais funções estatísticas são incluídas para dados numéricos.","en-us":"You are profiling data in a Fabric lakehouse and run df.describe().show(). You need to know which statistical functions are included for numeric data.","es":"Está creando un perfil de datos en un lakehouse Fabric y ejecuta df.describe().show(). Necesita saber qué funciones estadísticas se incluyen para datos numéricos.","fr":"Vous profilez des données dans un lakehouse Fabric et exécutez df.describe().show(). Vous devez savoir quelles fonctions statistiques sont incluses pour les données numériques."}', '{"pt-br":"Quais três funções são incluídas nos resultados de dados numéricos?","en-us":"Which three functions are included in numeric data results?","es":"¿Cuáles tres funciones se incluyen en los resultados de datos numéricos?","fr":"Quelles trois fonctions sont incluses dans les résultats de données numériques ?"}', '[{"key":"A","text":{"pt-br":"COUNT, MEAN e STD (desvio padrão)","en-us":"COUNT, MEAN, and STD (standard deviation)","es":"COUNT, MEAN y STD (desviación estándar)","fr":"COUNT, MEAN et STD (écart type)"}},{"key":"B","text":{"pt-br":"AVG, DISTINCTCOUNT e SUM","en-us":"AVG, DISTINCTCOUNT, and SUM","es":"AVG, DISTINCTCOUNT y SUM","fr":"AVG, DISTINCTCOUNT et SUM"}},{"key":"C","text":{"pt-br":"COUNT, AVG e MEDIAN","en-us":"COUNT, AVG, and MEDIAN","es":"COUNT, AVG y MEDIAN","fr":"COUNT, AVG et MEDIAN"}},{"key":"D","text":{"pt-br":"SUM, MIN e DISTINCTCOUNT","en-us":"SUM, MIN, and DISTINCTCOUNT","es":"SUM, MIN y DISTINCTCOUNT","fr":"SUM, MIN et DISTINCTCOUNT"}}]', 'A', '{"pt-br":"df.describe() gera estatísticas descritivas. Para dados numéricos, inclui COUNT, MEAN, STD, MIN e MAX. Para dados de objeto, também inclui TOP, UNIQUE e FREQ.","en-us":"df.describe() generates descriptive statistics. For numeric data, it includes COUNT, MEAN, STD, MIN, and MAX. For object data, it also includes TOP, UNIQUE, and FREQ.","es":"df.describe() genera estadísticas descriptivas. Para datos numéricos, incluye COUNT, MEAN, STD, MIN y MAX.","fr":"df.describe() génère des statistiques descriptives. Pour les données numériques, il inclut COUNT, MEAN, STD, MIN et MAX."}'),
('Consultar e Analisar', '{"pt-br":"Você tem um workspace Fabric com um relatório Power BI. Precisa modificar nomes de coluna sem alterar os nomes na tabela Delta subjacente.","en-us":"You have a Fabric workspace with a Power BI report. You need to modify column names without changing the names in the underlying Delta table.","es":"Tiene un workspace Fabric con un informe Power BI. Necesita modificar nombres de columna sin cambiar los nombres en la tabla Delta subyacente.","fr":"Vous avez un workspace Fabric avec un rapport Power BI. Vous devez modifier les noms de colonnes sans changer les noms dans la table Delta sous-jacente."}', '{"pt-br":"Qual objeto de warehouse você deve criar?","en-us":"Which warehouse object should you create?","es":"¿Qué objeto de warehouse debe crear?","fr":"Quel objet de warehouse devez-vous créer ?"}', '[{"key":"A","text":{"pt-br":"Exibição (View)","en-us":"View","es":"Vista (View)","fr":"Vue (View)"}},{"key":"B","text":{"pt-br":"Esquema","en-us":"Schema","es":"Esquema","fr":"Schéma"}},{"key":"C","text":{"pt-br":"Tabela materializada","en-us":"Materialized table","es":"Tabla materializada","fr":"Table matérialisée"}},{"key":"D","text":{"pt-br":"Stored Procedure","en-us":"Stored Procedure","es":"Stored Procedure","fr":"Procédure stockée"}}]', 'A', '{"pt-br":"Uma View encapsula lógica de consulta como renomear colunas, filtrar e agregar sem alterar as tabelas subjacentes. Contém apenas a definição da consulta.","en-us":"A View encapsulates query logic like renaming columns, filtering, and aggregating without altering underlying tables. It contains only the query definition.","es":"Una Vista encapsula lógica de consulta como renombrar columnas sin alterar las tablas subyacentes.","fr":"Une Vue encapsule la logique de requête comme le renommage de colonnes sans modifier les tables sous-jacentes."}'),
('Transformar Dados', '{"pt-br":"Você usa Dataflow Gen2 para adicionar uma coluna ao relatório de Vendas. Produtos com preço unitário > $1.000 devem ser ''Alto'', e < $1.000 devem ser ''Regular''.","en-us":"You use Dataflow Gen2 to add a column to the Sales report. Products with unit price > $1,000 should be ''High'', and < $1,000 should be ''Regular''.","es":"Usa Dataflow Gen2 para agregar una columna al informe de Ventas. Productos con precio > $1.000 deben ser ''Alto'', y < $1.000 deben ser ''Regular''.","fr":"Vous utilisez Dataflow Gen2 pour ajouter une colonne au rapport Ventes. Les produits avec prix > 1 000 $ doivent être ''Élevé'', et < 1 000 $ doivent être ''Standard''."}', '{"pt-br":"O que você deve selecionar na guia Adicionar coluna do Power Query?","en-us":"What should you select on the Add Column tab in Power Query?","es":"¿Qué debe seleccionar en la pestaña Agregar columna de Power Query?","fr":"Que devez-vous sélectionner dans l''onglet Ajouter une colonne de Power Query ?"}', '[{"key":"A","text":{"pt-br":"Coluna condicional","en-us":"Conditional column","es":"Columna condicional","fr":"Colonne conditionnelle"}},{"key":"B","text":{"pt-br":"Coluna personalizada","en-us":"Custom column","es":"Columna personalizada","fr":"Colonne personnalisée"}},{"key":"C","text":{"pt-br":"Coluna de exemplo","en-us":"Column from examples","es":"Columna de ejemplo","fr":"Colonne à partir d''exemples"}},{"key":"D","text":{"pt-br":"Coluna de índice","en-us":"Index column","es":"Columna de índice","fr":"Colonne d''index"}}]', 'A', '{"pt-br":"A Coluna condicional permite criar colunas cujos valores são baseados em condições aplicadas a colunas existentes, como classificar preços em categorias.","en-us":"Conditional column allows creating columns whose values are based on conditions applied to existing columns, like classifying prices into categories.","es":"La Columna condicional permite crear columnas cuyos valores se basan en condiciones aplicadas a columnas existentes.","fr":"La Colonne conditionnelle permet de créer des colonnes dont les valeurs sont basées sur des conditions appliquées aux colonnes existantes."}'),
('Transformar Dados', '{"pt-br":"Você tem um notebook Fabric com um DataFrame df referenciando a tabela Customers. Precisa criar perfil dos dados minimizando esforço administrativo.","en-us":"You have a Fabric notebook with a DataFrame df referencing the Customers table. You need to profile the data while minimizing administrative effort.","es":"Tiene un notebook Fabric con un DataFrame df referenciando la tabla Customers. Necesita crear un perfil de datos minimizando esfuerzo administrativo.","fr":"Vous avez un notebook Fabric avec un DataFrame df référençant la table Customers. Vous devez profiler les données en minimisant l''effort administratif."}', '{"pt-br":"O que você deve fazer para criar o perfil dos dados?","en-us":"What should you do to profile the data?","es":"¿Qué debe hacer para crear el perfil de datos?","fr":"Que devez-vous faire pour profiler les données ?"}', '[{"key":"A","text":{"pt-br":"Executar display(df) e usar a guia Inspecionar","en-us":"Run display(df) and use the Inspect tab","es":"Ejecutar display(df) y usar la pestaña Inspeccionar","fr":"Exécuter display(df) et utiliser l''onglet Inspecter"}},{"key":"B","text":{"pt-br":"Converter para pandas e usar QuickVisualize","en-us":"Convert to pandas and use QuickVisualize","es":"Convertir a pandas y usar QuickVisualize","fr":"Convertir en pandas et utiliser QuickVisualize"}},{"key":"C","text":{"pt-br":"Usar a opção Gráfico no notebook","en-us":"Use the Chart option in the notebook","es":"Usar la opción Gráfico en el notebook","fr":"Utiliser l''option Graphique dans le notebook"}},{"key":"D","text":{"pt-br":"Criar um relatório Power BI inserido","en-us":"Create an embedded Power BI report","es":"Crear un informe Power BI insertado","fr":"Créer un rapport Power BI intégré"}}]', 'A', '{"pt-br":"O botão Inspecionar em display(df) fornece distribuição resumida e estatísticas para cada coluna com mínimo esforço. QuickVisualize e Gráficos não geram as estatísticas de perfil necessárias.","en-us":"The Inspect button in display(df) provides summary distribution and statistics for each column with minimal effort. QuickVisualize and Charts don''t generate needed profiling statistics.","es":"El botón Inspeccionar en display(df) proporciona distribución resumida y estadísticas para cada columna con mínimo esfuerzo.","fr":"Le bouton Inspecter dans display(df) fournit la distribution résumée et les statistiques pour chaque colonne avec un effort minimal."}'),
('Transformar Dados', '{"pt-br":"Você tem um lakehouse Fabric com um notebook. Precisa identificar linhas do DataFrame df_customers onde qualquer coluna (eixo 1) é NULL.","en-us":"You have a Fabric lakehouse with a notebook. You need to identify rows in DataFrame df_customers where any column (axis 1) is NULL.","es":"Tiene un lakehouse Fabric con un notebook. Necesita identificar filas del DataFrame df_customers donde cualquier columna (eje 1) es NULL.","fr":"Vous avez un lakehouse Fabric avec un notebook. Vous devez identifier les lignes du DataFrame df_customers où toute colonne (axe 1) est NULL."}', '{"pt-br":"Qual instrução você deve executar?","en-us":"Which statement should you run?","es":"¿Qué instrucción debe ejecutar?","fr":"Quelle instruction devez-vous exécuter ?"}', '[{"key":"A","text":{"pt-br":"df_customers[df_customers.isnull().any(axis=1)]","en-us":"df_customers[df_customers.isnull().any(axis=1)]","es":"df_customers[df_customers.isnull().any(axis=1)]","fr":"df_customers[df_customers.isnull().any(axis=1)]"}},{"key":"B","text":{"pt-br":"df_customers.dropna()","en-us":"df_customers.dropna()","es":"df_customers.dropna()","fr":"df_customers.dropna()"}},{"key":"C","text":{"pt-br":"df_customers.isnull().sum()","en-us":"df_customers.isnull().sum()","es":"df_customers.isnull().sum()","fr":"df_customers.isnull().sum()"}},{"key":"D","text":{"pt-br":"df_customers[df_customers.isnull().all(axis=1)]","en-us":"df_customers[df_customers.isnull().all(axis=1)]","es":"df_customers[df_customers.isnull().all(axis=1)]","fr":"df_customers[df_customers.isnull().all(axis=1)]"}}]', 'A', '{"pt-br":"isnull() identifica valores NULL. any(axis=1) retorna True se qualquer coluna da linha for NULL. O filtro retorna apenas essas linhas.","en-us":"isnull() identifies NULL values. any(axis=1) returns True if any column in the row is NULL. The filter returns only those rows.","es":"isnull() identifica valores NULL. any(axis=1) retorna True si cualquier columna de la fila es NULL.","fr":"isnull() identifie les valeurs NULL. any(axis=1) retourne True si une colonne de la ligne est NULL."}'),
('Consultar e Analisar', '{"pt-br":"Você tem uma tabela Sales com OrderID, CustomerID, ProductID, Quantity e Sales_Date. Precisa encontrar o total de produtos vendidos por ProductID em janeiro de 2024.","en-us":"You have a Sales table with OrderID, CustomerID, ProductID, Quantity, and Sales_Date. You need to find total products sold per ProductID in January 2024.","es":"Tiene una tabla Sales con OrderID, CustomerID, ProductID, Quantity y Sales_Date. Necesita encontrar el total de productos vendidos por ProductID en enero 2024.","fr":"Vous avez une table Sales avec OrderID, CustomerID, ProductID, Quantity et Sales_Date. Vous devez trouver le total de produits vendus par ProductID en janvier 2024."}', '{"pt-br":"Qual instrução SQL você deve executar?","en-us":"Which SQL statement should you run?","es":"¿Qué instrucción SQL debe ejecutar?","fr":"Quelle instruction SQL devez-vous exécuter ?"}', '[{"key":"A","text":{"pt-br":"SELECT Product_ID, SUM(Quantity) FROM Sales WHERE MONTH(Sales_Date)=1 AND YEAR(Sales_Date)=2024 GROUP BY Product_ID","en-us":"SELECT Product_ID, SUM(Quantity) FROM Sales WHERE MONTH(Sales_Date)=1 AND YEAR(Sales_Date)=2024 GROUP BY Product_ID","es":"SELECT Product_ID, SUM(Quantity) FROM Sales WHERE MONTH(Sales_Date)=1 AND YEAR(Sales_Date)=2024 GROUP BY Product_ID","fr":"SELECT Product_ID, SUM(Quantity) FROM Sales WHERE MONTH(Sales_Date)=1 AND YEAR(Sales_Date)=2024 GROUP BY Product_ID"}},{"key":"B","text":{"pt-br":"SELECT Product_ID, COUNT(*) FROM Sales GROUP BY Product_ID HAVING Sales_Date LIKE ''2024-01%''","en-us":"SELECT Product_ID, COUNT(*) FROM Sales GROUP BY Product_ID HAVING Sales_Date LIKE ''2024-01%''","es":"SELECT Product_ID, COUNT(*) FROM Sales GROUP BY Product_ID HAVING Sales_Date LIKE ''2024-01%''","fr":"SELECT Product_ID, COUNT(*) FROM Sales GROUP BY Product_ID HAVING Sales_Date LIKE ''2024-01%''"}},{"key":"C","text":{"pt-br":"SELECT Product_ID, SUM(Quantity) FROM Sales GROUP BY Product_ID, Sales_Date","en-us":"SELECT Product_ID, SUM(Quantity) FROM Sales GROUP BY Product_ID, Sales_Date","es":"SELECT Product_ID, SUM(Quantity) FROM Sales GROUP BY Product_ID, Sales_Date","fr":"SELECT Product_ID, SUM(Quantity) FROM Sales GROUP BY Product_ID, Sales_Date"}},{"key":"D","text":{"pt-br":"SELECT Product_ID, AVG(Quantity) FROM Sales WHERE YEAR(Sales_Date)=2024 GROUP BY Product_ID","en-us":"SELECT Product_ID, AVG(Quantity) FROM Sales WHERE YEAR(Sales_Date)=2024 GROUP BY Product_ID","es":"SELECT Product_ID, AVG(Quantity) FROM Sales WHERE YEAR(Sales_Date)=2024 GROUP BY Product_ID","fr":"SELECT Product_ID, AVG(Quantity) FROM Sales WHERE YEAR(Sales_Date)=2024 GROUP BY Product_ID"}}]', 'A', '{"pt-br":"A instrução filtra corretamente por mês 1 e ano 2024 com WHERE, soma a quantidade com SUM e agrupa por Product_ID com GROUP BY.","en-us":"The statement correctly filters by month 1 and year 2024 with WHERE, sums quantity with SUM, and groups by Product_ID with GROUP BY.","es":"La instrucción filtra correctamente por mes 1 y año 2024, suma la cantidad y agrupa por Product_ID.","fr":"L''instruction filtre correctement par mois 1 et année 2024, somme la quantité et groupe par Product_ID."}'),
('Consultar e Analisar', '{"pt-br":"Você está escrevendo T-SQL para classificar CustomerKeys por SalesAmount em ordem decrescente. Após empates, o próximo valor de classificação deve incrementar em 1 (sem lacunas).","en-us":"You are writing T-SQL to rank CustomerKeys by SalesAmount descending. After ties, the next rank value should increment by 1 (no gaps).","es":"Está escribiendo T-SQL para clasificar CustomerKeys por SalesAmount de forma descendente. Después de empates, el siguiente valor de clasificación debe incrementar en 1 (sin lagunas).","fr":"Vous écrivez du T-SQL pour classer les CustomerKeys par SalesAmount décroissant. Après les égalités, la valeur de rang suivante doit s''incrémenter de 1 (sans lacunes)."}', '{"pt-br":"Qual função de janela você deve usar?","en-us":"Which window function should you use?","es":"¿Qué función de ventana debe usar?","fr":"Quelle fonction de fenêtre devez-vous utiliser ?"}', '[{"key":"A","text":{"pt-br":"DENSE_RANK()","en-us":"DENSE_RANK()","es":"DENSE_RANK()","fr":"DENSE_RANK()"}},{"key":"B","text":{"pt-br":"RANK()","en-us":"RANK()","es":"RANK()","fr":"RANK()"}},{"key":"C","text":{"pt-br":"ROW_NUMBER()","en-us":"ROW_NUMBER()","es":"ROW_NUMBER()","fr":"ROW_NUMBER()"}},{"key":"D","text":{"pt-br":"NTILE()","en-us":"NTILE()","es":"NTILE()","fr":"NTILE()"}}]', 'A', '{"pt-br":"DENSE_RANK() retorna a classificação sem lacunas nos valores. RANK() inclui lacunas após empates. ROW_NUMBER() atribui números únicos sequenciais.","en-us":"DENSE_RANK() returns ranking without gaps in values. RANK() includes gaps after ties. ROW_NUMBER() assigns unique sequential numbers.","es":"DENSE_RANK() retorna la clasificación sin lagunas. RANK() incluye lagunas después de empates. ROW_NUMBER() asigna números únicos.","fr":"DENSE_RANK() retourne le classement sans lacunes. RANK() inclut des lacunes après les égalités. ROW_NUMBER() attribue des numéros uniques."}'),
('Consultar e Analisar', '{"pt-br":"Você tem tabelas customer_info e order_info em um warehouse Fabric. Precisa retornar todos os clientes que ainda não fizeram um pedido.","en-us":"You have customer_info and order_info tables in a Fabric warehouse. You need to return all customers who haven''t placed an order yet.","es":"Tiene tablas customer_info y order_info en un warehouse Fabric. Necesita retornar todos los clientes que aún no han hecho un pedido.","fr":"Vous avez des tables customer_info et order_info dans un warehouse Fabric. Vous devez retourner tous les clients qui n''ont pas encore passé de commande."}', '{"pt-br":"Qual consulta SQL você deve executar?","en-us":"Which SQL query should you run?","es":"¿Qué consulta SQL debe ejecutar?","fr":"Quelle requête SQL devez-vous exécuter ?"}', '[{"key":"A","text":{"pt-br":"SELECT name FROM customer_info LEFT JOIN order_info ON customer_info.customer_id = order_info.customer_id WHERE order_info.order_id IS NULL","en-us":"SELECT name FROM customer_info LEFT JOIN order_info ON customer_info.customer_id = order_info.customer_id WHERE order_info.order_id IS NULL","es":"SELECT name FROM customer_info LEFT JOIN order_info ON customer_info.customer_id = order_info.customer_id WHERE order_info.order_id IS NULL","fr":"SELECT name FROM customer_info LEFT JOIN order_info ON customer_info.customer_id = order_info.customer_id WHERE order_info.order_id IS NULL"}},{"key":"B","text":{"pt-br":"SELECT name FROM customer_info INNER JOIN order_info ON customer_info.customer_id = order_info.customer_id","en-us":"SELECT name FROM customer_info INNER JOIN order_info ON customer_info.customer_id = order_info.customer_id","es":"SELECT name FROM customer_info INNER JOIN order_info ON customer_info.customer_id = order_info.customer_id","fr":"SELECT name FROM customer_info INNER JOIN order_info ON customer_info.customer_id = order_info.customer_id"}},{"key":"C","text":{"pt-br":"SELECT name FROM customer_info WHERE customer_id IN (SELECT customer_id FROM order_info)","en-us":"SELECT name FROM customer_info WHERE customer_id IN (SELECT customer_id FROM order_info)","es":"SELECT name FROM customer_info WHERE customer_id IN (SELECT customer_id FROM order_info)","fr":"SELECT name FROM customer_info WHERE customer_id IN (SELECT customer_id FROM order_info)"}},{"key":"D","text":{"pt-br":"SELECT name FROM customer_info JOIN order_info ON customer_info.customer_id = order_info.customer_id WHERE order_info.order_id IS NOT NULL","en-us":"SELECT name FROM customer_info JOIN order_info ON customer_info.customer_id = order_info.customer_id WHERE order_info.order_id IS NOT NULL","es":"SELECT name FROM customer_info JOIN order_info ON customer_info.customer_id = order_info.customer_id WHERE order_info.order_id IS NOT NULL","fr":"SELECT name FROM customer_info JOIN order_info ON customer_info.customer_id = order_info.customer_id WHERE order_info.order_id IS NOT NULL"}}]', 'A', '{"pt-br":"LEFT JOIN com WHERE IS NULL retorna clientes sem correspondência na tabela de pedidos. INNER JOIN e IN retornam apenas clientes com pedidos.","en-us":"LEFT JOIN with WHERE IS NULL returns customers without matches in the orders table. INNER JOIN and IN return only customers with orders.","es":"LEFT JOIN con WHERE IS NULL retorna clientes sin correspondencia en la tabla de pedidos.","fr":"LEFT JOIN avec WHERE IS NULL retourne les clients sans correspondance dans la table des commandes."}'),
('Consultar e Analisar', '{"pt-br":"Você tem tabelas Trip (TripDateID, PassengerCount) e Date (DateID, Day, Month, Quarter, Year) no warehouse. Precisa resumir passageiros por ano usando o Editor de Consultas Visuais.","en-us":"You have Trip (TripDateID, PassengerCount) and Date (DateID, Day, Month, Quarter, Year) tables in the warehouse. You need to summarize passengers by year using Visual Query Editor.","es":"Tiene tablas Trip y Date en el warehouse. Necesita resumir pasajeros por año usando el Editor de Consultas Visuales.","fr":"Vous avez des tables Trip et Date dans le warehouse. Vous devez résumer les passagers par année avec l''Éditeur de requêtes visuelles."}', '{"pt-br":"Quais transformações você deve usar?","en-us":"Which transformations should you use?","es":"¿Qué transformaciones debe usar?","fr":"Quelles transformations devez-vous utiliser ?"}', '[{"key":"A","text":{"pt-br":"Mesclar consultas para unir Trip e Date, depois GroupBy","en-us":"Merge queries to join Trip and Date, then GroupBy","es":"Fusionar consultas para unir Trip y Date, luego GroupBy","fr":"Fusionner les requêtes pour joindre Trip et Date, puis GroupBy"}},{"key":"B","text":{"pt-br":"Acrescentar consultas e depois filtrar por ano","en-us":"Append queries then filter by year","es":"Anexar consultas y luego filtrar por año","fr":"Ajouter des requêtes puis filtrer par année"}},{"key":"C","text":{"pt-br":"Criar uma tabela calculada com DAX","en-us":"Create a calculated table with DAX","es":"Crear una tabla calculada con DAX","fr":"Créer une table calculée avec DAX"}},{"key":"D","text":{"pt-br":"Usar Unpivot e depois Pivot","en-us":"Use Unpivot then Pivot","es":"Usar Unpivot y luego Pivot","fr":"Utiliser Dépivot puis Pivot"}}]', 'A', '{"pt-br":"Mesclar une as tabelas Trip e Date. Após expandir a coluna Year, GroupBy resume os passageiros por ano. Append faz uma operação de UNION, não JOIN.","en-us":"Merge joins Trip and Date tables. After expanding the Year column, GroupBy summarizes passengers by year. Append does a UNION, not JOIN.","es":"Fusionar une las tablas Trip y Date. Después de expandir Year, GroupBy resume los pasajeros por año.","fr":"Fusionner joint les tables Trip et Date. Après expansion de Year, GroupBy résume les passagers par année."}'),
('Consultar e Analisar', '{"pt-br":"Você tem uma tabela inventory com item_id, category, stock_quantity e last_stocked_date. Precisa encontrar a data de estoque mais recente por categoria onde stock_quantity < 50.","en-us":"You have an inventory table with item_id, category, stock_quantity, and last_stocked_date. You need to find the most recent stocked date per category where stock_quantity < 50.","es":"Tiene una tabla inventory con item_id, category, stock_quantity y last_stocked_date. Necesita encontrar la fecha de stock más reciente por categoría donde stock_quantity < 50.","fr":"Vous avez une table inventory avec item_id, category, stock_quantity et last_stocked_date. Vous devez trouver la date de stock la plus récente par catégorie où stock_quantity < 50."}', '{"pt-br":"Qual instrução SQL você deve executar?","en-us":"Which SQL statement should you run?","es":"¿Qué instrucción SQL debe ejecutar?","fr":"Quelle instruction SQL devez-vous exécuter ?"}', '[{"key":"A","text":{"pt-br":"SELECT category, MAX(last_stocked_date) FROM inventory WHERE stock_quantity < 50 GROUP BY category","en-us":"SELECT category, MAX(last_stocked_date) FROM inventory WHERE stock_quantity < 50 GROUP BY category","es":"SELECT category, MAX(last_stocked_date) FROM inventory WHERE stock_quantity < 50 GROUP BY category","fr":"SELECT category, MAX(last_stocked_date) FROM inventory WHERE stock_quantity < 50 GROUP BY category"}},{"key":"B","text":{"pt-br":"SELECT DISTINCT category, last_stocked_date FROM inventory WHERE stock_quantity < 50 ORDER BY last_stocked_date DESC","en-us":"SELECT DISTINCT category, last_stocked_date FROM inventory WHERE stock_quantity < 50 ORDER BY last_stocked_date DESC","es":"SELECT DISTINCT category, last_stocked_date FROM inventory WHERE stock_quantity < 50 ORDER BY last_stocked_date DESC","fr":"SELECT DISTINCT category, last_stocked_date FROM inventory WHERE stock_quantity < 50 ORDER BY last_stocked_date DESC"}},{"key":"C","text":{"pt-br":"SELECT category, last_stocked_date FROM inventory GROUP BY category HAVING MIN(stock_quantity) < 50","en-us":"SELECT category, last_stocked_date FROM inventory GROUP BY category HAVING MIN(stock_quantity) < 50","es":"SELECT category, last_stocked_date FROM inventory GROUP BY category HAVING MIN(stock_quantity) < 50","fr":"SELECT category, last_stocked_date FROM inventory GROUP BY category HAVING MIN(stock_quantity) < 50"}},{"key":"D","text":{"pt-br":"SELECT category, last_stocked_date FROM inventory WHERE stock_quantity < 50 ORDER BY last_stocked_date DESC LIMIT 1","en-us":"SELECT category, last_stocked_date FROM inventory WHERE stock_quantity < 50 ORDER BY last_stocked_date DESC LIMIT 1","es":"SELECT category, last_stocked_date FROM inventory WHERE stock_quantity < 50 ORDER BY last_stocked_date DESC LIMIT 1","fr":"SELECT category, last_stocked_date FROM inventory WHERE stock_quantity < 50 ORDER BY last_stocked_date DESC LIMIT 1"}}]', 'A', '{"pt-br":"MAX com GROUP BY retorna a data mais recente por categoria. WHERE filtra stock < 50. As outras opções não agregam corretamente ou retornam apenas um registro.","en-us":"MAX with GROUP BY returns the most recent date per category. WHERE filters stock < 50. Other options don''t aggregate correctly or return only one record.","es":"MAX con GROUP BY retorna la fecha más reciente por categoría. WHERE filtra stock < 50.","fr":"MAX avec GROUP BY retourne la date la plus récente par catégorie. WHERE filtre stock < 50."}'),
('Consultar e Analisar', '{"pt-br":"Sua empresa usa Microsoft Fabric para um data warehouse. Você precisa analisar dados de vendas filtrando e agregando sem escrever código.","en-us":"Your company uses Microsoft Fabric for a data warehouse. You need to analyze sales data by filtering and aggregating without writing code.","es":"Su empresa usa Microsoft Fabric para un data warehouse. Necesita analizar datos de ventas filtrando y agregando sin escribir código.","fr":"Votre entreprise utilise Microsoft Fabric pour un data warehouse. Vous devez analyser les données de ventes en filtrant et agrégeant sans écrire de code."}', '{"pt-br":"O que você deve fazer?","en-us":"What should you do?","es":"¿Qué debe hacer?","fr":"Que devez-vous faire ?"}', '[{"key":"A","text":{"pt-br":"Usar o editor de consultas visuais no Microsoft Fabric","en-us":"Use the Visual Query Editor in Microsoft Fabric","es":"Usar el editor de consultas visuales en Microsoft Fabric","fr":"Utiliser l''éditeur de requêtes visuelles dans Microsoft Fabric"}},{"key":"B","text":{"pt-br":"Usar um pipeline no Microsoft Fabric","en-us":"Use a pipeline in Microsoft Fabric","es":"Usar un pipeline en Microsoft Fabric","fr":"Utiliser un pipeline dans Microsoft Fabric"}},{"key":"C","text":{"pt-br":"Usar Dataflow Gen2","en-us":"Use Dataflow Gen2","es":"Usar Dataflow Gen2","fr":"Utiliser Dataflow Gen2"}},{"key":"D","text":{"pt-br":"Usar Power BI Desktop","en-us":"Use Power BI Desktop","es":"Usar Power BI Desktop","fr":"Utiliser Power BI Desktop"}}]', 'A', '{"pt-br":"O editor de consultas visuais permite filtrar e agregar dados sem SQL, diretamente no warehouse. Pipelines são para orquestração, não análise.","en-us":"The Visual Query Editor allows filtering and aggregating data without SQL, directly in the warehouse. Pipelines are for orchestration, not analysis.","es":"El editor de consultas visuales permite filtrar y agregar datos sin SQL, directamente en el warehouse.","fr":"L''éditeur de requêtes visuelles permet de filtrer et d''agréger les données sans SQL, directement dans le warehouse."}'),
('Consultar e Analisar', '{"pt-br":"Você precisa identificar os principais clientes por volume de vendas combinando dados das tabelas Sales e Customer usando o editor de consultas visuais.","en-us":"You need to identify top customers by sales volume by combining data from Sales and Customer tables using the Visual Query Editor.","es":"Necesita identificar los principales clientes por volumen de ventas combinando datos de las tablas Sales y Customer usando el editor de consultas visuales.","fr":"Vous devez identifier les meilleurs clients par volume de ventes en combinant les données des tables Sales et Customer avec l''éditeur de requêtes visuelles."}', '{"pt-br":"Quais três ações você deve executar?","en-us":"Which three actions should you perform?","es":"¿Cuáles tres acciones debe ejecutar?","fr":"Quelles trois actions devez-vous effectuer ?"}', '[{"key":"A","text":{"pt-br":"Adicionar tabelas ao canvas, identificar chave comum e mesclar consultas como novas","en-us":"Add tables to canvas, identify common key, and merge queries as new","es":"Agregar tablas al canvas, identificar clave común y fusionar consultas como nuevas","fr":"Ajouter les tables au canevas, identifier la clé commune et fusionner les requêtes comme nouvelles"}},{"key":"B","text":{"pt-br":"Acrescentar consultas, salvar como exibição e filtrar resultados","en-us":"Append queries, save as view, and filter results","es":"Anexar consultas, guardar como vista y filtrar resultados","fr":"Ajouter des requêtes, enregistrer comme vue et filtrer les résultats"}},{"key":"C","text":{"pt-br":"Criar um pipeline, adicionar atividade de cópia e definir destino","en-us":"Create a pipeline, add copy activity, and set destination","es":"Crear un pipeline, agregar actividad de copia y definir destino","fr":"Créer un pipeline, ajouter une activité de copie et définir la destination"}},{"key":"D","text":{"pt-br":"Usar Dataflow Gen2, importar tabelas e aplicar transformações","en-us":"Use Dataflow Gen2, import tables, and apply transformations","es":"Usar Dataflow Gen2, importar tablas y aplicar transformaciones","fr":"Utiliser Dataflow Gen2, importer les tables et appliquer les transformations"}}]', 'A', '{"pt-br":"No editor de consultas visuais, adicione as tabelas ao canvas, identifique a chave comum (CustomerID) e use Mesclar consultas como novas para unir os dados.","en-us":"In the Visual Query Editor, add tables to canvas, identify the common key (CustomerID), and use Merge queries as new to join the data.","es":"En el editor de consultas visuales, agregue tablas, identifique la clave común y use Fusionar consultas como nuevas.","fr":"Dans l''éditeur de requêtes visuelles, ajoutez les tables, identifiez la clé commune et utilisez Fusionner les requêtes comme nouvelles."}'),
('Consultar e Analisar', '{"pt-br":"Você criou uma consulta Query1 no editor de consultas visuais que combina Table1 com várias tabelas. Precisa minimizar o tempo de execução com mínimo esforço de desenvolvimento.","en-us":"You created a query Query1 in the Visual Query Editor combining Table1 with multiple tables. You need to minimize execution time with minimal development effort.","es":"Creó una consulta Query1 en el editor visual combinando Table1 con varias tablas. Necesita minimizar el tiempo de ejecución con mínimo esfuerzo.","fr":"Vous avez créé une requête Query1 dans l''éditeur visuel combinant Table1 avec plusieurs tables. Vous devez minimiser le temps d''exécution avec un effort minimal."}', '{"pt-br":"O que você deve fazer?","en-us":"What should you do?","es":"¿Qué debe hacer?","fr":"Que devez-vous faire ?"}', '[{"key":"A","text":{"pt-br":"Salvar Query1 como uma tabela no warehouse","en-us":"Save Query1 as a table in the warehouse","es":"Guardar Query1 como una tabla en el warehouse","fr":"Enregistrer Query1 comme table dans le warehouse"}},{"key":"B","text":{"pt-br":"Salvar Query1 como uma exibição (view)","en-us":"Save Query1 as a view","es":"Guardar Query1 como una vista","fr":"Enregistrer Query1 comme vue"}},{"key":"C","text":{"pt-br":"Exportar como modelo Power Query","en-us":"Export as a Power Query model","es":"Exportar como modelo Power Query","fr":"Exporter comme modèle Power Query"}},{"key":"D","text":{"pt-br":"Criar um endpoint SQL","en-us":"Create a SQL endpoint","es":"Crear un endpoint SQL","fr":"Créer un point de terminaison SQL"}}]', 'A', '{"pt-br":"Salvar como tabela materializa os resultados, permitindo leitura direta sem reexecutar joins complexos. View recompila a cada execução. Endpoint SQL não melhora performance.","en-us":"Saving as a table materializes results, allowing direct reads without re-running complex joins. View recompiles on each run. SQL endpoint doesn''t improve performance.","es":"Guardar como tabla materializa los resultados. View recompila en cada ejecución. Endpoint SQL no mejora el rendimiento.","fr":"Enregistrer comme table matérialise les résultats. La vue recompile à chaque exécution. Le point de terminaison SQL n''améliore pas les performances."}'),
('Projetar Modelos Semânticos', '{"pt-br":"Você tem um relatório Power BI com um gráfico de barras. Precisa permitir que usuários alterem a categoria do eixo Y usando uma segmentação de dados.","en-us":"You have a Power BI report with a bar chart. You need to allow users to change the Y-axis category using a slicer.","es":"Tiene un informe Power BI con un gráfico de barras. Necesita permitir que los usuarios cambien la categoría del eje Y usando una segmentación.","fr":"Vous avez un rapport Power BI avec un graphique à barres. Vous devez permettre aux utilisateurs de changer la catégorie de l''axe Y avec un segment."}', '{"pt-br":"Qual recurso do Power BI você deve adicionar?","en-us":"Which Power BI feature should you add?","es":"¿Qué recurso de Power BI debe agregar?","fr":"Quelle fonctionnalité Power BI devez-vous ajouter ?"}', '[{"key":"A","text":{"pt-br":"Parâmetros de campo","en-us":"Field parameters","es":"Parámetros de campo","fr":"Paramètres de champ"}},{"key":"B","text":{"pt-br":"Indicadores (Bookmarks)","en-us":"Bookmarks","es":"Marcadores (Bookmarks)","fr":"Signets (Bookmarks)"}},{"key":"C","text":{"pt-br":"Drill-through","en-us":"Drill-through","es":"Drill-through","fr":"Drill-through"}},{"key":"D","text":{"pt-br":"Botões de navegação","en-us":"Navigation buttons","es":"Botones de navegación","fr":"Boutons de navigation"}}]', 'A', '{"pt-br":"Parâmetros de campo permitem que usuários alternem entre colunas usadas no eixo categórico dos visuais via segmentação. As outras opções não oferecem essa capacidade.","en-us":"Field parameters allow users to switch between columns used in the visual''s categorical axis via a slicer. Other options don''t provide this capability.","es":"Los parámetros de campo permiten que los usuarios alternen entre columnas usadas en el eje categórico via segmentación.","fr":"Les paramètres de champ permettent aux utilisateurs de basculer entre les colonnes utilisées dans l''axe catégoriel via un segment."}'),
('Projetar Modelos Semânticos', '{"pt-br":"Seu modelo tem tabelas Sales (SalesAmount, OrderDateKey, ShipDateKey) e Date (DateKey). Date tem relação ativa com OrderDateKey e inativa com ShipDateKey. Precisa criar medidas para vendas por data de pedido e por data de envio.","en-us":"Your model has Sales (SalesAmount, OrderDateKey, ShipDateKey) and Date (DateKey) tables. Date has an active relationship with OrderDateKey and inactive with ShipDateKey. You need measures for sales by order date and ship date.","es":"Su modelo tiene tablas Sales y Date. Date tiene relación activa con OrderDateKey e inactiva con ShipDateKey. Necesita medidas para ventas por fecha de pedido y fecha de envío.","fr":"Votre modèle a des tables Sales et Date. Date a une relation active avec OrderDateKey et inactive avec ShipDateKey. Vous avez besoin de mesures pour les ventes par date de commande et date d''expédition."}', '{"pt-br":"Como você deve criar as medidas?","en-us":"How should you create the measures?","es":"¿Cómo debe crear las medidas?","fr":"Comment devez-vous créer les mesures ?"}', '[{"key":"A","text":{"pt-br":"Vendas Pedido = SUM(Sales[SalesAmount]); Vendas Envio = CALCULATE(SUM(Sales[SalesAmount]), USERELATIONSHIP(Date[DateKey], Sales[ShipDateKey]))","en-us":"Order Sales = SUM(Sales[SalesAmount]); Ship Sales = CALCULATE(SUM(Sales[SalesAmount]), USERELATIONSHIP(Date[DateKey], Sales[ShipDateKey]))","es":"Ventas Pedido = SUM; Ventas Envío = CALCULATE + USERELATIONSHIP","fr":"Ventes Commande = SUM; Ventes Expédition = CALCULATE + USERELATIONSHIP"}},{"key":"B","text":{"pt-br":"Ambas com CALCULATE e USERELATIONSHIP","en-us":"Both with CALCULATE and USERELATIONSHIP","es":"Ambas con CALCULATE y USERELATIONSHIP","fr":"Les deux avec CALCULATE et USERELATIONSHIP"}},{"key":"C","text":{"pt-br":"Ambas com SUM simples e filtros de página","en-us":"Both with simple SUM and page filters","es":"Ambas con SUM simple y filtros de página","fr":"Les deux avec SUM simple et filtres de page"}},{"key":"D","text":{"pt-br":"Usar RELATED para trazer a data de envio e SUM para ambas","en-us":"Use RELATED to bring ship date and SUM for both","es":"Usar RELATED para traer la fecha de envío y SUM para ambas","fr":"Utiliser RELATED pour amener la date d''expédition et SUM pour les deux"}}]', 'A', '{"pt-br":"A relação ativa (OrderDate) funciona com SUM simples. Para a relação inativa (ShipDate), use CALCULATE com USERELATIONSHIP para ativá-la. RELATED retorna valores, não ativa relações.","en-us":"Active relationship (OrderDate) works with simple SUM. For inactive relationship (ShipDate), use CALCULATE with USERELATIONSHIP to activate it.","es":"La relación activa funciona con SUM simple. Para la inactiva, use CALCULATE con USERELATIONSHIP.","fr":"La relation active fonctionne avec SUM simple. Pour l''inactive, utilisez CALCULATE avec USERELATIONSHIP."}'),
('Otimizar Modelos Semânticos', '{"pt-br":"Você tem um modelo grande com agregações definidas pelo usuário para acelerar consultas frequentes. Precisa confirmar se as consultas usam os dados agregados.","en-us":"You have a large model with user-defined aggregations to speed up frequent queries. You need to confirm if queries use the aggregated data.","es":"Tiene un modelo grande con agregaciones definidas por el usuario. Necesita confirmar si las consultas usan los datos agregados.","fr":"Vous avez un grand modèle avec des agrégations définies par l''utilisateur. Vous devez confirmer si les requêtes utilisent les données agrégées."}', '{"pt-br":"Quais duas ferramentas você deve usar?","en-us":"Which two tools should you use?","es":"¿Cuáles dos herramientas debe usar?","fr":"Quels deux outils devez-vous utiliser ?"}', '[{"key":"A","text":{"pt-br":"DAX Studio e SQL Server Profiler","en-us":"DAX Studio and SQL Server Profiler","es":"DAX Studio y SQL Server Profiler","fr":"DAX Studio et SQL Server Profiler"}},{"key":"B","text":{"pt-br":"DAX Studio e VertiPaq Analyzer","en-us":"DAX Studio and VertiPaq Analyzer","es":"DAX Studio y VertiPaq Analyzer","fr":"DAX Studio et VertiPaq Analyzer"}},{"key":"C","text":{"pt-br":"Performance Analyzer e Tabular Editor","en-us":"Performance Analyzer and Tabular Editor","es":"Performance Analyzer y Tabular Editor","fr":"Performance Analyzer et Tabular Editor"}},{"key":"D","text":{"pt-br":"ALM Toolkit e Best Practice Analyzer","en-us":"ALM Toolkit and Best Practice Analyzer","es":"ALM Toolkit y Best Practice Analyzer","fr":"ALM Toolkit et Best Practice Analyzer"}}]', 'A', '{"pt-br":"SQL Server Profiler e DAX Studio detectam se as consultas foram retornadas do cache em memória ou enviadas via DirectQuery à fonte de dados.","en-us":"SQL Server Profiler and DAX Studio can detect whether queries were returned from the in-memory cache or pushed via DirectQuery to the data source.","es":"SQL Server Profiler y DAX Studio detectan si las consultas fueron retornadas del cache o enviadas vía DirectQuery.","fr":"SQL Server Profiler et DAX Studio détectent si les requêtes ont été retournées du cache ou envoyées via DirectQuery."}'),
('Projetar Modelos Semânticos', '{"pt-br":"Você precisa implementar um modelo dimensional onde alterações no status do cliente devem ser mantidas com timestamp para análise pontual (point-in-time).","en-us":"You need to implement a dimensional model where customer status changes must be maintained with timestamps for point-in-time analysis.","es":"Necesita implementar un modelo dimensional donde los cambios de estado del cliente deben mantenerse con timestamp para análisis puntual.","fr":"Vous devez implémenter un modèle dimensionnel où les changements de statut client doivent être conservés avec des horodatages pour l''analyse ponctuelle."}', '{"pt-br":"Qual tipo de dimensão você deve usar para DimCustomer?","en-us":"Which dimension type should you use for DimCustomer?","es":"¿Qué tipo de dimensión debe usar para DimCustomer?","fr":"Quel type de dimension devez-vous utiliser pour DimCustomer ?"}', '[{"key":"A","text":{"pt-br":"SCD Tipo 2 (Slowly Changing Dimension)","en-us":"SCD Type 2 (Slowly Changing Dimension)","es":"SCD Tipo 2 (Slowly Changing Dimension)","fr":"SCD Type 2 (Dimension à évolution lente)"}},{"key":"B","text":{"pt-br":"SCD Tipo 1","en-us":"SCD Type 1","es":"SCD Tipo 1","fr":"SCD Type 1"}},{"key":"C","text":{"pt-br":"SCD Tipo 0","en-us":"SCD Type 0","es":"SCD Tipo 0","fr":"SCD Type 0"}},{"key":"D","text":{"pt-br":"SCD Tipo 3","en-us":"SCD Type 3","es":"SCD Tipo 3","fr":"SCD Type 3"}}]', 'A', '{"pt-br":"SCD Tipo 2 mantém múltiplas versões adicionando uma nova linha a cada alteração com timestamp. Tipo 1 sobrescreve. Tipo 0 não rastreia. Tipo 3 armazena duas versões como colunas.","en-us":"SCD Type 2 maintains multiple versions by adding a new row per change with timestamp. Type 1 overwrites. Type 0 doesn''t track. Type 3 stores two versions as columns.","es":"SCD Tipo 2 mantiene múltiples versiones agregando una nueva fila por cambio. Tipo 1 sobrescribe. Tipo 0 no rastrea. Tipo 3 almacena dos versiones.","fr":"SCD Type 2 maintient plusieurs versions en ajoutant une nouvelle ligne par changement. Type 1 écrase. Type 0 ne suit pas. Type 3 stocke deux versions."}'),
('Otimizar Modelos Semânticos', '{"pt-br":"Você publicou um modelo grande com incremental refresh. A carga inicial completa levará horas. Precisa criar as partições no serviço sem processá-las.","en-us":"You published a large model with incremental refresh. The full initial load will take hours. You need to create partitions in the service without processing them.","es":"Publicó un modelo grande con incremental refresh. La carga inicial completa tomará horas. Necesita crear las particiones sin procesarlas.","fr":"Vous avez publié un grand modèle avec actualisation incrémentielle. Le chargement initial complet prendra des heures. Vous devez créer les partitions sans les traiter."}', '{"pt-br":"O que você pode usar?","en-us":"What can you use?","es":"¿Qué puede usar?","fr":"Que pouvez-vous utiliser ?"}', '[{"key":"A","text":{"pt-br":"Editor Tabular (Tabular Editor)","en-us":"Tabular Editor","es":"Editor Tabular (Tabular Editor)","fr":"Tabular Editor"}},{"key":"B","text":{"pt-br":"Power BI Desktop","en-us":"Power BI Desktop","es":"Power BI Desktop","fr":"Power BI Desktop"}},{"key":"C","text":{"pt-br":"Microsoft Visual Studio Code","en-us":"Microsoft Visual Studio Code","es":"Microsoft Visual Studio Code","fr":"Microsoft Visual Studio Code"}},{"key":"D","text":{"pt-br":"DAX Studio","en-us":"DAX Studio","es":"DAX Studio","fr":"DAX Studio"}}]', 'A', '{"pt-br":"Tabular Editor permite executar ''Apply Refresh Policy'' para criar partições baseadas na política de incremental refresh sem processá-las. Power BI Desktop exige atualização completa.","en-us":"Tabular Editor allows executing ''Apply Refresh Policy'' to create partitions based on incremental refresh policy without processing them.","es":"Tabular Editor permite ejecutar ''Apply Refresh Policy'' para crear particiones sin procesarlas.","fr":"Tabular Editor permet d''exécuter ''Apply Refresh Policy'' pour créer des partitions sans les traiter."}'),
('Otimizar Modelos Semânticos', '{"pt-br":"Você tem um relatório Power BI com DirectQuery para um banco SQL do Azure. Precisa reduzir o número de consultas enviadas ao banco quando o usuário interage com filtros e segmentações.","en-us":"You have a Power BI report with DirectQuery to Azure SQL. You need to reduce queries sent to the database when users interact with filters and slicers.","es":"Tiene un informe Power BI con DirectQuery a Azure SQL. Necesita reducir las consultas enviadas al banco cuando los usuarios interactúan con filtros.","fr":"Vous avez un rapport Power BI avec DirectQuery vers Azure SQL. Vous devez réduire les requêtes envoyées à la base quand les utilisateurs interagissent avec les filtres."}', '{"pt-br":"O que você deve fazer?","en-us":"What should you do?","es":"¿Qué debe hacer?","fr":"Que devez-vous faire ?"}', '[{"key":"A","text":{"pt-br":"Adicionar botões Aplicar a todos os filtros","en-us":"Add Apply buttons to all filters","es":"Agregar botones Aplicar a todos los filtros","fr":"Ajouter des boutons Appliquer à tous les filtres"}},{"key":"B","text":{"pt-br":"Habilitar atualização automática de página","en-us":"Enable automatic page refresh","es":"Habilitar actualización automática de página","fr":"Activer l''actualisation automatique de la page"}},{"key":"C","text":{"pt-br":"Converter para modo Import","en-us":"Convert to Import mode","es":"Convertir a modo Import","fr":"Convertir en mode Import"}},{"key":"D","text":{"pt-br":"Aumentar o timeout das consultas","en-us":"Increase query timeout","es":"Aumentar el timeout de consultas","fr":"Augmenter le délai d''expiration des requêtes"}}]', 'A', '{"pt-br":"Botões Aplicar pausam as consultas até que o usuário finalize suas seleções de filtro, enviando uma única consulta ao clicar em Aplicar. As outras opções não reduzem o número de consultas.","en-us":"Apply buttons pause queries until the user finalizes filter selections, sending a single query when clicking Apply. Other options don''t reduce query count.","es":"Los botones Aplicar pausan las consultas hasta que el usuario finalice sus selecciones de filtro.","fr":"Les boutons Appliquer mettent en pause les requêtes jusqu''à ce que l''utilisateur finalise ses sélections de filtre."}'),
('Ciclo de Vida', '{"pt-br":"Você publicou um modelo semântico grande que leva 2 horas para atualizar. Precisa atualizar a definição de uma medida sem precisar atualizar o modelo no serviço.","en-us":"You published a large semantic model that takes 2 hours to refresh. You need to update a measure definition without refreshing the model in the service.","es":"Publicó un modelo semántico grande que tarda 2 horas en actualizarse. Necesita actualizar la definición de una medida sin actualizar el modelo.","fr":"Vous avez publié un grand modèle sémantique qui prend 2 heures à actualiser. Vous devez mettre à jour une définition de mesure sans actualiser le modèle."}', '{"pt-br":"O que você pode usar?","en-us":"What can you use?","es":"¿Qué puede usar?","fr":"Que pouvez-vous utiliser ?"}', '[{"key":"A","text":{"pt-br":"ALM Toolkit","en-us":"ALM Toolkit","es":"ALM Toolkit","fr":"ALM Toolkit"}},{"key":"B","text":{"pt-br":"Power BI Desktop","en-us":"Power BI Desktop","es":"Power BI Desktop","fr":"Power BI Desktop"}},{"key":"C","text":{"pt-br":"DAX Studio","en-us":"DAX Studio","es":"DAX Studio","fr":"DAX Studio"}},{"key":"D","text":{"pt-br":"Excel","en-us":"Excel","es":"Excel","fr":"Excel"}}]', 'A', '{"pt-br":"ALM Toolkit é uma ferramenta de diferenciação de esquema que implanta apenas metadados sem exigir atualização dos dados. Power BI Desktop substitui e exige refresh. DAX Studio não atualiza metadados.","en-us":"ALM Toolkit is a schema diff tool that deploys only metadata without requiring data refresh. Power BI Desktop replaces and requires refresh. DAX Studio doesn''t update metadata.","es":"ALM Toolkit despliega solo metadatos sin exigir actualización de datos. Power BI Desktop reemplaza y exige refresh.","fr":"ALM Toolkit est un outil de diff de schéma qui déploie uniquement les métadonnées sans nécessiter d''actualisation des données."}'),
('Otimizar Modelos Semânticos', '{"pt-br":"Você tem um modelo semântico grande e precisa identificar quais colunas contribuem mais para o tamanho do modelo para focar esforços de otimização.","en-us":"You have a large semantic model and need to identify which columns contribute most to model size to focus optimization efforts.","es":"Tiene un modelo semántico grande y necesita identificar qué columnas contribuyen más al tamaño del modelo.","fr":"Vous avez un grand modèle sémantique et devez identifier quelles colonnes contribuent le plus à la taille du modèle."}', '{"pt-br":"Qual ferramenta externa você pode usar?","en-us":"Which external tool can you use?","es":"¿Qué herramienta externa puede usar?","fr":"Quel outil externe pouvez-vous utiliser ?"}', '[{"key":"A","text":{"pt-br":"DAX Studio","en-us":"DAX Studio","es":"DAX Studio","fr":"DAX Studio"}},{"key":"B","text":{"pt-br":"ALM Toolkit","en-us":"ALM Toolkit","es":"ALM Toolkit","fr":"ALM Toolkit"}},{"key":"C","text":{"pt-br":"Tabular Editor","en-us":"Tabular Editor","es":"Tabular Editor","fr":"Tabular Editor"}},{"key":"D","text":{"pt-br":"Best Practice Analyzer","en-us":"Best Practice Analyzer","es":"Best Practice Analyzer","fr":"Best Practice Analyzer"}}]', 'A', '{"pt-br":"DAX Studio conecta ao modelo e fornece estatísticas detalhadas sobre tamanho de cada tabela e coluna (VertiPaq Analyzer). As outras ferramentas têm casos de uso diferentes.","en-us":"DAX Studio connects to the model and provides detailed statistics about each table and column size (VertiPaq Analyzer). Other tools have different use cases.","es":"DAX Studio se conecta al modelo y proporciona estadísticas detalladas sobre el tamaño de cada tabla y columna.","fr":"DAX Studio se connecte au modèle et fournit des statistiques détaillées sur la taille de chaque table et colonne."}'),
('Obter Dados', '{"pt-br":"Você tem um lakehouse Fabric e precisa migrar 200 milhões de linhas de um banco Snowflake externo usando um pipeline de dados.","en-us":"You have a Fabric lakehouse and need to migrate 200 million rows from an external Snowflake database using a data pipeline.","es":"Tiene un lakehouse Fabric y necesita migrar 200 millones de filas de un banco Snowflake externo usando un pipeline de datos.","fr":"Vous avez un lakehouse Fabric et devez migrer 200 millions de lignes d''une base Snowflake externe avec un pipeline de données."}', '{"pt-br":"Qual é o método mais eficaz (mais rápido)?","en-us":"What is the most effective (fastest) method?","es":"¿Cuál es el método más eficaz (más rápido)?","fr":"Quelle est la méthode la plus efficace (la plus rapide) ?"}', '[{"key":"A","text":{"pt-br":"Pipeline de Dados com atividade Copiar dados","en-us":"Data Pipeline with Copy Data activity","es":"Pipeline de Datos con actividad Copiar datos","fr":"Pipeline de données avec activité Copier les données"}},{"key":"B","text":{"pt-br":"Dataflow Gen2","en-us":"Dataflow Gen2","es":"Dataflow Gen2","fr":"Dataflow Gen2"}},{"key":"C","text":{"pt-br":"Notebook Spark","en-us":"Spark Notebook","es":"Notebook Spark","fr":"Notebook Spark"}},{"key":"D","text":{"pt-br":"Atalho (Shortcut)","en-us":"Shortcut","es":"Atajo (Shortcut)","fr":"Raccourci (Shortcut)"}}]', 'A', '{"pt-br":"A atividade Copiar dados é o método mais rápido e direto para migrar grandes volumes sem transformações. Dataflow Gen2 é para volumes menores. Atalhos não movem dados.","en-us":"Copy Data activity is the fastest and most direct method for migrating large volumes without transformations. Dataflow Gen2 is for smaller volumes. Shortcuts don''t move data.","es":"Copiar datos es el método más rápido para migrar grandes volúmenes sin transformaciones.","fr":"L''activité Copier les données est la méthode la plus rapide pour migrer de grands volumes sans transformations."}'),
('Obter Dados', '{"pt-br":"Você tem um warehouse Fabric e precisa ingerir 1 TB de dados de uma fonte externa. A solução deve ter a maior taxa de transferência e ser low-code/no-code.","en-us":"You have a Fabric warehouse and need to ingest 1 TB from an external source. The solution must have the highest throughput and be low-code/no-code.","es":"Tiene un warehouse Fabric y necesita ingerir 1 TB de una fuente externa. La solución debe tener la mayor tasa de transferencia y ser low-code.","fr":"Vous avez un warehouse Fabric et devez ingérer 1 To depuis une source externe. La solution doit avoir le débit le plus élevé et être low-code."}', '{"pt-br":"O que você deve recomendar?","en-us":"What should you recommend?","es":"¿Qué debe recomendar?","fr":"Que devez-vous recommander ?"}', '[{"key":"A","text":{"pt-br":"Atividade Copiar dados de um pipeline","en-us":"Copy Data activity from a pipeline","es":"Actividad Copiar datos de un pipeline","fr":"Activité Copier les données d''un pipeline"}},{"key":"B","text":{"pt-br":"Notebook Spark","en-us":"Spark Notebook","es":"Notebook Spark","fr":"Notebook Spark"}},{"key":"C","text":{"pt-br":"Atalho (Shortcut)","en-us":"Shortcut","es":"Atajo (Shortcut)","fr":"Raccourci (Shortcut)"}},{"key":"D","text":{"pt-br":"Dataflow Gen2","en-us":"Dataflow Gen2","es":"Dataflow Gen2","fr":"Dataflow Gen2"}}]', 'A', '{"pt-br":"Copiar dados oferece a maior taxa de transferência e é low-code. Notebooks são code-first. Atalhos não movem dados. Dataflow Gen2 tem performance inferior para grandes volumes.","en-us":"Copy Data provides highest throughput and is low-code. Notebooks are code-first. Shortcuts don''t move data. Dataflow Gen2 has lower performance for large volumes.","es":"Copiar datos ofrece la mayor tasa de transferencia y es low-code. Notebooks son code-first. Atalhos no mueven datos.","fr":"Copier les données offre le débit le plus élevé et est low-code. Les notebooks sont code-first. Les raccourcis ne déplacent pas les données."}'),
('Otimizar Modelos Semânticos', '{"pt-br":"Uma consulta SELECT em uma tabela Delta no lakehouse é lenta. A tabela tem 1.000 arquivos Parquet de 1 MB cada, recebe dados diários e deve manter histórico de 7 dias.","en-us":"A SELECT query on a Delta table in the lakehouse is slow. The table has 1,000 Parquet files of 1 MB each, receives daily data, and must maintain 7-day history.","es":"Una consulta SELECT en una tabla Delta del lakehouse es lenta. La tabla tiene 1.000 archivos Parquet de 1 MB cada uno, recibe datos diarios y debe mantener historial de 7 días.","fr":"Une requête SELECT sur une table Delta dans le lakehouse est lente. La table a 1 000 fichiers Parquet de 1 Mo chacun, reçoit des données quotidiennes et doit maintenir un historique de 7 jours."}', '{"pt-br":"O que você deve fazer no explorador do Lakehouse?","en-us":"What should you do in the Lakehouse explorer?","es":"¿Qué debe hacer en el explorador del Lakehouse?","fr":"Que devez-vous faire dans l''explorateur du Lakehouse ?"}', '[{"key":"A","text":{"pt-br":"Selecionar Manutenção e executar OPTIMIZE + VACUUM com retenção de 7 dias","en-us":"Select Maintenance and run OPTIMIZE + VACUUM with 7-day retention","es":"Seleccionar Mantenimiento y ejecutar OPTIMIZE + VACUUM con retención de 7 días","fr":"Sélectionner Maintenance et exécuter OPTIMIZE + VACUUM avec rétention de 7 jours"}},{"key":"B","text":{"pt-br":"Executar apenas VACUUM com retenção de 7 dias","en-us":"Run only VACUUM with 7-day retention","es":"Ejecutar solo VACUUM con retención de 7 días","fr":"Exécuter uniquement VACUUM avec rétention de 7 jours"}},{"key":"C","text":{"pt-br":"Recriar a tabela com particionamento","en-us":"Recreate the table with partitioning","es":"Recrear la tabla con particionamiento","fr":"Recréer la table avec partitionnement"}},{"key":"D","text":{"pt-br":"Aumentar a capacidade do workspace","en-us":"Increase workspace capacity","es":"Aumentar la capacidad del workspace","fr":"Augmenter la capacité du workspace"}}]', 'A', '{"pt-br":"OPTIMIZE compacta arquivos pequenos em arquivos maiores (ideal 128 MB - 1 GB). VACUUM remove arquivos antigos que não estão mais em uso, reduzindo custos de armazenamento.","en-us":"OPTIMIZE compacts small files into larger files (ideal 128 MB - 1 GB). VACUUM removes old files no longer in use, reducing storage costs.","es":"OPTIMIZE compacta archivos pequeños en archivos más grandes. VACUUM elimina archivos antiguos no utilizados.","fr":"OPTIMIZE compacte les petits fichiers en fichiers plus grands. VACUUM supprime les anciens fichiers inutilisés."}'),
('Otimizar Modelos Semânticos', '{"pt-br":"Você tem um warehouse Fabric com uma consulta SQL com desempenho ruim. As estatísticas da tabela estão desatualizadas. Precisa atualizar manualmente as estatísticas.","en-us":"You have a Fabric warehouse with a poorly performing SQL query. Table statistics are outdated. You need to manually update statistics.","es":"Tiene un warehouse Fabric con una consulta SQL de bajo rendimiento. Las estadísticas de la tabla están desactualizadas.","fr":"Vous avez un warehouse Fabric avec une requête SQL peu performante. Les statistiques de la table sont obsolètes."}', '{"pt-br":"Quais estatísticas de coluna você deve atualizar?","en-us":"Which column statistics should you update?","es":"¿Qué estadísticas de columna debe actualizar?","fr":"Quelles statistiques de colonne devez-vous mettre à jour ?"}', '[{"key":"A","text":{"pt-br":"Colunas usadas em cláusulas GROUP BY","en-us":"Columns used in GROUP BY clauses","es":"Columnas usadas en cláusulas GROUP BY","fr":"Colonnes utilisées dans les clauses GROUP BY"}},{"key":"B","text":{"pt-br":"Todas as colunas da tabela","en-us":"All columns in the table","es":"Todas las columnas de la tabla","fr":"Toutes les colonnes de la table"}},{"key":"C","text":{"pt-br":"Apenas colunas de chave primária","en-us":"Only primary key columns","es":"Solo columnas de clave primaria","fr":"Uniquement les colonnes de clé primaire"}},{"key":"D","text":{"pt-br":"Colunas usadas em SELECT","en-us":"Columns used in SELECT","es":"Columnas usadas en SELECT","fr":"Colonnes utilisées dans SELECT"}}]', 'A', '{"pt-br":"Ao atualizar estatísticas manualmente, foque em colunas usadas em cláusulas JOIN, ORDER BY e GROUP BY, pois são as que o otimizador de consultas usa para planos de execução.","en-us":"When manually updating statistics, focus on columns used in JOIN, ORDER BY, and GROUP BY clauses, as the query optimizer uses these for execution plans.","es":"Al actualizar estadísticas, enfóquese en columnas usadas en JOIN, ORDER BY y GROUP BY.","fr":"Lors de la mise à jour manuelle des statistiques, concentrez-vous sur les colonnes utilisées dans JOIN, ORDER BY et GROUP BY."}'),
('Obter Dados', '{"pt-br":"Você tem um Dataflow Gen2 que ingere e transforma a tabela FactSales. Devido ao número de transformações, há problemas de timeout. A consulta não pode ser otimizada e alterar o tempo de atualização não ajuda.","en-us":"You have a Dataflow Gen2 that ingests and transforms FactSales. Due to many transformations, there are timeout issues. The query can''t be optimized and changing refresh time doesn''t help.","es":"Tiene un Dataflow Gen2 que ingiere y transforma FactSales. Debido al número de transformaciones, hay problemas de timeout.","fr":"Vous avez un Dataflow Gen2 qui ingère et transforme FactSales. En raison du nombre de transformations, il y a des problèmes de délai d''attente."}', '{"pt-br":"Qual ação adicional você deve recomendar?","en-us":"What additional action should you recommend?","es":"¿Qué acción adicional debe recomendar?","fr":"Quelle action supplémentaire devez-vous recommander ?"}', '[{"key":"A","text":{"pt-br":"Criar um segundo dataflow de staging que ingere sem transformações, e conectar o original para transformar","en-us":"Create a second staging dataflow that ingests without transformations, and connect the original to transform","es":"Crear un segundo dataflow de staging que ingiere sin transformaciones, y conectar el original para transformar","fr":"Créer un second dataflow de staging qui ingère sans transformations, et connecter l''original pour transformer"}},{"key":"B","text":{"pt-br":"Criar um atalho para FactSales","en-us":"Create a shortcut for FactSales","es":"Crear un atajo para FactSales","fr":"Créer un raccourci pour FactSales"}},{"key":"C","text":{"pt-br":"Migrar para um Notebook Spark","en-us":"Migrate to a Spark Notebook","es":"Migrar a un Notebook Spark","fr":"Migrer vers un Notebook Spark"}},{"key":"D","text":{"pt-br":"Aumentar a capacidade do workspace","en-us":"Increase workspace capacity","es":"Aumentar la capacidad del workspace","fr":"Augmenter la capacité du workspace"}}]', 'A', '{"pt-br":"A melhor prática é criar um dataflow de staging que ingere dados brutos primeiro, e um segundo para transformar. Isso resolve problemas de timeout ao separar ingestão de transformação.","en-us":"Best practice is to create a staging dataflow that ingests raw data first, and a second to transform. This resolves timeout issues by separating ingestion from transformation.","es":"La mejor práctica es crear un dataflow de staging que ingiere datos brutos primero, y un segundo para transformar.","fr":"La meilleure pratique est de créer un dataflow de staging qui ingère les données brutes d''abord, et un second pour transformer."}'),
('Otimizar Modelos Semânticos', '{"pt-br":"Você tem uma medida DAX: KPI Variação = IF([Variação] > 0.80, \"Incrível!\", IF([Variação] > 0.60, \"Bom\", \"Ruim\")). Precisa otimizar para calcular mais rápido.","en-us":"You have a DAX measure: Variance KPI = IF([Variance] > 0.80, \"Amazing!\", IF([Variance] > 0.60, \"Good\", \"Bad\")). You need to optimize for faster calculation.","es":"Tiene una medida DAX: KPI Variación = IF([Variación] > 0.80, \"Increíble!\", IF([Variación] > 0.60, \"Bueno\", \"Malo\")). Necesita optimizar.","fr":"Vous avez une mesure DAX : KPI Variance = IF([Variance] > 0.80, \"Incroyable!\", IF([Variance] > 0.60, \"Bon\", \"Mauvais\")). Vous devez optimiser."}', '{"pt-br":"Qual código otimizado você deve usar?","en-us":"Which optimized code should you use?","es":"¿Qué código optimizado debe usar?","fr":"Quel code optimisé devez-vous utiliser ?"}', '[{"key":"A","text":{"pt-br":"VAR Calc = [Variação] RETURN SWITCH(TRUE(), Calc > 0.80, \"Incrível!\", Calc > 0.60, \"Bom\", \"Ruim\")","en-us":"VAR Calc = [Variance] RETURN SWITCH(TRUE(), Calc > 0.80, \"Amazing!\", Calc > 0.60, \"Good\", \"Bad\")","es":"VAR Calc = [Variación] RETURN SWITCH(TRUE(), Calc > 0.80, \"Increíble!\", Calc > 0.60, \"Bueno\", \"Malo\")","fr":"VAR Calc = [Variance] RETURN SWITCH(TRUE(), Calc > 0.80, \"Incroyable!\", Calc > 0.60, \"Bon\", \"Mauvais\")"}},{"key":"B","text":{"pt-br":"IF([Variação] > 0.80, \"Incrível!\", IF([Variação] > 0.60, \"Bom\", \"Ruim\"))","en-us":"IF([Variance] > 0.80, \"Amazing!\", IF([Variance] > 0.60, \"Good\", \"Bad\"))","es":"IF([Variación] > 0.80, \"Increíble!\", IF([Variación] > 0.60, \"Bueno\", \"Malo\"))","fr":"IF([Variance] > 0.80, \"Incroyable!\", IF([Variance] > 0.60, \"Bon\", \"Mauvais\"))"}},{"key":"C","text":{"pt-br":"SWITCH([Variação], 0.80, \"Incrível!\", 0.60, \"Bom\", \"Ruim\")","en-us":"SWITCH([Variance], 0.80, \"Amazing!\", 0.60, \"Good\", \"Bad\")","es":"SWITCH([Variación], 0.80, \"Increíble!\", 0.60, \"Bueno\", \"Malo\")","fr":"SWITCH([Variance], 0.80, \"Incroyable!\", 0.60, \"Bon\", \"Mauvais\")"}},{"key":"D","text":{"pt-br":"CALCULATE(IF([Variação] > 0.80, \"Incrível!\", \"Ruim\"))","en-us":"CALCULATE(IF([Variance] > 0.80, \"Amazing!\", \"Bad\"))","es":"CALCULATE(IF([Variación] > 0.80, \"Increíble!\", \"Malo\"))","fr":"CALCULATE(IF([Variance] > 0.80, \"Incroyable!\", \"Mauvais\"))"}}]', 'A', '{"pt-br":"VAR armazena [Variação] em cache, carregando apenas uma vez. SWITCH(TRUE()) é mais legível e eficiente que IF aninhados. As outras fórmulas não usam VAR para otimizar performance.","en-us":"VAR caches [Variance], loading it only once. SWITCH(TRUE()) is more readable and efficient than nested IFs. Other formulas don''t use VAR to optimize performance.","es":"VAR almacena [Variación] en caché, cargando solo una vez. SWITCH(TRUE()) es más legible y eficiente que IFs anidados.","fr":"VAR met en cache [Variance], ne le chargeant qu''une fois. SWITCH(TRUE()) est plus lisible et efficace que des IF imbriqués."}'),
('Segurança e Governança', '{"pt-br":"Você tem um workspace do Fabric que contém um lakehouse chamado Lakehouse1. Um usuário chamado User1 planeja usar o Lakehouse para ler dados do Lakehouse1.","en-us":"You have a Fabric workspace that contains a lakehouse called Lakehouse1. A user named User1 plans to use the Lakehouse to read data from Lakehouse1.","es":"Tiene un workspace de Fabric que contiene un lakehouse llamado Lakehouse1. Un usuario llamado User1 planea usar el Lakehouse para leer datos de Lakehouse1.","fr":"Vous avez un workspace Fabric contenant un lakehouse appelé Lakehouse1. Un utilisateur nommé User1 prévoit d''utiliser le Lakehouse pour lire les données de Lakehouse1."}', '{"pt-br":"Você precisa atribuir uma função de workspace ao User1. A solução deve seguir o princípio de privilégios mínimos. Qual função de workspace você deve atribuir?","en-us":"You need to assign a workspace role to User1. The solution must follow the principle of least privilege. Which workspace role should you assign?","es":"Necesita asignar un rol de workspace a User1. La solución debe seguir el principio de privilegios mínimos. ¿Qué rol de workspace debe asignar?","fr":"Vous devez attribuer un rôle de workspace à User1. La solution doit suivre le principe du moindre privilège. Quel rôle de workspace devez-vous attribuer ?"}', '[{"key":"A","text":{"pt-br":"Administrador","en-us":"Admin","es":"Administrador","fr":"Administrateur"}},{"key":"B","text":{"pt-br":"Membro","en-us":"Member","es":"Miembro","fr":"Membre"}},{"key":"C","text":{"pt-br":"Colaborador","en-us":"Contributor","es":"Colaborador","fr":"Contributeur"}},{"key":"D","text":{"pt-br":"Visualizador","en-us":"Viewer","es":"Visor","fr":"Visionneur"}}]', 'C', '{"pt-br":"Para ler dados de um lakehouse via Explorador de Lakehouse, os usuários precisam de Admin, Membro ou Colaborador. Pelo princípio de privilégio mínimo, Colaborador é a escolha correta. Visualizador não permite ler dados pelo Explorador do Lakehouse.","en-us":"To read data from a lakehouse via Lakehouse Explorer, users need Admin, Member, or Contributor roles. Following least privilege, Contributor is the correct choice. Viewer doesn''t permit reading data through Lakehouse Explorer.","es":"Para leer datos de un lakehouse vía Explorador de Lakehouse, los usuarios necesitan Admin, Miembro o Colaborador. Siguiendo el principio de privilegio mínimo, Colaborador es la opción correcta.","fr":"Pour lire les données d''un lakehouse via l''Explorateur Lakehouse, les utilisateurs ont besoin des rôles Admin, Membre ou Contributeur. Selon le principe du moindre privilège, Contributeur est le bon choix."}'),
('Ciclo de Vida', '{"pt-br":"Você usa o Microsoft Fabric para gerenciar soluções de análise de dados e precisa configurar um pipeline de implantação que mantenha dependências de item e suporte atualização incremental.","en-us":"You use Microsoft Fabric to manage data analytics solutions and need to configure a deployment pipeline that maintains item dependencies and supports incremental refresh.","es":"Usa Microsoft Fabric para gestionar soluciones de análisis de datos y necesita configurar un pipeline de implementación que mantenga dependencias de ítems y soporte actualización incremental.","fr":"Vous utilisez Microsoft Fabric pour gérer des solutions d''analyse de données et devez configurer un pipeline de déploiement qui maintient les dépendances d''éléments et prend en charge l''actualisation incrémentielle."}', '{"pt-br":"Quais três ações são necessárias para configurar o pipeline de implantação corretamente?","en-us":"Which three actions are required to correctly configure the deployment pipeline?","es":"¿Cuáles tres acciones son necesarias para configurar correctamente el pipeline de implementación?","fr":"Quelles trois actions sont nécessaires pour configurer correctement le pipeline de déploiement ?"}', '[{"key":"A","text":{"pt-br":"Vinculação automática, atualização incremental e regras de implantação para conexões","en-us":"Auto-binding, incremental refresh, and deployment rules for connections","es":"Vinculación automática, actualización incremental y reglas de implementación para conexiones","fr":"Liaison automatique, actualisation incrémentielle et règles de déploiement pour les connexions"}},{"key":"B","text":{"pt-br":"Agenda estática, criação manual de workspaces e vinculação automática","en-us":"Static schedule, manual workspace creation, and auto-binding","es":"Agenda estática, creación manual de workspaces y vinculación automática","fr":"Planning statique, création manuelle de workspaces et liaison automatique"}},{"key":"C","text":{"pt-br":"Regras de implantação, agenda estática e criação manual de workspaces","en-us":"Deployment rules, static schedule, and manual workspace creation","es":"Reglas de implementación, agenda estática y creación manual de workspaces","fr":"Règles de déploiement, planning statique et création manuelle de workspaces"}},{"key":"D","text":{"pt-br":"Vinculação automática, agenda estática e regras de implantação","en-us":"Auto-binding, static schedule, and deployment rules","es":"Vinculación automática, agenda estática y reglas de implementación","fr":"Liaison automatique, planning statique et règles de déploiement"}}]', 'A', '{"pt-br":"Vinculação automática mantém conexões entre estágios. Atualização incremental garante consistência da política de atualização. Regras de implantação gerenciam conexões de fonte de dados entre estágios.","en-us":"Auto-binding maintains connections between stages. Incremental refresh ensures refresh policy consistency. Deployment rules manage data source connections across stages.","es":"La vinculación automática mantiene conexiones entre etapas. La actualización incremental garantiza consistencia. Las reglas de implementación gestionan conexiones de fuentes de datos.","fr":"La liaison automatique maintient les connexions entre les étapes. L''actualisation incrémentielle assure la cohérence. Les règles de déploiement gèrent les connexions sources."}'),
('Segurança e Governança', '{"pt-br":"Você tem um workspace do Fabric com um lakehouse, pipeline de dados, notebook e relatórios Power BI. User1 precisa usar SQL para acessar o lakehouse com acesso somente leitura, sem acessar outros itens e sem usar Spark.","en-us":"You have a Fabric workspace with a lakehouse, data pipeline, notebook, and Power BI reports. User1 needs SQL read-only access to the lakehouse without accessing other items or using Spark.","es":"Tiene un workspace de Fabric con lakehouse, pipeline de datos, notebook e informes Power BI. User1 necesita acceso SQL de solo lectura al lakehouse sin acceder a otros ítems ni usar Spark.","fr":"Vous avez un workspace Fabric avec un lakehouse, un pipeline de données, un notebook et des rapports Power BI. User1 a besoin d''un accès SQL en lecture seule au lakehouse sans accéder aux autres éléments ni utiliser Spark."}', '{"pt-br":"O que você deve fazer para configurar o acesso do User1?","en-us":"What should you do to configure User1''s access?","es":"¿Qué debe hacer para configurar el acceso de User1?","fr":"Que devez-vous faire pour configurer l''accès de User1 ?"}', '[{"key":"A","text":{"pt-br":"Compartilhe o lakehouse diretamente com User1 e selecione ''Ler todos os dados do Endpoint do SQL''","en-us":"Share the lakehouse directly with User1 and select ''Read all SQL Endpoint data''","es":"Comparta el lakehouse directamente con User1 y seleccione ''Leer todos los datos del Endpoint SQL''","fr":"Partagez le lakehouse directement avec User1 et sélectionnez ''Lire toutes les données du point de terminaison SQL''"}},{"key":"B","text":{"pt-br":"Adicione User1 como Visualizador no workspace","en-us":"Add User1 as a Viewer in the workspace","es":"Agregue User1 como Visor en el workspace","fr":"Ajoutez User1 en tant que Visionneur dans le workspace"}},{"key":"C","text":{"pt-br":"Compartilhe o endpoint de análise SQL diretamente","en-us":"Share the SQL analytics endpoint directly","es":"Comparta el endpoint de análisis SQL directamente","fr":"Partagez le point de terminaison SQL directement"}},{"key":"D","text":{"pt-br":"Adicione User1 como Colaborador no workspace","en-us":"Add User1 as a Contributor in the workspace","es":"Agregue User1 como Colaborador en el workspace","fr":"Ajoutez User1 en tant que Contributeur dans le workspace"}}]', 'A', '{"pt-br":"Compartilhar o lakehouse diretamente com ''Ler todos os dados do Endpoint SQL'' dá acesso somente leitura via SQL sem acesso a outros itens do workspace. Adicionar ao workspace como membro/visualizador daria acesso a todos os relatórios.","en-us":"Sharing the lakehouse directly with ''Read all SQL Endpoint data'' gives SQL read-only access without accessing other workspace items. Adding as a workspace member/viewer would give access to all reports.","es":"Compartir el lakehouse directamente con ''Leer datos del Endpoint SQL'' da acceso de solo lectura sin acceder a otros ítems del workspace.","fr":"Partager le lakehouse directement avec ''Lire les données du point de terminaison SQL'' donne un accès en lecture seule sans accéder aux autres éléments du workspace."}'),
('Segurança e Governança', '{"pt-br":"Sua empresa usa Microsoft Fabric para análise de dados. O departamento de marketing precisa compartilhar relatórios com parceiros externos sem comprometer dados confidenciais.","en-us":"Your company uses Microsoft Fabric for data analytics. The marketing department needs to share reports with external partners without compromising sensitive data.","es":"Su empresa usa Microsoft Fabric para análisis de datos. El departamento de marketing necesita compartir informes con socios externos sin comprometer datos confidenciales.","fr":"Votre entreprise utilise Microsoft Fabric pour l''analyse de données. Le département marketing doit partager des rapports avec des partenaires externes sans compromettre les données sensibles."}', '{"pt-br":"Quais três ações você deve executar para compartilhar relatórios de forma segura com parceiros externos?","en-us":"Which three actions should you perform to securely share reports with external partners?","es":"¿Cuáles tres acciones debe ejecutar para compartir informes de forma segura con socios externos?","fr":"Quelles trois actions devez-vous effectuer pour partager des rapports de manière sécurisée avec des partenaires externes ?"}', '[{"key":"A","text":{"pt-br":"Implementar RLS, definir identidade fixa nas credenciais e configurar um aplicativo do Power BI","en-us":"Implement RLS, set fixed identity credentials, and configure a Power BI app","es":"Implementar RLS, definir identidad fija en credenciales y configurar un app de Power BI","fr":"Implémenter RLS, définir une identité fixe dans les identifiants et configurer une application Power BI"}},{"key":"B","text":{"pt-br":"Restringir compartilhamento do workspace, implementar RLS e compartilhar por email","en-us":"Restrict workspace sharing, implement RLS, and share via email","es":"Restringir compartir del workspace, implementar RLS y compartir por email","fr":"Restreindre le partage du workspace, implémenter RLS et partager par email"}},{"key":"C","text":{"pt-br":"Implementar RLS, compartilhar por email e atribuir função de visualizador","en-us":"Implement RLS, share via email, and assign viewer role","es":"Implementar RLS, compartir por email y asignar rol de visor","fr":"Implémenter RLS, partager par email et attribuer le rôle de visionneur"}},{"key":"D","text":{"pt-br":"Definir identidade fixa, restringir compartilhamento e compartilhar por email","en-us":"Set fixed identity, restrict sharing, and share via email","es":"Definir identidad fija, restringir compartir y compartir por email","fr":"Définir une identité fixe, restreindre le partage et partager par email"}}]', 'A', '{"pt-br":"RLS controla visibilidade de dados por identidade do usuário. Identidade fixa garante acesso adequado para parceiros externos. Aplicativos Power BI permitem compartilhamento seguro. Compartilhar por email pode causar vazamento de dados.","en-us":"RLS controls data visibility by user identity. Fixed identity ensures proper external partner access. Power BI apps enable secure sharing. Email sharing may cause data leaks.","es":"RLS controla visibilidad de datos por identidad de usuario. Identidad fija garantiza acceso adecuado para socios externos. Aplicaciones Power BI permiten compartir de forma segura.","fr":"RLS contrôle la visibilité des données par identité utilisateur. L''identité fixe garantit un accès approprié aux partenaires externes. Les applications Power BI permettent un partage sécurisé."}'),
('Segurança e Governança', '{"pt-br":"Sua organização usa Microsoft Fabric para gerenciar um data warehouse com dados confidenciais. Você precisa implementar medidas de segurança para limitar o acesso a determinados elementos de dados sem afetar a camada do aplicativo.","en-us":"Your organization uses Microsoft Fabric to manage a data warehouse with sensitive data. You need to implement security measures to limit access to certain data elements without affecting the application layer.","es":"Su organización usa Microsoft Fabric para gestionar un data warehouse con datos confidenciales. Necesita implementar medidas de seguridad para limitar el acceso a ciertos elementos de datos sin afectar la capa de aplicación.","fr":"Votre organisation utilise Microsoft Fabric pour gérer un data warehouse avec des données sensibles. Vous devez implémenter des mesures de sécurité pour limiter l''accès à certains éléments de données sans affecter la couche application."}', '{"pt-br":"Quais três ações você deve executar para proteger os dados granularmente?","en-us":"Which three actions should you perform to protect data granularly?","es":"¿Cuáles tres acciones debe ejecutar para proteger los datos de forma granular?","fr":"Quelles trois actions devez-vous effectuer pour protéger les données de manière granulaire ?"}', '[{"key":"A","text":{"pt-br":"Segurança em nível de coluna, segurança em nível de linha e máscara dinâmica de dados","en-us":"Column-level security, row-level security, and dynamic data masking","es":"Seguridad a nivel de columna, seguridad a nivel de fila y máscara dinámica de datos","fr":"Sécurité au niveau des colonnes, sécurité au niveau des lignes et masquage dynamique des données"}},{"key":"B","text":{"pt-br":"Funções de workspace, permissões de item e segurança em nível de linha","en-us":"Workspace roles, item permissions, and row-level security","es":"Roles de workspace, permisos de ítem y seguridad a nivel de fila","fr":"Rôles de workspace, autorisations d''éléments et sécurité au niveau des lignes"}},{"key":"C","text":{"pt-br":"Segurança em nível de coluna, permissões de item e funções de workspace","en-us":"Column-level security, item permissions, and workspace roles","es":"Seguridad a nivel de columna, permisos de ítem y roles de workspace","fr":"Sécurité au niveau des colonnes, autorisations d''éléments et rôles de workspace"}},{"key":"D","text":{"pt-br":"Máscara dinâmica de dados, funções de workspace e permissões de item","en-us":"Dynamic data masking, workspace roles, and item permissions","es":"Máscara dinámica de datos, roles de workspace y permisos de ítem","fr":"Masquage dynamique des données, rôles de workspace et autorisations d''éléments"}}]', 'A', '{"pt-br":"CLS limita acesso a colunas específicas. RLS garante que usuários vejam apenas linhas autorizadas. Mascaramento dinâmico oculta dados sensíveis nos resultados sem alterar dados reais. Funções de workspace e permissões de item não oferecem granularidade suficiente.","en-us":"CLS limits access to specific columns. RLS ensures users see only authorized rows. Dynamic masking hides sensitive data in results without altering actual data. Workspace roles and item permissions don''t provide sufficient granularity.","es":"CLS limita acceso a columnas específicas. RLS garantiza que los usuarios vean solo filas autorizadas. El mascaramiento dinámico oculta datos sensibles sin alterar los datos reales.","fr":"CLS limite l''accès aux colonnes spécifiques. RLS garantit que les utilisateurs ne voient que les lignes autorisées. Le masquage dynamique cache les données sensibles sans modifier les données réelles."}'),
('Segurança e Governança', '{"pt-br":"Sua empresa usa Microsoft Fabric para análise de dados e precisa garantir que somente usuários específicos possam acessar determinados dados de relatório com base em suas funções.","en-us":"Your company uses Microsoft Fabric for data analytics and needs to ensure only specific users can access certain report data based on their roles.","es":"Su empresa usa Microsoft Fabric para análisis de datos y necesita garantizar que solo usuarios específicos puedan acceder a ciertos datos de informes según sus roles.","fr":"Votre entreprise utilise Microsoft Fabric pour l''analyse de données et doit s''assurer que seuls des utilisateurs spécifiques peuvent accéder à certaines données de rapport en fonction de leurs rôles."}', '{"pt-br":"O que você deve configurar para controlar o acesso aos dados no relatório?","en-us":"What should you configure to control access to report data?","es":"¿Qué debe configurar para controlar el acceso a los datos del informe?","fr":"Que devez-vous configurer pour contrôler l''accès aux données du rapport ?"}', '[{"key":"A","text":{"pt-br":"Segurança em nível de linha (RLS)","en-us":"Row-level security (RLS)","es":"Seguridad a nivel de fila (RLS)","fr":"Sécurité au niveau des lignes (RLS)"}},{"key":"B","text":{"pt-br":"Funções de workspace","en-us":"Workspace roles","es":"Roles de workspace","fr":"Rôles de workspace"}},{"key":"C","text":{"pt-br":"Rótulos de confidencialidade","en-us":"Sensitivity labels","es":"Etiquetas de confidencialidad","fr":"Étiquettes de confidentialité"}},{"key":"D","text":{"pt-br":"Azure Active Directory B2C","en-us":"Azure Active Directory B2C","es":"Azure Active Directory B2C","fr":"Azure Active Directory B2C"}}]', 'A', '{"pt-br":"RLS garante que somente usuários autorizados vejam dados específicos nos relatórios. Funções de workspace não oferecem granularidade por linha. Rótulos de confidencialidade são para conformidade, não controle de acesso a dados. Azure AD B2C é para identidade externa.","en-us":"RLS ensures only authorized users see specific report data. Workspace roles don''t provide row-level granularity. Sensitivity labels are for compliance, not data access control. Azure AD B2C is for external identity management.","es":"RLS garantiza que solo usuarios autorizados vean datos específicos. Los roles de workspace no ofrecen granularidad por fila.","fr":"RLS garantit que seuls les utilisateurs autorisés voient des données spécifiques. Les rôles de workspace n''offrent pas de granularité au niveau des lignes."}'),
('Ciclo de Vida', '{"pt-br":"Você usa o Power BI Desktop para criar um modelo semântico e precisa colaborar com outro modelador, trabalhando em diferentes partes do modelo simultaneamente.","en-us":"You use Power BI Desktop to create a semantic model and need to collaborate with another modeler, working on different parts of the model simultaneously.","es":"Usa Power BI Desktop para crear un modelo semántico y necesita colaborar con otro modelador, trabajando en diferentes partes del modelo simultáneamente.","fr":"Vous utilisez Power BI Desktop pour créer un modèle sémantique et devez collaborer avec un autre modélisateur, en travaillant simultanément sur différentes parties du modèle."}', '{"pt-br":"O que você deve recomendar para colaboração eficiente?","en-us":"What should you recommend for efficient collaboration?","es":"¿Qué debe recomendar para una colaboración eficiente?","fr":"Que devez-vous recommander pour une collaboration efficace ?"}', '[{"key":"A","text":{"pt-br":"Salvar como PBIP e inicializar repositório Git com controle de versão","en-us":"Save as PBIP and initialize a Git repository with version control","es":"Guardar como PBIP e inicializar repositorio Git con control de versiones","fr":"Enregistrer en PBIP et initialiser un dépôt Git avec contrôle de version"}},{"key":"B","text":{"pt-br":"Enviar o arquivo PBIX por email entre os desenvolvedores","en-us":"Email the PBIX file between developers","es":"Enviar el archivo PBIX por email entre los desarrolladores","fr":"Envoyer le fichier PBIX par email entre les développeurs"}},{"key":"C","text":{"pt-br":"Salvar o PBIX no OneDrive compartilhado","en-us":"Save the PBIX to a shared OneDrive","es":"Guardar el PBIX en OneDrive compartido","fr":"Enregistrer le PBIX sur un OneDrive partagé"}},{"key":"D","text":{"pt-br":"Publicar o PBIX em um workspace compartilhado","en-us":"Publish the PBIX to a shared workspace","es":"Publicar el PBIX en un workspace compartido","fr":"Publier le PBIX dans un workspace partagé"}}]', 'A', '{"pt-br":"PBIP salva como arquivos de texto em estrutura de pastas, compatível com controle de código-fonte (Git), permitindo que múltiplos desenvolvedores trabalhem simultaneamente. PBIX no OneDrive permite apenas um usuário por vez. Email não é eficiente.","en-us":"PBIP saves as text files in a folder structure, compatible with source control (Git), allowing multiple developers to work simultaneously. PBIX on OneDrive only allows one user at a time.","es":"PBIP guarda como archivos de texto en estructura de carpetas, compatible con control de código fuente (Git), permitiendo que múltiples desarrolladores trabajen simultáneamente.","fr":"PBIP enregistre sous forme de fichiers texte dans une structure de dossiers, compatible avec le contrôle de source (Git), permettant à plusieurs développeurs de travailler simultanément."}'),
('Ciclo de Vida', '{"pt-br":"Você tem um modelo semântico sincronizado por pipelines de implantação do Fabric para workspaces de Desenvolvimento, Teste e Produção. O modelo extrai dados de um banco de dados SQL do Azure.","en-us":"You have a semantic model synced through Fabric deployment pipelines to Development, Test, and Production workspaces. The model pulls data from an Azure SQL Database.","es":"Tiene un modelo semántico sincronizado por pipelines de implementación de Fabric para workspaces de Desarrollo, Prueba y Producción. El modelo extrae datos de Azure SQL Database.","fr":"Vous avez un modèle sémantique synchronisé via des pipelines de déploiement Fabric vers les workspaces Développement, Test et Production. Le modèle extrait des données d''une base Azure SQL."}', '{"pt-br":"Você precisa reduzir o tamanho das consultas enviadas ao banco de dados nos workspaces de desenvolvimento e teste. O que você deve fazer?","en-us":"You need to reduce the size of queries sent to the database in development and test workspaces. What should you do?","es":"Necesita reducir el tamaño de las consultas enviadas a la base de datos en los workspaces de desarrollo y prueba. ¿Qué debe hacer?","fr":"Vous devez réduire la taille des requêtes envoyées à la base de données dans les workspaces de développement et de test. Que devez-vous faire ?"}', '[{"key":"A","text":{"pt-br":"Adicionar uma regra de parâmetro de implantação para filtrar os dados","en-us":"Add a deployment parameter rule to filter the data","es":"Agregar una regla de parámetro de implementación para filtrar los datos","fr":"Ajouter une règle de paramètre de déploiement pour filtrer les données"}},{"key":"B","text":{"pt-br":"Habilitar política de atualização incremental","en-us":"Enable incremental refresh policy","es":"Habilitar política de actualización incremental","fr":"Activer la politique d''actualisation incrémentielle"}},{"key":"C","text":{"pt-br":"Habilitar modo DirectQuery","en-us":"Enable DirectQuery mode","es":"Habilitar modo DirectQuery","fr":"Activer le mode DirectQuery"}},{"key":"D","text":{"pt-br":"Configurar regras de conexão de fonte de dados","en-us":"Configure data source connection rules","es":"Configurar reglas de conexión de fuente de datos","fr":"Configurer les règles de connexion de source de données"}}]', 'A', '{"pt-br":"Parâmetros de consulta permitem filtrar dados por categoria ou data, controlando a quantidade de dados extraídos entre workspaces de Dev, Teste e Produção. As outras opções não alteram quais dados são extraídos.","en-us":"Query parameters allow filtering data by category or date, controlling the amount of data pulled across Dev, Test, and Production workspaces. Other options don''t change what data is pulled.","es":"Los parámetros de consulta permiten filtrar datos por categoría o fecha, controlando la cantidad de datos extraídos entre workspaces.","fr":"Les paramètres de requête permettent de filtrer les données par catégorie ou date, contrôlant la quantité de données extraites entre les workspaces."}'),
('Ciclo de Vida', '{"pt-br":"Você tem um locatário do Fabric com endpoint XMLA configurado como Leitura/Gravação. Você precisa usar o endpoint XMLA para implantar alterações em apenas uma tabela do modelo.","en-us":"You have a Fabric tenant with the XMLA endpoint set to Read/Write. You need to use the XMLA endpoint to deploy changes to only one table in the model.","es":"Tiene un tenant de Fabric con el endpoint XMLA configurado como Lectura/Escritura. Necesita usar el endpoint XMLA para implementar cambios en solo una tabla del modelo.","fr":"Vous avez un tenant Fabric avec le point de terminaison XMLA configuré en Lecture/Écriture. Vous devez utiliser le point de terminaison XMLA pour déployer des modifications sur une seule table du modèle."}', '{"pt-br":"Qual é a principal limitação do uso de endpoints XMLA no processo de implantação?","en-us":"What is the main limitation of using XMLA endpoints in the deployment process?","es":"¿Cuál es la principal limitación del uso de endpoints XMLA en el proceso de implementación?","fr":"Quelle est la principale limitation de l''utilisation des points de terminaison XMLA dans le processus de déploiement ?"}', '[{"key":"A","text":{"pt-br":"Um arquivo PBIX não pode ser baixado do serviço do Power BI","en-us":"A PBIX file cannot be downloaded from the Power BI service","es":"Un archivo PBIX no se puede descargar del servicio de Power BI","fr":"Un fichier PBIX ne peut pas être téléchargé depuis le service Power BI"}},{"key":"B","text":{"pt-br":"O particionamento de tabela é impossível","en-us":"Table partitioning is impossible","es":"La partición de tablas es imposible","fr":"Le partitionnement des tables est impossible"}},{"key":"C","text":{"pt-br":"Parâmetros não podem ser usados","en-us":"Parameters cannot be used","es":"Los parámetros no pueden ser usados","fr":"Les paramètres ne peuvent pas être utilisés"}},{"key":"D","text":{"pt-br":"Apenas uma tabela pode ser alterada por vez","en-us":"Only one table can be changed at a time","es":"Solo una tabla puede ser alterada a la vez","fr":"Une seule table peut être modifiée à la fois"}}]', 'A', '{"pt-br":"Quando o modelo é alterado via endpoints XMLA, o arquivo PBIX não pode mais ser baixado do serviço. Particionamento de tabela e parâmetros ainda são suportados.","en-us":"When the model is changed via XMLA endpoints, the PBIX file can no longer be downloaded from the service. Table partitioning and parameters are still supported.","es":"Cuando el modelo se altera vía endpoints XMLA, el archivo PBIX ya no puede descargarse del servicio. La partición de tablas y los parámetros aún son soportados.","fr":"Lorsque le modèle est modifié via les points de terminaison XMLA, le fichier PBIX ne peut plus être téléchargé. Le partitionnement et les paramètres sont toujours pris en charge."}'),
('Obter Dados', '{"pt-br":"Você tem um pipeline de dados com uma tabela de fatos contendo dados de clientes e duas tabelas de dimensão (clientes com CustomerID e calendário com DateID). Você precisa garantir que os dados de cada cliente estejam em seu próprio arquivo Parquet.","en-us":"You have a data pipeline with a fact table containing customer data and two dimension tables. You need to ensure each customer''s data is in its own Parquet file.","es":"Tiene un pipeline de datos con una tabla de hechos que contiene datos de clientes y dos tablas de dimensión. Necesita garantizar que los datos de cada cliente estén en su propio archivo Parquet.","fr":"Vous avez un pipeline de données avec une table de faits contenant des données clients et deux tables de dimension. Vous devez vous assurer que les données de chaque client sont dans leur propre fichier Parquet."}', '{"pt-br":"Qual configuração de pipeline de dados você deve implementar?","en-us":"Which data pipeline configuration should you implement?","es":"¿Qué configuración de pipeline de datos debe implementar?","fr":"Quelle configuration de pipeline de données devez-vous implémenter ?"}', '[{"key":"A","text":{"pt-br":"Partição por ID do cliente na tabela de fatos","en-us":"Partition by Customer ID in the fact table","es":"Partición por ID del cliente en la tabla de hechos","fr":"Partitionnement par ID client dans la table de faits"}},{"key":"B","text":{"pt-br":"Partição por ID de Data na tabela de fatos","en-us":"Partition by Date ID in the fact table","es":"Partición por ID de Fecha en la tabla de hechos","fr":"Partitionnement par ID de date dans la table de faits"}},{"key":"C","text":{"pt-br":"Partição por ID do cliente na tabela de dimensão","en-us":"Partition by Customer ID in the dimension table","es":"Partición por ID del cliente en la tabla de dimensión","fr":"Partitionnement par ID client dans la table de dimension"}},{"key":"D","text":{"pt-br":"Criar um pipeline separado para cada cliente","en-us":"Create a separate pipeline for each customer","es":"Crear un pipeline separado para cada cliente","fr":"Créer un pipeline séparé pour chaque client"}}]', 'A', '{"pt-br":"O particionamento determina a estrutura dos arquivos Parquet. Particionar a tabela de fatos pelo CustomerID gera um arquivo por cliente.","en-us":"Partitioning determines the Parquet file structure. Partitioning the fact table by CustomerID generates one file per customer.","es":"La partición determina la estructura de los archivos Parquet. Particionar la tabla de hechos por CustomerID genera un archivo por cliente.","fr":"Le partitionnement détermine la structure des fichiers Parquet. Partitionner la table de faits par CustomerID génère un fichier par client."}'),
('Obter Dados', '{"pt-br":"Você tem um pipeline de dados Pipeline1 e precisa enviar um email via Outlook quando houver problemas com conectores, minimizando o número de emails enviados.","en-us":"You have a data pipeline Pipeline1 and need to send an email via Outlook when there are connector issues, minimizing the number of emails sent.","es":"Tiene un pipeline de datos Pipeline1 y necesita enviar un email vía Outlook cuando haya problemas con conectores, minimizando el número de emails enviados.","fr":"Vous avez un pipeline de données Pipeline1 et devez envoyer un email via Outlook en cas de problème de connecteur, en minimisant le nombre d''emails envoyés."}', '{"pt-br":"Qual ação de atividade deve ser conectada à atividade do Outlook?","en-us":"Which activity action should be connected to the Outlook activity?","es":"¿Qué acción de actividad debe conectarse a la actividad de Outlook?","fr":"Quelle action d''activité doit être connectée à l''activité Outlook ?"}', '[{"key":"A","text":{"pt-br":"Em caso de falha","en-us":"On failure","es":"En caso de fallo","fr":"En cas d''échec"}},{"key":"B","text":{"pt-br":"Na conclusão","en-us":"On completion","es":"Al completar","fr":"À la fin"}},{"key":"C","text":{"pt-br":"Em caso de sucesso","en-us":"On success","es":"En caso de éxito","fr":"En cas de succès"}},{"key":"D","text":{"pt-br":"Em caso de ignorar","en-us":"On skip","es":"En caso de omitir","fr":"En cas de saut"}}]', 'A', '{"pt-br":"''Em caso de falha'' envia notificação apenas quando há problema causado por falha de atividade. As outras opções notificariam incorretamente ou todas as vezes.","en-us":"''On failure'' sends notification only when there''s a problem caused by activity failure. Other options would notify incorrectly or every time.","es":"''En caso de fallo'' envía notificación solo cuando hay un problema. Las otras opciones notificarían incorrectamente.","fr":"''En cas d''échec'' n''envoie une notification que lorsqu''il y a un problème. Les autres options notifieraient incorrectement."}'),
('Obter Dados', '{"pt-br":"Você tem um pipeline Pipeline1 na região Oeste dos EUA. Precisa que ele execute à meia-noite no fuso horário UTC-0.","en-us":"You have a pipeline Pipeline1 in the US West region. You need it to run at midnight in the UTC-0 timezone.","es":"Tiene un pipeline Pipeline1 en la región Oeste de EE.UU. Necesita que se ejecute a medianoche en la zona horaria UTC-0.","fr":"Vous avez un pipeline Pipeline1 dans la région US West. Vous devez qu''il s''exécute à minuit dans le fuseau horaire UTC-0."}', '{"pt-br":"Como você deve configurar o agendamento?","en-us":"How should you configure the schedule?","es":"¿Cómo debe configurar la programación?","fr":"Comment devez-vous configurer la planification ?"}', '[{"key":"A","text":{"pt-br":"Definir o fuso horário do agendador do Pipeline1 como UTC-0","en-us":"Set Pipeline1''s scheduler timezone to UTC-0","es":"Definir la zona horaria del programador de Pipeline1 como UTC-0","fr":"Définir le fuseau horaire du planificateur de Pipeline1 sur UTC-0"}},{"key":"B","text":{"pt-br":"Alterar o fuso horário do workspace para UTC-0","en-us":"Change the workspace timezone to UTC-0","es":"Cambiar la zona horaria del workspace a UTC-0","fr":"Changer le fuseau horaire du workspace en UTC-0"}},{"key":"C","text":{"pt-br":"Configurar o fuso da capacidade do Fabric","en-us":"Configure the Fabric capacity timezone","es":"Configurar la zona horaria de la capacidad de Fabric","fr":"Configurer le fuseau horaire de la capacité Fabric"}},{"key":"D","text":{"pt-br":"Usar a região do Azure como referência de fuso horário","en-us":"Use the Azure region as the timezone reference","es":"Usar la región de Azure como referencia de zona horaria","fr":"Utiliser la région Azure comme référence de fuseau horaire"}}]', 'A', '{"pt-br":"O pipeline de dados tem sua própria configuração de fuso horário que se aplica somente a ele. É ali que você configura UTC-0.","en-us":"The data pipeline has its own timezone setting that applies only to it. That''s where you configure UTC-0.","es":"El pipeline de datos tiene su propia configuración de zona horaria que solo se aplica a él.","fr":"Le pipeline de données a sa propre configuration de fuseau horaire qui ne s''applique qu''à lui."}'),
('Obter Dados', '{"pt-br":"Você tem um lakehouse e precisa criar um pipeline de dados para ingerir dados usando a atividade Copiar dados.","en-us":"You have a lakehouse and need to create a data pipeline to ingest data using the Copy Data activity.","es":"Tiene un lakehouse y necesita crear un pipeline de datos para ingerir datos usando la actividad Copiar datos.","fr":"Vous avez un lakehouse et devez créer un pipeline de données pour ingérer des données avec l''activité Copier les données."}', '{"pt-br":"Quais propriedades na guia Geral são obrigatórias para a atividade Copiar dados?","en-us":"Which properties on the General tab are mandatory for the Copy Data activity?","es":"¿Qué propiedades en la pestaña General son obligatorias para la actividad Copiar datos?","fr":"Quelles propriétés de l''onglet Général sont obligatoires pour l''activité Copier les données ?"}', '[{"key":"A","text":{"pt-br":"Apenas nome","en-us":"Name only","es":"Solo nombre","fr":"Nom uniquement"}},{"key":"B","text":{"pt-br":"Nome e descrição","en-us":"Name and description","es":"Nombre y descripción","fr":"Nom et description"}},{"key":"C","text":{"pt-br":"Nome, descrição e timeout","en-us":"Name, description, and timeout","es":"Nombre, descripción y timeout","fr":"Nom, description et timeout"}},{"key":"D","text":{"pt-br":"Nome e timeout","en-us":"Name and timeout","es":"Nombre y timeout","fr":"Nom et timeout"}}]', 'A', '{"pt-br":"Na atividade Copiar dados, somente o nome é obrigatório na guia Geral. Todas as outras propriedades são opcionais.","en-us":"In the Copy Data activity, only the name is required on the General tab. All other properties are optional.","es":"En la actividad Copiar datos, solo el nombre es obligatorio en la pestaña General.","fr":"Dans l''activité Copier les données, seul le nom est obligatoire dans l''onglet Général."}'),
('Obter Dados', '{"pt-br":"Você tem um grande conjunto de dados de 1 TB em uma fonte externa. Precisa ingerir no Lakehouse com a maior taxa de transferência e opção low-code/no-code.","en-us":"You have a 1 TB dataset from an external source. You need to ingest it into the Lakehouse with the highest throughput and a low-code/no-code option.","es":"Tiene un dataset de 1 TB de una fuente externa. Necesita ingerirlo en el Lakehouse con la mayor tasa de transferencia y opción low-code/no-code.","fr":"Vous avez un dataset de 1 To provenant d''une source externe. Vous devez l''ingérer dans le Lakehouse avec le débit le plus élevé et une option low-code/no-code."}', '{"pt-br":"O que você deve recomendar?","en-us":"What should you recommend?","es":"¿Qué debe recomendar?","fr":"Que devez-vous recommander ?"}', '[{"key":"A","text":{"pt-br":"Atividade Copiar dados de um pipeline","en-us":"Copy Data activity from a pipeline","es":"Actividad Copiar datos de un pipeline","fr":"Activité Copier les données d''un pipeline"}},{"key":"B","text":{"pt-br":"Dataflow Gen2","en-us":"Dataflow Gen2","es":"Dataflow Gen2","fr":"Dataflow Gen2"}},{"key":"C","text":{"pt-br":"Notebook Spark","en-us":"Spark Notebook","es":"Notebook Spark","fr":"Notebook Spark"}},{"key":"D","text":{"pt-br":"Upload manual de arquivos","en-us":"Manual file upload","es":"Carga manual de archivos","fr":"Téléchargement manuel de fichiers"}}]', 'A', '{"pt-br":"A atividade Copiar dados oferece o melhor desempenho para grandes volumes de dados e é low-code. Dataflow Gen2 é para dados menores. Notebooks exigem codificação.","en-us":"Copy Data activity provides the best performance for large data volumes and is low-code. Dataflow Gen2 is for smaller data. Notebooks require coding.","es":"La actividad Copiar datos ofrece el mejor rendimiento para grandes volúmenes y es low-code.","fr":"L''activité Copier les données offre les meilleures performances pour de grands volumes et est low-code."}'),
('Transformar Dados', '{"pt-br":"Você tem um lakehouse do Fabric com uma tabela Delta chamada Produto. Você carrega os dados em um DataFrame com: df = spark.sql(\"SELECT * FROM Produto\").","en-us":"You have a Fabric lakehouse with a Delta table called Product. You load data into a DataFrame with: df = spark.sql(\"SELECT * FROM Product\").","es":"Tiene un lakehouse de Fabric con una tabla Delta llamada Producto. Carga los datos en un DataFrame con: df = spark.sql(\"SELECT * FROM Producto\").","fr":"Vous avez un lakehouse Fabric avec une table Delta appelée Produit. Vous chargez les données dans un DataFrame avec : df = spark.sql(\"SELECT * FROM Produit\")."}', '{"pt-br":"Qual comando PySpark você deve executar para exibir as 100 primeiras linhas?","en-us":"Which PySpark command should you run to display the first 100 rows?","es":"¿Qué comando PySpark debe ejecutar para mostrar las primeras 100 filas?","fr":"Quelle commande PySpark devez-vous exécuter pour afficher les 100 premières lignes ?"}', '[{"key":"A","text":{"pt-br":"display(df.limit(100))","en-us":"display(df.limit(100))","es":"display(df.limit(100))","fr":"display(df.limit(100))"}},{"key":"B","text":{"pt-br":"df.show(100)","en-us":"df.show(100)","es":"df.show(100)","fr":"df.show(100)"}},{"key":"C","text":{"pt-br":"df.head(100)","en-us":"df.head(100)","es":"df.head(100)","fr":"df.head(100)"}},{"key":"D","text":{"pt-br":"df.take(100)","en-us":"df.take(100)","es":"df.take(100)","fr":"df.take(100)"}}]', 'A', '{"pt-br":"display(df.limit(100)) é o método recomendado em notebooks Fabric para exibir dados formatados. df.show() exibe no console sem formatação rica.","en-us":"display(df.limit(100)) is the recommended method in Fabric notebooks for formatted data display. df.show() displays in console without rich formatting.","es":"display(df.limit(100)) es el método recomendado en notebooks Fabric para mostrar datos formateados.","fr":"display(df.limit(100)) est la méthode recommandée dans les notebooks Fabric pour afficher les données formatées."}'),
('Projetar Modelos Semânticos', '{"pt-br":"Você está projetando um modelo semântico no Power BI e tem tabelas de dimensão normalizadas (snowflaked) que precisam ser implementadas em um esquema estrela.","en-us":"You are designing a semantic model in Power BI and have normalized (snowflaked) dimension tables that need to be implemented in a star schema.","es":"Está diseñando un modelo semántico en Power BI y tiene tablas de dimensión normalizadas (snowflaked) que necesitan implementarse en un esquema estrela.","fr":"Vous concevez un modèle sémantique dans Power BI et avez des tables de dimension normalisées (snowflaked) devant être implémentées en schéma étoile."}', '{"pt-br":"O que você deve fazer com as tabelas de dimensão snowflaked?","en-us":"What should you do with the snowflaked dimension tables?","es":"¿Qué debe hacer con las tablas de dimensión snowflaked?","fr":"Que devez-vous faire avec les tables de dimension snowflaked ?"}', '[{"key":"A","text":{"pt-br":"Desnormalizar as tabelas em uma única tabela de dimensão","en-us":"Denormalize the tables into a single dimension table","es":"Desnormalizar las tablas en una sola tabla de dimensión","fr":"Dénormaliser les tables en une seule table de dimension"}},{"key":"B","text":{"pt-br":"Manter as tabelas normalizadas para performance","en-us":"Keep the tables normalized for performance","es":"Mantener las tablas normalizadas para rendimiento","fr":"Garder les tables normalisées pour la performance"}},{"key":"C","text":{"pt-br":"Criar uma tabela ponte entre as dimensões","en-us":"Create a bridge table between dimensions","es":"Crear una tabla puente entre dimensiones","fr":"Créer une table pont entre les dimensions"}},{"key":"D","text":{"pt-br":"Usar DirectQuery para as tabelas snowflaked","en-us":"Use DirectQuery for the snowflaked tables","es":"Usar DirectQuery para las tablas snowflaked","fr":"Utiliser DirectQuery pour les tables snowflaked"}}]', 'A', '{"pt-br":"Uma dimensão Snowflake é um conjunto de tabelas normalizadas. Para implementar um esquema estrela adequado, é necessário desnormalizar as tabelas em uma única tabela de dimensão com todos os atributos.","en-us":"A Snowflake dimension is a set of normalized tables. To implement a proper star schema, you need to denormalize them into a single dimension table with all attributes.","es":"Una dimensión Snowflake es un conjunto de tablas normalizadas. Para implementar un esquema estrela, se deben desnormalizar en una sola tabla de dimensión.","fr":"Une dimension Snowflake est un ensemble de tables normalisées. Pour implémenter un schéma étoile, il faut les dénormaliser en une seule table de dimension."}'),
('Transformar Dados', '{"pt-br":"Você tem tabelas Employee (EmployeeID, EmployeeName, EmployeePosition) e Contract (EmployeeID, ContractType). Precisa desnormalizar e incluir ContractType, preservando todas as linhas de Employee.","en-us":"You have Employee (EmployeeID, EmployeeName, EmployeePosition) and Contract (EmployeeID, ContractType) tables. You need to denormalize and include ContractType, preserving all Employee rows.","es":"Tiene tablas Employee y Contract. Necesita desnormalizar e incluir ContractType, preservando todas las filas de Employee.","fr":"Vous avez des tables Employee et Contract. Vous devez dénormaliser et inclure ContractType, en préservant toutes les lignes Employee."}', '{"pt-br":"Qual tipo de junção no Power Query você deve usar?","en-us":"Which join type in Power Query should you use?","es":"¿Qué tipo de unión en Power Query debe usar?","fr":"Quel type de jointure dans Power Query devez-vous utiliser ?"}', '[{"key":"A","text":{"pt-br":"Junção externa esquerda","en-us":"Left outer join","es":"Unión externa izquierda","fr":"Jointure externe gauche"}},{"key":"B","text":{"pt-br":"Antijunção esquerda","en-us":"Left anti join","es":"Anti unión izquierda","fr":"Anti-jointure gauche"}},{"key":"C","text":{"pt-br":"Junção interna","en-us":"Inner join","es":"Unión interna","fr":"Jointure interne"}},{"key":"D","text":{"pt-br":"Junção cruzada","en-us":"Cross join","es":"Unión cruzada","fr":"Jointure croisée"}}]', 'A', '{"pt-br":"A junção externa esquerda mantém todas as linhas da tabela esquerda (Employee) e traz as linhas correspondentes da direita (Contract). Antijunção exclui correspondências. Junção interna retorna só correspondências. Junção cruzada retorna produto cartesiano.","en-us":"Left outer join keeps all rows from the left table (Employee) and brings matching rows from the right (Contract). Anti join excludes matches. Inner join returns only matches. Cross join returns cartesian product.","es":"La unión externa izquierda mantiene todas las filas de la tabla izquierda y trae las correspondientes de la derecha.","fr":"La jointure externe gauche conserve toutes les lignes de la table gauche et apporte les correspondances de la droite."}'),
('Transformar Dados', '{"pt-br":"Você tem um warehouse do Fabric com tabelas Product e ProductCategory (ambas com ProductCategoryKey). Precisa mesclar em uma tabela Product combinada usando Dataflow Gen2, mantendo todas as linhas de Product.","en-us":"You have a Fabric warehouse with Product and ProductCategory tables (both with ProductCategoryKey). You need to merge into a combined Product table using Dataflow Gen2, keeping all Product rows.","es":"Tiene un warehouse de Fabric con tablas Product y ProductCategory. Necesita fusionar en una tabla combinada manteniendo todas las filas de Product.","fr":"Vous avez un warehouse Fabric avec des tables Product et ProductCategory. Vous devez fusionner en une table combinée en conservant toutes les lignes Product."}', '{"pt-br":"Qual configuração de junção você deve usar?","en-us":"Which join configuration should you use?","es":"¿Qué configuración de unión debe usar?","fr":"Quelle configuration de jointure devez-vous utiliser ?"}', '[{"key":"A","text":{"pt-br":"Junção externa esquerda de Product para ProductCategory","en-us":"Left outer join from Product to ProductCategory","es":"Unión externa izquierda de Product a ProductCategory","fr":"Jointure externe gauche de Product vers ProductCategory"}},{"key":"B","text":{"pt-br":"Junção externa esquerda de ProductCategory para Product","en-us":"Left outer join from ProductCategory to Product","es":"Unión externa izquierda de ProductCategory a Product","fr":"Jointure externe gauche de ProductCategory vers Product"}},{"key":"C","text":{"pt-br":"Antijunção esquerda de Product para ProductCategory","en-us":"Left anti join from Product to ProductCategory","es":"Anti unión izquierda de Product a ProductCategory","fr":"Anti-jointure gauche de Product vers ProductCategory"}},{"key":"D","text":{"pt-br":"Junção interna de Product para ProductCategory","en-us":"Inner join from Product to ProductCategory","es":"Unión interna de Product a ProductCategory","fr":"Jointure interne de Product vers ProductCategory"}}]', 'A', '{"pt-br":"A junção externa esquerda de Product para ProductCategory mantém todas as linhas do Product e traz apenas as correspondentes de ProductCategory. A direção da junção importa.","en-us":"Left outer join from Product to ProductCategory keeps all Product rows and brings only matching ProductCategory rows. Join direction matters.","es":"La unión externa izquierda de Product a ProductCategory mantiene todas las filas de Product y trae solo las correspondientes.","fr":"La jointure externe gauche de Product vers ProductCategory conserve toutes les lignes Product et apporte uniquement les correspondances."}'),
('Transformar Dados', '{"pt-br":"Você tem um relatório Power BI que usa Power Query para transformar dados de um SQL Server. Precisa garantir que a dobragem de consultas (query folding) permaneça ativa.","en-us":"You have a Power BI report using Power Query to transform data from SQL Server. You need to ensure query folding remains active.","es":"Tiene un informe Power BI que usa Power Query para transformar datos de SQL Server. Necesita garantizar que el query folding permanezca activo.","fr":"Vous avez un rapport Power BI utilisant Power Query pour transformer des données SQL Server. Vous devez vous assurer que le pliage de requêtes reste actif."}', '{"pt-br":"Qual transformação impede a dobragem de consulta?","en-us":"Which transformation prevents query folding?","es":"¿Qué transformación impide el query folding?","fr":"Quelle transformation empêche le pliage de requêtes ?"}', '[{"key":"A","text":{"pt-br":"Adicionar colunas de índice","en-us":"Adding index columns","es":"Agregar columnas de índice","fr":"Ajouter des colonnes d''index"}},{"key":"B","text":{"pt-br":"Pivot/Unpivot de colunas","en-us":"Pivot/Unpivot columns","es":"Pivot/Unpivot de columnas","fr":"Pivot/Dépivot de colonnes"}},{"key":"C","text":{"pt-br":"Manter linhas superiores","en-us":"Keep top rows","es":"Mantener filas superiores","fr":"Garder les premières lignes"}},{"key":"D","text":{"pt-br":"Filtrar linhas","en-us":"Filter rows","es":"Filtrar filas","fr":"Filtrer les lignes"}}]', 'A', '{"pt-br":"Adicionar colunas de índice sempre impede a dobragem de consulta no Power Query. Pivot/Unpivot e Manter linhas são transformações que podem ser dobradas.","en-us":"Adding index columns always prevents query folding in Power Query. Pivot/Unpivot and Keep rows are transformations that can be folded.","es":"Agregar columnas de índice siempre impide el query folding. Pivot/Unpivot y Mantener filas pueden ser dobladas.","fr":"L''ajout de colonnes d''index empêche toujours le pliage. Pivot/Dépivot et Garder les lignes peuvent être pliés."}'),
('Consultar e Analisar', '{"pt-br":"Você tem um lakehouse Fabric com um notebook. Precisa consultar a tabela de fatos para encontrar o total de registros por ProductKey, ordenados de forma decrescente.","en-us":"You have a Fabric lakehouse with a notebook. You need to query the fact table to find total records per ProductKey, sorted descending.","es":"Tiene un lakehouse Fabric con un notebook. Necesita consultar la tabla de hechos para encontrar el total de registros por ProductKey, ordenados de forma descendente.","fr":"Vous avez un lakehouse Fabric avec un notebook. Vous devez interroger la table de faits pour trouver le total d''enregistrements par ProductKey, trié de manière décroissante."}', '{"pt-br":"Como você deve estruturar a consulta PySpark?","en-us":"How should you structure the PySpark query?","es":"¿Cómo debe estructurar la consulta PySpark?","fr":"Comment devez-vous structurer la requête PySpark ?"}', '[{"key":"A","text":{"pt-br":"df.groupBy(\"ProductKey\").count().sort(\"count\", descending=True).show()","en-us":"df.groupBy(\"ProductKey\").count().sort(\"count\", descending=True).show()","es":"df.groupBy(\"ProductKey\").count().sort(\"count\", descending=True).show()","fr":"df.groupBy(\"ProductKey\").count().sort(\"count\", descending=True).show()"}},{"key":"B","text":{"pt-br":"df.filter(\"ProductKey\").count().show()","en-us":"df.filter(\"ProductKey\").count().show()","es":"df.filter(\"ProductKey\").count().show()","fr":"df.filter(\"ProductKey\").count().show()"}},{"key":"C","text":{"pt-br":"df.select(\"ProductKey\").distinct().show()","en-us":"df.select(\"ProductKey\").distinct().show()","es":"df.select(\"ProductKey\").distinct().show()","fr":"df.select(\"ProductKey\").distinct().show()"}},{"key":"D","text":{"pt-br":"df.orderBy(\"ProductKey\").count().show()","en-us":"df.orderBy(\"ProductKey\").count().show()","es":"df.orderBy(\"ProductKey\").count().show()","fr":"df.orderBy(\"ProductKey\").count().show()"}}]', 'A', '{"pt-br":"groupBy agrupa por ProductKey, count() retorna o total de registros para cada chave, sort ordena em ordem decrescente e show() exibe os resultados.","en-us":"groupBy groups by ProductKey, count() returns total records per key, sort orders descending and show() displays results.","es":"groupBy agrupa por ProductKey, count() retorna el total de registros por clave, sort ordena descendente y show() muestra resultados.","fr":"groupBy groupe par ProductKey, count() retourne le total par clé, sort trie en ordre décroissant et show() affiche les résultats."}'),
('Transformar Dados', '{"pt-br":"Você está criando perfil de dados em um lakehouse Fabric e executa df.describe().show(). Precisa saber quais funções estatísticas são incluídas para dados numéricos.","en-us":"You are profiling data in a Fabric lakehouse and run df.describe().show(). You need to know which statistical functions are included for numeric data.","es":"Está creando un perfil de datos en un lakehouse Fabric y ejecuta df.describe().show(). Necesita saber qué funciones estadísticas se incluyen para datos numéricos.","fr":"Vous profilez des données dans un lakehouse Fabric et exécutez df.describe().show(). Vous devez savoir quelles fonctions statistiques sont incluses pour les données numériques."}', '{"pt-br":"Quais três funções são incluídas nos resultados de dados numéricos?","en-us":"Which three functions are included in numeric data results?","es":"¿Cuáles tres funciones se incluyen en los resultados de datos numéricos?","fr":"Quelles trois fonctions sont incluses dans les résultats de données numériques ?"}', '[{"key":"A","text":{"pt-br":"COUNT, MEAN e STD (desvio padrão)","en-us":"COUNT, MEAN, and STD (standard deviation)","es":"COUNT, MEAN y STD (desviación estándar)","fr":"COUNT, MEAN et STD (écart type)"}},{"key":"B","text":{"pt-br":"AVG, DISTINCTCOUNT e SUM","en-us":"AVG, DISTINCTCOUNT, and SUM","es":"AVG, DISTINCTCOUNT y SUM","fr":"AVG, DISTINCTCOUNT et SUM"}},{"key":"C","text":{"pt-br":"COUNT, AVG e MEDIAN","en-us":"COUNT, AVG, and MEDIAN","es":"COUNT, AVG y MEDIAN","fr":"COUNT, AVG et MEDIAN"}},{"key":"D","text":{"pt-br":"SUM, MIN e DISTINCTCOUNT","en-us":"SUM, MIN, and DISTINCTCOUNT","es":"SUM, MIN y DISTINCTCOUNT","fr":"SUM, MIN et DISTINCTCOUNT"}}]', 'A', '{"pt-br":"df.describe() gera estatísticas descritivas. Para dados numéricos, inclui COUNT, MEAN, STD, MIN e MAX. Para dados de objeto, também inclui TOP, UNIQUE e FREQ.","en-us":"df.describe() generates descriptive statistics. For numeric data, it includes COUNT, MEAN, STD, MIN, and MAX. For object data, it also includes TOP, UNIQUE, and FREQ.","es":"df.describe() genera estadísticas descriptivas. Para datos numéricos, incluye COUNT, MEAN, STD, MIN y MAX.","fr":"df.describe() génère des statistiques descriptives. Pour les données numériques, il inclut COUNT, MEAN, STD, MIN et MAX."}'),
('Consultar e Analisar', '{"pt-br":"Você tem um workspace Fabric com um relatório Power BI. Precisa modificar nomes de coluna sem alterar os nomes na tabela Delta subjacente.","en-us":"You have a Fabric workspace with a Power BI report. You need to modify column names without changing the names in the underlying Delta table.","es":"Tiene un workspace Fabric con un informe Power BI. Necesita modificar nombres de columna sin cambiar los nombres en la tabla Delta subyacente.","fr":"Vous avez un workspace Fabric avec un rapport Power BI. Vous devez modifier les noms de colonnes sans changer les noms dans la table Delta sous-jacente."}', '{"pt-br":"Qual objeto de warehouse você deve criar?","en-us":"Which warehouse object should you create?","es":"¿Qué objeto de warehouse debe crear?","fr":"Quel objet de warehouse devez-vous créer ?"}', '[{"key":"A","text":{"pt-br":"Exibição (View)","en-us":"View","es":"Vista (View)","fr":"Vue (View)"}},{"key":"B","text":{"pt-br":"Esquema","en-us":"Schema","es":"Esquema","fr":"Schéma"}},{"key":"C","text":{"pt-br":"Tabela materializada","en-us":"Materialized table","es":"Tabla materializada","fr":"Table matérialisée"}},{"key":"D","text":{"pt-br":"Stored Procedure","en-us":"Stored Procedure","es":"Stored Procedure","fr":"Procédure stockée"}}]', 'A', '{"pt-br":"Uma View encapsula lógica de consulta como renomear colunas, filtrar e agregar sem alterar as tabelas subjacentes. Contém apenas a definição da consulta.","en-us":"A View encapsulates query logic like renaming columns, filtering, and aggregating without altering underlying tables. It contains only the query definition.","es":"Una Vista encapsula lógica de consulta como renombrar columnas sin alterar las tablas subyacentes.","fr":"Une Vue encapsule la logique de requête comme le renommage de colonnes sans modifier les tables sous-jacentes."}'),
('Transformar Dados', '{"pt-br":"Você usa Dataflow Gen2 para adicionar uma coluna ao relatório de Vendas. Produtos com preço unitário > $1.000 devem ser ''Alto'', e < $1.000 devem ser ''Regular''.","en-us":"You use Dataflow Gen2 to add a column to the Sales report. Products with unit price > $1,000 should be ''High'', and < $1,000 should be ''Regular''.","es":"Usa Dataflow Gen2 para agregar una columna al informe de Ventas. Productos con precio > $1.000 deben ser ''Alto'', y < $1.000 deben ser ''Regular''.","fr":"Vous utilisez Dataflow Gen2 pour ajouter une colonne au rapport Ventes. Les produits avec prix > 1 000 $ doivent être ''Élevé'', et < 1 000 $ doivent être ''Standard''."}', '{"pt-br":"O que você deve selecionar na guia Adicionar coluna do Power Query?","en-us":"What should you select on the Add Column tab in Power Query?","es":"¿Qué debe seleccionar en la pestaña Agregar columna de Power Query?","fr":"Que devez-vous sélectionner dans l''onglet Ajouter une colonne de Power Query ?"}', '[{"key":"A","text":{"pt-br":"Coluna condicional","en-us":"Conditional column","es":"Columna condicional","fr":"Colonne conditionnelle"}},{"key":"B","text":{"pt-br":"Coluna personalizada","en-us":"Custom column","es":"Columna personalizada","fr":"Colonne personnalisée"}},{"key":"C","text":{"pt-br":"Coluna de exemplo","en-us":"Column from examples","es":"Columna de ejemplo","fr":"Colonne à partir d''exemples"}},{"key":"D","text":{"pt-br":"Coluna de índice","en-us":"Index column","es":"Columna de índice","fr":"Colonne d''index"}}]', 'A', '{"pt-br":"A Coluna condicional permite criar colunas cujos valores são baseados em condições aplicadas a colunas existentes, como classificar preços em categorias.","en-us":"Conditional column allows creating columns whose values are based on conditions applied to existing columns, like classifying prices into categories.","es":"La Columna condicional permite crear columnas cuyos valores se basan en condiciones aplicadas a columnas existentes.","fr":"La Colonne conditionnelle permet de créer des colonnes dont les valeurs sont basées sur des conditions appliquées aux colonnes existantes."}'),
('Transformar Dados', '{"pt-br":"Você tem um notebook Fabric com um DataFrame df referenciando a tabela Customers. Precisa criar perfil dos dados minimizando esforço administrativo.","en-us":"You have a Fabric notebook with a DataFrame df referencing the Customers table. You need to profile the data while minimizing administrative effort.","es":"Tiene un notebook Fabric con un DataFrame df referenciando la tabla Customers. Necesita crear un perfil de datos minimizando esfuerzo administrativo.","fr":"Vous avez un notebook Fabric avec un DataFrame df référençant la table Customers. Vous devez profiler les données en minimisant l''effort administratif."}', '{"pt-br":"O que você deve fazer para criar o perfil dos dados?","en-us":"What should you do to profile the data?","es":"¿Qué debe hacer para crear el perfil de datos?","fr":"Que devez-vous faire pour profiler les données ?"}', '[{"key":"A","text":{"pt-br":"Executar display(df) e usar a guia Inspecionar","en-us":"Run display(df) and use the Inspect tab","es":"Ejecutar display(df) y usar la pestaña Inspeccionar","fr":"Exécuter display(df) et utiliser l''onglet Inspecter"}},{"key":"B","text":{"pt-br":"Converter para pandas e usar QuickVisualize","en-us":"Convert to pandas and use QuickVisualize","es":"Convertir a pandas y usar QuickVisualize","fr":"Convertir en pandas et utiliser QuickVisualize"}},{"key":"C","text":{"pt-br":"Usar a opção Gráfico no notebook","en-us":"Use the Chart option in the notebook","es":"Usar la opción Gráfico en el notebook","fr":"Utiliser l''option Graphique dans le notebook"}},{"key":"D","text":{"pt-br":"Criar um relatório Power BI inserido","en-us":"Create an embedded Power BI report","es":"Crear un informe Power BI insertado","fr":"Créer un rapport Power BI intégré"}}]', 'A', '{"pt-br":"O botão Inspecionar em display(df) fornece distribuição resumida e estatísticas para cada coluna com mínimo esforço. QuickVisualize e Gráficos não geram as estatísticas de perfil necessárias.","en-us":"The Inspect button in display(df) provides summary distribution and statistics for each column with minimal effort. QuickVisualize and Charts don''t generate needed profiling statistics.","es":"El botón Inspeccionar en display(df) proporciona distribución resumida y estadísticas para cada columna con mínimo esfuerzo.","fr":"Le bouton Inspecter dans display(df) fournit la distribution résumée et les statistiques pour chaque colonne avec un effort minimal."}'),
('Transformar Dados', '{"pt-br":"Você tem um lakehouse Fabric com um notebook. Precisa identificar linhas do DataFrame df_customers onde qualquer coluna (eixo 1) é NULL.","en-us":"You have a Fabric lakehouse with a notebook. You need to identify rows in DataFrame df_customers where any column (axis 1) is NULL.","es":"Tiene un lakehouse Fabric con un notebook. Necesita identificar filas del DataFrame df_customers donde cualquier columna (eje 1) es NULL.","fr":"Vous avez un lakehouse Fabric avec un notebook. Vous devez identifier les lignes du DataFrame df_customers où toute colonne (axe 1) est NULL."}', '{"pt-br":"Qual instrução você deve executar?","en-us":"Which statement should you run?","es":"¿Qué instrucción debe ejecutar?","fr":"Quelle instruction devez-vous exécuter ?"}', '[{"key":"A","text":{"pt-br":"df_customers[df_customers.isnull().any(axis=1)]","en-us":"df_customers[df_customers.isnull().any(axis=1)]","es":"df_customers[df_customers.isnull().any(axis=1)]","fr":"df_customers[df_customers.isnull().any(axis=1)]"}},{"key":"B","text":{"pt-br":"df_customers.dropna()","en-us":"df_customers.dropna()","es":"df_customers.dropna()","fr":"df_customers.dropna()"}},{"key":"C","text":{"pt-br":"df_customers.isnull().sum()","en-us":"df_customers.isnull().sum()","es":"df_customers.isnull().sum()","fr":"df_customers.isnull().sum()"}},{"key":"D","text":{"pt-br":"df_customers[df_customers.isnull().all(axis=1)]","en-us":"df_customers[df_customers.isnull().all(axis=1)]","es":"df_customers[df_customers.isnull().all(axis=1)]","fr":"df_customers[df_customers.isnull().all(axis=1)]"}}]', 'A', '{"pt-br":"isnull() identifica valores NULL. any(axis=1) retorna True se qualquer coluna da linha for NULL. O filtro retorna apenas essas linhas.","en-us":"isnull() identifies NULL values. any(axis=1) returns True if any column in the row is NULL. The filter returns only those rows.","es":"isnull() identifica valores NULL. any(axis=1) retorna True si cualquier columna de la fila es NULL.","fr":"isnull() identifie les valeurs NULL. any(axis=1) retourne True si une colonne de la ligne est NULL."}'),
('Consultar e Analisar', '{"pt-br":"Você tem uma tabela Sales com OrderID, CustomerID, ProductID, Quantity e Sales_Date. Precisa encontrar o total de produtos vendidos por ProductID em janeiro de 2024.","en-us":"You have a Sales table with OrderID, CustomerID, ProductID, Quantity, and Sales_Date. You need to find total products sold per ProductID in January 2024.","es":"Tiene una tabla Sales con OrderID, CustomerID, ProductID, Quantity y Sales_Date. Necesita encontrar el total de productos vendidos por ProductID en enero 2024.","fr":"Vous avez une table Sales avec OrderID, CustomerID, ProductID, Quantity et Sales_Date. Vous devez trouver le total de produits vendus par ProductID en janvier 2024."}', '{"pt-br":"Qual instrução SQL você deve executar?","en-us":"Which SQL statement should you run?","es":"¿Qué instrucción SQL debe ejecutar?","fr":"Quelle instruction SQL devez-vous exécuter ?"}', '[{"key":"A","text":{"pt-br":"SELECT Product_ID, SUM(Quantity) FROM Sales WHERE MONTH(Sales_Date)=1 AND YEAR(Sales_Date)=2024 GROUP BY Product_ID","en-us":"SELECT Product_ID, SUM(Quantity) FROM Sales WHERE MONTH(Sales_Date)=1 AND YEAR(Sales_Date)=2024 GROUP BY Product_ID","es":"SELECT Product_ID, SUM(Quantity) FROM Sales WHERE MONTH(Sales_Date)=1 AND YEAR(Sales_Date)=2024 GROUP BY Product_ID","fr":"SELECT Product_ID, SUM(Quantity) FROM Sales WHERE MONTH(Sales_Date)=1 AND YEAR(Sales_Date)=2024 GROUP BY Product_ID"}},{"key":"B","text":{"pt-br":"SELECT Product_ID, COUNT(*) FROM Sales GROUP BY Product_ID HAVING Sales_Date LIKE ''2024-01%''","en-us":"SELECT Product_ID, COUNT(*) FROM Sales GROUP BY Product_ID HAVING Sales_Date LIKE ''2024-01%''","es":"SELECT Product_ID, COUNT(*) FROM Sales GROUP BY Product_ID HAVING Sales_Date LIKE ''2024-01%''","fr":"SELECT Product_ID, COUNT(*) FROM Sales GROUP BY Product_ID HAVING Sales_Date LIKE ''2024-01%''"}},{"key":"C","text":{"pt-br":"SELECT Product_ID, SUM(Quantity) FROM Sales GROUP BY Product_ID, Sales_Date","en-us":"SELECT Product_ID, SUM(Quantity) FROM Sales GROUP BY Product_ID, Sales_Date","es":"SELECT Product_ID, SUM(Quantity) FROM Sales GROUP BY Product_ID, Sales_Date","fr":"SELECT Product_ID, SUM(Quantity) FROM Sales GROUP BY Product_ID, Sales_Date"}},{"key":"D","text":{"pt-br":"SELECT Product_ID, AVG(Quantity) FROM Sales WHERE YEAR(Sales_Date)=2024 GROUP BY Product_ID","en-us":"SELECT Product_ID, AVG(Quantity) FROM Sales WHERE YEAR(Sales_Date)=2024 GROUP BY Product_ID","es":"SELECT Product_ID, AVG(Quantity) FROM Sales WHERE YEAR(Sales_Date)=2024 GROUP BY Product_ID","fr":"SELECT Product_ID, AVG(Quantity) FROM Sales WHERE YEAR(Sales_Date)=2024 GROUP BY Product_ID"}}]', 'A', '{"pt-br":"A instrução filtra corretamente por mês 1 e ano 2024 com WHERE, soma a quantidade com SUM e agrupa por Product_ID com GROUP BY.","en-us":"The statement correctly filters by month 1 and year 2024 with WHERE, sums quantity with SUM, and groups by Product_ID with GROUP BY.","es":"La instrucción filtra correctamente por mes 1 y año 2024, suma la cantidad y agrupa por Product_ID.","fr":"L''instruction filtre correctement par mois 1 et année 2024, somme la quantité et groupe par Product_ID."}'),
('Consultar e Analisar', '{"pt-br":"Você está escrevendo T-SQL para classificar CustomerKeys por SalesAmount em ordem decrescente. Após empates, o próximo valor de classificação deve incrementar em 1 (sem lacunas).","en-us":"You are writing T-SQL to rank CustomerKeys by SalesAmount descending. After ties, the next rank value should increment by 1 (no gaps).","es":"Está escribiendo T-SQL para clasificar CustomerKeys por SalesAmount de forma descendente. Después de empates, el siguiente valor de clasificación debe incrementar en 1 (sin lagunas).","fr":"Vous écrivez du T-SQL pour classer les CustomerKeys par SalesAmount décroissant. Après les égalités, la valeur de rang suivante doit s''incrémenter de 1 (sans lacunes)."}', '{"pt-br":"Qual função de janela você deve usar?","en-us":"Which window function should you use?","es":"¿Qué función de ventana debe usar?","fr":"Quelle fonction de fenêtre devez-vous utiliser ?"}', '[{"key":"A","text":{"pt-br":"DENSE_RANK()","en-us":"DENSE_RANK()","es":"DENSE_RANK()","fr":"DENSE_RANK()"}},{"key":"B","text":{"pt-br":"RANK()","en-us":"RANK()","es":"RANK()","fr":"RANK()"}},{"key":"C","text":{"pt-br":"ROW_NUMBER()","en-us":"ROW_NUMBER()","es":"ROW_NUMBER()","fr":"ROW_NUMBER()"}},{"key":"D","text":{"pt-br":"NTILE()","en-us":"NTILE()","es":"NTILE()","fr":"NTILE()"}}]', 'A', '{"pt-br":"DENSE_RANK() retorna a classificação sem lacunas nos valores. RANK() inclui lacunas após empates. ROW_NUMBER() atribui números únicos sequenciais.","en-us":"DENSE_RANK() returns ranking without gaps in values. RANK() includes gaps after ties. ROW_NUMBER() assigns unique sequential numbers.","es":"DENSE_RANK() retorna la clasificación sin lagunas. RANK() incluye lagunas después de empates. ROW_NUMBER() asigna números únicos.","fr":"DENSE_RANK() retourne le classement sans lacunes. RANK() inclut des lacunes après les égalités. ROW_NUMBER() attribue des numéros uniques."}'),
('Consultar e Analisar', '{"pt-br":"Você tem tabelas customer_info e order_info em um warehouse Fabric. Precisa retornar todos os clientes que ainda não fizeram um pedido.","en-us":"You have customer_info and order_info tables in a Fabric warehouse. You need to return all customers who haven''t placed an order yet.","es":"Tiene tablas customer_info y order_info en un warehouse Fabric. Necesita retornar todos los clientes que aún no han hecho un pedido.","fr":"Vous avez des tables customer_info et order_info dans un warehouse Fabric. Vous devez retourner tous les clients qui n''ont pas encore passé de commande."}', '{"pt-br":"Qual consulta SQL você deve executar?","en-us":"Which SQL query should you run?","es":"¿Qué consulta SQL debe ejecutar?","fr":"Quelle requête SQL devez-vous exécuter ?"}', '[{"key":"A","text":{"pt-br":"SELECT name FROM customer_info LEFT JOIN order_info ON customer_info.customer_id = order_info.customer_id WHERE order_info.order_id IS NULL","en-us":"SELECT name FROM customer_info LEFT JOIN order_info ON customer_info.customer_id = order_info.customer_id WHERE order_info.order_id IS NULL","es":"SELECT name FROM customer_info LEFT JOIN order_info ON customer_info.customer_id = order_info.customer_id WHERE order_info.order_id IS NULL","fr":"SELECT name FROM customer_info LEFT JOIN order_info ON customer_info.customer_id = order_info.customer_id WHERE order_info.order_id IS NULL"}},{"key":"B","text":{"pt-br":"SELECT name FROM customer_info INNER JOIN order_info ON customer_info.customer_id = order_info.customer_id","en-us":"SELECT name FROM customer_info INNER JOIN order_info ON customer_info.customer_id = order_info.customer_id","es":"SELECT name FROM customer_info INNER JOIN order_info ON customer_info.customer_id = order_info.customer_id","fr":"SELECT name FROM customer_info INNER JOIN order_info ON customer_info.customer_id = order_info.customer_id"}},{"key":"C","text":{"pt-br":"SELECT name FROM customer_info WHERE customer_id IN (SELECT customer_id FROM order_info)","en-us":"SELECT name FROM customer_info WHERE customer_id IN (SELECT customer_id FROM order_info)","es":"SELECT name FROM customer_info WHERE customer_id IN (SELECT customer_id FROM order_info)","fr":"SELECT name FROM customer_info WHERE customer_id IN (SELECT customer_id FROM order_info)"}},{"key":"D","text":{"pt-br":"SELECT name FROM customer_info JOIN order_info ON customer_info.customer_id = order_info.customer_id WHERE order_info.order_id IS NOT NULL","en-us":"SELECT name FROM customer_info JOIN order_info ON customer_info.customer_id = order_info.customer_id WHERE order_info.order_id IS NOT NULL","es":"SELECT name FROM customer_info JOIN order_info ON customer_info.customer_id = order_info.customer_id WHERE order_info.order_id IS NOT NULL","fr":"SELECT name FROM customer_info JOIN order_info ON customer_info.customer_id = order_info.customer_id WHERE order_info.order_id IS NOT NULL"}}]', 'A', '{"pt-br":"LEFT JOIN com WHERE IS NULL retorna clientes sem correspondência na tabela de pedidos. INNER JOIN e IN retornam apenas clientes com pedidos.","en-us":"LEFT JOIN with WHERE IS NULL returns customers without matches in the orders table. INNER JOIN and IN return only customers with orders.","es":"LEFT JOIN con WHERE IS NULL retorna clientes sin correspondencia en la tabla de pedidos.","fr":"LEFT JOIN avec WHERE IS NULL retourne les clients sans correspondance dans la table des commandes."}'),
('Consultar e Analisar', '{"pt-br":"Você tem tabelas Trip (TripDateID, PassengerCount) e Date (DateID, Day, Month, Quarter, Year) no warehouse. Precisa resumir passageiros por ano usando o Editor de Consultas Visuais.","en-us":"You have Trip (TripDateID, PassengerCount) and Date (DateID, Day, Month, Quarter, Year) tables in the warehouse. You need to summarize passengers by year using Visual Query Editor.","es":"Tiene tablas Trip y Date en el warehouse. Necesita resumir pasajeros por año usando el Editor de Consultas Visuales.","fr":"Vous avez des tables Trip et Date dans le warehouse. Vous devez résumer les passagers par année avec l''Éditeur de requêtes visuelles."}', '{"pt-br":"Quais transformações você deve usar?","en-us":"Which transformations should you use?","es":"¿Qué transformaciones debe usar?","fr":"Quelles transformations devez-vous utiliser ?"}', '[{"key":"A","text":{"pt-br":"Mesclar consultas para unir Trip e Date, depois GroupBy","en-us":"Merge queries to join Trip and Date, then GroupBy","es":"Fusionar consultas para unir Trip y Date, luego GroupBy","fr":"Fusionner les requêtes pour joindre Trip et Date, puis GroupBy"}},{"key":"B","text":{"pt-br":"Acrescentar consultas e depois filtrar por ano","en-us":"Append queries then filter by year","es":"Anexar consultas y luego filtrar por año","fr":"Ajouter des requêtes puis filtrer par année"}},{"key":"C","text":{"pt-br":"Criar uma tabela calculada com DAX","en-us":"Create a calculated table with DAX","es":"Crear una tabla calculada con DAX","fr":"Créer une table calculée avec DAX"}},{"key":"D","text":{"pt-br":"Usar Unpivot e depois Pivot","en-us":"Use Unpivot then Pivot","es":"Usar Unpivot y luego Pivot","fr":"Utiliser Dépivot puis Pivot"}}]', 'A', '{"pt-br":"Mesclar une as tabelas Trip e Date. Após expandir a coluna Year, GroupBy resume os passageiros por ano. Append faz uma operação de UNION, não JOIN.","en-us":"Merge joins Trip and Date tables. After expanding the Year column, GroupBy summarizes passengers by year. Append does a UNION, not JOIN.","es":"Fusionar une las tablas Trip y Date. Después de expandir Year, GroupBy resume los pasajeros por año.","fr":"Fusionner joint les tables Trip et Date. Après expansion de Year, GroupBy résume les passagers par année."}'),
('Consultar e Analisar', '{"pt-br":"Você tem uma tabela inventory com item_id, category, stock_quantity e last_stocked_date. Precisa encontrar a data de estoque mais recente por categoria onde stock_quantity < 50.","en-us":"You have an inventory table with item_id, category, stock_quantity, and last_stocked_date. You need to find the most recent stocked date per category where stock_quantity < 50.","es":"Tiene una tabla inventory con item_id, category, stock_quantity y last_stocked_date. Necesita encontrar la fecha de stock más reciente por categoría donde stock_quantity < 50.","fr":"Vous avez une table inventory avec item_id, category, stock_quantity et last_stocked_date. Vous devez trouver la date de stock la plus récente par catégorie où stock_quantity < 50."}', '{"pt-br":"Qual instrução SQL você deve executar?","en-us":"Which SQL statement should you run?","es":"¿Qué instrucción SQL debe ejecutar?","fr":"Quelle instruction SQL devez-vous exécuter ?"}', '[{"key":"A","text":{"pt-br":"SELECT category, MAX(last_stocked_date) FROM inventory WHERE stock_quantity < 50 GROUP BY category","en-us":"SELECT category, MAX(last_stocked_date) FROM inventory WHERE stock_quantity < 50 GROUP BY category","es":"SELECT category, MAX(last_stocked_date) FROM inventory WHERE stock_quantity < 50 GROUP BY category","fr":"SELECT category, MAX(last_stocked_date) FROM inventory WHERE stock_quantity < 50 GROUP BY category"}},{"key":"B","text":{"pt-br":"SELECT DISTINCT category, last_stocked_date FROM inventory WHERE stock_quantity < 50 ORDER BY last_stocked_date DESC","en-us":"SELECT DISTINCT category, last_stocked_date FROM inventory WHERE stock_quantity < 50 ORDER BY last_stocked_date DESC","es":"SELECT DISTINCT category, last_stocked_date FROM inventory WHERE stock_quantity < 50 ORDER BY last_stocked_date DESC","fr":"SELECT DISTINCT category, last_stocked_date FROM inventory WHERE stock_quantity < 50 ORDER BY last_stocked_date DESC"}},{"key":"C","text":{"pt-br":"SELECT category, last_stocked_date FROM inventory GROUP BY category HAVING MIN(stock_quantity) < 50","en-us":"SELECT category, last_stocked_date FROM inventory GROUP BY category HAVING MIN(stock_quantity) < 50","es":"SELECT category, last_stocked_date FROM inventory GROUP BY category HAVING MIN(stock_quantity) < 50","fr":"SELECT category, last_stocked_date FROM inventory GROUP BY category HAVING MIN(stock_quantity) < 50"}},{"key":"D","text":{"pt-br":"SELECT category, last_stocked_date FROM inventory WHERE stock_quantity < 50 ORDER BY last_stocked_date DESC LIMIT 1","en-us":"SELECT category, last_stocked_date FROM inventory WHERE stock_quantity < 50 ORDER BY last_stocked_date DESC LIMIT 1","es":"SELECT category, last_stocked_date FROM inventory WHERE stock_quantity < 50 ORDER BY last_stocked_date DESC LIMIT 1","fr":"SELECT category, last_stocked_date FROM inventory WHERE stock_quantity < 50 ORDER BY last_stocked_date DESC LIMIT 1"}}]', 'A', '{"pt-br":"MAX com GROUP BY retorna a data mais recente por categoria. WHERE filtra stock < 50. As outras opções não agregam corretamente ou retornam apenas um registro.","en-us":"MAX with GROUP BY returns the most recent date per category. WHERE filters stock < 50. Other options don''t aggregate correctly or return only one record.","es":"MAX con GROUP BY retorna la fecha más reciente por categoría. WHERE filtra stock < 50.","fr":"MAX avec GROUP BY retourne la date la plus récente par catégorie. WHERE filtre stock < 50."}'),
('Consultar e Analisar', '{"pt-br":"Sua empresa usa Microsoft Fabric para um data warehouse. Você precisa analisar dados de vendas filtrando e agregando sem escrever código.","en-us":"Your company uses Microsoft Fabric for a data warehouse. You need to analyze sales data by filtering and aggregating without writing code.","es":"Su empresa usa Microsoft Fabric para un data warehouse. Necesita analizar datos de ventas filtrando y agregando sin escribir código.","fr":"Votre entreprise utilise Microsoft Fabric pour un data warehouse. Vous devez analyser les données de ventes en filtrant et agrégeant sans écrire de code."}', '{"pt-br":"O que você deve fazer?","en-us":"What should you do?","es":"¿Qué debe hacer?","fr":"Que devez-vous faire ?"}', '[{"key":"A","text":{"pt-br":"Usar o editor de consultas visuais no Microsoft Fabric","en-us":"Use the Visual Query Editor in Microsoft Fabric","es":"Usar el editor de consultas visuales en Microsoft Fabric","fr":"Utiliser l''éditeur de requêtes visuelles dans Microsoft Fabric"}},{"key":"B","text":{"pt-br":"Usar um pipeline no Microsoft Fabric","en-us":"Use a pipeline in Microsoft Fabric","es":"Usar un pipeline en Microsoft Fabric","fr":"Utiliser un pipeline dans Microsoft Fabric"}},{"key":"C","text":{"pt-br":"Usar Dataflow Gen2","en-us":"Use Dataflow Gen2","es":"Usar Dataflow Gen2","fr":"Utiliser Dataflow Gen2"}},{"key":"D","text":{"pt-br":"Usar Power BI Desktop","en-us":"Use Power BI Desktop","es":"Usar Power BI Desktop","fr":"Utiliser Power BI Desktop"}}]', 'A', '{"pt-br":"O editor de consultas visuais permite filtrar e agregar dados sem SQL, diretamente no warehouse. Pipelines são para orquestração, não análise.","en-us":"The Visual Query Editor allows filtering and aggregating data without SQL, directly in the warehouse. Pipelines are for orchestration, not analysis.","es":"El editor de consultas visuales permite filtrar y agregar datos sin SQL, directamente en el warehouse.","fr":"L''éditeur de requêtes visuelles permet de filtrer et d''agréger les données sans SQL, directement dans le warehouse."}'),
('Consultar e Analisar', '{"pt-br":"Você precisa identificar os principais clientes por volume de vendas combinando dados das tabelas Sales e Customer usando o editor de consultas visuais.","en-us":"You need to identify top customers by sales volume by combining data from Sales and Customer tables using the Visual Query Editor.","es":"Necesita identificar los principales clientes por volumen de ventas combinando datos de las tablas Sales y Customer usando el editor de consultas visuales.","fr":"Vous devez identifier les meilleurs clients par volume de ventes en combinant les données des tables Sales et Customer avec l''éditeur de requêtes visuelles."}', '{"pt-br":"Quais três ações você deve executar?","en-us":"Which three actions should you perform?","es":"¿Cuáles tres acciones debe ejecutar?","fr":"Quelles trois actions devez-vous effectuer ?"}', '[{"key":"A","text":{"pt-br":"Adicionar tabelas ao canvas, identificar chave comum e mesclar consultas como novas","en-us":"Add tables to canvas, identify common key, and merge queries as new","es":"Agregar tablas al canvas, identificar clave común y fusionar consultas como nuevas","fr":"Ajouter les tables au canevas, identifier la clé commune et fusionner les requêtes comme nouvelles"}},{"key":"B","text":{"pt-br":"Acrescentar consultas, salvar como exibição e filtrar resultados","en-us":"Append queries, save as view, and filter results","es":"Anexar consultas, guardar como vista y filtrar resultados","fr":"Ajouter des requêtes, enregistrer comme vue et filtrer les résultats"}},{"key":"C","text":{"pt-br":"Criar um pipeline, adicionar atividade de cópia e definir destino","en-us":"Create a pipeline, add copy activity, and set destination","es":"Crear un pipeline, agregar actividad de copia y definir destino","fr":"Créer un pipeline, ajouter une activité de copie et définir la destination"}},{"key":"D","text":{"pt-br":"Usar Dataflow Gen2, importar tabelas e aplicar transformações","en-us":"Use Dataflow Gen2, import tables, and apply transformations","es":"Usar Dataflow Gen2, importar tablas y aplicar transformaciones","fr":"Utiliser Dataflow Gen2, importer les tables et appliquer les transformations"}}]', 'A', '{"pt-br":"No editor de consultas visuais, adicione as tabelas ao canvas, identifique a chave comum (CustomerID) e use Mesclar consultas como novas para unir os dados.","en-us":"In the Visual Query Editor, add tables to canvas, identify the common key (CustomerID), and use Merge queries as new to join the data.","es":"En el editor de consultas visuales, agregue tablas, identifique la clave común y use Fusionar consultas como nuevas.","fr":"Dans l''éditeur de requêtes visuelles, ajoutez les tables, identifiez la clé commune et utilisez Fusionner les requêtes comme nouvelles."}'),
('Consultar e Analisar', '{"pt-br":"Você criou uma consulta Query1 no editor de consultas visuais que combina Table1 com várias tabelas. Precisa minimizar o tempo de execução com mínimo esforço de desenvolvimento.","en-us":"You created a query Query1 in the Visual Query Editor combining Table1 with multiple tables. You need to minimize execution time with minimal development effort.","es":"Creó una consulta Query1 en el editor visual combinando Table1 con varias tablas. Necesita minimizar el tiempo de ejecución con mínimo esfuerzo.","fr":"Vous avez créé une requête Query1 dans l''éditeur visuel combinant Table1 avec plusieurs tables. Vous devez minimiser le temps d''exécution avec un effort minimal."}', '{"pt-br":"O que você deve fazer?","en-us":"What should you do?","es":"¿Qué debe hacer?","fr":"Que devez-vous faire ?"}', '[{"key":"A","text":{"pt-br":"Salvar Query1 como uma tabela no warehouse","en-us":"Save Query1 as a table in the warehouse","es":"Guardar Query1 como una tabla en el warehouse","fr":"Enregistrer Query1 comme table dans le warehouse"}},{"key":"B","text":{"pt-br":"Salvar Query1 como uma exibição (view)","en-us":"Save Query1 as a view","es":"Guardar Query1 como una vista","fr":"Enregistrer Query1 comme vue"}},{"key":"C","text":{"pt-br":"Exportar como modelo Power Query","en-us":"Export as a Power Query model","es":"Exportar como modelo Power Query","fr":"Exporter comme modèle Power Query"}},{"key":"D","text":{"pt-br":"Criar um endpoint SQL","en-us":"Create a SQL endpoint","es":"Crear un endpoint SQL","fr":"Créer un point de terminaison SQL"}}]', 'A', '{"pt-br":"Salvar como tabela materializa os resultados, permitindo leitura direta sem reexecutar joins complexos. View recompila a cada execução. Endpoint SQL não melhora performance.","en-us":"Saving as a table materializes results, allowing direct reads without re-running complex joins. View recompiles on each run. SQL endpoint doesn''t improve performance.","es":"Guardar como tabla materializa los resultados. View recompila en cada ejecución. Endpoint SQL no mejora el rendimiento.","fr":"Enregistrer comme table matérialise les résultats. La vue recompile à chaque exécution. Le point de terminaison SQL n''améliore pas les performances."}'),
('Projetar Modelos Semânticos', '{"pt-br":"Você tem um relatório Power BI com um gráfico de barras. Precisa permitir que usuários alterem a categoria do eixo Y usando uma segmentação de dados.","en-us":"You have a Power BI report with a bar chart. You need to allow users to change the Y-axis category using a slicer.","es":"Tiene un informe Power BI con un gráfico de barras. Necesita permitir que los usuarios cambien la categoría del eje Y usando una segmentación.","fr":"Vous avez un rapport Power BI avec un graphique à barres. Vous devez permettre aux utilisateurs de changer la catégorie de l''axe Y avec un segment."}', '{"pt-br":"Qual recurso do Power BI você deve adicionar?","en-us":"Which Power BI feature should you add?","es":"¿Qué recurso de Power BI debe agregar?","fr":"Quelle fonctionnalité Power BI devez-vous ajouter ?"}', '[{"key":"A","text":{"pt-br":"Parâmetros de campo","en-us":"Field parameters","es":"Parámetros de campo","fr":"Paramètres de champ"}},{"key":"B","text":{"pt-br":"Indicadores (Bookmarks)","en-us":"Bookmarks","es":"Marcadores (Bookmarks)","fr":"Signets (Bookmarks)"}},{"key":"C","text":{"pt-br":"Drill-through","en-us":"Drill-through","es":"Drill-through","fr":"Drill-through"}},{"key":"D","text":{"pt-br":"Botões de navegação","en-us":"Navigation buttons","es":"Botones de navegación","fr":"Boutons de navigation"}}]', 'A', '{"pt-br":"Parâmetros de campo permitem que usuários alternem entre colunas usadas no eixo categórico dos visuais via segmentação. As outras opções não oferecem essa capacidade.","en-us":"Field parameters allow users to switch between columns used in the visual''s categorical axis via a slicer. Other options don''t provide this capability.","es":"Los parámetros de campo permiten que los usuarios alternen entre columnas usadas en el eje categórico via segmentación.","fr":"Les paramètres de champ permettent aux utilisateurs de basculer entre les colonnes utilisées dans l''axe catégoriel via un segment."}'),
('Projetar Modelos Semânticos', '{"pt-br":"Seu modelo tem tabelas Sales (SalesAmount, OrderDateKey, ShipDateKey) e Date (DateKey). Date tem relação ativa com OrderDateKey e inativa com ShipDateKey. Precisa criar medidas para vendas por data de pedido e por data de envio.","en-us":"Your model has Sales (SalesAmount, OrderDateKey, ShipDateKey) and Date (DateKey) tables. Date has an active relationship with OrderDateKey and inactive with ShipDateKey. You need measures for sales by order date and ship date.","es":"Su modelo tiene tablas Sales y Date. Date tiene relación activa con OrderDateKey e inactiva con ShipDateKey. Necesita medidas para ventas por fecha de pedido y fecha de envío.","fr":"Votre modèle a des tables Sales et Date. Date a une relation active avec OrderDateKey et inactive avec ShipDateKey. Vous avez besoin de mesures pour les ventes par date de commande et date d''expédition."}', '{"pt-br":"Como você deve criar as medidas?","en-us":"How should you create the measures?","es":"¿Cómo debe crear las medidas?","fr":"Comment devez-vous créer les mesures ?"}', '[{"key":"A","text":{"pt-br":"Vendas Pedido = SUM(Sales[SalesAmount]); Vendas Envio = CALCULATE(SUM(Sales[SalesAmount]), USERELATIONSHIP(Date[DateKey], Sales[ShipDateKey]))","en-us":"Order Sales = SUM(Sales[SalesAmount]); Ship Sales = CALCULATE(SUM(Sales[SalesAmount]), USERELATIONSHIP(Date[DateKey], Sales[ShipDateKey]))","es":"Ventas Pedido = SUM; Ventas Envío = CALCULATE + USERELATIONSHIP","fr":"Ventes Commande = SUM; Ventes Expédition = CALCULATE + USERELATIONSHIP"}},{"key":"B","text":{"pt-br":"Ambas com CALCULATE e USERELATIONSHIP","en-us":"Both with CALCULATE and USERELATIONSHIP","es":"Ambas con CALCULATE y USERELATIONSHIP","fr":"Les deux avec CALCULATE et USERELATIONSHIP"}},{"key":"C","text":{"pt-br":"Ambas com SUM simples e filtros de página","en-us":"Both with simple SUM and page filters","es":"Ambas con SUM simple y filtros de página","fr":"Les deux avec SUM simple et filtres de page"}},{"key":"D","text":{"pt-br":"Usar RELATED para trazer a data de envio e SUM para ambas","en-us":"Use RELATED to bring ship date and SUM for both","es":"Usar RELATED para traer la fecha de envío y SUM para ambas","fr":"Utiliser RELATED pour amener la date d''expédition et SUM pour les deux"}}]', 'A', '{"pt-br":"A relação ativa (OrderDate) funciona com SUM simples. Para a relação inativa (ShipDate), use CALCULATE com USERELATIONSHIP para ativá-la. RELATED retorna valores, não ativa relações.","en-us":"Active relationship (OrderDate) works with simple SUM. For inactive relationship (ShipDate), use CALCULATE with USERELATIONSHIP to activate it.","es":"La relación activa funciona con SUM simple. Para la inactiva, use CALCULATE con USERELATIONSHIP.","fr":"La relation active fonctionne avec SUM simple. Pour l''inactive, utilisez CALCULATE avec USERELATIONSHIP."}'),
('Otimizar Modelos Semânticos', '{"pt-br":"Você tem um modelo grande com agregações definidas pelo usuário para acelerar consultas frequentes. Precisa confirmar se as consultas usam os dados agregados.","en-us":"You have a large model with user-defined aggregations to speed up frequent queries. You need to confirm if queries use the aggregated data.","es":"Tiene un modelo grande con agregaciones definidas por el usuario. Necesita confirmar si las consultas usan los datos agregados.","fr":"Vous avez un grand modèle avec des agrégations définies par l''utilisateur. Vous devez confirmer si les requêtes utilisent les données agrégées."}', '{"pt-br":"Quais duas ferramentas você deve usar?","en-us":"Which two tools should you use?","es":"¿Cuáles dos herramientas debe usar?","fr":"Quels deux outils devez-vous utiliser ?"}', '[{"key":"A","text":{"pt-br":"DAX Studio e SQL Server Profiler","en-us":"DAX Studio and SQL Server Profiler","es":"DAX Studio y SQL Server Profiler","fr":"DAX Studio et SQL Server Profiler"}},{"key":"B","text":{"pt-br":"DAX Studio e VertiPaq Analyzer","en-us":"DAX Studio and VertiPaq Analyzer","es":"DAX Studio y VertiPaq Analyzer","fr":"DAX Studio et VertiPaq Analyzer"}},{"key":"C","text":{"pt-br":"Performance Analyzer e Tabular Editor","en-us":"Performance Analyzer and Tabular Editor","es":"Performance Analyzer y Tabular Editor","fr":"Performance Analyzer et Tabular Editor"}},{"key":"D","text":{"pt-br":"ALM Toolkit e Best Practice Analyzer","en-us":"ALM Toolkit and Best Practice Analyzer","es":"ALM Toolkit y Best Practice Analyzer","fr":"ALM Toolkit et Best Practice Analyzer"}}]', 'A', '{"pt-br":"SQL Server Profiler e DAX Studio detectam se as consultas foram retornadas do cache em memória ou enviadas via DirectQuery à fonte de dados.","en-us":"SQL Server Profiler and DAX Studio can detect whether queries were returned from the in-memory cache or pushed via DirectQuery to the data source.","es":"SQL Server Profiler y DAX Studio detectan si las consultas fueron retornadas del cache o enviadas vía DirectQuery.","fr":"SQL Server Profiler et DAX Studio détectent si les requêtes ont été retournées du cache ou envoyées via DirectQuery."}'),
('Projetar Modelos Semânticos', '{"pt-br":"Você precisa implementar um modelo dimensional onde alterações no status do cliente devem ser mantidas com timestamp para análise pontual (point-in-time).","en-us":"You need to implement a dimensional model where customer status changes must be maintained with timestamps for point-in-time analysis.","es":"Necesita implementar un modelo dimensional donde los cambios de estado del cliente deben mantenerse con timestamp para análisis puntual.","fr":"Vous devez implémenter un modèle dimensionnel où les changements de statut client doivent être conservés avec des horodatages pour l''analyse ponctuelle."}', '{"pt-br":"Qual tipo de dimensão você deve usar para DimCustomer?","en-us":"Which dimension type should you use for DimCustomer?","es":"¿Qué tipo de dimensión debe usar para DimCustomer?","fr":"Quel type de dimension devez-vous utiliser pour DimCustomer ?"}', '[{"key":"A","text":{"pt-br":"SCD Tipo 2 (Slowly Changing Dimension)","en-us":"SCD Type 2 (Slowly Changing Dimension)","es":"SCD Tipo 2 (Slowly Changing Dimension)","fr":"SCD Type 2 (Dimension à évolution lente)"}},{"key":"B","text":{"pt-br":"SCD Tipo 1","en-us":"SCD Type 1","es":"SCD Tipo 1","fr":"SCD Type 1"}},{"key":"C","text":{"pt-br":"SCD Tipo 0","en-us":"SCD Type 0","es":"SCD Tipo 0","fr":"SCD Type 0"}},{"key":"D","text":{"pt-br":"SCD Tipo 3","en-us":"SCD Type 3","es":"SCD Tipo 3","fr":"SCD Type 3"}}]', 'A', '{"pt-br":"SCD Tipo 2 mantém múltiplas versões adicionando uma nova linha a cada alteração com timestamp. Tipo 1 sobrescreve. Tipo 0 não rastreia. Tipo 3 armazena duas versões como colunas.","en-us":"SCD Type 2 maintains multiple versions by adding a new row per change with timestamp. Type 1 overwrites. Type 0 doesn''t track. Type 3 stores two versions as columns.","es":"SCD Tipo 2 mantiene múltiples versiones agregando una nueva fila por cambio. Tipo 1 sobrescribe. Tipo 0 no rastrea. Tipo 3 almacena dos versiones.","fr":"SCD Type 2 maintient plusieurs versions en ajoutant une nouvelle ligne par changement. Type 1 écrase. Type 0 ne suit pas. Type 3 stocke deux versions."}'),
('Otimizar Modelos Semânticos', '{"pt-br":"Você publicou um modelo grande com incremental refresh. A carga inicial completa levará horas. Precisa criar as partições no serviço sem processá-las.","en-us":"You published a large model with incremental refresh. The full initial load will take hours. You need to create partitions in the service without processing them.","es":"Publicó un modelo grande con incremental refresh. La carga inicial completa tomará horas. Necesita crear las particiones sin procesarlas.","fr":"Vous avez publié un grand modèle avec actualisation incrémentielle. Le chargement initial complet prendra des heures. Vous devez créer les partitions sans les traiter."}', '{"pt-br":"O que você pode usar?","en-us":"What can you use?","es":"¿Qué puede usar?","fr":"Que pouvez-vous utiliser ?"}', '[{"key":"A","text":{"pt-br":"Editor Tabular (Tabular Editor)","en-us":"Tabular Editor","es":"Editor Tabular (Tabular Editor)","fr":"Tabular Editor"}},{"key":"B","text":{"pt-br":"Power BI Desktop","en-us":"Power BI Desktop","es":"Power BI Desktop","fr":"Power BI Desktop"}},{"key":"C","text":{"pt-br":"Microsoft Visual Studio Code","en-us":"Microsoft Visual Studio Code","es":"Microsoft Visual Studio Code","fr":"Microsoft Visual Studio Code"}},{"key":"D","text":{"pt-br":"DAX Studio","en-us":"DAX Studio","es":"DAX Studio","fr":"DAX Studio"}}]', 'A', '{"pt-br":"Tabular Editor permite executar ''Apply Refresh Policy'' para criar partições baseadas na política de incremental refresh sem processá-las. Power BI Desktop exige atualização completa.","en-us":"Tabular Editor allows executing ''Apply Refresh Policy'' to create partitions based on incremental refresh policy without processing them.","es":"Tabular Editor permite ejecutar ''Apply Refresh Policy'' para crear particiones sin procesarlas.","fr":"Tabular Editor permet d''exécuter ''Apply Refresh Policy'' pour créer des partitions sans les traiter."}'),
('Otimizar Modelos Semânticos', '{"pt-br":"Você tem um relatório Power BI com DirectQuery para um banco SQL do Azure. Precisa reduzir o número de consultas enviadas ao banco quando o usuário interage com filtros e segmentações.","en-us":"You have a Power BI report with DirectQuery to Azure SQL. You need to reduce queries sent to the database when users interact with filters and slicers.","es":"Tiene un informe Power BI con DirectQuery a Azure SQL. Necesita reducir las consultas enviadas al banco cuando los usuarios interactúan con filtros.","fr":"Vous avez un rapport Power BI avec DirectQuery vers Azure SQL. Vous devez réduire les requêtes envoyées à la base quand les utilisateurs interagissent avec les filtres."}', '{"pt-br":"O que você deve fazer?","en-us":"What should you do?","es":"¿Qué debe hacer?","fr":"Que devez-vous faire ?"}', '[{"key":"A","text":{"pt-br":"Adicionar botões Aplicar a todos os filtros","en-us":"Add Apply buttons to all filters","es":"Agregar botones Aplicar a todos los filtros","fr":"Ajouter des boutons Appliquer à tous les filtres"}},{"key":"B","text":{"pt-br":"Habilitar atualização automática de página","en-us":"Enable automatic page refresh","es":"Habilitar actualización automática de página","fr":"Activer l''actualisation automatique de la page"}},{"key":"C","text":{"pt-br":"Converter para modo Import","en-us":"Convert to Import mode","es":"Convertir a modo Import","fr":"Convertir en mode Import"}},{"key":"D","text":{"pt-br":"Aumentar o timeout das consultas","en-us":"Increase query timeout","es":"Aumentar el timeout de consultas","fr":"Augmenter le délai d''expiration des requêtes"}}]', 'A', '{"pt-br":"Botões Aplicar pausam as consultas até que o usuário finalize suas seleções de filtro, enviando uma única consulta ao clicar em Aplicar. As outras opções não reduzem o número de consultas.","en-us":"Apply buttons pause queries until the user finalizes filter selections, sending a single query when clicking Apply. Other options don''t reduce query count.","es":"Los botones Aplicar pausan las consultas hasta que el usuario finalice sus selecciones de filtro.","fr":"Les boutons Appliquer mettent en pause les requêtes jusqu''à ce que l''utilisateur finalise ses sélections de filtre."}'),
('Ciclo de Vida', '{"pt-br":"Você publicou um modelo semântico grande que leva 2 horas para atualizar. Precisa atualizar a definição de uma medida sem precisar atualizar o modelo no serviço.","en-us":"You published a large semantic model that takes 2 hours to refresh. You need to update a measure definition without refreshing the model in the service.","es":"Publicó un modelo semántico grande que tarda 2 horas en actualizarse. Necesita actualizar la definición de una medida sin actualizar el modelo.","fr":"Vous avez publié un grand modèle sémantique qui prend 2 heures à actualiser. Vous devez mettre à jour une définition de mesure sans actualiser le modèle."}', '{"pt-br":"O que você pode usar?","en-us":"What can you use?","es":"¿Qué puede usar?","fr":"Que pouvez-vous utiliser ?"}', '[{"key":"A","text":{"pt-br":"ALM Toolkit","en-us":"ALM Toolkit","es":"ALM Toolkit","fr":"ALM Toolkit"}},{"key":"B","text":{"pt-br":"Power BI Desktop","en-us":"Power BI Desktop","es":"Power BI Desktop","fr":"Power BI Desktop"}},{"key":"C","text":{"pt-br":"DAX Studio","en-us":"DAX Studio","es":"DAX Studio","fr":"DAX Studio"}},{"key":"D","text":{"pt-br":"Excel","en-us":"Excel","es":"Excel","fr":"Excel"}}]', 'A', '{"pt-br":"ALM Toolkit é uma ferramenta de diferenciação de esquema que implanta apenas metadados sem exigir atualização dos dados. Power BI Desktop substitui e exige refresh. DAX Studio não atualiza metadados.","en-us":"ALM Toolkit is a schema diff tool that deploys only metadata without requiring data refresh. Power BI Desktop replaces and requires refresh. DAX Studio doesn''t update metadata.","es":"ALM Toolkit despliega solo metadatos sin exigir actualización de datos. Power BI Desktop reemplaza y exige refresh.","fr":"ALM Toolkit est un outil de diff de schéma qui déploie uniquement les métadonnées sans nécessiter d''actualisation des données."}'),
('Otimizar Modelos Semânticos', '{"pt-br":"Você tem um modelo semântico grande e precisa identificar quais colunas contribuem mais para o tamanho do modelo para focar esforços de otimização.","en-us":"You have a large semantic model and need to identify which columns contribute most to model size to focus optimization efforts.","es":"Tiene un modelo semántico grande y necesita identificar qué columnas contribuyen más al tamaño del modelo.","fr":"Vous avez un grand modèle sémantique et devez identifier quelles colonnes contribuent le plus à la taille du modèle."}', '{"pt-br":"Qual ferramenta externa você pode usar?","en-us":"Which external tool can you use?","es":"¿Qué herramienta externa puede usar?","fr":"Quel outil externe pouvez-vous utiliser ?"}', '[{"key":"A","text":{"pt-br":"DAX Studio","en-us":"DAX Studio","es":"DAX Studio","fr":"DAX Studio"}},{"key":"B","text":{"pt-br":"ALM Toolkit","en-us":"ALM Toolkit","es":"ALM Toolkit","fr":"ALM Toolkit"}},{"key":"C","text":{"pt-br":"Tabular Editor","en-us":"Tabular Editor","es":"Tabular Editor","fr":"Tabular Editor"}},{"key":"D","text":{"pt-br":"Best Practice Analyzer","en-us":"Best Practice Analyzer","es":"Best Practice Analyzer","fr":"Best Practice Analyzer"}}]', 'A', '{"pt-br":"DAX Studio conecta ao modelo e fornece estatísticas detalhadas sobre tamanho de cada tabela e coluna (VertiPaq Analyzer). As outras ferramentas têm casos de uso diferentes.","en-us":"DAX Studio connects to the model and provides detailed statistics about each table and column size (VertiPaq Analyzer). Other tools have different use cases.","es":"DAX Studio se conecta al modelo y proporciona estadísticas detalladas sobre el tamaño de cada tabla y columna.","fr":"DAX Studio se connecte au modèle et fournit des statistiques détaillées sur la taille de chaque table et colonne."}'),
('Obter Dados', '{"pt-br":"Você tem um lakehouse Fabric e precisa migrar 200 milhões de linhas de um banco Snowflake externo usando um pipeline de dados.","en-us":"You have a Fabric lakehouse and need to migrate 200 million rows from an external Snowflake database using a data pipeline.","es":"Tiene un lakehouse Fabric y necesita migrar 200 millones de filas de un banco Snowflake externo usando un pipeline de datos.","fr":"Vous avez un lakehouse Fabric et devez migrer 200 millions de lignes d''une base Snowflake externe avec un pipeline de données."}', '{"pt-br":"Qual é o método mais eficaz (mais rápido)?","en-us":"What is the most effective (fastest) method?","es":"¿Cuál es el método más eficaz (más rápido)?","fr":"Quelle est la méthode la plus efficace (la plus rapide) ?"}', '[{"key":"A","text":{"pt-br":"Pipeline de Dados com atividade Copiar dados","en-us":"Data Pipeline with Copy Data activity","es":"Pipeline de Datos con actividad Copiar datos","fr":"Pipeline de données avec activité Copier les données"}},{"key":"B","text":{"pt-br":"Dataflow Gen2","en-us":"Dataflow Gen2","es":"Dataflow Gen2","fr":"Dataflow Gen2"}},{"key":"C","text":{"pt-br":"Notebook Spark","en-us":"Spark Notebook","es":"Notebook Spark","fr":"Notebook Spark"}},{"key":"D","text":{"pt-br":"Atalho (Shortcut)","en-us":"Shortcut","es":"Atajo (Shortcut)","fr":"Raccourci (Shortcut)"}}]', 'A', '{"pt-br":"A atividade Copiar dados é o método mais rápido e direto para migrar grandes volumes sem transformações. Dataflow Gen2 é para volumes menores. Atalhos não movem dados.","en-us":"Copy Data activity is the fastest and most direct method for migrating large volumes without transformations. Dataflow Gen2 is for smaller volumes. Shortcuts don''t move data.","es":"Copiar datos es el método más rápido para migrar grandes volúmenes sin transformaciones.","fr":"L''activité Copier les données est la méthode la plus rapide pour migrer de grands volumes sans transformations."}'),
('Obter Dados', '{"pt-br":"Você tem um warehouse Fabric e precisa ingerir 1 TB de dados de uma fonte externa. A solução deve ter a maior taxa de transferência e ser low-code/no-code.","en-us":"You have a Fabric warehouse and need to ingest 1 TB from an external source. The solution must have the highest throughput and be low-code/no-code.","es":"Tiene un warehouse Fabric y necesita ingerir 1 TB de una fuente externa. La solución debe tener la mayor tasa de transferencia y ser low-code.","fr":"Vous avez un warehouse Fabric et devez ingérer 1 To depuis une source externe. La solution doit avoir le débit le plus élevé et être low-code."}', '{"pt-br":"O que você deve recomendar?","en-us":"What should you recommend?","es":"¿Qué debe recomendar?","fr":"Que devez-vous recommander ?"}', '[{"key":"A","text":{"pt-br":"Atividade Copiar dados de um pipeline","en-us":"Copy Data activity from a pipeline","es":"Actividad Copiar datos de un pipeline","fr":"Activité Copier les données d''un pipeline"}},{"key":"B","text":{"pt-br":"Notebook Spark","en-us":"Spark Notebook","es":"Notebook Spark","fr":"Notebook Spark"}},{"key":"C","text":{"pt-br":"Atalho (Shortcut)","en-us":"Shortcut","es":"Atajo (Shortcut)","fr":"Raccourci (Shortcut)"}},{"key":"D","text":{"pt-br":"Dataflow Gen2","en-us":"Dataflow Gen2","es":"Dataflow Gen2","fr":"Dataflow Gen2"}}]', 'A', '{"pt-br":"Copiar dados oferece a maior taxa de transferência e é low-code. Notebooks são code-first. Atalhos não movem dados. Dataflow Gen2 tem performance inferior para grandes volumes.","en-us":"Copy Data provides highest throughput and is low-code. Notebooks are code-first. Shortcuts don''t move data. Dataflow Gen2 has lower performance for large volumes.","es":"Copiar datos ofrece la mayor tasa de transferencia y es low-code. Notebooks son code-first. Atalhos no mueven datos.","fr":"Copier les données offre le débit le plus élevé et est low-code. Les notebooks sont code-first. Les raccourcis ne déplacent pas les données."}'),
('Otimizar Modelos Semânticos', '{"pt-br":"Uma consulta SELECT em uma tabela Delta no lakehouse é lenta. A tabela tem 1.000 arquivos Parquet de 1 MB cada, recebe dados diários e deve manter histórico de 7 dias.","en-us":"A SELECT query on a Delta table in the lakehouse is slow. The table has 1,000 Parquet files of 1 MB each, receives daily data, and must maintain 7-day history.","es":"Una consulta SELECT en una tabla Delta del lakehouse es lenta. La tabla tiene 1.000 archivos Parquet de 1 MB cada uno, recibe datos diarios y debe mantener historial de 7 días.","fr":"Une requête SELECT sur une table Delta dans le lakehouse est lente. La table a 1 000 fichiers Parquet de 1 Mo chacun, reçoit des données quotidiennes et doit maintenir un historique de 7 jours."}', '{"pt-br":"O que você deve fazer no explorador do Lakehouse?","en-us":"What should you do in the Lakehouse explorer?","es":"¿Qué debe hacer en el explorador del Lakehouse?","fr":"Que devez-vous faire dans l''explorateur du Lakehouse ?"}', '[{"key":"A","text":{"pt-br":"Selecionar Manutenção e executar OPTIMIZE + VACUUM com retenção de 7 dias","en-us":"Select Maintenance and run OPTIMIZE + VACUUM with 7-day retention","es":"Seleccionar Mantenimiento y ejecutar OPTIMIZE + VACUUM con retención de 7 días","fr":"Sélectionner Maintenance et exécuter OPTIMIZE + VACUUM avec rétention de 7 jours"}},{"key":"B","text":{"pt-br":"Executar apenas VACUUM com retenção de 7 dias","en-us":"Run only VACUUM with 7-day retention","es":"Ejecutar solo VACUUM con retención de 7 días","fr":"Exécuter uniquement VACUUM avec rétention de 7 jours"}},{"key":"C","text":{"pt-br":"Recriar a tabela com particionamento","en-us":"Recreate the table with partitioning","es":"Recrear la tabla con particionamiento","fr":"Recréer la table avec partitionnement"}},{"key":"D","text":{"pt-br":"Aumentar a capacidade do workspace","en-us":"Increase workspace capacity","es":"Aumentar la capacidad del workspace","fr":"Augmenter la capacité du workspace"}}]', 'A', '{"pt-br":"OPTIMIZE compacta arquivos pequenos em arquivos maiores (ideal 128 MB - 1 GB). VACUUM remove arquivos antigos que não estão mais em uso, reduzindo custos de armazenamento.","en-us":"OPTIMIZE compacts small files into larger files (ideal 128 MB - 1 GB). VACUUM removes old files no longer in use, reducing storage costs.","es":"OPTIMIZE compacta archivos pequeños en archivos más grandes. VACUUM elimina archivos antiguos no utilizados.","fr":"OPTIMIZE compacte les petits fichiers en fichiers plus grands. VACUUM supprime les anciens fichiers inutilisés."}'),
('Otimizar Modelos Semânticos', '{"pt-br":"Você tem um warehouse Fabric com uma consulta SQL com desempenho ruim. As estatísticas da tabela estão desatualizadas. Precisa atualizar manualmente as estatísticas.","en-us":"You have a Fabric warehouse with a poorly performing SQL query. Table statistics are outdated. You need to manually update statistics.","es":"Tiene un warehouse Fabric con una consulta SQL de bajo rendimiento. Las estadísticas de la tabla están desactualizadas.","fr":"Vous avez un warehouse Fabric avec une requête SQL peu performante. Les statistiques de la table sont obsolètes."}', '{"pt-br":"Quais estatísticas de coluna você deve atualizar?","en-us":"Which column statistics should you update?","es":"¿Qué estadísticas de columna debe actualizar?","fr":"Quelles statistiques de colonne devez-vous mettre à jour ?"}', '[{"key":"A","text":{"pt-br":"Colunas usadas em cláusulas GROUP BY","en-us":"Columns used in GROUP BY clauses","es":"Columnas usadas en cláusulas GROUP BY","fr":"Colonnes utilisées dans les clauses GROUP BY"}},{"key":"B","text":{"pt-br":"Todas as colunas da tabela","en-us":"All columns in the table","es":"Todas las columnas de la tabla","fr":"Toutes les colonnes de la table"}},{"key":"C","text":{"pt-br":"Apenas colunas de chave primária","en-us":"Only primary key columns","es":"Solo columnas de clave primaria","fr":"Uniquement les colonnes de clé primaire"}},{"key":"D","text":{"pt-br":"Colunas usadas em SELECT","en-us":"Columns used in SELECT","es":"Columnas usadas en SELECT","fr":"Colonnes utilisées dans SELECT"}}]', 'A', '{"pt-br":"Ao atualizar estatísticas manualmente, foque em colunas usadas em cláusulas JOIN, ORDER BY e GROUP BY, pois são as que o otimizador de consultas usa para planos de execução.","en-us":"When manually updating statistics, focus on columns used in JOIN, ORDER BY, and GROUP BY clauses, as the query optimizer uses these for execution plans.","es":"Al actualizar estadísticas, enfóquese en columnas usadas en JOIN, ORDER BY y GROUP BY.","fr":"Lors de la mise à jour manuelle des statistiques, concentrez-vous sur les colonnes utilisées dans JOIN, ORDER BY et GROUP BY."}'),
('Obter Dados', '{"pt-br":"Você tem um Dataflow Gen2 que ingere e transforma a tabela FactSales. Devido ao número de transformações, há problemas de timeout. A consulta não pode ser otimizada e alterar o tempo de atualização não ajuda.","en-us":"You have a Dataflow Gen2 that ingests and transforms FactSales. Due to many transformations, there are timeout issues. The query can''t be optimized and changing refresh time doesn''t help.","es":"Tiene un Dataflow Gen2 que ingiere y transforma FactSales. Debido al número de transformaciones, hay problemas de timeout.","fr":"Vous avez un Dataflow Gen2 qui ingère et transforme FactSales. En raison du nombre de transformations, il y a des problèmes de délai d''attente."}', '{"pt-br":"Qual ação adicional você deve recomendar?","en-us":"What additional action should you recommend?","es":"¿Qué acción adicional debe recomendar?","fr":"Quelle action supplémentaire devez-vous recommander ?"}', '[{"key":"A","text":{"pt-br":"Criar um segundo dataflow de staging que ingere sem transformações, e conectar o original para transformar","en-us":"Create a second staging dataflow that ingests without transformations, and connect the original to transform","es":"Crear un segundo dataflow de staging que ingiere sin transformaciones, y conectar el original para transformar","fr":"Créer un second dataflow de staging qui ingère sans transformations, et connecter l''original pour transformer"}},{"key":"B","text":{"pt-br":"Criar um atalho para FactSales","en-us":"Create a shortcut for FactSales","es":"Crear un atajo para FactSales","fr":"Créer un raccourci pour FactSales"}},{"key":"C","text":{"pt-br":"Migrar para um Notebook Spark","en-us":"Migrate to a Spark Notebook","es":"Migrar a un Notebook Spark","fr":"Migrer vers un Notebook Spark"}},{"key":"D","text":{"pt-br":"Aumentar a capacidade do workspace","en-us":"Increase workspace capacity","es":"Aumentar la capacidad del workspace","fr":"Augmenter la capacité du workspace"}}]', 'A', '{"pt-br":"A melhor prática é criar um dataflow de staging que ingere dados brutos primeiro, e um segundo para transformar. Isso resolve problemas de timeout ao separar ingestão de transformação.","en-us":"Best practice is to create a staging dataflow that ingests raw data first, and a second to transform. This resolves timeout issues by separating ingestion from transformation.","es":"La mejor práctica es crear un dataflow de staging que ingiere datos brutos primero, y un segundo para transformar.","fr":"La meilleure pratique est de créer un dataflow de staging qui ingère les données brutes d''abord, et un second pour transformer."}'),
('Otimizar Modelos Semânticos', '{"pt-br":"Você tem uma medida DAX: KPI Variação = IF([Variação] > 0.80, \"Incrível!\", IF([Variação] > 0.60, \"Bom\", \"Ruim\")). Precisa otimizar para calcular mais rápido.","en-us":"You have a DAX measure: Variance KPI = IF([Variance] > 0.80, \"Amazing!\", IF([Variance] > 0.60, \"Good\", \"Bad\")). You need to optimize for faster calculation.","es":"Tiene una medida DAX: KPI Variación = IF([Variación] > 0.80, \"Increíble!\", IF([Variación] > 0.60, \"Bueno\", \"Malo\")). Necesita optimizar.","fr":"Vous avez une mesure DAX : KPI Variance = IF([Variance] > 0.80, \"Incroyable!\", IF([Variance] > 0.60, \"Bon\", \"Mauvais\")). Vous devez optimiser."}', '{"pt-br":"Qual código otimizado você deve usar?","en-us":"Which optimized code should you use?","es":"¿Qué código optimizado debe usar?","fr":"Quel code optimisé devez-vous utiliser ?"}', '[{"key":"A","text":{"pt-br":"VAR Calc = [Variação] RETURN SWITCH(TRUE(), Calc > 0.80, \"Incrível!\", Calc > 0.60, \"Bom\", \"Ruim\")","en-us":"VAR Calc = [Variance] RETURN SWITCH(TRUE(), Calc > 0.80, \"Amazing!\", Calc > 0.60, \"Good\", \"Bad\")","es":"VAR Calc = [Variación] RETURN SWITCH(TRUE(), Calc > 0.80, \"Increíble!\", Calc > 0.60, \"Bueno\", \"Malo\")","fr":"VAR Calc = [Variance] RETURN SWITCH(TRUE(), Calc > 0.80, \"Incroyable!\", Calc > 0.60, \"Bon\", \"Mauvais\")"}},{"key":"B","text":{"pt-br":"IF([Variação] > 0.80, \"Incrível!\", IF([Variação] > 0.60, \"Bom\", \"Ruim\"))","en-us":"IF([Variance] > 0.80, \"Amazing!\", IF([Variance] > 0.60, \"Good\", \"Bad\"))","es":"IF([Variación] > 0.80, \"Increíble!\", IF([Variación] > 0.60, \"Bueno\", \"Malo\"))","fr":"IF([Variance] > 0.80, \"Incroyable!\", IF([Variance] > 0.60, \"Bon\", \"Mauvais\"))"}},{"key":"C","text":{"pt-br":"SWITCH([Variação], 0.80, \"Incrível!\", 0.60, \"Bom\", \"Ruim\")","en-us":"SWITCH([Variance], 0.80, \"Amazing!\", 0.60, \"Good\", \"Bad\")","es":"SWITCH([Variación], 0.80, \"Increíble!\", 0.60, \"Bueno\", \"Malo\")","fr":"SWITCH([Variance], 0.80, \"Incroyable!\", 0.60, \"Bon\", \"Mauvais\")"}},{"key":"D","text":{"pt-br":"CALCULATE(IF([Variação] > 0.80, \"Incrível!\", \"Ruim\"))","en-us":"CALCULATE(IF([Variance] > 0.80, \"Amazing!\", \"Bad\"))","es":"CALCULATE(IF([Variación] > 0.80, \"Increíble!\", \"Malo\"))","fr":"CALCULATE(IF([Variance] > 0.80, \"Incroyable!\", \"Mauvais\"))"}}]', 'A', '{"pt-br":"VAR armazena [Variação] em cache, carregando apenas uma vez. SWITCH(TRUE()) é mais legível e eficiente que IF aninhados. As outras fórmulas não usam VAR para otimizar performance.","en-us":"VAR caches [Variance], loading it only once. SWITCH(TRUE()) is more readable and efficient than nested IFs. Other formulas don''t use VAR to optimize performance.","es":"VAR almacena [Variación] en caché, cargando solo una vez. SWITCH(TRUE()) es más legible y eficiente que IFs anidados.","fr":"VAR met en cache [Variance], ne le chargeant qu''une fois. SWITCH(TRUE()) est plus lisible et efficace que des IF imbriqués."}');
